    def run_ingestion_job(self, payload: Mapping[str, Any], *, actor: str = "system") -> IngestionJob:
        items = list(payload.get("items", []))
        job = IngestionJob(
            job_id=str(payload.get("job_id", new_id("job"))),
            status="running",
            total=len(items),
            completed_at=utcnow(),
        )
        if job.job_id in self.store.ingestion_jobs:
            raise ConflictError(f"ingestion job {job.job_id} already exists")
        default_rights = payload.get("rights_tag")
        include_body = bool(payload.get("include_body", False))
        user_agent = self._sec_user_agent(payload)
        for index, item in enumerate(items):
            try:
                market = str(item["market"])
                issuer_id = str(item["issuer_id"])
                security_id = str(item.get("security_id", ""))
                raw = dict(item["raw"])
                normalized = self.connectors.normalize(market, raw)
                source_id = str(item.get("source_id", normalized.source_id))
                if source_id not in self.store.sources:
                    if source_id in {"ashare_exchange", "hkexnews", "sec_edgar"}:
                        self.seed_default_sources(actor=actor)
                    else:
                        raise NotFoundError(f"source {source_id} not found")
                if issuer_id not in self.store.issuers:
                    raise NotFoundError(f"issuer {issuer_id} not found")
                if security_id and security_id not in self.store.securities:
                    raise NotFoundError(f"security {security_id} not found")
                document_id = str(item.get("document_id", self._job_document_id(market, raw, normalized.source_uri)))
                if document_id in self.store.documents:
                    job.skipped += 1
                    continue
                body = str(item.get("body", normalized.body))
                if include_body and market == "U" and normalized.source_uri and not body:
                    body = self.connectors.fetch_sec_document_body(normalized.source_uri, user_agent=user_agent, max_bytes=int(payload.get("max_body_bytes", 2_000_000)))
                source = self.store.sources[source_id]
                document = self.ingest_document(
                    {
                        "document_id": document_id,
                        "issuer_id": issuer_id,
                        "security_id": security_id,
                        "source_id": source_id,
                        "source_type": normalized.source_type,
                        "document_type": normalized.document_type,
                        "source_uri": normalized.source_uri,
                        "rights_tag": dict(default_rights or item.get("rights_tag") or to_plain(source.rights_tag)),
                        "body": body,
                        "title": normalized.title,
                        "published_at": normalized.published_at or None,
                        "language": normalized.language,
                        "version": str(payload.get("version", "job")),
                    },
                    actor=actor,
                )
                job.created += 1
                job.created_document_ids.append(document.document_id)
            except Exception as exc:
                job.failed += 1
                job.errors.append({"index": index, "error": str(exc)})
        job.status = "failed" if job.failed and not job.created else "partial" if job.failed else "completed"
        job.completed_at = utcnow()
        self.store.ingestion_jobs[job.job_id] = job
        self._audit(actor, "run_ingestion_job", "ingestion_job", job.job_id, approval_state=job.status)
        return job

    def register_ingestion_schedule(self, payload: Mapping[str, Any], *, actor: str = "system") -> IngestionSchedule:
        schedule = IngestionSchedule(
            schedule_id=str(payload.get("schedule_id", new_id("sched"))),
            name=str(payload.get("name", "ingestion schedule")),
            payload=dict(payload.get("payload", {})),
            cadence=str(payload.get("cadence", "manual")),
            status=str(payload.get("status", "active")),
            retry_limit=int(payload.get("retry_limit", 2)),
            next_run_at=parse_datetime(payload.get("next_run_at")),
        )
        if schedule.schedule_id in self.store.ingestion_schedules:
            raise ConflictError(f"ingestion schedule {schedule.schedule_id} already exists")
        self.store.ingestion_schedules[schedule.schedule_id] = schedule
        self._audit(actor, "register_ingestion_schedule", "ingestion_schedule", schedule.schedule_id, approval_state=schedule.status)
        return schedule

    def run_ingestion_schedules(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        now = utcnow()
        due_only = bool(payload.get("due_only", True))
        schedule_ids = {str(item) for item in payload.get("schedule_ids", [])}
        ran: list[dict[str, Any]] = []
        skipped: list[dict[str, str]] = []
        for schedule in list(self.store.ingestion_schedules.values()):
            if schedule_ids and schedule.schedule_id not in schedule_ids:
                continue
            if schedule.status not in {"active", "retrying"}:
                skipped.append({"schedule_id": schedule.schedule_id, "reason": schedule.status})
                continue
            if due_only and schedule.next_run_at > now:
                skipped.append({"schedule_id": schedule.schedule_id, "reason": "not_due"})
                continue
            result = self._run_ingestion_schedule(schedule, actor=actor)
            ran.append(result)
        return {"ran": ran, "skipped": skipped}

    def _run_ingestion_schedule(self, schedule: IngestionSchedule, *, actor: str) -> dict[str, Any]:
        run_payload = dict(schedule.payload)
        base_job_id = str(run_payload.get("job_id") or schedule.schedule_id)
        run_payload["job_id"] = f"{base_job_id}_{utcnow().strftime('%Y%m%d%H%M%S')}"
        try:
            job = self.run_ingestion_job(run_payload, actor=actor)
            schedule.last_job_id = job.job_id
            schedule.last_status = job.status
            schedule.last_error = ""
            if job.status in {"completed", "partial"}:
                schedule.retry_count = 0
                schedule.status = "active"
                schedule.next_run_at = self._next_schedule_run(schedule.cadence)
            else:
                self._mark_schedule_retry(schedule, f"job status {job.status}")
            schedule.updated_at = utcnow()
            self.store.commit()
            self._audit(actor, "run_ingestion_schedule", "ingestion_schedule", schedule.schedule_id, approval_state=schedule.status)
            return {"schedule_id": schedule.schedule_id, "job": to_plain(job), "status": schedule.status}
        except Exception as exc:
            self._mark_schedule_retry(schedule, str(exc))
            schedule.updated_at = utcnow()
            self.store.commit()
            self._audit(actor, "run_ingestion_schedule", "ingestion_schedule", schedule.schedule_id, approval_state=schedule.status)
            return {"schedule_id": schedule.schedule_id, "error": str(exc), "status": schedule.status}

    def register_issuer(self, payload: Mapping[str, Any], *, actor: str = "system") -> Issuer:
        issuer = payload if isinstance(payload, Issuer) else Issuer.from_dict(payload)
        if issuer.issuer_id in self.store.issuers:
            raise ConflictError(f"issuer {issuer.issuer_id} already exists")
        self.store.issuers[issuer.issuer_id] = issuer
        self._audit(actor, "register_issuer", "issuer", issuer.issuer_id)
        return issuer

    def register_security(self, payload: Mapping[str, Any], *, actor: str = "system") -> Security:
        security = payload if isinstance(payload, Security) else Security.from_dict(payload)
        if security.issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {security.issuer_id} not found")
        if security.security_id in self.store.securities:
            raise ConflictError(f"security {security.security_id} already exists")
        self.store.securities[security.security_id] = security
        self._audit(actor, "register_security", "security", security.security_id)
        return security

    def register_market_data_point(self, payload: Mapping[str, Any], *, actor: str = "system") -> MarketDataPoint:
        security_id = str(payload["security_id"])
        security = self.store.securities.get(security_id)
        if security is None:
            raise NotFoundError(f"security {security_id} not found")
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id == PUBLIC_EOD_MARKET_DATA_SOURCE_ID:
                self.seed_default_sources(actor=actor)
            else:
                raise NotFoundError(f"source {source_id} not found")
        source = self.store.sources[source_id]
        if source.risk_level == "red":
            raise PermissionDenied("red market data source cannot enter research layer")
        market = str(payload.get("market", security.market))
        if market != security.market:
            raise ValidationError(f"market {market} does not match security market {security.market}")
        as_of_date = str(payload["as_of_date"])
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", as_of_date):
            raise ValidationError("as_of_date must use YYYY-MM-DD")
        data_type = str(payload.get("data_type", "eod"))
        if data_type not in {"eod", "delayed"}:
            raise ValidationError("market data only supports public eod or delayed data")
        rights_tag = source.rights_tag if "rights_tag" not in payload else type(source.rights_tag).from_dict(payload["rights_tag"])
        if not source.rights_tag.allows(rights_tag):
            raise PermissionDenied("market data rights exceed source rights")
        self._validate_market_data_field_boundary(payload, source)
        prices = {
            "open": float(payload.get("open", 0.0)),
            "high": float(payload.get("high", 0.0)),
            "low": float(payload.get("low", 0.0)),
            "close": float(payload.get("close", 0.0)),
            "adjusted_close": float(payload.get("adjusted_close", payload.get("close", 0.0))),
            "volume": float(payload.get("volume", 0.0)),
        }
        amount = float(payload.get("amount", 0.0) or 0.0)
        if any(value < 0 for value in prices.values()) or amount < 0:
            raise ValidationError("market data prices and volume must be non-negative")
        data_id = str(payload.get("data_id", self._market_data_id(security_id, as_of_date, data_type, source_id)))
        if self._market_data_point_exists(security_id, source_id=source_id, data_type=data_type, as_of_date=as_of_date):
            raise ConflictError(f"market data {data_id} already exists")
        point = MarketDataPoint(
            data_id=data_id,
            security_id=security_id,
            source_id=source_id,
            market=market,
            as_of_date=as_of_date,
            data_type=data_type,
            currency=str(payload.get("currency", security.currency)),
            rights_tag=rights_tag,
            amount=amount,
            **prices,
        )
        self.store.market_data[point.data_id] = point
        self._audit(
            actor,
            "register_market_data_point",
            "market_data",
            point.data_id,
            source=source.source_type,
            version=point.rights_tag.license_class,
            approval_state=point.data_type,
        )
        return point

    def register_market_data_batch(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        items = payload.get("items", [])
        if not isinstance(items, list):
            raise ValidationError("market data batch requires items list")
        created: list[MarketDataPoint] = []
        errors: list[dict[str, Any]] = []
        for index, item in enumerate(items):
            if not isinstance(item, Mapping):
                errors.append({"index": index, "error": "item must be an object"})
                continue
            try:
                created.append(self.register_market_data_point(item, actor=actor))
            except (ValidationError, NotFoundError, PermissionDenied, ConflictError) as exc:
                errors.append({"index": index, "error": str(exc)})
        self._audit(actor, "register_market_data_batch", "market_data", str(payload.get("batch_id", "batch")), approval_state=f"created={len(created)};failed={len(errors)}")
        return {"created": [to_plain(item) for item in created], "errors": errors, "created_count": len(created), "failed_count": len(errors)}

    def register_corporate_action(self, payload: Mapping[str, Any], *, actor: str = "system") -> CorporateAction:
        security_id = str(payload["security_id"])
        if security_id not in self.store.securities:
            raise NotFoundError(f"security {security_id} not found")
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id == PUBLIC_EOD_MARKET_DATA_SOURCE_ID:
                self.seed_default_sources(actor=actor)
            else:
                raise NotFoundError(f"source {source_id} not found")
        source = self.store.sources[source_id]
        if source.risk_level == "red":
            raise PermissionDenied("red corporate action source cannot enter research layer")
        action_type = str(payload["action_type"])
        if action_type not in {"split", "reverse_split", "cash_dividend", "stock_dividend", "symbol_change"}:
            raise ValidationError("unsupported corporate action type")
        ex_date = str(payload["ex_date"])
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", ex_date):
            raise ValidationError("ex_date must use YYYY-MM-DD")
        action = CorporateAction(
            action_id=str(payload.get("action_id", self._corporate_action_id(security_id, action_type, ex_date, source_id))),
            security_id=security_id,
            source_id=source_id,
            action_type=action_type,
            ex_date=ex_date,
            ratio=float(payload.get("ratio", 1.0)),
            cash_amount=float(payload.get("cash_amount", 0.0)),
            currency=str(payload.get("currency", self.store.securities[security_id].currency)),
            description=str(payload.get("description", "")),
        )
        if action.ratio < 0 or action.cash_amount < 0:
            raise ValidationError("corporate action ratio and cash amount must be non-negative")
        if action.action_id in self.store.corporate_actions:
            raise ConflictError(f"corporate action {action.action_id} already exists")
        self.store.corporate_actions[action.action_id] = action
        self._audit(actor, "register_corporate_action", "corporate_action", action.action_id, source=source.source_type, approval_state=action.action_type)
        return action

    def corporate_actions_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        security_id = str(filters.get("security_id", "")).strip()
        action_type = str(filters.get("action_type", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 50))
        actions = list(self.store.corporate_actions.values())
        if security_id:
            actions = [item for item in actions if item.security_id == security_id]
        if action_type:
            actions = [item for item in actions if item.action_type == action_type]
        actions.sort(key=lambda item: (item.ex_date, item.security_id), reverse=True)
        return {"count": len(actions), "corporate_actions": [to_plain(item) for item in actions[:limit]]}

    def market_data_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        security_id = str(filters.get("security_id", "")).strip()
        market = str(filters.get("market", "")).strip()
        source_id = self._canonical_source_id(str(filters.get("source_id", "")).strip()) if filters.get("source_id") else ""
        data_type = str(filters.get("data_type", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 50))
        if self._market_data_direct_query_enabled():
            points = self._query_market_data_points(
                security_id=security_id,
                market=market,
                source_id=source_id,
                data_type=data_type,
                limit=limit,
                descending=True,
            )
            return {"market_data": [to_plain(item) for item in points]}
        points = list(self.store.market_data.values())
        if security_id:
            points = [item for item in points if item.security_id == security_id]
        if market:
            points = [item for item in points if item.market == market]
        if source_id:
            points = [item for item in points if item.source_id == source_id]
        if data_type:
            points = [item for item in points if item.data_type == data_type]
        points.sort(key=lambda item: (item.as_of_date, item.security_id, item.source_id), reverse=True)
        return {"market_data": [to_plain(item) for item in points[:limit]]}

    def _market_data_direct_query_enabled(self) -> bool:
        return hasattr(self.store, "query_market_data_points")

    def _query_market_data_points(
        self,
        *,
        security_id: str = "",
        market: str = "",
        source_id: str = "",
        data_type: str = "",
        start_date: str = "",
        end_date: str = "",
        as_of_date_lte: str = "",
        limit: int = 50,
        descending: bool = True,
    ) -> list[MarketDataPoint]:
        query = getattr(self.store, "query_market_data_points")
        return query(
            security_id=security_id,
            market=market,
            source_id=source_id,
            data_type=data_type,
            start_date=start_date,
            end_date=end_date,
            as_of_date_lte=as_of_date_lte,
            limit=limit,
            descending=descending,
        )

    def _count_market_data_points(self, *, security_id: str = "", market: str = "", source_id: str = "", data_type: str = "") -> int:
        counter = getattr(self.store, "count_market_data_points")
        return int(counter(security_id=security_id, market=market, source_id=source_id, data_type=data_type))

    def adjusted_market_data_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        security_id = str(filters.get("security_id", "")).strip()
        if not security_id:
            raise ValidationError("adjusted market data requires security_id")
        if security_id not in self.store.securities:
            raise NotFoundError(f"security {security_id} not found")
        source_id = self._canonical_source_id(str(filters.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        data_type = str(filters.get("data_type", "eod"))
        adjustment_mode = str(filters.get("adjustment_mode", filters.get("mode", "backward"))).strip().lower()
        if adjustment_mode not in {"raw", "backward", "forward"}:
            raise ValidationError("adjustment_mode must be raw, backward, or forward")
        start_date = str(filters.get("start_date", ""))
        end_date = str(filters.get("end_date", ""))
        limit = self._bounded_limit(filters.get("limit", 500), 10000)
        if self._market_data_direct_query_enabled():
            points = self._query_market_data_points(
                security_id=security_id,
                source_id=source_id,
                data_type=data_type,
                start_date=start_date,
                end_date=end_date,
                limit=limit,
                descending=False,
            )
        else:
            points = [
                point
                for point in self.store.market_data.values()
                if point.security_id == security_id and point.source_id == source_id and point.data_type == data_type
            ]
            if start_date:
                points = [point for point in points if point.as_of_date >= start_date]
            if end_date:
                points = [point for point in points if point.as_of_date <= end_date]
            points.sort(key=lambda item: item.as_of_date)
        actions = [
            action
            for action in self.store.corporate_actions.values()
            if action.security_id == security_id and action.source_id == source_id
        ]
        actions.sort(key=lambda item: (item.ex_date, item.action_id))
        adjusted_rows: list[dict[str, Any]] = []
        for point in points[:limit]:
            factor, event_ids = self._market_data_adjustment_factor(point, actions, adjustment_mode=adjustment_mode)
            cash_dividend = self._cash_dividend_for_date(point.as_of_date, actions)
            adjusted_rows.append(
                {
                    **to_plain(point),
                    "raw_close": point.close,
                    "raw_adjusted_close": point.adjusted_close,
                    "adjustment_mode": adjustment_mode,
                    "adjustment_factor": round(factor, 10),
                    "computed_adjusted_open": round(point.open * factor, 6),
                    "computed_adjusted_high": round(point.high * factor, 6),
                    "computed_adjusted_low": round(point.low * factor, 6),
                    "computed_adjusted_close": round(point.close * factor, 6),
                    "corporate_action_ids": event_ids,
                    "cash_dividend": round(cash_dividend, 6),
                    "computed_adjusted_cash_dividend": round(cash_dividend * factor, 6),
                }
            )
        return {
            "security_id": security_id,
            "source_id": source_id,
            "data_type": data_type,
            "adjustment_mode": adjustment_mode,
            "adjustment_policy": {
                "raw": "Use stored OHLC and adjusted_close without applying corporate actions.",
                "backward": "Apply future split, reverse split, and stock dividend actions to older prices for backtest continuity.",
                "forward": "Apply past split, reverse split, and stock dividend actions to newer prices for old-share-basis continuity.",
                "cash_dividends": "Cash dividends are returned per ex-date and are only included in returns when total_return_method=cash_dividend_reinvested.",
            },
            "corporate_actions": [to_plain(action) for action in actions],
            "count": len(adjusted_rows),
            "market_data": adjusted_rows,
        }

    def market_data_returns_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        adjusted = self.adjusted_market_data_payload(filters)
        price_field = str(filters.get("price_field", "computed_adjusted_close"))
        if price_field not in {"computed_adjusted_close", "close", "adjusted_close"}:
            raise ValidationError("price_field must be computed_adjusted_close, close, or adjusted_close")
        total_return_method = str(filters.get("total_return_method", "price_only")).strip().lower()
        if total_return_method not in {"price_only", "cash_dividend_reinvested"}:
            raise ValidationError("total_return_method must be price_only or cash_dividend_reinvested")
        prices = [
            (
                str(row["as_of_date"]),
                float(row.get(price_field, 0.0) or 0.0),
                float(row.get("computed_adjusted_cash_dividend" if price_field == "computed_adjusted_close" else "cash_dividend", 0.0) or 0.0),
            )
            for row in adjusted["market_data"]
            if float(row.get(price_field, 0.0) or 0.0) > 0
        ]
        returns: list[dict[str, Any]] = []
        for (previous_date, previous_price, _previous_cash), (current_date, current_price, current_cash) in zip(prices, prices[1:]):
            cash_component = current_cash if total_return_method == "cash_dividend_reinvested" else 0.0
            period_return = (current_price + cash_component) / previous_price - 1.0 if previous_price else 0.0
            returns.append(
                {
                    "previous_date": previous_date,
                    "as_of_date": current_date,
                    "previous_price": round(previous_price, 6),
                    "price": round(current_price, 6),
                    "cash_dividend": round(cash_component, 6),
                    "return": round(period_return, 8),
                }
            )
        return_values = [item["return"] for item in returns]
        total_return = self._compound_return(return_values) if return_values else 0.0
        volatility = self._series_volatility(return_values)
        return {
            "security_id": adjusted["security_id"],
            "source_id": adjusted["source_id"],
            "data_type": adjusted["data_type"],
            "adjustment_mode": adjusted["adjustment_mode"],
            "price_field": price_field,
            "total_return_method": total_return_method,
            "price_count": len(prices),
            "return_count": len(returns),
            "total_return": round(total_return, 8),
            "volatility": round(volatility, 8),
            "max_drawdown": round(self._max_drawdown(return_values), 8) if return_values else 0.0,
            "returns": returns,
            "adjustment_policy": adjusted["adjustment_policy"],
        }

    def market_data_quality_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        security_id = str(filters.get("security_id", "")).strip()
        market = str(filters.get("market", "")).strip()
        source_id = self._canonical_source_id(str(filters.get("source_id", "")).strip()) if filters.get("source_id") else ""
        data_type = str(filters.get("data_type", "")).strip()
        max_gap_days = int(filters.get("max_gap_days", 7))
        sampled = False
        if self._market_data_direct_query_enabled():
            points = self._query_market_data_points(
                security_id=security_id,
                market=market,
                source_id=source_id,
                data_type=data_type,
                limit=self._bounded_limit(filters.get("sample_limit", 10000), 10000),
                descending=False,
            )
            total = self._count_market_data_points(security_id=security_id, market=market, source_id=source_id, data_type=data_type)
            sampled = total > len(points)
        else:
            points = list(self.store.market_data.values())
            if security_id:
                points = [item for item in points if item.security_id == security_id]
            if market:
                points = [item for item in points if item.market == market]
            if source_id:
                points = [item for item in points if item.source_id == source_id]
            if data_type:
                points = [item for item in points if item.data_type == data_type]
            total = len(points)

        invalid_ohlc: list[dict[str, Any]] = []
        source_rights_gaps: list[dict[str, Any]] = []
        source_counts: dict[str, int] = {}
        security_counts: dict[str, int] = {}
        series: dict[tuple[str, str, str], list[MarketDataPoint]] = {}
        for point in points:
            source_counts[point.source_id] = source_counts.get(point.source_id, 0) + 1
            security_counts[point.security_id] = security_counts.get(point.security_id, 0) + 1
            series.setdefault((point.security_id, point.source_id, point.data_type), []).append(point)
            if point.high < max(point.open, point.close, point.low) or point.low > min(point.open, point.close, point.high):
                invalid_ohlc.append(
                    {
                        "data_id": point.data_id,
                        "security_id": point.security_id,
                        "as_of_date": point.as_of_date,
                        "open": point.open,
                        "high": point.high,
                        "low": point.low,
                        "close": point.close,
                        "issue": "ohlc_range_inconsistent",
                    }
                )
            source = self.store.sources.get(point.source_id)
            if source is None:
                source_rights_gaps.append({"data_id": point.data_id, "source_id": point.source_id, "issue": "source_not_registered"})
            elif source.risk_level == "red":
                source_rights_gaps.append({"data_id": point.data_id, "source_id": point.source_id, "issue": "red_source_in_research_layer"})
            elif not source.rights_tag.allows(point.rights_tag):
                source_rights_gaps.append({"data_id": point.data_id, "source_id": point.source_id, "issue": "point_rights_exceed_source"})

        source_governance = self.source_governance_report({"source_type": ""})
        source_gap_map = {row["source_id"]: row["gaps"] for row in source_governance["sources"]}
        used_source_gaps = [
            {"source_id": used_source_id, "gaps": source_gap_map.get(used_source_id, ["source_not_registered"])}
            for used_source_id in sorted(source_counts)
            if source_gap_map.get(used_source_id, ["source_not_registered"])
        ]

        date_gaps: list[dict[str, Any]] = []
        series_summary: list[dict[str, Any]] = []
        for (series_security_id, series_source_id, series_data_type), items in sorted(series.items()):
            valid_dates = sorted(parsed for item in items if (parsed := self._parse_quality_date(item.as_of_date)) is not None)
            for previous, current in zip(valid_dates, valid_dates[1:]):
                gap_days = (current - previous).days - 1
                if gap_days > max_gap_days:
                    date_gaps.append(
                        {
                            "security_id": series_security_id,
                            "source_id": series_source_id,
                            "data_type": series_data_type,
                            "previous_date": previous.isoformat(),
                            "current_date": current.isoformat(),
                            "gap_days": gap_days,
                        }
                    )
            series_summary.append(
                {
                    "security_id": series_security_id,
                    "source_id": series_source_id,
                    "data_type": series_data_type,
                    "count": len(items),
                    "start_date": min(valid_dates).isoformat() if valid_dates else "",
                    "end_date": max(valid_dates).isoformat() if valid_dates else "",
                }
            )

        issue_count = len(invalid_ohlc) + len(source_rights_gaps) + len(used_source_gaps) + len(date_gaps)
        return {
            "total_points": total,
            "sampled": sampled,
            "sample_points": len(points),
            "quality_score": round(max(0.0, 1.0 - issue_count / max(1, total)), 4) if total else 1.0,
            "source_counts": source_counts,
            "security_counts": security_counts,
            "series": series_summary,
            "invalid_ohlc": invalid_ohlc[:100],
            "source_rights_gaps": source_rights_gaps[:100],
            "source_governance_gaps": used_source_gaps[:100],
            "date_gaps": date_gaps[:100],
            "issue_count": issue_count,
        }

    def market_data_schema_coverage_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        source_format = str(filters.get("source_format", filters.get("adapter", "vipdoc"))).strip().lower()
        if source_format not in {"vipdoc", "day", "tdx_vipdoc", ""}:
            raise ValidationError("market data schema coverage report currently supports TDX vipdoc input")
        source_id = self._canonical_source_id(str(filters.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id == PUBLIC_EOD_MARKET_DATA_SOURCE_ID:
                self.seed_default_sources(actor="system")
            else:
                raise NotFoundError(f"source {source_id} not found")
        source = self.store.sources[source_id]
        schema_samples = filters.get("schema_samples")
        if schema_samples is not None and not isinstance(schema_samples, list):
            raise ValidationError("schema_samples must be a list when provided")
        report = self.tdx_market_data.schema_coverage_report(
            schema_samples=schema_samples,
            sample_limit=self._bounded_limit(filters.get("sample_limit", filters.get("limit", 50)), 500),
        )
        source_whitelist = set(source.field_whitelist)
        required_whitelist_fields = set(report["target_fields"])
        missing_whitelist_fields = sorted(required_whitelist_fields - source_whitelist)
        automation_blockers: list[str] = []
        source_gaps = self._source_governance_gaps(source)
        if report["schema_count"] == 0:
            automation_blockers.append("no_schema_samples")
        if report["schema_recognition_coverage"] < 1.0:
            automation_blockers.append("unrecognized_schema")
        if report["target_field_coverage"] < 1.0:
            automation_blockers.append("target_field_mapping_incomplete")
        if missing_whitelist_fields:
            automation_blockers.append("source_field_whitelist_missing_target_fields")
        if source.risk_level == "red":
            automation_blockers.append("red_source_manual_reference_only")
        if source_gaps:
            automation_blockers.append("source_governance_gaps")
        automation_ready = not automation_blockers
        return {
            **report,
            "source_id": source.source_id,
            "source_type": source.source_type,
            "risk_level": source.risk_level,
            "source_field_whitelist": sorted(source_whitelist),
            "missing_whitelist_fields": missing_whitelist_fields,
            "source_governance_gaps": source_gaps,
            "automation_ready": automation_ready,
            "automation_blockers": automation_blockers,
            "schema_anomaly_count": len(report["anomaly_samples"]),
            "usage_boundary": "schema_coverage_report_only_validates_public_eod_field_mapping_no_market_data_is_imported",
        }

    def tdx_market_data_preview(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        adapter = self._tdx_adapter(payload)
        rows = adapter.query_daily(
            symbols=self._tdx_symbols(payload),
            start_date=str(payload.get("start_date", "1900-01-01")),
            end_date=str(payload.get("end_date", "2099-12-31")),
            limit=self._bounded_limit(payload.get("limit", 100), 10000),
        )
        result = {
            "adapter": adapter.describe(),
            "rows": rows,
            "count": len(rows),
        }
        if bool(payload.get("include_summary", False)):
            result["summary"] = adapter.summary()
        return result

    def import_tdx_market_data(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id == PUBLIC_EOD_MARKET_DATA_SOURCE_ID:
                self.seed_default_sources(actor=actor)
            else:
                raise NotFoundError(f"source {source_id} not found")
        data_type = str(payload.get("data_type", "eod"))
        adapter = self._tdx_adapter(payload)
        rows = adapter.query_daily(
            symbols=self._tdx_symbols(payload),
            start_date=str(payload.get("start_date", "1900-01-01")),
            end_date=str(payload.get("end_date", "2099-12-31")),
            limit=self._bounded_limit(payload.get("limit", 100), 10000),
        )
        security_map = payload.get("security_map", {})
        if not isinstance(security_map, Mapping):
            raise ValidationError("security_map must be an object when provided")
        created: list[MarketDataPoint] = []
        skipped: list[dict[str, Any]] = []
        errors: list[dict[str, Any]] = []
        for index, row in enumerate(rows):
            symbol = str(row.get("symbol", "")).strip()
            trade_date = str(row.get("trade_date", "")).strip()
            security = self._resolve_tdx_security(symbol, security_map)
            if security is None:
                errors.append({"index": index, "symbol": symbol, "trade_date": trade_date, "error": "security mapping not found"})
                continue
            data_id = self._market_data_id(security.security_id, trade_date, data_type, source_id)
            if self._market_data_point_exists(security.security_id, source_id=source_id, data_type=data_type, as_of_date=trade_date) and bool(payload.get("skip_existing", True)):
                skipped.append({"index": index, "symbol": symbol, "trade_date": trade_date, "data_id": data_id})
                continue
            try:
                created.append(
                    self.register_market_data_point(
                        {
                            "data_id": data_id,
                            "security_id": security.security_id,
                            "source_id": source_id,
                            "market": security.market,
                            "as_of_date": trade_date,
                            "data_type": data_type,
                            "currency": security.currency,
                            "open": row.get("open", 0.0) or 0.0,
                            "high": row.get("high", 0.0) or 0.0,
                            "low": row.get("low", 0.0) or 0.0,
                            "close": row.get("close", 0.0) or 0.0,
                            "adjusted_close": row.get("close", 0.0) or 0.0,
                            "volume": row.get("volume", 0.0) or 0.0,
                            "amount": row.get("amount", 0.0) or 0.0,
                        },
                        actor=actor,
                    )
                )
            except (ValidationError, NotFoundError, PermissionDenied, ConflictError) as exc:
                errors.append({"index": index, "symbol": symbol, "trade_date": trade_date, "error": str(exc)})
        self._audit(
            actor,
            "import_tdx_market_data",
            "market_data",
            str(payload.get("batch_id", "tdx_import")),
            source="tdx",
            approval_state=f"created={len(created)};skipped={len(skipped)};failed={len(errors)}",
        )
        return {
            "adapter": adapter.describe(),
            "source_rows": len(rows),
            "created": [to_plain(item) for item in created],
            "skipped": skipped,
            "errors": errors,
            "created_count": len(created),
            "skipped_count": len(skipped),
            "failed_count": len(errors),
        }

    def market_data_backfill(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        self.seed_default_sources(actor=actor)
        dry_run = self._truthy(payload.get("dry_run", False))
        skip_existing = self._truthy(payload.get("skip_existing", True))
        refresh_existing = self._truthy(payload.get("refresh_existing", False))
        data_type = str(payload.get("data_type", "eod")).strip() or "eod"
        if data_type not in {"eod", "delayed"}:
            raise ValidationError("market data backfill only supports eod or delayed data")
        end_date = str(payload.get("end_date") or date.today().isoformat())
        self._validate_backfill_date(end_date, "end_date")
        fallback_window_days = max(1, min(3660, int(payload.get("fallback_window_days", 10) or 10)))
        requested_start_date = str(payload.get("start_date", "")).strip()
        if requested_start_date:
            self._validate_backfill_date(requested_start_date, "start_date")
        markets = self._market_data_backfill_markets(payload.get("market", "both"))
        batch_id = str(payload.get("batch_id") or f"market_data_backfill_{'_'.join(markets).lower()}_{end_date}").strip()
        result: dict[str, Any] = {
            "batch_id": batch_id,
            "started_at": utcnow().isoformat(),
            "completed_at": "",
            "market": payload.get("market", "both"),
            "markets": {},
            "data_type": data_type,
            "dry_run": dry_run,
            "skip_existing": skip_existing,
            "refresh_existing": refresh_existing,
            "requested_start_date": requested_start_date,
            "requested_end_date": end_date,
            "fallback_window_days": fallback_window_days,
            "created_count": 0,
            "skipped_count": 0,
            "planned_count": 0,
            "failed_symbol_count": 0,
            "empty_symbol_count": 0,
            "queried_symbol_count": 0,
            "symbol_count": 0,
            "failed_symbols": [],
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "public_or_candidate_eod_backfill_for_local_research_and_simulated_portfolio_only_no_live_trading",
        }
        for market in markets:
            market_summary = self._market_data_backfill_market(
                market,
                payload,
                actor=actor,
                dry_run=dry_run,
                skip_existing=skip_existing,
                refresh_existing=refresh_existing,
                data_type=data_type,
                requested_start_date=requested_start_date,
                end_date=end_date,
                fallback_window_days=fallback_window_days,
            )
            result["markets"][market] = market_summary
            for key in ("created_count", "skipped_count", "planned_count", "failed_symbol_count", "empty_symbol_count", "queried_symbol_count", "symbol_count"):
                result[key] += int(market_summary.get(key, 0) or 0)
            result["failed_symbols"].extend(market_summary.get("failed_symbols", []))
        result["status"] = "passed" if result["failed_symbol_count"] == 0 else "partial"
        result["completed_at"] = utcnow().isoformat()
        self._audit(
            actor,
            "market_data_backfill",
            "market_data",
            batch_id,
            source="market_data_backfill",
            approval_state=f"{result['status']};created={result['created_count']};failed={result['failed_symbol_count']}",
        )
        return result

    def market_data_backfill_coverage_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        self.seed_default_sources(actor="system")
        as_of_date = str(filters.get("as_of_date") or filters.get("end_date") or date.today().isoformat())
        self._validate_backfill_date(as_of_date, "as_of_date")
        markets = self._market_data_backfill_markets(filters.get("market", "both"))
        stale_after_days = max(0, int(filters.get("stale_after_days", 3) or 3))
        limit = max(1, min(10000, int(filters.get("limit", 100) or 100)))
        by_market: dict[str, Any] = {}
        for market in markets:
            source_id = self._market_data_source_for_market(market, filters)
            securities = [security for security in self.store.securities.values() if security.market == market and security.status == "active"]
            securities.sort(key=lambda item: (item.ticker.upper(), item.security_id))
            missing: list[dict[str, Any]] = []
            stale: list[dict[str, Any]] = []
            covered = 0
            latest_market_date = ""
            for security in securities:
                latest = self._latest_market_data_point(security.security_id, source_id=source_id, data_type=str(filters.get("data_type", "eod")), as_of_date=as_of_date)
                if latest is None:
                    if len(missing) < limit:
                        missing.append({"security_id": security.security_id, "ticker": security.ticker, "issue": "missing_market_data"})
                    continue
                covered += 1
                latest_market_date = max(latest_market_date, latest.as_of_date)
                lag_days = (date.fromisoformat(as_of_date) - date.fromisoformat(latest.as_of_date)).days
                if lag_days > stale_after_days and len(stale) < limit:
                    stale.append(
                        {
                            "security_id": security.security_id,
                            "ticker": security.ticker,
                            "latest_as_of_date": latest.as_of_date,
                            "lag_days": lag_days,
                        }
                    )
            source = self.store.sources.get(source_id)
            by_market[market] = {
                "market": market,
                "source_id": source_id,
                "security_count": len(securities),
                "covered_count": covered,
                "missing_count": len(securities) - covered,
                "stale_count": len(stale),
                "latest_market_date": latest_market_date,
                "coverage": round(covered / max(1, len(securities)), 4) if securities else 1.0,
                "missing_samples": missing,
                "stale_samples": stale,
                "source_governance_gaps": self._source_governance_gaps(source) if source else ["missing_source_definition"],
            }
        return {
            "as_of_date": as_of_date,
            "markets": by_market,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "market_data_backfill_coverage_report_only_no_market_data_imported",
        }

    def _market_data_backfill_market(
        self,
        market: str,
        payload: Mapping[str, Any],
        *,
        actor: str,
        dry_run: bool,
        skip_existing: bool,
        refresh_existing: bool,
        data_type: str,
        requested_start_date: str,
        end_date: str,
        fallback_window_days: int,
    ) -> dict[str, Any]:
        source_id = self._market_data_source_for_market(market, payload)
        symbols = self._market_data_backfill_symbols_for_market(market, payload)
        offset = max(0, int(payload.get("offset", 0) or 0))
        max_symbols = max(0, int(payload.get("max_symbols", payload.get("limit", 0)) or 0))
        total_discovered = len(symbols)
        if offset:
            symbols = symbols[offset:]
        if max_symbols:
            symbols = symbols[:max_symbols]
        summary: dict[str, Any] = {
            "market": market,
            "source_id": source_id,
            "total_discovered": total_discovered,
            "offset": offset,
            "max_symbols": max_symbols,
            "symbol_count": len(symbols),
            "queried_symbol_count": 0,
            "created_count": 0,
            "skipped_count": 0,
            "planned_count": 0,
            "empty_symbol_count": 0,
            "failed_symbol_count": 0,
            "failed_symbols": [],
            "symbol_results": [],
        }
        baostock_client: Any = None
        try:
            for item in symbols:
                symbol = str(item.get("symbol", "")).strip()
                if not symbol:
                    continue
                security = self._market_data_backfill_resolve_security(market, item, actor=actor, create=not dry_run)
                latest = self._latest_market_data_point(security.security_id, source_id=source_id, data_type=data_type, as_of_date=end_date)
                latest_before = latest.as_of_date if latest else ""
                start_date = requested_start_date or ((date.fromisoformat(latest_before) + timedelta(days=1)).isoformat() if latest_before else (date.fromisoformat(end_date) - timedelta(days=fallback_window_days)).isoformat())
                if start_date > end_date:
                    row = {"symbol": symbol, "security_id": security.security_id, "status": "skipped_current", "latest_before": latest_before, "start_date": start_date, "end_date": end_date}
                    summary["symbol_results"].append(row)
                    continue
                summary["queried_symbol_count"] += 1
                try:
                    if market == "A":
                        if baostock_client is None and self._truthy(payload.get("use_baostock", True)):
                            try:
                                baostock_client = self._open_baostock_session()
                            except Exception:
                                baostock_client = None
                        symbol_result = self._market_data_backfill_ashare_symbol(
                            symbol,
                            security,
                            source_id=source_id,
                            data_type=data_type,
                            start_date=start_date,
                            end_date=end_date,
                            dry_run=dry_run,
                            skip_existing=skip_existing,
                            refresh_existing=refresh_existing,
                            baostock_client=baostock_client,
                            adjustflag=str(payload.get("adjustflag", "3")),
                            actor=actor,
                        )
                    else:
                        symbol_result = self._market_data_backfill_us_symbol(
                            symbol,
                            security,
                            source_id=source_id,
                            data_type=data_type,
                            start_date=start_date,
                            end_date=end_date,
                            dry_run=dry_run,
                            skip_existing=skip_existing,
                            refresh_existing=refresh_existing,
                            user_agent=str(payload.get("user_agent") or DEFAULT_SEC_USER_AGENT),
                            timeout=float(payload.get("timeout", 30.0) or 30.0),
                            actor=actor,
                        )
                except Exception as exc:
                    symbol_result = {
                        "symbol": symbol,
                        "security_id": security.security_id,
                        "status": "failed",
                        "latest_before": latest_before,
                        "start_date": start_date,
                        "end_date": end_date,
                        "error_type": type(exc).__name__,
                        "error": str(exc),
                    }
                symbol_result.setdefault("latest_before", latest_before)
                if symbol_result.get("status") == "failed":
                    summary["failed_symbol_count"] += 1
                    summary["failed_symbols"].append({key: symbol_result.get(key, "") for key in ("symbol", "security_id", "error_type", "error")})
                if symbol_result.get("status") == "empty":
                    summary["empty_symbol_count"] += 1
                for key in ("created_count", "skipped_count", "planned_count"):
                    summary[key] += int(symbol_result.get(key, 0) or 0)
                summary["symbol_results"].append(symbol_result)
        finally:
            if baostock_client is not None:
                self._close_baostock_session(baostock_client)
        return summary

    def _market_data_backfill_ashare_symbol(
        self,
        symbol: str,
        security: Security,
        *,
        source_id: str,
        data_type: str,
        start_date: str,
        end_date: str,
        dry_run: bool,
        skip_existing: bool,
        refresh_existing: bool,
        baostock_client: Any,
        adjustflag: str,
        actor: str,
    ) -> dict[str, Any]:
        provider_errors: list[dict[str, str]] = []
        rows: list[dict[str, Any]] = []
        try:
            rows.extend(self.tdx_vipdoc.query_daily(symbols=[symbol], start_date=start_date, end_date=end_date, limit=10000))
        except Exception as exc:
            provider_errors.append({"provider": "tdx_vipdoc", "error_type": type(exc).__name__, "error": str(exc)})
        latest_row_date = max([str(row.get("trade_date") or row.get("as_of_date") or "") for row in rows] or [""])
        baostock_start = (date.fromisoformat(latest_row_date) + timedelta(days=1)).isoformat() if latest_row_date else start_date
        if baostock_client is not None and baostock_start <= end_date:
            try:
                rows.extend(self._fetch_ashare_baostock_rows(baostock_client, symbol, start_date=baostock_start, end_date=end_date, adjustflag=adjustflag))
            except Exception as exc:
                provider_errors.append({"provider": "baostock", "error_type": type(exc).__name__, "error": str(exc)})
        write = self._market_data_backfill_write_rows(
            security,
            rows,
            source_id=source_id,
            data_type=data_type,
            market="A",
            currency="CNY",
            dry_run=dry_run,
            skip_existing=skip_existing,
            refresh_existing=refresh_existing,
            actor=actor,
        )
        status = "planned" if dry_run and write["planned_count"] else "updated" if write["created_count"] else "empty"
        if not rows and provider_errors:
            status = "failed"
        return {
            "symbol": symbol,
            "security_id": security.security_id,
            "status": status,
            "start_date": start_date,
            "end_date": end_date,
            "source_rows": len(rows),
            "provider_errors": provider_errors,
            **write,
        }

    def _market_data_backfill_us_symbol(
        self,
        symbol: str,
        security: Security,
        *,
        source_id: str,
        data_type: str,
        start_date: str,
        end_date: str,
        dry_run: bool,
        skip_existing: bool,
        refresh_existing: bool,
        user_agent: str,
        timeout: float,
        actor: str,
    ) -> dict[str, Any]:
        rows = self._fetch_us_yahoo_rows(symbol, start_date=start_date, end_date=end_date, user_agent=user_agent, timeout=timeout)
        write = self._market_data_backfill_write_rows(
            security,
            rows,
            source_id=source_id,
            data_type=data_type,
            market="U",
            currency="USD",
            dry_run=dry_run,
            skip_existing=skip_existing,
            refresh_existing=refresh_existing,
            actor=actor,
        )
        status = "planned" if dry_run and write["planned_count"] else "updated" if write["created_count"] else "empty"
        return {
            "symbol": symbol,
            "security_id": security.security_id,
            "status": status,
            "start_date": start_date,
            "end_date": end_date,
            "source_rows": len(rows),
            **write,
        }

    def _market_data_backfill_write_rows(
        self,
        security: Security,
        rows: list[Mapping[str, Any]],
        *,
        source_id: str,
        data_type: str,
        market: str,
        currency: str,
        dry_run: bool,
        skip_existing: bool,
        refresh_existing: bool,
        actor: str,
    ) -> dict[str, Any]:
        created = 0
        skipped = 0
        planned = 0
        latest_after = ""
        source = self.store.sources[source_id]
        for raw_row in rows:
            as_of_date = str(raw_row.get("as_of_date") or raw_row.get("trade_date") or "").strip()
            if not as_of_date:
                continue
            close = float(raw_row.get("close", 0.0) or 0.0)
            if close <= 0:
                continue
            latest_after = max(latest_after, as_of_date)
            data_id = self._market_data_id(security.security_id, as_of_date, data_type, source_id)
            exists = self._market_data_point_exists(security.security_id, source_id=source_id, data_type=data_type, as_of_date=as_of_date)
            if exists and skip_existing and not refresh_existing:
                skipped += 1
                continue
            payload = {
                "data_id": data_id,
                "security_id": security.security_id,
                "source_id": source_id,
                "market": market,
                "as_of_date": as_of_date,
                "data_type": data_type,
                "currency": currency,
                "open": float(raw_row.get("open", 0.0) or 0.0),
                "high": float(raw_row.get("high", 0.0) or 0.0),
                "low": float(raw_row.get("low", 0.0) or 0.0),
                "close": close,
                "adjusted_close": float(raw_row.get("adjusted_close", raw_row.get("close", 0.0)) or close),
                "volume": float(raw_row.get("volume", 0.0) or 0.0),
                "amount": float(raw_row.get("amount", 0.0) or 0.0),
                "rights_tag": to_plain(source.rights_tag),
            }
            if dry_run:
                planned += 1
                continue
            if exists and refresh_existing:
                self._validate_market_data_field_boundary(payload, source)
                point = MarketDataPoint.from_dict(payload)
                self.store.market_data[point.data_id] = point
                created += 1
                continue
            try:
                self.register_market_data_point(payload, actor=actor)
                created += 1
            except ConflictError:
                if refresh_existing:
                    point = MarketDataPoint.from_dict(payload)
                    self.store.market_data[point.data_id] = point
                    created += 1
                else:
                    skipped += 1
        return {"created_count": created, "skipped_count": skipped, "planned_count": planned, "latest_after": latest_after}

    def _market_data_backfill_symbols_for_market(self, market: str, payload: Mapping[str, Any]) -> list[dict[str, Any]]:
        requested = self._market_data_backfill_symbol_values(payload.get("symbols", payload.get("symbol", "")))
        if requested:
            rows: list[dict[str, Any]] = []
            for raw_symbol in requested:
                if market == "A":
                    symbol = self._normalize_tdx_symbol(raw_symbol)
                    if len(symbol) == 6:
                        rows.append({"symbol": symbol, "name": symbol, "market": "A", "source": "payload"})
                else:
                    symbol = self._normalize_us_backfill_symbol(raw_symbol)
                    if symbol and not symbol.isdigit():
                        rows.append({"symbol": symbol, "name": symbol, "market": "U", "source": "payload"})
            return self._dedupe_backfill_symbols(rows)
        discover = self._truthy(payload.get("discover_universe", True))
        if discover:
            return self._discover_ashare_backfill_universe(payload) if market == "A" else self._discover_us_backfill_universe(payload)
        return self._registered_market_backfill_symbols(market)

    def _discover_ashare_backfill_universe(self, payload: Mapping[str, Any]) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        discovery_limit = max(1, min(100000, int(payload.get("discovery_limit", 50000) or 50000)))
        try:
            for symbol in self.tdx_vipdoc.symbols(prefix=str(payload.get("symbol_prefix", "")), limit=discovery_limit):
                if len(symbol) == 6:
                    rows.append({"symbol": symbol, "name": symbol, "market": "A", "source": "tdx_vipdoc"})
        except Exception:
            pass
        if self._truthy(payload.get("discover_baostock", True)):
            client = None
            try:
                client = self._open_baostock_session()
                rows.extend(
                    self._discover_ashare_baostock_symbols(
                        client,
                        symbol_prefix=str(payload.get("symbol_prefix", "")),
                        include_b_shares=self._truthy(payload.get("include_b_shares", False)),
                    )
                )
            except Exception:
                if not rows:
                    rows.extend(self._registered_market_backfill_symbols("A"))
            finally:
                if client is not None:
                    self._close_baostock_session(client)
        if not rows:
            rows.extend(self._registered_market_backfill_symbols("A"))
        return self._dedupe_backfill_symbols(rows)

    def _discover_us_backfill_universe(self, payload: Mapping[str, Any]) -> list[dict[str, Any]]:
        try:
            return self._dedupe_backfill_symbols(self._fetch_us_symbol_directory(include_etf=self._truthy(payload.get("include_etf", False))))
        except Exception:
            return self._registered_market_backfill_symbols("U")

    def _registered_market_backfill_symbols(self, market: str) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for security in self.store.securities.values():
            if security.market != market or security.status != "active":
                continue
            symbol = self._normalize_tdx_symbol(security.ticker) if market == "A" else self._normalize_us_backfill_symbol(security.ticker)
            if not symbol:
                continue
            rows.append(
                {
                    "symbol": symbol,
                    "name": security.ticker,
                    "market": market,
                    "security_id": security.security_id,
                    "issuer_id": security.issuer_id,
                    "exchange": security.exchange,
                    "source": "registered_security",
                }
            )
        return self._dedupe_backfill_symbols(rows)

    def _market_data_backfill_resolve_security(self, market: str, item: Mapping[str, Any], *, actor: str, create: bool) -> Security:
        symbol = str(item.get("symbol", "")).strip()
        normalized = self._normalize_tdx_symbol(symbol) if market == "A" else self._normalize_us_backfill_symbol(symbol)
        explicit_security_id = str(item.get("security_id", "")).strip()
        if explicit_security_id and explicit_security_id in self.store.securities and self.store.securities[explicit_security_id].market == market:
            return self.store.securities[explicit_security_id]
        for security in self.store.securities.values():
            if security.market != market:
                continue
            ticker = self._normalize_tdx_symbol(security.ticker) if market == "A" else self._normalize_us_backfill_symbol(security.ticker)
            if ticker == normalized:
                return security
        if market == "A":
            issuer_id = str(item.get("issuer_id") or f"issuer_{normalized}")
            security_id = explicit_security_id or f"sec_{normalized}"
            exchange = str(item.get("exchange") or self._tdx_exchange_from_symbol(normalized))
            currency = "CNY"
            country = "CN"
        else:
            safe = self._safe_identifier(normalized.lower()).lower()
            issuer_id = str(item.get("issuer_id") or f"issuer_{safe}")
            security_id = explicit_security_id or f"security_{safe}_us"
            exchange = str(item.get("exchange") or "US")
            currency = "USD"
            country = "US"
        if not create:
            return Security(security_id=security_id, issuer_id=issuer_id, ticker=normalized, exchange=exchange, currency=currency, market=market, status="active")
        if issuer_id not in self.store.issuers:
            self.register_issuer(
                {
                    "issuer_id": issuer_id,
                    "legal_name": str(item.get("name") or normalized),
                    "aliases": [normalized],
                    "market": [market],
                    "country": country,
                    "status": "active",
                },
                actor=actor,
            )
        if security_id not in self.store.securities:
            self.register_security(
                {
                    "security_id": security_id,
                    "issuer_id": issuer_id,
                    "ticker": normalized,
                    "exchange": exchange,
                    "currency": currency,
                    "market": market,
                    "status": "active",
                    "security_type": str(item.get("security_type") or ("common_stock" if market == "A" else "listed_company")),
                },
                actor=actor,
            )
        return self.store.securities[security_id]

    def _fetch_us_yahoo_rows(self, ticker: str, *, start_date: str, end_date: str, user_agent: str, timeout: float) -> list[dict[str, Any]]:
        start_ts = int(datetime.combine(date.fromisoformat(start_date), datetime.min.time(), tzinfo=timezone.utc).timestamp())
        end_ts = int(datetime.combine(date.fromisoformat(end_date), datetime.min.time(), tzinfo=timezone.utc).timestamp()) + 86400
        params = {
            "period1": start_ts,
            "period2": end_ts,
            "interval": "1d",
            "events": "history",
            "includeAdjustedClose": "true",
        }
        errors: list[str] = []
        saw_empty_payload = False
        for yahoo_symbol in self._yahoo_chart_symbol_candidates(ticker):
            url = f"https://query1.finance.yahoo.com/v8/finance/chart/{yahoo_symbol}?{urlencode(params)}"
            request = Request(url, headers={"User-Agent": user_agent, "Accept": "application/json"})
            try:
                with urlopen(request, timeout=timeout) as response:
                    payload = json.loads(response.read().decode("utf-8"))
            except (HTTPError, URLError, TimeoutError) as exc:
                errors.append(f"{type(exc).__name__}: {exc}")
                continue
            error = payload.get("chart", {}).get("error")
            if error:
                errors.append(str(error))
                continue
            result = (payload.get("chart", {}).get("result") or [None])[0]
            if not result:
                saw_empty_payload = True
                continue
            timestamps = result.get("timestamp") or []
            if not timestamps:
                saw_empty_payload = True
                continue
            quote = ((result.get("indicators") or {}).get("quote") or [{}])[0]
            adjclose = ((result.get("indicators") or {}).get("adjclose") or [{}])[0].get("adjclose") or []
            rows: list[dict[str, Any]] = []
            for index, timestamp in enumerate(timestamps):
                close = (quote.get("close") or [None] * len(timestamps))[index]
                if close is None:
                    continue
                rows.append(
                    {
                        "as_of_date": datetime.fromtimestamp(int(timestamp), tz=timezone.utc).date().isoformat(),
                        "open": float((quote.get("open") or [0.0] * len(timestamps))[index] or 0.0),
                        "high": float((quote.get("high") or [0.0] * len(timestamps))[index] or 0.0),
                        "low": float((quote.get("low") or [0.0] * len(timestamps))[index] or 0.0),
                        "close": float(close),
                        "adjusted_close": float((adjclose or [close] * len(timestamps))[index] or close),
                        "volume": float((quote.get("volume") or [0.0] * len(timestamps))[index] or 0.0),
                    }
                )
            if rows:
                return rows
            saw_empty_payload = True
        if saw_empty_payload:
            return []
        raise RuntimeError("; ".join(errors) or "Yahoo chart returned no usable response")

    def _yahoo_chart_symbol_candidates(self, ticker: str) -> list[str]:
        raw = str(ticker or "").strip().upper().replace("/", "-")
        candidates = [raw]
        if "." in raw:
            candidates.append(raw.replace(".", "-"))
        if "$" in raw:
            candidates.append(raw.replace("$", "-P"))
            candidates.append(raw.replace("$", "-"))
        if raw.endswith("$"):
            candidates.append(raw.rstrip("$"))
        return [item for item in dict.fromkeys(candidates) if item]

    def _fetch_us_symbol_directory(self, *, include_etf: bool = False) -> list[dict[str, Any]]:
        urls = [
            ("https://www.nasdaqtrader.com/dynamic/SymDir/nasdaqlisted.txt", "NASDAQ"),
            ("https://www.nasdaqtrader.com/dynamic/SymDir/otherlisted.txt", "OTHER"),
        ]
        rows: list[dict[str, Any]] = []
        seen: set[str] = set()
        for url, fallback_exchange in urls:
            text = self._fetch_text_url(url, user_agent=DEFAULT_SEC_USER_AGENT, timeout=30.0)
            lines = [line for line in text.splitlines() if line and not line.startswith("File Creation Time")]
            reader = csv.DictReader(lines, delimiter="|")
            for item in reader:
                raw_symbol = str(item.get("Symbol") or item.get("ACT Symbol") or item.get("NASDAQ Symbol") or "").strip()
                symbol = self._normalize_us_backfill_symbol(raw_symbol)
                if not symbol or symbol in seen:
                    continue
                if str(item.get("Test Issue") or "").upper() == "Y":
                    continue
                is_etf = str(item.get("ETF") or "").upper() == "Y"
                name = str(item.get("Security Name") or item.get("Company Name") or symbol).strip()
                if (is_etf and not include_etf) or self._is_us_non_company_security(symbol, name):
                    continue
                rows.append(
                    {
                        "symbol": symbol,
                        "name": name or symbol,
                        "market": "U",
                        "exchange": str(item.get("Exchange") or fallback_exchange or "US").strip() or "US",
                        "source": "nasdaq_trader_symbol_directory",
                        "security_type": "etf" if is_etf else "listed_company",
                    }
                )
                seen.add(symbol)
        return rows

    def _open_baostock_session(self) -> Any:
        import baostock as bs  # type: ignore[import-not-found]

        login = bs.login()
        if login.error_code != "0":
            raise RuntimeError(f"baostock login failed: {login.error_code} {login.error_msg}")
        return bs

    def _close_baostock_session(self, client: Any) -> None:
        try:
            client.logout()
        except Exception:
            return

    def _discover_ashare_baostock_symbols(self, client: Any, *, symbol_prefix: str = "", include_b_shares: bool = False) -> list[dict[str, Any]]:
        result = client.query_stock_basic()
        if result.error_code != "0":
            raise RuntimeError(f"baostock query_stock_basic failed: {result.error_code} {result.error_msg}")
        fields = list(getattr(result, "fields", []) or ["code", "code_name", "ipoDate", "outDate", "type", "status"])
        rows: list[dict[str, Any]] = []
        while result.next():
            item = dict(zip(fields, result.get_row_data()))
            symbol = self._normalize_tdx_symbol(str(item.get("code") or ""))
            name = str(item.get("code_name") or symbol)
            stock_type = str(item.get("type") or "")
            status = str(item.get("status") or "")
            if symbol_prefix and not symbol.startswith(self._normalize_tdx_symbol(symbol_prefix)):
                continue
            if len(symbol) != 6 or stock_type != "1" or status != "1":
                continue
            if not include_b_shares and symbol.startswith(("200", "900")):
                continue
            rows.append({"symbol": symbol, "name": name, "market": "A", "exchange": self._tdx_exchange_from_symbol(symbol), "source": "baostock_stock_basic"})
        return rows

    def _fetch_ashare_baostock_rows(self, client: Any, symbol: str, *, start_date: str, end_date: str, adjustflag: str) -> list[dict[str, Any]]:
        code = self._baostock_code(symbol)
        fields = "date,code,open,high,low,close,volume,amount"
        result = client.query_history_k_data_plus(code, fields, start_date=start_date, end_date=end_date, frequency="d", adjustflag=adjustflag)
        if result.error_code != "0":
            raise RuntimeError(f"baostock query_history_k_data_plus failed: {result.error_code} {result.error_msg}")
        rows: list[dict[str, Any]] = []
        columns = fields.split(",")
        while result.next():
            item = dict(zip(columns, result.get_row_data()))
            close = float(item.get("close") or 0.0)
            if close <= 0:
                continue
            rows.append(
                {
                    "as_of_date": str(item.get("date") or ""),
                    "open": float(item.get("open") or 0.0),
                    "high": float(item.get("high") or 0.0),
                    "low": float(item.get("low") or 0.0),
                    "close": close,
                    "adjusted_close": close,
                    "volume": float(item.get("volume") or 0.0),
                    "amount": float(item.get("amount") or 0.0),
                }
            )
        return rows

    def _market_data_source_for_market(self, market: str, payload: Mapping[str, Any]) -> str:
        if market == "U":
            return self._canonical_source_id(str(payload.get("us_source_id", payload.get("source_id", "yahoo_chart_us_eod"))))
        return self._canonical_source_id(str(payload.get("ashare_source_id", payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID))))

    def _market_data_backfill_markets(self, value: Any) -> list[str]:
        if isinstance(value, str):
            raw = [item.strip().upper() for item in re.split(r"[,\s]+", value) if item.strip()]
        elif isinstance(value, (list, tuple, set)):
            raw = [str(item).strip().upper() for item in value if str(item).strip()]
        else:
            raw = ["BOTH"]
        if not raw or "BOTH" in raw:
            return ["A", "U"]
        markets = [item for item in raw if item in {"A", "U"}]
        if not markets:
            raise ValidationError("market data backfill market must be A, U, or both")
        return list(dict.fromkeys(markets))

    def _market_data_backfill_symbol_values(self, value: Any) -> list[str]:
        if isinstance(value, str):
            return [item.strip() for item in re.split(r"[,\s]+", value) if item.strip()]
        if isinstance(value, (list, tuple, set)):
            return [str(item).strip() for item in value if str(item).strip()]
        return []

    def _dedupe_backfill_symbols(self, rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        deduped: list[dict[str, Any]] = []
        seen: set[str] = set()
        for row in rows:
            symbol = str(row.get("symbol", "")).strip().upper()
            market = str(row.get("market", "")).strip().upper()
            key = f"{market}:{symbol}"
            if not symbol or key in seen:
                continue
            seen.add(key)
            deduped.append({**row, "symbol": symbol if market == "U" else self._normalize_tdx_symbol(symbol), "market": market})
        return deduped

    def _normalize_us_backfill_symbol(self, value: Any) -> str:
        return re.sub(r"[^A-Za-z0-9.-]+", "", str(value or "").strip().upper())

    def _validate_backfill_date(self, value: str, field_name: str) -> None:
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(value)):
            raise ValidationError(f"{field_name} must use YYYY-MM-DD")
        date.fromisoformat(str(value))

    def _market_data_point_exists(self, security_id: str, *, source_id: str, data_type: str, as_of_date: str) -> bool:
        if self._market_data_direct_query_enabled():
            return bool(
                self._query_market_data_points(
                    security_id=security_id,
                    source_id=source_id,
                    data_type=data_type,
                    start_date=as_of_date,
                    end_date=as_of_date,
                    limit=1,
                    descending=True,
                )
            )
        return any(
            point.security_id == security_id and point.source_id == source_id and point.data_type == data_type and point.as_of_date == as_of_date
            for point in self.store.market_data.values()
        )

    def _fetch_text_url(self, url: str, *, user_agent: str, timeout: float) -> str:
        request = Request(url, headers={"User-Agent": user_agent, "Accept": "text/plain,*/*"})
        with urlopen(request, timeout=timeout) as response:
            return response.read().decode("utf-8", errors="replace")

    def _is_us_non_company_security(self, symbol: str, name: str) -> bool:
        lowered = f"{symbol} {name}".lower()
        blocked = [" warrant", " right", " unit", " notes due", " preferred stock", "depositary shares", " fund", " etf", " etn"]
        return any(term in lowered for term in blocked)

    def _baostock_code(self, symbol: str) -> str:
        clean = self._normalize_tdx_symbol(symbol)
        if clean.startswith(("5", "6", "9")):
            return f"sh.{clean}"
        if clean.startswith(("4", "8")):
            return f"bj.{clean}"
        return f"sz.{clean}"

    def _tdx_exchange_from_symbol(self, symbol: str) -> str:
        clean = self._normalize_tdx_symbol(symbol)
        if clean.startswith(("5", "6", "9")):
            return "SSE"
        if clean.startswith(("4", "8")):
            return "BSE"
        return "SZSE"

    def register_entity_mapping(self, payload: Mapping[str, Any], *, actor: str = "system") -> EntityMapping:
        issuer_id = str(payload["issuer_id"])
        if issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {issuer_id} not found")
        mapping_id = str(payload.get("mapping_id", new_id("map")))
        if mapping_id in self.store.entity_mappings:
            raise ConflictError(f"entity mapping {mapping_id} already exists")
        valid_from = parse_datetime(payload.get("valid_from")) if payload.get("valid_from") else utcnow()
        valid_to = parse_datetime(payload.get("valid_to")) if payload.get("valid_to") else None
        recorded_at = parse_datetime(payload.get("recorded_at")) if payload.get("recorded_at") else utcnow()
        if valid_to is not None and valid_to <= valid_from:
            raise ValidationError("entity mapping valid_to must be after valid_from")
        supersedes_mapping_id = str(payload.get("supersedes_mapping_id", "")).strip()
        if supersedes_mapping_id:
            previous = self.store.entity_mappings.get(supersedes_mapping_id)
            if previous is None:
                raise NotFoundError(f"entity mapping {supersedes_mapping_id} not found")
            if previous.issuer_id != issuer_id:
                raise ValidationError("superseded mapping must belong to the same issuer")
            if previous.valid_to is None or parse_datetime(previous.valid_to) > valid_from:
                previous.valid_to = valid_from
                previous.status = "superseded"
        mapping = EntityMapping(
            mapping_id=mapping_id,
            issuer_id=issuer_id,
            lei=str(payload.get("lei", "")),
            cik=str(payload.get("cik", "")),
            figi=str(payload.get("figi", "")),
            isin=str(payload.get("isin", "")),
            ticker=str(payload.get("ticker", "")),
            market=str(payload.get("market", "")),
            confidence=float(payload.get("confidence", self._entity_mapping_confidence(payload))),
            source=str(payload.get("source", "entity_mapping_registry")),
            version=str(payload.get("version", "v1")),
            valid_from=valid_from,
            valid_to=valid_to,
            recorded_at=recorded_at,
            supersedes_mapping_id=supersedes_mapping_id,
            status=str(payload.get("status", "active")),
        )
        self.store.entity_mappings[mapping.mapping_id] = mapping
        self._audit(actor, "register_entity_mapping", "mapping", mapping.mapping_id)
        return mapping

    def entity_mappings_payload(self, payload: Mapping[str, Any] | None = None) -> dict[str, Any]:
        payload = payload or {}
        issuer_id = str(payload.get("issuer_id", "")).strip()
        ticker = str(payload.get("ticker", "")).strip().upper()
        market = str(payload.get("market", "")).strip()
        status = str(payload.get("status", "")).strip()
        valid_at = parse_datetime(payload.get("valid_at")) if payload.get("valid_at") else None
        recorded_at = parse_datetime(payload.get("recorded_at")) if payload.get("recorded_at") else None
        limit = self._bounded_limit(payload.get("limit", 100), 1000)
        mappings = self._filter_entity_mappings(
            self.store.entity_mappings.values(),
            issuer_id=issuer_id,
            ticker=ticker,
            market=market,
            status=status,
            valid_at=valid_at,
            recorded_at=recorded_at,
        )
        mappings.sort(key=lambda item: (parse_datetime(item.recorded_at), parse_datetime(item.valid_from), item.mapping_id), reverse=True)
        return {
            "total": len(mappings),
            "valid_at": to_plain(valid_at) if valid_at else "",
            "recorded_at": to_plain(recorded_at) if recorded_at else "",
            "mappings": [to_plain(item) for item in mappings[:limit]],
        }

    def register_entity_mapping_batch(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        items = payload.get("items", [])
        if not isinstance(items, list):
            raise ValidationError("entity mapping batch requires items list")
        created: list[EntityMapping] = []
        errors: list[dict[str, Any]] = []
        for index, item in enumerate(items):
            if not isinstance(item, Mapping):
                errors.append({"index": index, "error": "item must be an object"})
                continue
            try:
                created.append(self.register_entity_mapping(item, actor=actor))
            except (ValidationError, NotFoundError, ConflictError) as exc:
                errors.append({"index": index, "error": str(exc)})
        self._audit(actor, "register_entity_mapping_batch", "mapping", str(payload.get("batch_id", "batch")), approval_state=f"created={len(created)};failed={len(errors)}")
        return {"created": [to_plain(item) for item in created], "errors": errors, "created_count": len(created), "failed_count": len(errors)}

    def record_entity_mapping_label(self, payload: Mapping[str, Any], *, actor: str = "system") -> EntityMappingLabel:
        mapping_id = str(payload["mapping_id"])
        mapping = self.store.entity_mappings.get(mapping_id)
        if mapping is None:
            raise NotFoundError(f"entity mapping {mapping_id} not found")
        label_id = str(payload.get("label_id", f"emlbl_{self._safe_identifier(mapping_id)}"))
        if label_id in self.store.entity_mapping_labels:
            raise ConflictError(f"entity mapping label {label_id} already exists")
        label = EntityMappingLabel(
            label_id=label_id,
            mapping_id=mapping_id,
            issuer_id=str(payload.get("issuer_id", mapping.issuer_id)),
            ticker=str(payload.get("ticker", mapping.ticker)),
            market=str(payload.get("market", mapping.market)),
            reviewer=str(payload.get("reviewer", actor)),
            source=str(payload.get("source", "manual_gold_label")),
            notes=str(payload.get("notes", "")),
        )
        self.store.entity_mapping_labels[label.label_id] = label
        self._audit(actor, "record_entity_mapping_label", "mapping_label", label.label_id, approval_state="labeled")
        return label

    def record_entity_mapping_label_batch(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        items = payload.get("items", [])
        if not isinstance(items, list):
            raise ValidationError("entity mapping label batch requires items list")
        created: list[EntityMappingLabel] = []
        errors: list[dict[str, Any]] = []
        for index, item in enumerate(items):
            if not isinstance(item, Mapping):
                errors.append({"index": index, "error": "item must be an object"})
                continue
            try:
                created.append(self.record_entity_mapping_label(item, actor=actor))
            except (ValidationError, NotFoundError, ConflictError) as exc:
                errors.append({"index": index, "error": str(exc)})
        self._audit(actor, "record_entity_mapping_label_batch", "mapping_label", str(payload.get("batch_id", "batch")), approval_state=f"created={len(created)};failed={len(errors)}")
        return {"created": [to_plain(item) for item in created], "errors": errors, "created_count": len(created), "failed_count": len(errors)}

    def entity_mapping_labels_payload(self, payload: Mapping[str, Any] | None = None) -> dict[str, Any]:
        payload = payload or {}
        mapping_id = str(payload.get("mapping_id", "")).strip()
        issuer_id = str(payload.get("issuer_id", "")).strip()
        limit = self._bounded_limit(payload.get("limit", 100), 1000)
        labels = list(self.store.entity_mapping_labels.values())
        if mapping_id:
            labels = [item for item in labels if item.mapping_id == mapping_id]
        if issuer_id:
            labels = [item for item in labels if item.issuer_id == issuer_id]
        labels.sort(key=lambda item: (item.created_at, item.label_id), reverse=True)
        return {"total": len(labels), "labels": [to_plain(item) for item in labels[:limit]]}

    def entity_mapping_quality_report(self, payload: Mapping[str, Any] | None = None) -> dict[str, Any]:
        payload = payload or {}
        issuer_id = str(payload.get("issuer_id", "")).strip()
        valid_at = parse_datetime(payload.get("valid_at")) if payload.get("valid_at") else None
        recorded_at = parse_datetime(payload.get("recorded_at")) if payload.get("recorded_at") else None
        mappings = self._filter_entity_mappings(
            self.store.entity_mappings.values(),
            issuer_id=issuer_id,
            valid_at=valid_at,
            recorded_at=recorded_at,
        )
        labels = payload.get("labels")
        if labels is None:
            stored_labels = list(self.store.entity_mapping_labels.values())
            if issuer_id:
                stored_labels = [item for item in stored_labels if item.issuer_id == issuer_id]
            labels = [to_plain(item) for item in stored_labels]
        checked = 0
        correct = 0
        mismatches: list[dict[str, Any]] = []
        if isinstance(labels, list):
            mapping_by_id = {item.mapping_id: item for item in mappings}
            for label in labels:
                if not isinstance(label, Mapping):
                    continue
                mapping = mapping_by_id.get(str(label.get("mapping_id", "")))
                if mapping is None:
                    mismatches.append({"mapping_id": str(label.get("mapping_id", "")), "reason": "missing_mapping"})
                    checked += 1
                    continue
                expected = {
                    "issuer_id": str(label.get("issuer_id", mapping.issuer_id)),
                    "market": str(label.get("market", mapping.market)),
                    "ticker": str(label.get("ticker", mapping.ticker)),
                }
                actual = {"issuer_id": mapping.issuer_id, "market": mapping.market, "ticker": mapping.ticker}
                checked += 1
                if actual == expected:
                    correct += 1
                else:
                    mismatches.append({"mapping_id": mapping.mapping_id, "expected": expected, "actual": actual})
        covered_issuers = {item.issuer_id for item in mappings}
        market_counts: dict[str, int] = {}
        status_counts: dict[str, int] = {}
        for mapping in mappings:
            market_counts[mapping.market] = market_counts.get(mapping.market, 0) + 1
            status_counts[mapping.status] = status_counts.get(mapping.status, 0) + 1
        low_confidence_threshold = float(payload.get("low_confidence_threshold", 0.8))
        low_confidence = [
            {
                "mapping_id": mapping.mapping_id,
                "issuer_id": mapping.issuer_id,
                "ticker": mapping.ticker,
                "market": mapping.market,
                "confidence": round(float(mapping.confidence), 4),
                "source": mapping.source,
                "version": mapping.version,
                "valid_from": to_plain(mapping.valid_from),
                "valid_to": to_plain(mapping.valid_to),
                "recorded_at": to_plain(mapping.recorded_at),
            }
            for mapping in mappings
            if float(mapping.confidence) < low_confidence_threshold
        ]
        versioned = [item for item in mappings if item.version and item.valid_from and item.recorded_at]
        open_ended = [item for item in mappings if item.valid_to is None and item.status == "active"]
        temporal_overlaps = self._entity_mapping_temporal_overlaps(mappings)
        average_confidence = sum(float(mapping.confidence) for mapping in mappings) / len(mappings) if mappings else 1.0
        return {
            "issuer_id": issuer_id,
            "valid_at": to_plain(valid_at) if valid_at else "",
            "recorded_at": to_plain(recorded_at) if recorded_at else "",
            "mappings": len(mappings),
            "covered_issuers": len(covered_issuers),
            "market_counts": market_counts,
            "status_counts": status_counts,
            "checked_labels": checked,
            "accuracy": round(correct / max(1, checked), 4) if checked else 0.0,
            "average_confidence": round(average_confidence, 4),
            "bitemporal_version_coverage": round(len(versioned) / max(1, len(mappings)), 4) if mappings else 1.0,
            "active_open_ended_count": len(open_ended),
            "temporal_overlap_count": len(temporal_overlaps),
            "temporal_overlaps": temporal_overlaps[: self._bounded_limit(payload.get("limit", 100), 1000)],
            "low_confidence_threshold": low_confidence_threshold,
            "low_confidence_count": len(low_confidence),
            "low_confidence_mappings": low_confidence[: self._bounded_limit(payload.get("limit", 100), 1000)],
            "mismatches": mismatches,
        }

    def entity_mapping_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        issuer_id = str(payload.get("issuer_id", "")).strip()
        valid_at = parse_datetime(payload.get("valid_at")) if payload.get("valid_at") else None
        recorded_at = parse_datetime(payload.get("recorded_at")) if payload.get("recorded_at") else None
        quality_payload: dict[str, Any] = {
            "issuer_id": issuer_id,
            "low_confidence_threshold": payload.get("low_confidence_threshold", 0.8),
            "limit": payload.get("limit", 1000),
        }
        if valid_at is not None:
            quality_payload["valid_at"] = to_plain(valid_at)
        if recorded_at is not None:
            quality_payload["recorded_at"] = to_plain(recorded_at)
        if "labels" in payload:
            quality_payload["labels"] = payload.get("labels")
        quality = self.entity_mapping_quality_report(quality_payload)
        mappings = self._filter_entity_mappings(
            self.store.entity_mappings.values(),
            issuer_id=issuer_id,
            valid_at=valid_at,
            recorded_at=recorded_at,
        )
        market_summary = self._entity_mapping_market_readiness_summary(mappings, payload)
        label_summary = self._entity_mapping_label_market_summary(payload, issuer_id, market_summary["required_markets"])
        metadata_summary = self._entity_mapping_metadata_summary(mappings)
        graph_filters = {"issuer_id": issuer_id, "include_details": False, "limit": payload.get("graph_limit", 1000)}
        traceability = self.graph_traceability_report(graph_filters)
        edge_quality = self._entity_mapping_edge_quality_summary(payload, mappings)
        graph_export = self._entity_mapping_graph_export_summary(payload, mappings, actor=actor)
        vector_filters: dict[str, Any] = {
            "issuer_id": issuer_id,
            "include_restricted": payload.get("include_restricted", False),
        }
        resource_types = payload.get("vector_resource_types", payload.get("resource_types", []))
        if isinstance(resource_types, list):
            vector_filters["resource_types"] = resource_types
        if payload.get("collection"):
            vector_filters["collection"] = payload.get("collection")
        qdrant_export = self.qdrant_vector_export(vector_filters, actor=actor)
        adapters = self._graph_vector_adapter_config(payload)
        artifacts = self._entity_mapping_readiness_artifact_uris(payload)
        min_accuracy = float(payload.get("min_accuracy", 0.98))
        min_traceability = float(payload.get("min_traceability_rate", 0.95))
        min_traceable_resources = int(payload.get("min_traceable_resource_count", 1))
        min_edge_coverage = float(payload.get("min_edge_metadata_coverage", 1.0))
        min_mapping_count = int(payload.get("min_mapping_count", max(1, len(market_summary["required_markets"]))))
        min_label_count = int(payload.get("min_label_count", max(1, len(market_summary["required_markets"]))))
        min_graph_nodes = int(payload.get("min_graph_node_count", 1))
        min_vector_points = int(payload.get("min_vector_point_count", 1))
        gates = [
            self._readiness_numeric_gate("entity_mapping_count", float(quality["mappings"]), float(min_mapping_count), ">=", "registered EntityMapping records after requested bitemporal filters"),
            self._readiness_numeric_gate("required_market_coverage", market_summary["coverage"], float(payload.get("min_market_coverage", 1.0)), ">=", "A/H/U or configured required market coverage"),
            self._readiness_numeric_gate("checked_gold_label_count", float(quality["checked_labels"]), float(min_label_count), ">=", "manual gold labels available for mapping accuracy"),
            self._readiness_numeric_gate("gold_label_market_coverage", label_summary["coverage"], float(payload.get("min_label_market_coverage", 1.0)), ">=", "gold labels cover required A/H/U markets"),
            self._readiness_numeric_gate("entity_mapping_accuracy", float(quality["accuracy"]), min_accuracy, ">=", "gold-label entity mapping accuracy"),
            self._readiness_numeric_gate("source_metadata_coverage", metadata_summary["source_metadata_coverage"], float(payload.get("min_source_metadata_coverage", 1.0)), ">=", "mapping source/version/confidence/ticker/market metadata coverage"),
            self._readiness_numeric_gate("identifier_coverage", metadata_summary["identifier_coverage"], float(payload.get("min_identifier_coverage", 1.0)), ">=", "mapping records retain LEI/CIK/FIGI/ISIN/ticker identifiers"),
            self._readiness_numeric_gate("bitemporal_version_coverage", float(quality["bitemporal_version_coverage"]), float(payload.get("min_bitemporal_version_coverage", 1.0)), ">=", "valid_from/recorded_at/version coverage for bitemporal lookup"),
            self._readiness_numeric_gate("temporal_overlap_count", float(quality["temporal_overlap_count"]), 0.0, "==", "no overlapping active business-time mapping versions"),
            self._readiness_numeric_gate("low_confidence_mapping_count", float(quality["low_confidence_count"]), 0.0, "==", "no unresolved low-confidence mappings under the readiness threshold"),
            self._readiness_numeric_gate("label_mismatch_count", float(len(quality["mismatches"])), 0.0, "==", "gold-label mismatches resolved before production"),
            self._readiness_numeric_gate("graph_traceable_resource_count", float(sum(int(value) for value in traceability["counts"].values() if not str(value).startswith("untraceable_"))), float(min_traceable_resources), ">=", "traceability report includes thesis, decision, or research-answer resources"),
            self._readiness_numeric_gate("graph_traceability_rate", float(traceability["traceability_rate"]), min_traceability, ">=", "thesis/decision/research-answer graph links trace to evidence and documents"),
            self._readiness_numeric_gate("edge_metadata_coverage", float(edge_quality["edge_metadata_coverage"]), min_edge_coverage, ">=", "graph edges contain source, timestamp, version, and confidence"),
            self._readiness_numeric_gate("neo4j_graph_node_count", float(graph_export["node_count"]), float(min_graph_nodes), ">=", "Neo4j-compatible graph export includes subject-page nodes"),
            self._readiness_numeric_gate("neo4j_graph_relationship_count", float(graph_export["relationship_count"]), 1.0, ">=", "Neo4j-compatible graph export includes subject-page relationships"),
            self._readiness_numeric_gate("qdrant_vector_point_count", float(qdrant_export["point_count"]), float(min_vector_points), ">=", "Qdrant-compatible vector export includes searchable subject evidence"),
            self._readiness_bool_gate("neo4j_non_local_config", adapters["neo4j"]["non_local_configured"], "non-local Neo4j staging/production endpoint configured"),
            self._readiness_bool_gate("qdrant_non_local_config", adapters["qdrant"]["non_local_configured"], "non-local Qdrant staging/production endpoint configured"),
            self._readiness_bool_gate("real_batch_mapping_artifact_uri", bool(artifacts.get("real_batch_mapping_artifact_uri")), "real ADR/China/A-H-U batch mapping run artifact URI"),
            self._readiness_bool_gate("adr_china_queue_mapping_uri", bool(artifacts.get("adr_china_queue_mapping_uri")), "ADR/China concept mapping queue review artifact URI"),
            self._readiness_bool_gate("mapping_gold_uri", bool(artifacts.get("mapping_gold_uri")), "entity mapping gold-label sample artifact URI"),
            self._readiness_bool_gate("entity_page_acceptance_uri", bool(artifacts.get("entity_page_acceptance_uri")), "production subject-page browser acceptance artifact URI"),
            self._readiness_bool_gate("graph_adapter_evidence_uri", bool(artifacts.get("graph_adapter_evidence_uri")), "external graph adapter sync evidence URI"),
            self._readiness_bool_gate("vector_adapter_evidence_uri", bool(artifacts.get("vector_adapter_evidence_uri")), "external vector adapter sync evidence URI"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "ready_for_entity_graph_production": ready,
            "ready_for_external_acceptance": ready,
            "missing_requirements": missing,
            "gates": gates,
            "quality_report": {
                "mappings": quality["mappings"],
                "covered_issuers": quality["covered_issuers"],
                "market_counts": quality["market_counts"],
                "checked_labels": quality["checked_labels"],
                "accuracy": quality["accuracy"],
                "average_confidence": quality["average_confidence"],
                "bitemporal_version_coverage": quality["bitemporal_version_coverage"],
                "temporal_overlap_count": quality["temporal_overlap_count"],
                "low_confidence_count": quality["low_confidence_count"],
                "mismatch_count": len(quality["mismatches"]),
            },
            "market_summary": market_summary,
            "label_summary": label_summary,
            "metadata_summary": metadata_summary,
            "graph_traceability": {
                "traceability_rate": traceability["traceability_rate"],
                "counts": traceability["counts"],
            },
            "edge_quality": {
                "edge_metadata_coverage": edge_quality["edge_metadata_coverage"],
                "total_edges": edge_quality["total_edges"],
                "missing_counts": edge_quality["missing_counts"],
            },
            "graph_export": {
                "node_count": graph_export["node_count"],
                "relationship_count": graph_export["relationship_count"],
                "content_sha256": graph_export["content_sha256"],
                "format": graph_export["adapter"]["format"],
            },
            "vector_export": {
                "point_count": qdrant_export["point_count"],
                "content_sha256": qdrant_export["content_sha256"],
                "format": qdrant_export["adapter"]["format"],
                "rights_filter": qdrant_export["rights_filter"],
            },
            "adapters": adapters,
            "artifact_uris": artifacts,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "entity_mapping_readiness_report_validates_ahu_accuracy_bitemporal_graph_traceability_and_external_adapter_evidence_without_calling_production_graph_or_vector_databases",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "entity_mapping_readiness_report", "entity_mapping", issuer_id or "A_H_U", source="entity_mapping_governance", approval_state="ready" if ready else "missing_evidence")
        return report

    def _entity_mapping_readiness_artifact_uris(self, payload: Mapping[str, Any]) -> dict[str, str]:
        aliases = {
            "real_batch_mapping_artifact_uri": ["real_batch_mapping_artifact_uri", "batch_mapping_uri", "adr_china_batch_mapping_uri", "batch_artifact_uri"],
            "adr_china_queue_mapping_uri": ["adr_china_queue_mapping_uri", "adr_queue_mapping_uri", "china_concept_queue_uri", "mapping_queue_uri"],
            "mapping_gold_uri": ["mapping_gold_uri", "gold_label_uri", "entity_mapping_gold_uri", "gold_sample_uri"],
            "entity_page_acceptance_uri": ["entity_page_acceptance_uri", "subject_page_acceptance_uri", "browser_acceptance_uri", "ui_acceptance_uri"],
            "graph_adapter_evidence_uri": ["graph_adapter_evidence_uri", "neo4j_sync_artifact_uri", "neo4j_artifact_uri", "graph_sync_artifact_uri"],
            "vector_adapter_evidence_uri": ["vector_adapter_evidence_uri", "qdrant_sync_artifact_uri", "qdrant_artifact_uri", "vector_sync_artifact_uri"],
        }
        return self._readiness_artifact_aliases(payload, aliases)

    def _entity_mapping_market_readiness_summary(self, mappings: list[EntityMapping], payload: Mapping[str, Any]) -> dict[str, Any]:
        raw_required = payload.get("required_markets", ["A", "H", "U"])
        if isinstance(raw_required, str):
            required_markets = self._unique_strings(part.upper() for part in re.split(r"[,;/\s]+", raw_required) if part.strip())
        elif isinstance(raw_required, list):
            required_markets = self._unique_strings(str(item).strip().upper() for item in raw_required if str(item).strip())
        else:
            required_markets = ["A", "H", "U"]
        market_counts: dict[str, int] = {}
        for mapping in mappings:
            market = str(mapping.market).strip().upper()
            if not market:
                continue
            market_counts[market] = market_counts.get(market, 0) + 1
        covered = [market for market in required_markets if market_counts.get(market, 0) > 0]
        missing = [market for market in required_markets if market not in covered]
        coverage = round(len(covered) / max(1, len(required_markets)), 4) if required_markets else 1.0
        return {
            "required_markets": required_markets,
            "market_counts": market_counts,
            "covered_required_markets": covered,
            "missing_required_markets": missing,
            "coverage": coverage,
        }

    def _entity_mapping_label_market_summary(self, payload: Mapping[str, Any], issuer_id: str, required_markets: list[str]) -> dict[str, Any]:
        labels = payload.get("labels")
        if not isinstance(labels, list):
            stored_labels = list(self.store.entity_mapping_labels.values())
            if issuer_id:
                stored_labels = [item for item in stored_labels if item.issuer_id == issuer_id]
            labels = [to_plain(item) for item in stored_labels]
        market_counts: dict[str, int] = {}
        for label in labels:
            if not isinstance(label, Mapping):
                continue
            market = str(label.get("market", "")).strip().upper()
            if not market:
                continue
            market_counts[market] = market_counts.get(market, 0) + 1
        covered = [market for market in required_markets if market_counts.get(market, 0) > 0]
        missing = [market for market in required_markets if market not in covered]
        coverage = round(len(covered) / max(1, len(required_markets)), 4) if required_markets else 1.0
        return {
            "label_count": len([item for item in labels if isinstance(item, Mapping)]),
            "market_counts": market_counts,
            "covered_required_markets": covered,
            "missing_required_markets": missing,
            "coverage": coverage,
        }

    def _entity_mapping_metadata_summary(self, mappings: list[EntityMapping]) -> dict[str, Any]:
        total = len(mappings)
        source_complete = 0
        identifier_complete = 0
        bitemporal_complete = 0
        for mapping in mappings:
            if (
                str(mapping.source).strip()
                and str(mapping.version).strip()
                and str(mapping.ticker).strip()
                and str(mapping.market).strip()
                and float(mapping.confidence) > 0.0
            ):
                source_complete += 1
            if any(str(getattr(mapping, field, "")).strip() for field in ["lei", "cik", "figi", "isin", "ticker"]):
                identifier_complete += 1
            if str(mapping.version).strip() and mapping.valid_from and mapping.recorded_at:
                bitemporal_complete += 1
        return {
            "mapping_count": total,
            "source_metadata_complete": source_complete,
            "identifier_complete": identifier_complete,
            "bitemporal_complete": bitemporal_complete,
            "source_metadata_coverage": round(source_complete / max(1, total), 4) if total else 1.0,
            "identifier_coverage": round(identifier_complete / max(1, total), 4) if total else 1.0,
            "bitemporal_coverage": round(bitemporal_complete / max(1, total), 4) if total else 1.0,
        }

    def _entity_mapping_graph_export_summary(self, payload: Mapping[str, Any], mappings: list[EntityMapping], *, actor: str) -> dict[str, Any]:
        if mappings:
            issuer_ids = sorted({mapping.issuer_id for mapping in mappings})
            nodes = 0
            relationships = 0
            content_hashes: list[str] = []
            fmt = "neo4j_bulk_upsert_compatible"
            for issuer_id in issuer_ids:
                export = self.graph_neo4j_export({"issuer_id": issuer_id}, actor=actor)
                nodes += int(export["node_count"])
                relationships += int(export["relationship_count"])
                content_hashes.append(str(export["content_sha256"]))
                fmt = str(export["adapter"]["format"])
            return {
                "node_count": nodes,
                "relationship_count": relationships,
                "content_sha256": self._payload_sha256({"issuer_ids": issuer_ids, "hashes": content_hashes}),
                "adapter": {"format": fmt},
            }
        issuer_id = str(payload.get("issuer_id", "")).strip()
        export = self.graph_neo4j_export({"issuer_id": issuer_id}, actor=actor)
        return {
            "node_count": int(export["node_count"]),
            "relationship_count": int(export["relationship_count"]),
            "content_sha256": str(export["content_sha256"]),
            "adapter": {"format": str(export["adapter"]["format"])},
        }

    def _entity_mapping_edge_quality_summary(self, payload: Mapping[str, Any], mappings: list[EntityMapping]) -> dict[str, Any]:
        if not mappings:
            return self.graph_edge_quality_report({"issuer_id": str(payload.get("issuer_id", "")).strip(), "limit": payload.get("edge_limit", 1000)})
        all_edges: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str]] = set()
        for issuer_id in sorted({mapping.issuer_id for mapping in mappings}):
            graph = self.query_graph({"issuer_id": issuer_id})
            for edge in graph.get("edges", []):
                if not isinstance(edge, Mapping):
                    continue
                key = (str(edge.get("type", "")), str(edge.get("from", "")), str(edge.get("to", "")))
                if key in seen:
                    continue
                seen.add(key)
                all_edges.append(dict(edge))
        required_fields = ["source", "timestamp", "version", "confidence"]
        issues: list[dict[str, Any]] = []
        missing_counts = {field: 0 for field in required_fields}
        for edge in all_edges:
            missing = [field for field in required_fields if edge.get(field) in {"", None}]
            for field in missing:
                missing_counts[field] += 1
            if missing:
                issues.append(
                    {
                        "type": edge.get("type", ""),
                        "from": edge.get("from", ""),
                        "to": edge.get("to", ""),
                        "missing_fields": missing,
                    }
                )
        total = len(all_edges)
        complete = total - len(issues)
        limit = self._bounded_limit(payload.get("edge_limit", 1000), 1000)
        return {
            "total_edges": total,
            "complete_edges": complete,
            "edge_metadata_coverage": round(complete / max(1, total), 4) if total else 1.0,
            "required_fields": required_fields,
            "missing_counts": missing_counts,
            "issues": issues[:limit],
        }

    def _filter_entity_mappings(
        self,
        values: Any,
        *,
        issuer_id: str = "",
        ticker: str = "",
        market: str = "",
        status: str = "",
        valid_at: Any = None,
        recorded_at: Any = None,
    ) -> list[EntityMapping]:
        mappings = list(values)
        if issuer_id:
            mappings = [item for item in mappings if item.issuer_id == issuer_id]
        if ticker:
            mappings = [item for item in mappings if item.ticker.upper() == ticker]
        if market:
            mappings = [item for item in mappings if item.market == market]
        if status:
            mappings = [item for item in mappings if item.status == status]
        if valid_at is not None:
            mappings = [item for item in mappings if self._entity_mapping_valid_at(item, valid_at)]
        if recorded_at is not None:
            mappings = [item for item in mappings if parse_datetime(item.recorded_at) <= recorded_at]
        return mappings

    def _entity_mapping_valid_at(self, mapping: EntityMapping, valid_at: Any) -> bool:
        valid_from = parse_datetime(mapping.valid_from)
        valid_to = parse_datetime(mapping.valid_to) if mapping.valid_to else None
        return valid_from <= valid_at and (valid_to is None or valid_at < valid_to)

    def _entity_mapping_temporal_overlaps(self, mappings: list[EntityMapping]) -> list[dict[str, Any]]:
        grouped: dict[tuple[str, str, str, str], list[EntityMapping]] = {}
        for mapping in mappings:
            key = (mapping.issuer_id, mapping.ticker, mapping.market, mapping.figi or mapping.isin or mapping.cik or mapping.lei)
            grouped.setdefault(key, []).append(mapping)
        overlaps: list[dict[str, Any]] = []
        for key, group in grouped.items():
            if len(group) < 2:
                continue
            group.sort(key=lambda item: parse_datetime(item.valid_from))
            for left, right in zip(group, group[1:]):
                left_to = parse_datetime(left.valid_to) if left.valid_to else None
                if left_to is None or left_to > parse_datetime(right.valid_from):
                    overlaps.append(
                        {
                            "issuer_id": key[0],
                            "ticker": key[1],
                            "market": key[2],
                            "left_mapping_id": left.mapping_id,
                            "right_mapping_id": right.mapping_id,
                            "left_valid_to": to_plain(left.valid_to),
                            "right_valid_from": to_plain(right.valid_from),
                        }
                    )
        return overlaps

    def ingest_document(self, payload: Mapping[str, Any], *, actor: str = "system") -> Document:
        document = payload if isinstance(payload, Document) else Document.from_dict(payload)
        canonical_source_id = self._canonical_source_id(document.source_id)
        if canonical_source_id != document.source_id:
            document = replace(document, source_id=canonical_source_id)
        sanitized_source_uri = self._sanitize_source_uri(document.source_uri)
        if sanitized_source_uri != document.source_uri:
            document = replace(document, source_uri=sanitized_source_uri)
        issuer = self.store.issuers.get(document.issuer_id)
        if issuer is None:
            raise NotFoundError(f"issuer {document.issuer_id} not found")
        source = self.store.sources.get(document.source_id)
        if source is None:
            raise NotFoundError(f"source {document.source_id} not found")
        if source.risk_level == "red":
            raise PermissionDenied("red source cannot enter automated document ingestion")
        if not source.rights_tag.allows(document.rights_tag):
            raise PermissionDenied("document rights exceed source rights")
        if document.security_id and document.security_id not in self.store.securities:
            raise NotFoundError(f"security {document.security_id} not found")
        if source.allowed_document_types and document.document_type not in source.allowed_document_types:
            raise ValidationError(f"document_type {document.document_type} is not allowed for source {source.source_id}")
        if document.document_id in self.store.documents:
            raise ConflictError(f"document {document.document_id} already exists")
        if document.body and not document.object_uri:
            suffix = ".html" if looks_like_html(document.body) else ".txt"
            stored = self.object_store.put_text(document.source_id, document.document_id, document.body, suffix=suffix)
            document = replace(document, object_uri=stored.uri, content_sha256=stored.sha256)
        self.store.documents[document.document_id] = document
        self._audit(
            actor,
            "ingest_document",
            "document",
            document.document_id,
            source=document.source_type or source.source_type,
            version=document.version,
        )
        return document

    def scan_research_reports(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        raw_root = str(payload.get("root_path") or os.environ.get("AI_QUANT_RESEARCH_REPORT_ROOT") or "").strip()
        if not raw_root:
            raise ValidationError("research report scan requires root_path or AI_QUANT_RESEARCH_REPORT_ROOT")
        root = Path(raw_root).expanduser()
        if not root.exists() or not root.is_dir():
            raise ValidationError(f"research report root not found: {root}")
        extensions = payload.get("extensions", [".pdf"])
        if isinstance(extensions, str):
            extensions = [item.strip() for item in extensions.split(",")]
        if not isinstance(extensions, list):
            raise ValidationError("extensions must be a list or comma-separated string")
        limit = self._bounded_limit(payload.get("limit", 1000), 50000)
        hash_files = bool(payload.get("hash_files", False))
        per_broker_sources = bool(payload.get("per_broker_sources", True))
        files = iter_report_files(root, extensions={str(item).lower() for item in extensions}, limit=limit)
        reports: list[ResearchReportAsset] = []
        for path in files:
            metadata = infer_report_metadata(path, root)
            broker = str(metadata["broker"])
            source_id = self._research_report_source_id(broker) if per_broker_sources else LOCAL_RESEARCH_REPORT_SOURCE_ID
            self._ensure_research_report_source(source_id, broker, actor=actor)
            report = ResearchReportAsset(
                report_id=report_id_for_path(path),
                source_id=source_id,
                broker=broker,
                file_path=str(path),
                file_name=path.name,
                title=str(metadata["title"]),
                year=str(metadata["year"]),
                month=str(metadata["month"]),
                file_type=path.suffix.lower().lstrip(".") or "unknown",
                size_bytes=path.stat().st_size,
                fingerprint=cheap_fingerprint(path, root),
                content_sha256=content_sha256(path) if hash_files else "",
                rights_tag=self.store.sources[source_id].rights_tag,
                industry=str(metadata.get("industry", "")),
                evidence_topics=[str(item) for item in metadata.get("evidence_topics", [])],
                risk_tags=[str(item) for item in metadata.get("risk_tags", [])],
                financial_metric_tags=[str(item) for item in metadata.get("financial_metric_tags", [])],
                viewpoint=dict(metadata.get("viewpoint", {})),
            )
            existing = self.store.research_reports.get(report.report_id)
            if existing:
                report.document_id = existing.document_id
                report.issuer_id = existing.issuer_id
                report.security_id = existing.security_id
                report.industry = existing.industry or report.industry
                report.evidence_topics = list(existing.evidence_topics or report.evidence_topics)
                report.risk_tags = list(existing.risk_tags or report.risk_tags)
                report.financial_metric_tags = list(existing.financial_metric_tags or report.financial_metric_tags)
                report.viewpoint = dict(existing.viewpoint or report.viewpoint)
                report.event_ids = list(existing.event_ids)
                report.status = existing.status
            self.store.research_reports[report.report_id] = report
            reports.append(report)
        self._audit(
            actor,
            "scan_research_reports",
            "research_report",
            str(root),
            source="research_report_manifest",
            approval_state=f"indexed={len(reports)}",
        )
        return {"root_path": str(root), "indexed_count": len(reports), "reports": [to_plain(item) for item in reports]}

    def research_report_incremental_schedule(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        """T-417: 研报大目录增量调度框架.

        为本地研报资产库生成增量处理调度计划，解决 22G/11742 文件的批量 OCR 成本控制问题。
        支持：
        - 增量扫描（只处理 fingerprint 变更或尚未入库的文件）
        - OCR 成本预估和 ocr_budget_mb 限额控制
        - batch_size 分批窗口，适配 Airflow/Cron/DAG 分批触发
        - dry_run=True 时只输出 schedule_plan，不执行任何提取
        - execute=True 时按计划执行首批（batch_size 内）
        - 输出 schedule_plan 供外部调度器接入
        """
        raw_root = str(payload.get("root_path") or os.environ.get("AI_QUANT_RESEARCH_REPORT_ROOT") or "").strip()
        if not raw_root:
            raise ValidationError("incremental schedule requires root_path or AI_QUANT_RESEARCH_REPORT_ROOT")
        root = Path(raw_root).expanduser()
        if not root.exists() or not root.is_dir():
            raise ValidationError(f"research report root not found: {root}")

        extensions = payload.get("extensions", [".pdf"])
        if isinstance(extensions, str):
            extensions = [item.strip() for item in extensions.split(",")]
        extensions = {str(item).lower() for item in extensions}

        dry_run = self._truthy(payload.get("dry_run", True))
        execute = self._truthy(payload.get("execute", False)) and not dry_run
        batch_size = self._bounded_limit(payload.get("batch_size", 50), 500)
        ocr_budget_mb = float(payload.get("ocr_budget_mb", 200.0))
        scan_limit = self._bounded_limit(payload.get("scan_limit", 5000), 20000)
        citation_char_limit = self._bounded_limit(payload.get("citation_char_limit", 1200), 4000)
        parser_version = str(payload.get("parser_version", "research-report-incremental-v1"))
        broker_filter = str(payload.get("broker", "")).strip().lower()
        year_filter = str(payload.get("year", "")).strip()

        # Phase 1: filesystem scan (incremental — only new or changed fingerprints)
        new_count = 0
        changed_count = 0
        skipped_count = 0
        total_scanned = 0
        batch_candidates: list[dict[str, Any]] = []
        ocr_budget_used_mb = 0.0

        try:
            files = iter_report_files(root, extensions=extensions, limit=scan_limit)
        except Exception as exc:
            raise ValidationError(f"cannot iterate research report root: {exc}") from exc

        per_broker_sources = self._truthy(payload.get("per_broker_sources", True))
        for path in files:
            total_scanned += 1
            metadata = infer_report_metadata(path, root)
            broker = str(metadata["broker"])
            if broker_filter and broker_filter not in broker.lower():
                skipped_count += 1
                continue
            year = str(metadata["year"])
            if year_filter and year_filter != year:
                skipped_count += 1
                continue

            report_id = report_id_for_path(path)
            fp = cheap_fingerprint(path, root)
            existing = self.store.research_reports.get(report_id)
            is_new = existing is None
            is_changed = not is_new and existing.fingerprint != fp

            if not is_new and not is_changed:
                skipped_count += 1
                continue

            if is_new:
                new_count += 1
            else:
                changed_count += 1

            # OCR budget control
            size_mb = path.stat().st_size / (1024 * 1024)
            if ocr_budget_used_mb + size_mb > ocr_budget_mb:
                # Over budget — still record in schedule_plan but skip from batch_candidates
                batch_candidates.append({
                    "report_id": report_id,
                    "file_path": str(path),
                    "file_name": path.name,
                    "broker": broker,
                    "year": year,
                    "month": str(metadata["month"]),
                    "size_mb": round(size_mb, 3),
                    "is_new": is_new,
                    "is_changed": is_changed,
                    "status": "ocr_budget_exceeded",
                    "batch": "deferred",
                })
                continue

            ocr_budget_used_mb += size_mb

            if not dry_run:
                # Register/update the report asset in the store only when the
                # operator has moved from planning into an executable schedule.
                source_id = self._research_report_source_id(broker) if per_broker_sources else LOCAL_RESEARCH_REPORT_SOURCE_ID
                self._ensure_research_report_source(source_id, broker, actor=actor)
                report = ResearchReportAsset(
                    report_id=report_id,
                    source_id=source_id,
                    broker=broker,
                    file_path=str(path),
                    file_name=path.name,
                    title=str(metadata["title"]),
                    year=year,
                    month=str(metadata["month"]),
                    file_type=path.suffix.lower().lstrip(".") or "unknown",
                    size_bytes=path.stat().st_size,
                    fingerprint=fp,
                    content_sha256="",
                    rights_tag=self.store.sources[source_id].rights_tag,
                    industry=str(metadata.get("industry", "")),
                    evidence_topics=[str(item) for item in metadata.get("evidence_topics", [])],
                    risk_tags=[str(item) for item in metadata.get("risk_tags", [])],
                    financial_metric_tags=[str(item) for item in metadata.get("financial_metric_tags", [])],
                    viewpoint=dict(metadata.get("viewpoint", {})),
                )
                if existing:
                    report.document_id = existing.document_id
                    report.issuer_id = existing.issuer_id
                    report.security_id = existing.security_id
                    report.industry = existing.industry or report.industry
                    report.evidence_topics = list(existing.evidence_topics or report.evidence_topics)
                    report.risk_tags = list(existing.risk_tags or report.risk_tags)
                    report.financial_metric_tags = list(existing.financial_metric_tags or report.financial_metric_tags)
                    report.viewpoint = dict(existing.viewpoint or report.viewpoint)
                    report.event_ids = list(existing.event_ids)
                    report.status = existing.status
                self.store.research_reports[report.report_id] = report

            batch_candidates.append({
                "report_id": report_id,
                "file_path": str(path),
                "file_name": path.name,
                "broker": broker,
                "year": year,
                "month": str(metadata["month"]),
                "size_mb": round(size_mb, 3),
                "is_new": is_new,
                "is_changed": is_changed,
                "status": "ready_for_extraction",
                "batch": "current",
            })

        # Phase 2: generate schedule_plan — batch assignments for Airflow/Cron
        current_batch = [item for item in batch_candidates if item["batch"] == "current"]
        deferred_batch = [item for item in batch_candidates if item["batch"] == "deferred"]
        schedule_plan = []
        for batch_start in range(0, len(current_batch), batch_size):
            batch_items = current_batch[batch_start:batch_start + batch_size]
            schedule_plan.append({
                "batch_index": batch_start // batch_size,
                "batch_size": len(batch_items),
                "report_ids": [item["report_id"] for item in batch_items],
                "brokers": sorted({item["broker"] for item in batch_items}),
                "estimated_size_mb": round(sum(item["size_mb"] for item in batch_items), 2),
                "trigger_suggestion": "cron_or_airflow_daily_batch",
            })

        # Phase 3: optionally execute the first batch
        executed_results: list[dict[str, Any]] = []
        if execute and current_batch:
            first_batch_ids = [item["report_id"] for item in current_batch[:batch_size]]
            for report_id in first_batch_ids:
                try:
                    report = self.store.research_reports.get(report_id)
                    if report is not None and not report.document_id:
                        document_id = f"doc_{report.report_id}"
                        source = self.store.sources.get(report.source_id)
                        if source is None:
                            raise NotFoundError(f"source {report.source_id} not found")
                        document = self.store.documents.get(document_id)
                        if document is None:
                            document = Document(
                                document_id=document_id,
                                issuer_id="",
                                security_id="",
                                document_type="research",
                                source_id=report.source_id,
                                source_type="local_reference",
                                source_uri=f"research-report://{report.report_id}",
                                object_uri=report.file_path,
                                content_sha256=report.content_sha256,
                                body="",
                                title=report.title,
                                rights_tag=report.rights_tag,
                                language=str(payload.get("language", "zh")),
                                version=str(payload.get("version", "incremental-v1")),
                            )
                            if source.allowed_document_types and document.document_type not in source.allowed_document_types:
                                raise ValidationError(f"document_type {document.document_type} is not allowed for source {source.source_id}")
                            if not source.rights_tag.allows(document.rights_tag):
                                raise PermissionDenied("document rights exceed source rights")
                            self.store.documents[document.document_id] = document
                            self._audit(
                                actor,
                                "register_research_report_reference_document",
                                "document",
                                document.document_id,
                                source=source.source_type,
                                approval_state="local_reference_only",
                            )
                        report.document_id = document.document_id
                        report.status = "ingested"
                        self.store.research_reports[report.report_id] = report
                        self._audit(
                            actor,
                            "link_research_report_reference_document",
                            "research_report",
                            report.report_id,
                            source=report.source_id,
                            approval_state=report.status,
                        )
                    result = self.extract_research_report_text(
                        report_id,
                        {"citation_char_limit": citation_char_limit, "parser_version": parser_version},
                        actor=actor,
                    )
                    executed_results.append({
                        "report_id": report_id,
                        "status": result["status"],
                        "evidence_count": len(result.get("evidence", [])),
                        "manual_review": bool(result.get("manual_review")),
                    })
                except (ValidationError, NotFoundError, PermissionDenied, ConflictError) as exc:
                    executed_results.append({
                        "report_id": report_id,
                        "status": "failed",
                        "error": str(exc),
                    })

        self._audit(
            actor,
            "research_report_incremental_schedule",
            "research_report",
            str(root),
            source="research_report_manifest",
            approval_state=(
                f"dry_run={dry_run};execute={execute};"
                f"new={new_count};changed={changed_count};"
                f"skipped={skipped_count};batches={len(schedule_plan)}"
            ),
        )
        return {
            "root_path": str(root),
            "dry_run": dry_run,
            "execute": execute,
            "total_scanned": total_scanned,
            "new_count": new_count,
            "changed_count": changed_count,
            "skipped_count": skipped_count,
            "ocr_budget_mb": ocr_budget_mb,
            "ocr_budget_used_mb": round(ocr_budget_used_mb, 3),
            "deferred_count": len(deferred_batch),
            "batch_size": batch_size,
            "batch_count": len(schedule_plan),
            "schedule_plan": schedule_plan,
            "candidates": batch_candidates,
            "executed_results": executed_results,
            "usage_boundary": "local_reference_only_not_training_or_fact_source",
            "airflow_dagster_trigger_suggestion": (
                "Register schedule_plan batches as Airflow/Dagster tasks; "
                "trigger one batch per daily DAG run; check ocr_budget_mb before each batch."
            ),
        }


    def research_reports_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        broker = str(filters.get("broker", "")).strip().lower()
        source_id = str(filters.get("source_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        query = str(filters.get("q", "")).strip().lower()
        limit = self._bounded_limit(filters.get("limit", 50), 1000)
        reports = list(self.store.research_reports.values())
        if broker:
            reports = [item for item in reports if broker in item.broker.lower()]
        if source_id:
            reports = [item for item in reports if item.source_id == source_id]
        if status:
            reports = [item for item in reports if item.status == status]
        if query:
            reports = [item for item in reports if query in f"{item.title} {item.file_name} {item.broker} {item.year} {item.month}".lower()]
        reports.sort(key=lambda item: (item.year, item.month, item.broker, item.file_name), reverse=True)
        return {"count": len(reports), "reports": [to_plain(item) for item in reports[:limit]]}

    def research_report_extraction_queue(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        broker = str(payload.get("broker", "")).strip().lower()
        source_id = str(payload.get("source_id", "")).strip()
        status = str(payload.get("status", "")).strip()
        file_type = str(payload.get("file_type", "")).strip().lower().lstrip(".")
        execute = self._truthy(payload.get("execute", False))
        force = self._truthy(payload.get("force", False))
        limit = self._bounded_limit(payload.get("limit", 50), 1000)
        citation_char_limit = self._bounded_limit(payload.get("citation_char_limit", 1200), max_value=4000)
        parser_version = str(payload.get("parser_version", "research-report-batch-1"))
        raw_text_cache_ttl_days = int(payload.get("raw_text_cache_ttl_days", 90))
        citation_index_ttl_days = int(payload.get("citation_index_ttl_days", 365))
        reports = list(self.store.research_reports.values())
        if broker:
            reports = [item for item in reports if broker in item.broker.lower()]
        if source_id:
            reports = [item for item in reports if item.source_id == source_id]
        if status:
            reports = [item for item in reports if item.status == status]
        if file_type:
            reports = [item for item in reports if item.file_type.lower().lstrip(".") == file_type]
        reports.sort(key=lambda item: (item.status, item.year, item.month, item.broker, item.file_name), reverse=True)

        rows: list[dict[str, Any]] = []
        counters = {"ready_text": 0, "ocr_required": 0, "needs_ingest": 0, "already_indexed": 0, "executed": 0, "manual_review": 0, "failed": 0}
        for report in reports[:limit]:
            row = self._research_report_extraction_queue_row(report, citation_char_limit=citation_char_limit, parser_version=parser_version, force=force)
            if execute and row["action"] in {"ready_text_extract", "ocr_required"}:
                try:
                    result = self.extract_research_report_text(
                        report.report_id,
                        {"citation_char_limit": citation_char_limit, "parser_version": parser_version},
                        actor=actor,
                    )
                    row["executed"] = True
                    row["result_status"] = result["status"]
                    row["evidence_count"] = len(result.get("evidence", []))
                    row["manual_review_id"] = result["manual_review"]["review_id"] if result.get("manual_review") else ""
                    counters["executed"] += 1
                    if result.get("manual_review"):
                        counters["manual_review"] += 1
                except (ValidationError, NotFoundError, PermissionDenied, ConflictError) as exc:
                    row["executed"] = True
                    row["result_status"] = "failed"
                    row["error"] = str(exc)
                    counters["failed"] += 1
            else:
                row["executed"] = False
            counters[row["action_bucket"]] = counters.get(row["action_bucket"], 0) + 1
            rows.append(row)
        self._audit(
            actor,
            "research_report_extraction_queue",
            "research_report",
            "batch",
            source="local_research_reports",
            approval_state=f"execute={execute};count={len(rows)}",
        )
        return {
            "count": len(rows),
            "execute": execute,
            "counters": counters,
            "cache_policy": {
                "raw_text_cache_ttl_days": raw_text_cache_ttl_days,
                "citation_index_ttl_days": citation_index_ttl_days,
                "usage_boundary": "local_reference_only_not_training_or_fact_source",
            },
            "items": rows,
        }

    def research_report_governance_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        broker = str(filters.get("broker", "")).strip().lower()
        source_id = str(filters.get("source_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        as_of = parse_datetime(filters.get("as_of")).date() if filters.get("as_of") else utcnow().date()
        stale_after_days = int(filters.get("stale_after_days", 180))
        max_single_source_share = float(filters.get("max_single_source_share", 0.6))
        limit = self._bounded_limit(filters.get("limit", 100), 1000)

        reports = list(self.store.research_reports.values())
        if broker:
            reports = [item for item in reports if broker in item.broker.lower()]
        if source_id:
            reports = [item for item in reports if item.source_id == source_id]
        if status:
            reports = [item for item in reports if item.status == status]
        if issuer_id or security_id:
            filtered: list[ResearchReportAsset] = []
            for report in reports:
                document = self.store.documents.get(report.document_id)
                if document is None:
                    continue
                if issuer_id and document.issuer_id != issuer_id:
                    continue
                if security_id and document.security_id != security_id:
                    continue
                filtered.append(report)
            reports = filtered

        broker_counts: dict[str, int] = {}
        source_counts: dict[str, int] = {}
        rows: list[dict[str, Any]] = []
        stale_count = 0
        missing_document_count = 0
        for report in reports:
            document = self.store.documents.get(report.document_id)
            report_date = self._research_report_month_date(report)
            age_days = (as_of - report_date).days if report_date else None
            stale = age_days is not None and age_days > stale_after_days
            issues: list[str] = []
            if stale:
                issues.append("stale_research_report")
                stale_count += 1
            if not document:
                issues.append("missing_document_link")
                missing_document_count += 1
            if report.rights_tag.training_allowed or report.rights_tag.display_use != "restricted":
                issues.append("rights_boundary_needs_review")
            broker_key = report.broker or "unknown"
            broker_counts[broker_key] = broker_counts.get(broker_key, 0) + 1
            source_counts[report.source_id] = source_counts.get(report.source_id, 0) + 1
            rows.append(
                {
                    "report_id": report.report_id,
                    "broker": report.broker,
                    "source_id": report.source_id,
                    "title": report.title,
                    "file_name": report.file_name,
                    "year": report.year,
                    "month": report.month,
                    "report_date": report_date.isoformat() if report_date else "",
                    "age_days": age_days,
                    "status": report.status,
                    "document_id": report.document_id,
                    "issuer_id": document.issuer_id if document else "",
                    "security_id": document.security_id if document else "",
                    "stale": stale,
                    "issues": issues,
                    "usage_boundary": "local_reference_only_not_fact_or_training_source",
                }
            )
        top_broker = max(broker_counts.items(), key=lambda item: item[1], default=("", 0))
        top_source = max(source_counts.items(), key=lambda item: item[1], default=("", 0))
        total = len(reports)
        top_broker_share = (top_broker[1] / total) if total else 0.0
        top_source_share = (top_source[1] / total) if total else 0.0
        concentration_issues: list[str] = []
        if total and top_broker_share > max_single_source_share:
            concentration_issues.append("single_broker_concentration_breach")
        if total and top_source_share > max_single_source_share:
            concentration_issues.append("single_source_concentration_breach")
        rows.sort(key=lambda item: (item["stale"], item["age_days"] or 0, item["broker"], item["file_name"]), reverse=True)
        return {
            "as_of": as_of.isoformat(),
            "count": total,
            "stale_after_days": stale_after_days,
            "stale_count": stale_count,
            "missing_document_count": missing_document_count,
            "max_single_source_share": max_single_source_share,
            "top_broker": top_broker[0],
            "top_broker_share": round(top_broker_share, 4),
            "top_source_id": top_source[0],
            "top_source_share": round(top_source_share, 4),
            "broker_counts": broker_counts,
            "source_counts": source_counts,
            "concentration_issues": concentration_issues,
            "automation_allowed": False,
            "usage_boundary": "research_reports_are_external_view_or_local_reference_only",
            "reports": rows[:limit],
        }

    def research_report_mapping_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        broker = str(filters.get("broker", "")).strip().lower()
        source_id = str(filters.get("source_id", "")).strip()
        industry = str(filters.get("industry", "")).strip().lower()
        event_id = str(filters.get("event_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        include_candidate_events = self._truthy(filters.get("include_candidate_events", True))
        limit = self._bounded_limit(filters.get("limit", 100), 1000)

        reports = list(self.store.research_reports.values())
        if broker:
            reports = [item for item in reports if broker in item.broker.lower()]
        if source_id:
            reports = [item for item in reports if item.source_id == source_id]
        if status:
            reports = [item for item in reports if item.status == status]

        rows: list[dict[str, Any]] = []
        industry_counts: dict[str, int] = {}
        mapped_issuer_count = 0
        mapped_security_count = 0
        mapped_event_count = 0
        unmapped_count = 0
        for report in reports:
            row = self._research_report_mapping_row(report, include_candidate_events=include_candidate_events)
            if issuer_id and row["issuer_id"] != issuer_id:
                continue
            if security_id and row["security_id"] != security_id:
                continue
            if industry and industry != str(row["industry"]).lower():
                continue
            if event_id and event_id not in row["event_ids"] and event_id not in row["candidate_event_ids"]:
                continue
            rows.append(row)
            if row["issuer_id"]:
                mapped_issuer_count += 1
            if row["security_id"]:
                mapped_security_count += 1
            if row["event_ids"] or row["candidate_event_ids"]:
                mapped_event_count += 1
            if not row["mapped"]:
                unmapped_count += 1
            if row["industry"]:
                industry_counts[row["industry"]] = industry_counts.get(row["industry"], 0) + 1

        rows.sort(key=lambda item: (item["mapped"], item["year"], item["month"], item["broker"], item["file_name"]), reverse=True)
        return {
            "count": len(rows),
            "mapped_issuer_count": mapped_issuer_count,
            "mapped_security_count": mapped_security_count,
            "mapped_event_count": mapped_event_count,
            "unmapped_count": unmapped_count,
            "industry_counts": industry_counts,
            "include_candidate_events": include_candidate_events,
            "automation_allowed": False,
            "usage_boundary": "research_reports_are_local_reference_only_not_fact_source_or_training_data",
            "reports": rows[:limit],
        }

    def research_report_viewpoint_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        broker = str(filters.get("broker", "")).strip().lower()
        topic = str(filters.get("topic", "")).strip().lower()
        max_single_broker_share = float(filters.get("max_single_broker_share", 0.6))
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        reports = list(self.store.research_reports.values())
        if broker:
            reports = [item for item in reports if broker in item.broker.lower()]
        rows = [self._research_report_viewpoint_row(report) for report in reports]
        if issuer_id:
            rows = [item for item in rows if item["issuer_id"] == issuer_id]
        if security_id:
            rows = [item for item in rows if item["security_id"] == security_id]
        if topic:
            rows = [item for item in rows if topic in item["topic_terms"] or topic in item["title"].lower()]
        rows.sort(key=lambda item: (item["year"], item["month"], item["broker"], item["file_name"]), reverse=True)

        topic_groups: dict[str, dict[str, Any]] = {}
        for row in rows:
            terms = row["topic_terms"] or ["uncategorized"]
            for term in terms:
                group = topic_groups.setdefault(term, {"topic": term, "count": 0, "brokers": {}, "sentiment_counts": {}, "reports": []})
                group["count"] += 1
                group["brokers"][row["broker"]] = group["brokers"].get(row["broker"], 0) + 1
                group["sentiment_counts"][row["sentiment"]] = group["sentiment_counts"].get(row["sentiment"], 0) + 1
                group["reports"].append(row["report_id"])
        topic_rows: list[dict[str, Any]] = []
        bias_alerts: list[dict[str, Any]] = []
        for group in topic_groups.values():
            top_broker, top_count = max(group["brokers"].items(), key=lambda item: item[1], default=("", 0))
            single_broker_share = round(top_count / max(1, group["count"]), 4)
            sentiment_counts = group["sentiment_counts"]
            issues: list[str] = []
            if len(group["brokers"]) < 2 and group["count"] > 1:
                issues.append("single_broker_viewpoint")
            if single_broker_share > max_single_broker_share:
                issues.append("broker_concentration_bias")
            if sentiment_counts.get("positive", 0) and not sentiment_counts.get("negative", 0):
                issues.append("missing_negative_counterview")
            if sentiment_counts.get("negative", 0) and not sentiment_counts.get("positive", 0):
                issues.append("missing_positive_counterview")
            topic_row = {
                "topic": group["topic"],
                "count": group["count"],
                "broker_counts": group["brokers"],
                "sentiment_counts": sentiment_counts,
                "top_broker": top_broker,
                "single_broker_share": single_broker_share,
                "issues": issues,
                "report_ids": group["reports"][:limit],
            }
            topic_rows.append(topic_row)
            for issue in issues:
                bias_alerts.append({"topic": group["topic"], "issue": issue, "top_broker": top_broker, "single_broker_share": single_broker_share})
        topic_rows.sort(key=lambda item: (len(item["issues"]), item["count"], item["single_broker_share"]), reverse=True)
        return {
            "count": len(rows),
            "topic_count": len(topic_rows),
            "bias_alert_count": len(bias_alerts),
            "max_single_broker_share": max_single_broker_share,
            "automation_allowed": False,
            "usage_boundary": "research_report_viewpoints_are_local_reference_only_not_fact_source_or_training_data",
            "topics": topic_rows[:limit],
            "bias_alerts": bias_alerts[:limit],
            "reports": rows[:limit],
        }

    def ingest_research_report(self, report_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        report = self.store.research_reports.get(report_id)
        if report is None:
            raise NotFoundError(f"research report {report_id} not found")
        issuer_id = str(payload["issuer_id"])
        security_id = str(payload.get("security_id", ""))
        document_id = str(payload.get("document_id", f"doc_{report.report_id}"))
        if document_id in self.store.documents:
            report.document_id = document_id
            existing_document = self.store.documents[document_id]
            report.issuer_id = existing_document.issuer_id
            report.security_id = existing_document.security_id
            report.industry = str(payload.get("industry", report.industry))
            report.event_ids = [str(item) for item in payload.get("event_ids", report.event_ids)]
            report.status = "ingested"
            self.store.commit()
            return {"report": to_plain(report), "document": to_plain(self.store.documents[document_id]), "created": False}
        document = self.ingest_document(
            {
                "document_id": document_id,
                "issuer_id": issuer_id,
                "security_id": security_id,
                "source_id": report.source_id,
                "source_type": "local_reference",
                "document_type": "research",
                "source_uri": f"research-report://{report.report_id}",
                "object_uri": report.file_path,
                "content_sha256": report.content_sha256,
                "body": "",
                "title": report.title,
                "rights_tag": to_plain(report.rights_tag),
                "language": str(payload.get("language", "zh")),
                "version": str(payload.get("version", "v1")),
            },
            actor=actor,
        )
        report.document_id = document.document_id
        report.issuer_id = issuer_id
        report.security_id = security_id
        report.industry = str(payload.get("industry", report.industry))
        report.event_ids = [str(item) for item in payload.get("event_ids", report.event_ids)]
        report.status = "ingested"
        self.store.research_reports[report.report_id] = report
        self._audit(actor, "ingest_research_report", "research_report", report.report_id, source=report.source_id, approval_state=report.status)
        return {"report": to_plain(report), "document": to_plain(document), "created": True}

    def extract_research_report_text(self, report_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        report = self.store.research_reports.get(report_id)
        if report is None:
            raise NotFoundError(f"research report {report_id} not found")
        if not report.document_id:
            raise ValidationError("research report must be ingested before text extraction")
        document = self.store.documents.get(report.document_id)
        if document is None:
            raise NotFoundError(f"document {report.document_id} not found")
        citation_char_limit = self._bounded_limit(payload.get("citation_char_limit", 1200), max_value=4000)
        parser_version = str(payload.get("parser_version", "research-report-text-1"))
        text = str(payload.get("text", "")).strip()
        if not text:
            text = document.body.strip() or self._read_research_report_text(report)
        if not text:
            review = self._create_manual_review(
                document,
                issue_type="research_report_text_extraction_required",
                severity="medium",
                message="No extractable local research report text is available for citation indexing.",
                suggested_action="Run OCR/text extraction before citing this local research report.",
                actor=actor,
                parser_version=parser_version,
            )
            report.status = "needs_text_review"
            self._audit(actor, "extract_research_report_text", "research_report", report.report_id, source=report.source_id, approval_state=report.status)
            return {
                "report": to_plain(report),
                "document": to_plain(document),
                "status": report.status,
                "evidence": [],
                "manual_review": to_plain(review),
                "citation_char_limit": citation_char_limit,
            }
        limited_text, truncated = self._citation_limited_text(text, source_publicness="restricted", char_limit=citation_char_limit)
        document.body = limited_text
        evidence = self._research_report_citation_evidence(document, limited_text, parser_version=parser_version)
        for item in evidence:
            self.store.evidence[item.evidence_id] = item
        report.status = "text_indexed"
        self._audit(actor, "extract_research_report_text", "research_report", report.report_id, source=report.source_id, approval_state=report.status)
        return {
            "report": to_plain(report),
            "document": to_plain(document),
            "status": report.status,
            "evidence": [to_plain(item) for item in evidence],
            "manual_review": None,
            "citation_char_limit": citation_char_limit,
            "citation_truncated": truncated,
        }

    def extract_evidence(
        self,
        document_id: str,
        *,
        actor: str = "system",
        parser_version: str = "rule-0",
        model_version: str = "rule-0",
    ) -> list[Evidence]:
        document = self.store.documents.get(document_id)
        if document is None:
            raise NotFoundError(f"document {document_id} not found")
        source_text = document.body or self._document_object_text(document)
        chunks = chunk_text_by_page(source_text)
        fallback_error = ""
        parsed_pages: list[dict[str, Any]] = []
        locator_source = "rule_text"
        if not chunks and self.document_parser.configured():
            try:
                parsed = self._parse_document_with_paddleocr(document, retry_attempts=1)
                source_text = str(parsed.get("text", ""))
                chunks = chunk_text_by_page(source_text)
                parsed_pages = [dict(page) for page in parsed.get("pages", []) if isinstance(page, Mapping)]
                locator_source = "paddleocr"
                if chunks:
                    parser_version = f"{parser_version}+paddleocr-vl"
                    model_version = str(parsed.get("model") or model_version)
                    self._audit(
                        actor,
                        "parse_document_with_paddleocr",
                        "document",
                        document_id,
                        source="paddleocr",
                        version=str(parsed.get("job_id", "")),
                        model_version=model_version,
                    )
                else:
                    fallback_error = "PaddleOCR returned no extractable markdown"
            except ValidationError as exc:
                fallback_error = str(exc)
        if not chunks:
            message = "No extractable text was found. The file may be scanned, image-only, encrypted, or unsupported by the current parser."
            if fallback_error:
                message = f"{message} OCR fallback failed or returned no text: {fallback_error}"
            self._create_manual_review(
                document,
                issue_type="empty_or_scanned_document",
                severity="high",
                parser_version=parser_version,
                message=message,
                suggested_action="Run OCR fallback or route the document to analyst review before using it as evidence.",
                actor=actor,
            )
            raise ValidationError("document body is empty")
        created: list[Evidence] = []
        source_pages = self._evidence_source_pages(source_text, parsed_pages)
        for index, (page_no, chunk_index, chunk) in enumerate(chunks, start=1):
            locator = self._evidence_locator(
                document_id=document_id,
                page_no=page_no,
                chunk_index=chunk_index,
                chunk=chunk,
                source_pages=source_pages,
                locator_source=locator_source,
            )
            evidence = Evidence(
                evidence_id=new_id("evi"),
                document_id=document_id,
                section=f"page_{page_no}_paragraph_{chunk_index}",
                page_no=page_no,
                bbox=self._locator_bbox_string(locator, page_no=page_no, chunk_index=chunk_index),
                span_text=chunk,
                canonical_text=chunk.strip(),
                confidence=0.9 if index == 1 else 0.8,
                locator=locator,
                assets=[dict(item) for item in locator.get("assets", []) if isinstance(item, Mapping)],
            )
            self.store.evidence[evidence.evidence_id] = evidence
            created.append(evidence)
        self._audit(
            actor,
            "extract_evidence",
            "document",
            document_id,
            version=parser_version,
            model_version=model_version,
        )
        return created

    def _evidence_source_pages(self, source_text: str, parsed_pages: list[dict[str, Any]]) -> dict[int, dict[str, Any]]:
        pages: dict[int, dict[str, Any]] = {}
        for index, page_text in enumerate(source_text.split("\f"), start=1):
            pages[index] = {"page_no": index, "markdown": page_text, "layout_items": [], "tables": [], "assets": []}
        for page in parsed_pages:
            page_no = int(page.get("page_no") or len(pages) + 1)
            merged = dict(pages.get(page_no, {"page_no": page_no, "markdown": ""}))
            merged.update(page)
            pages[page_no] = merged
        return pages

    def _evidence_locator(
        self,
        *,
        document_id: str,
        page_no: int,
        chunk_index: int,
        chunk: str,
        source_pages: Mapping[int, Mapping[str, Any]],
        locator_source: str,
    ) -> dict[str, Any]:
        page = source_pages.get(page_no, {})
        page_text = str(page.get("markdown", ""))
        layout_item = self._best_layout_item(chunk, page.get("layout_items", []), chunk_index=chunk_index)
        bbox = dict(layout_item.get("bbox", {})) if isinstance(layout_item.get("bbox"), Mapping) else {}
        tables = self._matching_locator_tables(chunk, page.get("tables", []))
        assets = [dict(item) for item in page.get("assets", []) if isinstance(item, Mapping)]
        scheme = "ocr_bbox_span_v1" if bbox or tables or assets else "page_chunk_v1"
        return {
            "scheme": scheme,
            "document_id": document_id,
            "page_no": page_no,
            "chunk_index": chunk_index,
            "source": locator_source,
            "span": self._chunk_span(page_text, chunk),
            "bbox": bbox,
            "layout_type": str(layout_item.get("type", "")) if layout_item else "",
            "layout_confidence": float(layout_item.get("confidence", 0.0) or 0.0) if layout_item else 0.0,
            "tables": tables,
            "assets": assets,
            "legacy_bbox": f"page={page_no};chunk={chunk_index}",
        }

    def _chunk_span(self, page_text: str, chunk: str) -> dict[str, Any]:
        start = page_text.find(chunk) if page_text else -1
        if start < 0:
            compact_page = re.sub(r"\s+", " ", page_text)
            compact_chunk = re.sub(r"\s+", " ", chunk).strip()
            start = compact_page.find(compact_chunk) if compact_page and compact_chunk else -1
            return {
                "start": max(0, start),
                "end": max(0, start) + len(compact_chunk) if start >= 0 else len(chunk),
                "length": len(chunk),
                "matched": start >= 0,
                "text_sha256": hashlib.sha256(chunk.encode("utf-8")).hexdigest(),
            }
        return {
            "start": start,
            "end": start + len(chunk),
            "length": len(chunk),
            "matched": True,
            "text_sha256": hashlib.sha256(chunk.encode("utf-8")).hexdigest(),
        }

    def _best_layout_item(self, chunk: str, layout_items: Any, *, chunk_index: int) -> dict[str, Any]:
        if not isinstance(layout_items, list):
            return {}
        candidates = [dict(item) for item in layout_items if isinstance(item, Mapping)]
        if not candidates:
            return {}
        scored = [(self._text_overlap_score(chunk, str(item.get("text", ""))), item) for item in candidates]
        scored.sort(key=lambda item: item[0], reverse=True)
        if scored and scored[0][0] > 0:
            return scored[0][1]
        if 0 <= chunk_index - 1 < len(candidates):
            return candidates[chunk_index - 1]
        return {}

    def _text_overlap_score(self, left: str, right: str) -> float:
        left_norm = re.sub(r"\s+", " ", left).strip().lower()
        right_norm = re.sub(r"\s+", " ", right).strip().lower()
        if not left_norm or not right_norm:
            return 0.0
        if left_norm in right_norm or right_norm in left_norm:
            return min(len(left_norm), len(right_norm)) / max(1, max(len(left_norm), len(right_norm)))
        left_terms = set(re.findall(r"[\w\u4e00-\u9fff]+", left_norm))
        right_terms = set(re.findall(r"[\w\u4e00-\u9fff]+", right_norm))
        return len(left_terms & right_terms) / max(1, len(left_terms | right_terms))

    def _matching_locator_tables(self, chunk: str, tables: Any) -> list[dict[str, Any]]:
        if not isinstance(tables, list):
            return []
        matched: list[dict[str, Any]] = []
        for table in tables:
            if not isinstance(table, Mapping):
                continue
            table_copy = dict(table)
            cells = [dict(cell) for cell in table_copy.get("cells", []) if isinstance(cell, Mapping)] if isinstance(table_copy.get("cells", []), list) else []
            cell_text = " ".join(str(cell.get("text", "")) for cell in cells)
            if cells and (self._text_overlap_score(chunk, cell_text) > 0 or len(tables) == 1):
                table_copy["cells"] = cells
                matched.append(table_copy)
        return matched

    def _locator_bbox_string(self, locator: Mapping[str, Any], *, page_no: int, chunk_index: int) -> str:
        bbox = locator.get("bbox", {})
        if isinstance(bbox, Mapping) and bbox:
            coords = [bbox.get("x", 0), bbox.get("y", 0), bbox.get("width", 0), bbox.get("height", 0)]
            formatted = ",".join(self._format_locator_number(value) for value in coords)
            return f"page={page_no};chunk={chunk_index};bbox={formatted}"
        return f"page={page_no};chunk={chunk_index}"

    def _format_locator_number(self, value: Any) -> str:
        number = float(value or 0)
        return str(int(number)) if number.is_integer() else f"{number:.4f}".rstrip("0").rstrip(".")

    def manual_review_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        document_id = str(filters.get("document_id", "")).strip()
        issue_type = str(filters.get("issue_type", "")).strip()
        status = str(filters.get("status", "")).strip()
        severity = str(filters.get("severity", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 50))
        items = list(self.store.manual_reviews.values())
        if document_id:
            items = [item for item in items if item.document_id == document_id]
        if issue_type:
            items = [item for item in items if item.issue_type == issue_type]
        if status:
            items = [item for item in items if item.status == status]
        if severity:
            items = [item for item in items if item.severity == severity]
        items.sort(key=lambda item: (item.status == "open", item.updated_at), reverse=True)
        return {"manual_reviews": [to_plain(item) for item in items[:limit]]}

    def create_manual_reference(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        self.seed_default_sources(actor=actor)
        raw_text = str(payload.get("body") or payload.get("text") or payload.get("content") or "").strip()
        if raw_text:
            raise ValidationError("manual reference intake stores metadata only; do not submit private or unclear source text")
        source_id = self._canonical_source_id(str(payload.get("source_id", MANUAL_TRANSCRIPT_REFERENCE_SOURCE_ID)))
        source = self.store.sources.get(source_id)
        if source is None:
            raise NotFoundError(f"source {source_id} not found")
        if source.source_type != "manual_reference" and source.risk_level != "red":
            raise ValidationError("manual reference intake requires a manual/red source")
        document_type = str(payload.get("document_type", "transcript"))
        if source.allowed_document_types and document_type not in source.allowed_document_types:
            raise ValidationError(f"document_type {document_type} is not allowed for source {source.source_id}")
        issuer_id = str(payload.get("issuer_id", "")).strip()
        security_id = str(payload.get("security_id", "")).strip()
        if issuer_id and issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {issuer_id} not found")
        if security_id and security_id not in self.store.securities:
            raise NotFoundError(f"security {security_id} not found")
        rights_tag = source.rights_tag if "rights_tag" not in payload else type(source.rights_tag).from_dict(payload["rights_tag"])
        if not source.rights_tag.allows(rights_tag):
            raise PermissionDenied("manual reference rights exceed source rights")
        document_id = str(payload.get("document_id", new_id("manualref")))
        if document_id in self.store.documents:
            raise ConflictError(f"document {document_id} already exists")
        source_uri = str(payload.get("source_uri") or f"manual-reference://{source_id}/{document_id}")
        document = Document(
            document_id=document_id,
            issuer_id=issuer_id,
            security_id=security_id,
            document_type=document_type,
            source_id=source_id,
            source_type=source.source_type,
            source_uri=self._sanitize_source_uri(source_uri),
            rights_tag=rights_tag,
            body="",
            title=str(payload.get("title", "")),
            object_uri="",
            content_sha256="",
            published_at=parse_datetime(payload.get("published_at")) if payload.get("published_at") else utcnow(),
            language=str(payload.get("language", "mixed")),
            version="manual_reference_metadata_only",
        )
        self.store.documents[document.document_id] = document
        review = self._create_manual_review(
            document,
            issue_type="manual_reference_boundary_review",
            severity=str(payload.get("severity", "high")),
            parser_version="manual-reference-metadata",
            message=str(payload.get("notes", "Manual-only reference metadata requires compliance review before any automated ingestion.")),
            suggested_action="Confirm publicness, TOS/robots, Reg FD status, and usage boundary. Keep text outside the automated fact layer unless reclassified.",
            actor=actor,
        )
        self._audit(actor, "create_manual_reference", "document", document.document_id, source=source.source_type, version=rights_tag.license_class, approval_state=review.status)
        return {"document": to_plain(document), "manual_review": to_plain(review)}

    def citation_boundary_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        self.seed_default_sources(actor=actor)
        source_ids = self._citation_boundary_source_ids(payload)
        source_summary = self._citation_boundary_source_summary(source_ids)
        manual_summary = self._citation_boundary_manual_reference_summary()
        governance = self.research_report_governance_report(payload)
        viewpoints = self.research_report_viewpoint_report(payload)
        answers = self.research_answer_quality_report(payload)
        artifacts = self._citation_boundary_artifact_uris(payload)
        red_zone_training_records = self._citation_boundary_training_or_fact_records()
        min_review_coverage = float(payload.get("min_source_review_coverage", 1.0))
        min_answer_review_coverage = float(payload.get("min_answer_review_coverage", 1.0))
        min_answer_link_rate = float(payload.get("min_answer_source_link_rate", 1.0))
        gates = [
            self._readiness_bool_gate("canonical_sources_seeded", source_summary["canonical_sources_seeded"], "public webcast, manual transcript reference, and local research report sources are registered"),
            self._readiness_numeric_gate("source_review_coverage", source_summary["review_coverage"], min_review_coverage, ">=", "citation-boundary sources have current risk/compliance reviews"),
            self._readiness_numeric_gate("source_review_blocker_count", float(source_summary["blocker_count"]), 0.0, "==", "no TOS/robots/publicness/usage blockers on citation-boundary sources"),
            self._readiness_numeric_gate("manual_reference_body_count", float(manual_summary["manual_reference_body_count"]), 0.0, "==", "manual/private transcript references are metadata-only"),
            self._readiness_numeric_gate("manual_reference_review_coverage", manual_summary["review_coverage"], 1.0, ">=", "manual reference records have boundary review records"),
            self._readiness_numeric_gate("research_report_rights_issue_count", float(governance["stale_count"] + governance["missing_document_count"] + sum(1 for row in governance.get("reports", []) if "rights_boundary_needs_review" in row.get("issues", []))), 0.0, "==", "research reports are current, linked, and local-reference-only"),
            self._readiness_bool_gate("research_viewpoints_reference_only", viewpoints.get("automation_allowed") is False and "not_fact_source" in str(viewpoints.get("usage_boundary", "")), "research report viewpoints remain reference/opinion only"),
            self._readiness_numeric_gate("research_answer_source_link_rate", float(answers["source_link_rate"]), min_answer_link_rate, ">=", "research answers retain English source evidence and document links"),
            self._readiness_numeric_gate("research_answer_review_coverage", float(answers["review_coverage"]), min_answer_review_coverage, ">=", "research answers are human reviewed before production use"),
            self._readiness_numeric_gate("restricted_answer_missing_citation_limit", float(sum(1 for row in answers.get("answers", []) if "missing_restricted_citation_limit" in row.get("issues", []))), 0.0, "==", "restricted/local-reference answer quotes have citation length limits"),
            self._readiness_numeric_gate("red_zone_training_records", float(red_zone_training_records), 0.0, "==", "red/manual/private sources do not enter training or automated fact paths"),
            self._readiness_bool_gate("citation_policy_artifact_uri", bool(artifacts.get("citation_policy_uri")), "current transcript/research citation policy artifact URI"),
            self._readiness_bool_gate("source_review_artifact_uri", bool(artifacts.get("source_review_uri")), "source publicness/TOS/robots review artifact URI"),
            self._readiness_bool_gate("manual_reference_review_artifact_uri", bool(artifacts.get("manual_reference_review_uri")), "manual reference boundary review or reviewed-empty artifact URI"),
            self._readiness_bool_gate("research_report_governance_artifact_uri", bool(artifacts.get("research_report_governance_uri")), "research report governance/bias review or reviewed-empty artifact URI"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "ready_for_citation_boundary_production": ready,
            "ready_for_external_acceptance": ready,
            "missing_requirements": missing,
            "gates": gates,
            "source_summary": source_summary,
            "manual_reference_summary": manual_summary,
            "research_report_governance": {
                "count": governance["count"],
                "stale_count": governance["stale_count"],
                "missing_document_count": governance["missing_document_count"],
                "concentration_issues": governance["concentration_issues"],
                "automation_allowed": governance["automation_allowed"],
            },
            "research_viewpoints": {
                "count": viewpoints["count"],
                "topic_count": viewpoints["topic_count"],
                "bias_alert_count": viewpoints["bias_alert_count"],
                "automation_allowed": viewpoints["automation_allowed"],
            },
            "research_answers": {
                "total": answers["total"],
                "pending_review": answers["pending_review"],
                "source_link_rate": answers["source_link_rate"],
                "review_coverage": answers["review_coverage"],
                "citation_truncated": answers["citation_truncated"],
            },
            "red_zone_training_records": red_zone_training_records,
            "artifact_uris": artifacts,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "citation_boundary_readiness_report_keeps_transcripts_and_research_reports_as_public_or_local_reference_layers_not_fact_training_or_trade_inputs",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "citation_boundary_readiness_report", "research_boundary", "transcripts_research_reports", source="citation_governance", approval_state="ready" if ready else "missing_evidence")
        return report

    def _citation_boundary_source_ids(self, payload: Mapping[str, Any]) -> list[str]:
        raw = payload.get("source_ids", [])
        if isinstance(raw, str):
            supplied = [item for item in re.split(r"[,;/\s]+", raw) if item.strip()]
        elif isinstance(raw, list):
            supplied = [str(item) for item in raw if str(item).strip()]
        else:
            supplied = []
        defaults = ["company_public_webcast", MANUAL_TRANSCRIPT_REFERENCE_SOURCE_ID, LOCAL_RESEARCH_REPORT_SOURCE_ID]
        return self._unique_strings([self._canonical_source_id(item) for item in [*defaults, *supplied]])

    def _citation_boundary_source_summary(self, source_ids: list[str]) -> dict[str, Any]:
        rows: list[dict[str, Any]] = []
        reviewed = 0
        blocker_count = 0
        for source_id in source_ids:
            source = self.store.sources.get(source_id)
            if source is None:
                rows.append({"source_id": source_id, "present": False, "reviewed": False, "blocked_reasons": ["missing_source"]})
                blocker_count += 1
                continue
            latest_review = max(
                [review for review in self.store.source_reviews.values() if review.source_id == source_id],
                key=lambda item: parse_datetime(item.reviewed_at),
                default=None,
            )
            blockers = self._source_governance_gaps(source)
            if latest_review:
                reviewed += 1
                blockers.extend(self._source_review_blockers(latest_review))
            else:
                blockers.append("missing_review")
            if source_id in {MANUAL_TRANSCRIPT_REFERENCE_SOURCE_ID, LOCAL_RESEARCH_REPORT_SOURCE_ID}:
                allowed = (
                    source.rights_tag.training_allowed is False
                    and source.rights_tag.redistribution_allowed is False
                    and source.rights_tag.display_use == "restricted"
                    and source.rights_tag.derived_data_use == "restricted"
                    and source.usage_scope in {"manual_reference_only", "local_reference_citation_tracking_only"}
                )
                if not allowed:
                    blockers.append("manual_or_research_boundary_not_restricted")
            elif source_id == "company_public_webcast":
                if source.rights_tag.training_allowed or source.rights_tag.redistribution_allowed or source.rights_tag.derived_data_use != "restricted":
                    blockers.append("public_webcast_boundary_too_permissive")
            blocker_count += len(blockers)
            rows.append(
                {
                    "source_id": source_id,
                    "present": True,
                    "risk_level": source.risk_level,
                    "source_type": source.source_type,
                    "usage_scope": source.usage_scope,
                    "license_class": source.rights_tag.license_class,
                    "reviewed": latest_review is not None,
                    "latest_review_status": latest_review.status if latest_review else "",
                    "blocked_reasons": blockers,
                }
            )
        return {
            "source_ids": source_ids,
            "canonical_sources_seeded": all(row["present"] for row in rows),
            "reviewed_sources": reviewed,
            "review_coverage": round(reviewed / max(1, len(source_ids)), 4),
            "blocker_count": blocker_count,
            "sources": rows,
        }

    def _citation_boundary_manual_reference_summary(self) -> dict[str, Any]:
        docs = [
            document
            for document in self.store.documents.values()
            if document.source_id == MANUAL_TRANSCRIPT_REFERENCE_SOURCE_ID
            or self.store.sources.get(document.source_id, None) and self.store.sources[document.source_id].risk_level == "red"
        ]
        manual_reviews_by_doc = {
            review.document_id: review
            for review in self.store.manual_reviews.values()
            if review.issue_type == "manual_reference_boundary_review"
        }
        body_count = sum(1 for document in docs if document.body.strip())
        reviewed_count = sum(1 for document in docs if document.document_id in manual_reviews_by_doc)
        open_review_count = sum(1 for document in docs if manual_reviews_by_doc.get(document.document_id) and manual_reviews_by_doc[document.document_id].status == "open")
        return {
            "manual_reference_count": len(docs),
            "manual_reference_body_count": body_count,
            "boundary_review_count": reviewed_count,
            "open_boundary_review_count": open_review_count,
            "review_coverage": round(reviewed_count / max(1, len(docs)), 4) if docs else 1.0,
        }

    def _citation_boundary_training_or_fact_records(self) -> int:
        count = 0
        for document in self.store.documents.values():
            source = self.store.sources.get(document.source_id)
            if document.rights_tag.training_allowed:
                count += 1
                continue
            if source and source.risk_level == "red" and document.body.strip():
                count += 1
                continue
            if document.source_id == MANUAL_TRANSCRIPT_REFERENCE_SOURCE_ID and document.body.strip():
                count += 1
        for report in self.store.research_reports.values():
            source = self.store.sources.get(report.source_id)
            if report.rights_tag.training_allowed or (source and source.risk_level == "red"):
                count += 1
        return count

    def _citation_boundary_artifact_uris(self, payload: Mapping[str, Any]) -> dict[str, str]:
        aliases = {
            "citation_policy_uri": ["citation_policy_uri", "transcript_policy_uri", "research_citation_policy_uri"],
            "source_review_uri": ["source_review_uri", "source_governance_uri", "tos_robots_review_uri"],
            "manual_reference_review_uri": ["manual_reference_review_uri", "manual_boundary_review_uri", "private_transcript_review_uri"],
            "research_report_governance_uri": ["research_report_governance_uri", "research_report_review_uri", "viewpoint_bias_review_uri"],
        }
        return self._readiness_artifact_aliases(payload, aliases)

    def evidence_quality_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        documents = list(self.store.documents.values())
        if issuer_id:
            documents = [document for document in documents if document.issuer_id == issuer_id]
        document_ids = {document.document_id for document in documents}
        evidence = [item for item in self.store.evidence.values() if item.document_id in document_ids]
        located = [item for item in evidence if item.page_no > 0 and bool(item.bbox)]
        structured_located = [item for item in evidence if self._evidence_has_structured_locator(item)]
        bbox_located = [item for item in evidence if self._evidence_has_real_bbox(item)]
        table_cell_total = sum(self._evidence_table_cell_count(item) for item in evidence)
        table_cell_with_bbox = sum(self._evidence_table_cell_bbox_count(item) for item in evidence)
        asset_refs = sum(len(item.assets) for item in evidence)
        manual_reviews = [item for item in self.store.manual_reviews.values() if item.document_id in document_ids]
        open_reviews = [item for item in manual_reviews if item.status == "open"]
        issue_counts: dict[str, int] = {}
        for item in manual_reviews:
            issue_counts[item.issue_type] = issue_counts.get(item.issue_type, 0) + 1
        document_ids_with_evidence = {item.document_id for item in evidence}
        documents_with_evidence = len(document_ids_with_evidence)
        avg_confidence = sum(item.confidence for item in evidence) / len(evidence) if evidence else 0.0
        bbox_validation = self._bbox_gold_label_validation(evidence, filters)
        return {
            "issuer_id": issuer_id,
            "documents": len(documents),
            "documents_with_evidence": documents_with_evidence,
            "missing_document_ids": sorted(document_ids - document_ids_with_evidence),
            "evidence": len(evidence),
            "locator_coverage": round(len(located) / max(1, len(evidence)), 4) if evidence else 0.0,
            "structured_locator_coverage": round(len(structured_located) / max(1, len(evidence)), 4) if evidence else 0.0,
            "bbox_coverage": round(len(bbox_located) / max(1, len(evidence)), 4) if evidence else 0.0,
            "table_cell_count": table_cell_total,
            "table_cell_bbox_coverage": round(table_cell_with_bbox / max(1, table_cell_total), 4) if table_cell_total else 0.0,
            "asset_reference_count": asset_refs,
            "avg_confidence": round(avg_confidence, 4),
            "manual_reviews": len(manual_reviews),
            "open_manual_reviews": len(open_reviews),
            "parse_failure_rate": round(len({item.document_id for item in open_reviews}) / max(1, len(documents)), 4) if documents else 0.0,
            "issue_counts": issue_counts,
            "bbox_gold_validation": bbox_validation,
        }

    def _evidence_has_structured_locator(self, evidence: Evidence) -> bool:
        return isinstance(evidence.locator, Mapping) and bool(evidence.locator.get("scheme"))

    def _evidence_has_real_bbox(self, evidence: Evidence) -> bool:
        bbox = evidence.locator.get("bbox", {}) if isinstance(evidence.locator, Mapping) else {}
        return isinstance(bbox, Mapping) and {"x", "y", "width", "height"}.issubset(bbox.keys())

    def _evidence_table_cell_count(self, evidence: Evidence) -> int:
        tables = evidence.locator.get("tables", []) if isinstance(evidence.locator, Mapping) else []
        if not isinstance(tables, list):
            return 0
        return sum(len(table.get("cells", [])) for table in tables if isinstance(table, Mapping) and isinstance(table.get("cells", []), list))

    def _evidence_table_cell_bbox_count(self, evidence: Evidence) -> int:
        tables = evidence.locator.get("tables", []) if isinstance(evidence.locator, Mapping) else []
        if not isinstance(tables, list):
            return 0
        count = 0
        for table in tables:
            if not isinstance(table, Mapping):
                continue
            cells = table.get("cells", [])
            if not isinstance(cells, list):
                continue
            for cell in cells:
                bbox = cell.get("bbox", {}) if isinstance(cell, Mapping) else {}
                if isinstance(bbox, Mapping) and bbox:
                    count += 1
        return count

    def _bbox_gold_label_validation(self, evidence: list[Evidence], filters: Mapping[str, Any]) -> dict[str, Any]:
        labels = filters.get("bbox_gold_labels", filters.get("gold_labels", []))
        if labels is None:
            labels = []
        if not isinstance(labels, list):
            raise ValidationError("bbox_gold_labels must be a list when provided")
        min_iou = float(filters.get("min_bbox_iou", 0.5))
        evidence_by_id = {item.evidence_id: item for item in evidence}
        evidence_by_document_page: dict[tuple[str, int], list[Evidence]] = {}
        for item in evidence:
            evidence_by_document_page.setdefault((item.document_id, int(item.page_no or 0)), []).append(item)
        rows: list[dict[str, Any]] = []
        for index, label in enumerate(labels, start=1):
            if not isinstance(label, Mapping):
                rows.append({"label_index": index, "matched": False, "issue": "label_must_be_object", "iou": 0.0})
                continue
            expected_bbox = self._normalize_gold_bbox(label.get("bbox", label.get("expected_bbox", {})))
            expected_page = int(label.get("page_no", label.get("page", 0)) or 0)
            expected_document_id = str(label.get("document_id", "")).strip()
            candidates: list[Evidence] = []
            evidence_id = str(label.get("evidence_id", "")).strip()
            if evidence_id and evidence_id in evidence_by_id:
                candidates = [evidence_by_id[evidence_id]]
            elif expected_document_id and expected_page:
                candidates = evidence_by_document_page.get((expected_document_id, expected_page), [])
            elif expected_document_id:
                candidates = [item for item in evidence if item.document_id == expected_document_id]
            else:
                candidates = evidence
            best: tuple[float, Evidence | None, dict[str, Any]] = (0.0, None, {})
            for candidate in candidates:
                actual_bbox = self._evidence_bbox(candidate)
                iou = self._bbox_iou(actual_bbox, expected_bbox)
                if iou > best[0]:
                    best = (iou, candidate, actual_bbox)
            matched = best[0] >= min_iou
            rows.append(
                {
                    "label_index": index,
                    "document_id": expected_document_id or (best[1].document_id if best[1] else ""),
                    "page_no": expected_page,
                    "expected_bbox": expected_bbox,
                    "matched_evidence_id": best[1].evidence_id if best[1] else "",
                    "actual_bbox": best[2],
                    "iou": round(best[0], 4),
                    "matched": matched,
                    "issue": "" if matched else "bbox_iou_below_threshold_or_missing_evidence",
                }
            )
        matched_count = sum(1 for row in rows if row["matched"])
        average_iou = sum(float(row["iou"]) for row in rows) / len(rows) if rows else 0.0
        return {
            "label_count": len(rows),
            "matched_count": matched_count,
            "min_iou": min_iou,
            "bbox_hit_rate": round(matched_count / max(1, len(rows)), 4) if rows else 1.0,
            "average_iou": round(average_iou, 4),
            "failures": [row for row in rows if not row["matched"]],
            "labels": rows,
        }

    def _evidence_bbox(self, evidence: Evidence) -> dict[str, Any]:
        bbox = evidence.locator.get("bbox", {}) if isinstance(evidence.locator, Mapping) else {}
        if isinstance(bbox, Mapping) and bbox:
            return self._normalize_gold_bbox(bbox)
        return {}

    def _normalize_gold_bbox(self, value: Any) -> dict[str, Any]:
        if isinstance(value, Mapping):
            x = float(value.get("x", 0) or 0)
            y = float(value.get("y", 0) or 0)
            if "width" in value or "height" in value:
                width = float(value.get("width", 0) or 0)
                height = float(value.get("height", 0) or 0)
            else:
                width = float(value.get("right", value.get("x2", x)) or x) - x
                height = float(value.get("bottom", value.get("y2", y)) or y) - y
            return {"x": x, "y": y, "width": max(0.0, width), "height": max(0.0, height)}
        if isinstance(value, list) and len(value) >= 4:
            x1, y1, x2, y2 = [float(item or 0) for item in value[:4]]
            return {"x": x1, "y": y1, "width": max(0.0, x2 - x1), "height": max(0.0, y2 - y1)}
        return {}

    def _bbox_iou(self, left: Mapping[str, Any], right: Mapping[str, Any]) -> float:
        if not left or not right:
            return 0.0
        left_x1 = float(left.get("x", 0) or 0)
        left_y1 = float(left.get("y", 0) or 0)
        left_x2 = left_x1 + float(left.get("width", 0) or 0)
        left_y2 = left_y1 + float(left.get("height", 0) or 0)
        right_x1 = float(right.get("x", 0) or 0)
        right_y1 = float(right.get("y", 0) or 0)
        right_x2 = right_x1 + float(right.get("width", 0) or 0)
        right_y2 = right_y1 + float(right.get("height", 0) or 0)
        intersection_width = max(0.0, min(left_x2, right_x2) - max(left_x1, right_x1))
        intersection_height = max(0.0, min(left_y2, right_y2) - max(left_y1, right_y1))
        intersection = intersection_width * intersection_height
        left_area = max(0.0, left_x2 - left_x1) * max(0.0, left_y2 - left_y1)
        right_area = max(0.0, right_x2 - right_x1) * max(0.0, right_y2 - right_y1)
        union = left_area + right_area - intersection
        return intersection / union if union > 0 else 0.0

    def _create_manual_review(
        self,
        document: Document,
        *,
        issue_type: str,
        severity: str,
        parser_version: str,
        message: str,
        suggested_action: str,
        actor: str,
    ) -> ManualReviewItem:
        review_id = self._manual_review_id(document.document_id, issue_type)
        existing = self.store.manual_reviews.get(review_id)
        if existing:
            existing.status = "open"
            existing.severity = severity
            existing.parser_version = parser_version
            existing.message = message
            existing.suggested_action = suggested_action
            existing.updated_at = utcnow()
            item = existing
            action = "update_manual_review"
        else:
            item = ManualReviewItem(
                review_id=review_id,
                document_id=document.document_id,
                issue_type=issue_type,
                severity=severity,
                parser_version=parser_version,
                message=message,
                suggested_action=suggested_action,
            )
            self.store.manual_reviews[item.review_id] = item
            action = "create_manual_review"
        self._audit(actor, action, "manual_review", item.review_id, version=parser_version, approval_state=item.status)
        return item

    def _document_object_text(self, document: Document) -> str:
        if not document.object_uri:
            return ""
        try:
            data = self.object_store.read_bytes(document.object_uri)
        except (FileNotFoundError, IsADirectoryError, OSError, ValueError):
            return ""
        suffix = Path(urlparse(document.object_uri).path).suffix.lower()
        if suffix == ".pdf" or data.startswith(b"%PDF"):
            return pdf_bytes_to_text(data)
        return data.decode("utf-8", errors="ignore")

    def _document_parser_optional_payload(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        raw = payload.get("optional_payload", payload.get("optionalPayload", {}))
        if raw is None:
            return {}
        if not isinstance(raw, Mapping):
            raise ValidationError("optional_payload must be an object")
        return dict(raw)

    def _document_parse_retry_attempts(self, value: Any) -> int:
        try:
            attempts = int(value or 0)
        except (TypeError, ValueError):
            raise ValidationError("retry_attempts must be an integer") from None
        return max(0, min(3, attempts))

    def _parse_document_with_paddleocr(
        self,
        document: Document,
        *,
        optional_payload: Mapping[str, Any] | None = None,
        use_cache: bool = True,
        retry_attempts: int = 0,
    ) -> dict[str, Any]:
        cache_key = self._document_parse_cache_key("document", document.document_id, document.content_sha256 or document.object_uri or document.source_uri, optional_payload)
        if use_cache and cache_key in self.document_parse_cache:
            return {**self.document_parse_cache[cache_key], "cache_hit": True}
        started = time.perf_counter()
        if document.object_uri:
            try:
                data = self.object_store.read_bytes(document.object_uri)
            except (FileNotFoundError, IsADirectoryError, OSError, ValueError):
                data = b""
            if data:
                filename = Path(urlparse(document.object_uri).path).name or f"{document.document_id}.pdf"
                return self._cache_document_parse_result(
                    cache_key,
                    self._run_document_parse_with_retries(lambda: self.document_parser.parse_bytes(data, filename=filename, optional_payload=optional_payload), retry_attempts=retry_attempts),
                    started=started,
                    cache_enabled=use_cache,
                )
        source_uri = str(document.source_uri or "").strip()
        if source_uri.startswith(("http://", "https://")):
            return self._cache_document_parse_result(
                cache_key,
                self._run_document_parse_with_retries(lambda: self.document_parser.parse_url(source_uri, optional_payload=optional_payload), retry_attempts=retry_attempts),
                started=started,
                cache_enabled=use_cache,
            )
        raise ValidationError("document has no readable object_uri or http(s) source_uri for PaddleOCR parsing")

    def _parse_url_with_paddleocr(self, file_url: str, *, optional_payload: Mapping[str, Any] | None = None, use_cache: bool = True, retry_attempts: int = 0) -> dict[str, Any]:
        cache_key = self._document_parse_cache_key("url", file_url, file_url, optional_payload)
        if use_cache and cache_key in self.document_parse_cache:
            return {**self.document_parse_cache[cache_key], "cache_hit": True}
        started = time.perf_counter()
        return self._cache_document_parse_result(
            cache_key,
            self._run_document_parse_with_retries(lambda: self.document_parser.parse_url(file_url, optional_payload=optional_payload), retry_attempts=retry_attempts),
            started=started,
            cache_enabled=use_cache,
        )

    def _run_document_parse_with_retries(self, operation: Any, *, retry_attempts: int = 0) -> dict[str, Any]:
        max_attempts = max(1, min(4, int(retry_attempts) + 1))
        errors: list[str] = []
        for attempt in range(1, max_attempts + 1):
            try:
                result = dict(operation())
                result["retry_attempts"] = attempt - 1
                result["attempt_count"] = attempt
                if errors:
                    result["retry_errors"] = errors
                return result
            except ValidationError as exc:
                errors.append(str(exc))
                if attempt >= max_attempts:
                    raise ValidationError(f"PaddleOCR parsing failed after {max_attempts} attempt(s): {'; '.join(errors)}") from exc
        raise ValidationError("PaddleOCR parsing failed")

    def _cache_document_parse_result(self, cache_key: str, result: Mapping[str, Any], *, started: float, cache_enabled: bool) -> dict[str, Any]:
        enriched = dict(result)
        elapsed_ms = max(0, int((time.perf_counter() - started) * 1000))
        enriched["elapsed_ms"] = elapsed_ms
        enriched["cache_hit"] = False
        enriched["estimated_cost"] = round(
            float(enriched.get("page_count", 0) or 0) * env_float("AI_QUANT_PADDLEOCR_COST_PER_PAGE", 0.0, minimum=0.0),
            6,
        )
        enriched["cache_key"] = cache_key
        enriched["cached_at"] = to_plain(utcnow())
        if cache_enabled:
            self.document_parse_cache[cache_key] = dict(enriched)
        return enriched

    def _document_parse_cache_key(self, resource_type: str, resource_id: str, version: str, optional_payload: Mapping[str, Any] | None) -> str:
        material = {
            "provider": "paddleocr",
            "model": self.document_parser.model,
            "resource_type": resource_type,
            "resource_id": resource_id,
            "version": version,
            "optional_payload": dict(optional_payload or {}),
        }
        raw = json.dumps(material, ensure_ascii=False, sort_keys=True, default=str)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def create_thesis(
        self,
        payload: Mapping[str, Any],
        *,
        actor: str = "system",
    ) -> ThesisCard:
        evidence_ids = list(payload.get("evidence_ids", []))
        if not evidence_ids:
            raise ValidationError("thesis requires evidence")
        for evidence_id in evidence_ids:
            if evidence_id not in self.store.evidence:
                raise NotFoundError(f"evidence {evidence_id} not found")
        thesis_id = str(payload.get("thesis_id", new_id("thesis")))
        if thesis_id in self.store.theses:
            raise ConflictError(f"thesis {thesis_id} already exists")
        thesis = ThesisCard(
            thesis_id=thesis_id,
            issuer_id=str(payload["issuer_id"]),
            horizon=str(payload.get("horizon", "mid")),
            hypothesis=str(payload["hypothesis"]),
            catalyst=list(payload.get("catalyst", [])),
            evidence_ids=evidence_ids,
            falsifiers=list(payload.get("falsifiers", [])),
            risk_factors=list(payload.get("risk_factors", [])),
            confidence=float(payload.get("confidence", 0.0)),
            owner=str(payload.get("owner", actor)),
            status=str(payload.get("status", "draft")),
        )
        if thesis.issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {thesis.issuer_id} not found")
        self.store.theses[thesis.thesis_id] = thesis
        self._audit(actor, "create_thesis", "thesis", thesis.thesis_id)
        return thesis

    def run_scoring(self, payload: Mapping[str, Any], *, actor: str = "system") -> ResearchSignal:
        thesis_id = str(payload["thesis_id"])
        strategy_type = str(payload.get("strategy_type", "long"))
        thesis = self.store.theses.get(thesis_id)
        if thesis is None:
            raise NotFoundError(f"thesis {thesis_id} not found")
        evidence_docs = [self.store.documents[self.store.evidence[eid].document_id] for eid in thesis.evidence_ids]
        factor_scores = dict(payload.get("factor_scores", {}))
        profile_id = str(payload.get("profile_id", ""))
        profile = self.store.scorecards.get(profile_id) if profile_id else None
        if profile and factor_scores:
            total_weight = sum(float(weight) for weight in profile.weights.values()) or 1.0
            raw_score = sum(float(profile.weights.get(name, 0.0)) * float(value) for name, value in factor_scores.items()) / total_weight
            score = max(0.0, min(1.0, raw_score))
            long_threshold = profile.threshold_long
            short_threshold = profile.threshold_short
        else:
            source_weights = {
                "regulatory": 0.18,
                "exchange": 0.16,
                "company_ir": 0.12,
                "public_market_data": 0.08,
                "local_reference": 0.04,
            }
            base = 0.25 + min(0.4, 0.08 * len(thesis.evidence_ids))
            source_bonus = sum(source_weights.get(doc.source_type, 0.05) for doc in evidence_docs) / max(1, len(evidence_docs))
            falsifier_penalty = 0.1 * len(thesis.falsifiers)
            thesis_penalty = 0.05 if thesis.status not in {"review", "approved"} else 0.0
            score = max(0.0, min(1.0, base + source_bonus - falsifier_penalty - thesis_penalty))
            long_threshold = 0.55
            short_threshold = 0.55
        if strategy_type == "short":
            direction = "short" if score >= short_threshold else "neutral"
            signal_type = "event"
        elif strategy_type == "long":
            direction = "long" if score >= long_threshold else "neutral"
            signal_type = "value"
        else:
            direction = "neutral"
            signal_type = strategy_type
        signal = ResearchSignal(
            signal_id=str(payload.get("signal_id", new_id("sig"))),
            thesis_id=thesis_id,
            signal_type=signal_type,
            direction=direction,
            score=score,
            source_model=str(payload.get("source_model", "rules")),
            model_version=str(payload.get("model_version", "v1")),
            rationale=str(payload.get("rationale", "")),
            profile_id=profile.profile_id if profile else "",
            factor_scores=factor_scores,
        )
        self.store.signals[signal.signal_id] = signal
        thesis.confidence = score
        thesis.status = "review" if score >= 0.45 else thesis.status
        self._audit(actor, "run_scoring", "thesis", thesis_id, model_version=signal.model_version)
        return signal

    def build_decision_pack(self, payload: Mapping[str, Any], *, actor: str = "system") -> DecisionPack:
        signal_ids = list(payload.get("signal_ids", []))
        if not signal_ids:
            raise ValidationError("decision pack requires signal_ids")
        for signal_id in signal_ids:
            if signal_id not in self.store.signals:
                raise NotFoundError(f"signal {signal_id} not found")
        source_labels = {str(item).lower() for item in payload.get("source_labels", [])}
        if "private" in source_labels or "non_public" in source_labels:
            raise ComplianceGateError("Reg FD gate blocked non-public source")
        if payload.get("non_display_requested") and not payload.get("non_display_approved", False):
            raise ComplianceGateError("non-display gate blocked request")
        pack = DecisionPack(
            decision_id=str(payload.get("decision_id", new_id("dec"))),
            signal_ids=signal_ids,
            risk_checks=list(payload.get("risk_checks", [])),
            red_team_note=str(payload.get("red_team_note", "")),
        )
        self.store.decisions[pack.decision_id] = pack
        self._audit(actor, "build_decision_pack", "decision", pack.decision_id)
        return pack

    def sign_decision(self, decision_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> DecisionPack:
        pack = self.store.decisions.get(decision_id)
        if pack is None:
            raise NotFoundError(f"decision {decision_id} not found")
        signature = DecisionSignature(
            role=str(payload["role"]),
            user=str(payload["user"]),
            comment=str(payload.get("comment", "")),
        )
        pack.signatures.append(signature)
        pack.approval_state = self._decision_state(pack)
        self._audit(actor, "sign_decision", "decision", decision_id, approval_state=pack.approval_state)
        return pack

    def create_exception(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        decision_id = str(payload["decision_id"])
        if decision_id not in self.store.decisions:
            raise NotFoundError(f"decision {decision_id} not found")
        exception = ExceptionItem(
            exception_id=str(payload.get("exception_id", new_id("exc"))),
            decision_id=decision_id,
            reason=str(payload.get("reason", "")),
            severity=str(payload.get("severity", "medium")),
        )
        self.store.exceptions[exception.exception_id] = exception
        self._audit(actor, "create_exception", "decision", decision_id, approval_state="exception")
        return to_plain(exception)

    def create_execution_intent(self, payload: Mapping[str, Any], *, actor: str = "system") -> ExecutionIntent:
        decision_id = str(payload["decision_id"])
        decision = self.store.decisions.get(decision_id)
        if decision is None:
            raise NotFoundError(f"decision {decision_id} not found")
        if decision.approval_state != "approved":
            raise ComplianceGateError("unsigned decision cannot enter execution intent")
        security_id = str(payload.get("security_id", ""))
        if security_id and security_id not in self.store.securities:
            raise NotFoundError(f"security {security_id} not found")
        intent = ExecutionIntent(
            intent_id=str(payload.get("intent_id", new_id("intent"))),
            decision_id=decision_id,
            action=str(payload["action"]),
            security_id=security_id,
            target_weight=float(payload.get("target_weight", 0.0)),
            rationale=str(payload.get("rationale", "")),
            status=str(payload.get("status", "draft")),
            created_by=str(payload.get("created_by", actor)),
        )
        if intent.intent_id in self.store.execution_intents:
            raise ConflictError(f"execution intent {intent.intent_id} already exists")
        self.store.execution_intents[intent.intent_id] = intent
        self._audit(actor, "create_execution_intent", "execution_intent", intent.intent_id, approval_state=decision.approval_state)
        return intent

    def simulate_execution_intent(self, intent_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        mode = str(payload.get("mode", "simulated")).strip()
        if mode != "simulated":
            raise ComplianceGateError("only simulated execution is supported; live broker routing is blocked")
        intent = self.store.execution_intents.get(intent_id)
        if intent is None:
            raise NotFoundError(f"execution intent {intent_id} not found")
        decision = self.store.decisions.get(intent.decision_id)
        if decision is None or decision.approval_state != "approved":
            raise ComplianceGateError("execution simulation requires an approved decision")
        if intent.security_id not in self.store.securities:
            raise NotFoundError(f"security {intent.security_id} not found")
        side = str(payload.get("side", intent.action)).strip().lower()
        if side not in {"buy", "sell"}:
            raise ValidationError("simulated execution side must be buy or sell")
        quantity = float(payload.get("quantity", 0.0))
        if quantity <= 0:
            raise ValidationError("simulated execution quantity must be positive")
        trade_date = str(payload.get("trade_date", utcnow().date().isoformat()))
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", trade_date):
            raise ValidationError("trade_date must use YYYY-MM-DD")
        self.seed_default_sources(actor=actor)
        price = payload.get("fill_price", payload.get("price"))
        if price is None:
            point = self._latest_market_data_point(
                intent.security_id,
                source_id=str(payload.get("market_data_source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)),
                data_type=str(payload.get("data_type", "eod")),
                as_of_date=trade_date,
            )
            if point is None:
                raise ValidationError("fill_price is required when no public EOD price is available")
            price = point.close
        fill_price = float(price)
        slippage_bps = float(payload.get("slippage_bps", 0.0))
        if slippage_bps:
            multiplier = 1.0 + (slippage_bps / 10000.0 if side == "buy" else -slippage_bps / 10000.0)
            fill_price *= multiplier
        fees = float(payload.get("fees", 0.0))
        if fill_price < 0 or fees < 0:
            raise ValidationError("fill price and fees must be non-negative")
        execution_id = str(payload.get("execution_id", new_id("simexec")))
        if execution_id in self.store.simulated_executions:
            raise ConflictError(f"simulated execution {execution_id} already exists")
        transaction_id = str(payload.get("transaction_id", f"ptxn_{execution_id}"))
        transaction = self.register_portfolio_transaction(
            {
                "transaction_id": transaction_id,
                "security_id": intent.security_id,
                "trade_date": trade_date,
                "side": side,
                "quantity": quantity,
                "price": fill_price,
                "currency": str(payload.get("currency", self.store.securities[intent.security_id].currency)),
                "fees": fees,
                "source_id": SIMULATED_TRADE_SOURCE_ID,
                "account_id": str(payload.get("account_id", "simulated_account")),
                "strategy_id": str(payload.get("strategy_id", intent.decision_id)),
            },
            actor=actor,
        )
        execution = SimulatedExecution(
            execution_id=execution_id,
            intent_id=intent.intent_id,
            transaction_id=transaction.transaction_id,
            mode="simulated",
            status="filled",
            fill_price=round(fill_price, 8),
            quantity=quantity,
            notional=round(quantity * fill_price, 8),
            slippage_bps=slippage_bps,
            fees=fees,
            account_id=transaction.account_id,
            simulator_version=str(payload.get("simulator_version", "sim-v1")),
            live_execution_allowed=False,
            created_by=str(payload.get("created_by", actor)),
        )
        self.store.simulated_executions[execution.execution_id] = execution
        intent.status = "simulated_filled"
        self._audit(
            actor,
            "simulate_execution_intent",
            "simulated_execution",
            execution.execution_id,
            source="simulated_execution",
            approval_state=f"filled;intent={intent.intent_id};transaction={transaction.transaction_id}",
        )
        return {
            "execution": to_plain(execution),
            "transaction": to_plain(transaction),
            "intent": to_plain(intent),
            "mode": "simulated",
            "live_execution_allowed": False,
            "usage_boundary": "simulated_trade_only_no_broker_order_or_live_execution",
        }

    def simulated_executions_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        intent_id = str(filters.get("intent_id", "")).strip()
        account_id = str(filters.get("account_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        executions = list(self.store.simulated_executions.values())
        if intent_id:
            executions = [item for item in executions if item.intent_id == intent_id]
        if account_id:
            executions = [item for item in executions if item.account_id == account_id]
        if status:
            executions = [item for item in executions if item.status == status]
        executions.sort(key=lambda item: (item.created_at, item.execution_id), reverse=True)
        return {
            "total": len(executions),
            "executions": [to_plain(item) for item in executions[:limit]],
            "live_execution_allowed": False,
            "usage_boundary": "simulated_trade_only_no_broker_order_or_live_execution",
        }

    def create_review(self, payload: Mapping[str, Any], *, actor: str = "system") -> ReviewRecord:
        decision_id = str(payload["decision_id"])
        if decision_id not in self.store.decisions:
            raise NotFoundError(f"decision {decision_id} not found")
        review_id = str(payload.get("review_id", new_id("rev")))
        if review_id in self.store.reviews:
            raise ConflictError(f"review {review_id} already exists")
        review = ReviewRecord(
            review_id=review_id,
            decision_id=decision_id,
            realized_outcome=str(payload.get("realized_outcome", "")),
            attribution=str(payload.get("attribution", "")),
            lesson=str(payload.get("lesson", "")),
            next_action=str(payload.get("next_action", "")),
        )
        self.store.reviews[review.review_id] = review
        self._audit(actor, "create_review", "review", review.review_id)
        return review

    def generate_operating_report(self, payload: Mapping[str, Any], *, actor: str = "system") -> OperatingReport:
        period = str(payload["period"])
        report_id = str(payload.get("report_id", f"opr_{period.replace('-', '_')}"))
        if report_id in self.store.operating_reports:
            raise ConflictError(f"operating report {report_id} already exists")
        pending_decisions = sum(1 for decision in self.store.decisions.values() if decision.approval_state == "pending")
        approved_decisions = sum(1 for decision in self.store.decisions.values() if decision.approval_state == "approved")
        theses_with_evidence = sum(1 for thesis in self.store.theses.values() if thesis.evidence_ids)
        evidence_coverage = theses_with_evidence / max(1, len(self.store.theses))
        pending_prompts = sum(1 for request in self.store.prompt_changes.values() if request.status == "pending")
        open_exceptions = [item for item in self.store.exceptions.values() if item.status == "open"]
        challenger_coverage = len({item.thesis_id for item in self.store.challengers.values()}) / max(1, len(self.store.theses))
        metrics = {
            "sources": len(self.store.sources),
            "issuers": len(self.store.issuers),
            "documents": len(self.store.documents),
            "evidence": len(self.store.evidence),
            "theses": len(self.store.theses),
            "signals": len(self.store.signals),
            "pending_decisions": pending_decisions,
            "approved_decisions": approved_decisions,
            "execution_intents": len(self.store.execution_intents),
            "simulated_executions": len(self.store.simulated_executions),
            "portfolio_transactions": len(self.store.portfolio_transactions),
            "reviews": len(self.store.reviews),
            "audit_events": len(self.store.audit_log),
            "evidence_coverage": round(evidence_coverage, 4),
            "challenger_coverage": round(challenger_coverage, 4),
            "pending_prompt_changes": pending_prompts,
            "open_exceptions": len(open_exceptions),
        }
        red_flags: list[dict[str, Any]] = []
        if open_exceptions:
            red_flags.append({"type": "open_exceptions", "count": len(open_exceptions), "owner": "风险/合规", "due": "next_review"})
        if pending_decisions:
            red_flags.append({"type": "pending_decisions", "count": pending_decisions, "owner": "CIO", "due": "committee"})
        if pending_prompts:
            red_flags.append({"type": "pending_prompt_changes", "count": pending_prompts, "owner": "NLP/ML 负责人", "due": "before_release"})
        if evidence_coverage < 0.95 and self.store.theses:
            red_flags.append({"type": "low_evidence_coverage", "value": round(evidence_coverage, 4), "owner": "分析师", "due": "month_end"})
        if challenger_coverage < 1.0 and self.store.theses:
            red_flags.append({"type": "low_challenger_coverage", "value": round(challenger_coverage, 4), "owner": "风险/合规", "due": "month_end"})
        all_red_flags = list(payload.get("red_flags", [])) + red_flags
        all_red_flags = [self._normalize_operating_red_flag(item, report_id=report_id, index=index, period=period) for index, item in enumerate(all_red_flags, start=1)]
        report = OperatingReport(
            report_id=report_id,
            period=period,
            metrics=dict(payload.get("metrics", {})) | self._performance_metrics(payload) | metrics,
            red_flags=all_red_flags,
            owner=str(payload.get("owner", actor)),
            status=str(payload.get("status", "draft")),
        )
        self.store.operating_reports[report.report_id] = report
        self._audit(actor, "generate_operating_report", "operating_report", report.report_id)
        return report

    def publish_operating_report(self, report_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> OperatingReport:
        report = self.store.operating_reports.get(report_id)
        if report is None:
            raise NotFoundError(f"operating report {report_id} not found")
        if report.status == "published":
            raise ConflictError(f"operating report {report_id} already published")
        approver_role = str(payload.get("approver_role", "CEO"))
        if approver_role not in {"CEO", "CIO", "风险/合规"}:
            raise PermissionDenied("operating report publish requires CEO, CIO, or risk approval")
        report.approvals.append(
            {
                "role": approver_role,
                "user": str(payload.get("user", actor)),
                "comment": str(payload.get("comment", "")),
                "signed_at": to_plain(utcnow()),
            }
        )
        report.status = "published"
        report.published_at = utcnow()
        self._audit(actor, "publish_operating_report", "operating_report", report.report_id, approval_state=report.status)
        return report

    def export_operating_report_board_pack(self, report_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        report = self.store.operating_reports.get(report_id)
        if report is None:
            raise NotFoundError(f"operating report {report_id} not found")
        if report.status != "published" and not self._truthy(payload.get("allow_draft", False)):
            raise ComplianceGateError("operating report must be published before board pack export")
        format_name = str(payload.get("format", "markdown")).strip().lower()
        if format_name not in {"markdown", "md", "pdf"}:
            raise ValidationError("board pack format must be markdown or pdf")
        content = self._operating_report_board_pack_markdown(report)
        object_id = str(payload.get("object_id", f"{report.report_id}_board_pack"))
        if format_name == "pdf":
            data = self._board_pack_pdf_bytes(content)
            stored = self.object_store.put_bytes("operating_reports", object_id, data, suffix=".pdf")
            response_format = "pdf"
            content_type = "application/pdf"
        else:
            stored = self.object_store.put_text("operating_reports", object_id, content, suffix=".md")
            response_format = "markdown"
            content_type = "text/markdown; charset=utf-8"
        self._audit(
            actor,
            "export_operating_report_board_pack",
            "operating_report",
            report.report_id,
            source="object_store",
            approval_state=report.status,
        )
        return {
            "report_id": report.report_id,
            "period": report.period,
            "status": report.status,
            "format": response_format,
            "source_format": "markdown",
            "content_type": content_type,
            "object_uri": stored.uri,
            "sha256": stored.sha256,
            "size_bytes": stored.size_bytes,
            "content": content if self._truthy(payload.get("include_content", True)) else "",
        }

    def resolve_operating_report_red_flag(self, report_id: str, red_flag_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> OperatingReport:
        report = self.store.operating_reports.get(report_id)
        if report is None:
            raise NotFoundError(f"operating report {report_id} not found")
        for item in report.red_flags:
            if str(item.get("red_flag_id", "")) == red_flag_id:
                item["status"] = str(payload.get("status", "resolved"))
                item["resolution"] = str(payload.get("resolution", ""))
                item["resolved_by"] = str(payload.get("resolved_by", actor))
                item["resolved_at"] = to_plain(utcnow())
                self._audit(actor, "resolve_operating_report_red_flag", "operating_report", report.report_id, approval_state=item["status"])
                return report
        raise NotFoundError(f"red flag {red_flag_id} not found")

    def operating_report_red_flag_reminders(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        as_of_date = str(filters.get("as_of_date", utcnow().date().isoformat()))
        owner = str(filters.get("owner", "")).strip()
        status = str(filters.get("status", "open")).strip()
        reminders: list[dict[str, Any]] = []
        for report in self.store.operating_reports.values():
            for item in report.red_flags:
                if owner and str(item.get("owner", "")) != owner and str(item.get("owner_role", "")) != owner:
                    continue
                if status and str(item.get("status", "")) != status:
                    continue
                due_date = str(item.get("due_date", ""))
                reminders.append(
                    {
                        "report_id": report.report_id,
                        "period": report.period,
                        "red_flag_id": item.get("red_flag_id", ""),
                        "type": item.get("type", ""),
                        "owner": item.get("owner", ""),
                        "owner_role": item.get("owner_role", item.get("owner", "")),
                        "due_date": due_date,
                        "status": item.get("status", ""),
                        "overdue": bool(due_date and due_date < as_of_date and item.get("status") == "open"),
                    }
                )
        reminders.sort(key=lambda item: (not item["overdue"], item["due_date"], item["report_id"]))
        return {
            "as_of_date": as_of_date,
            "total": len(reminders),
            "overdue": sum(1 for item in reminders if item["overdue"]),
            "reminders": reminders,
        }

    def _performance_metrics(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        metrics: dict[str, Any] = {}
        portfolio_returns = self._float_series(payload.get("portfolio_returns") or payload.get("returns"))
        if not portfolio_returns:
            portfolio_returns = self._returns_from_values(payload.get("portfolio_values") or payload.get("nav_series"))
        benchmark_returns = self._float_series(payload.get("benchmark_returns"))
        if not benchmark_returns:
            benchmark_returns = self._returns_from_values(payload.get("benchmark_values"))

        if portfolio_returns:
            total_return = self._compound_return(portfolio_returns)
            metrics.update(
                {
                    "period_count": len(portfolio_returns),
                    "total_return": round(total_return, 4),
                    "twr": round(total_return, 4),
                    "max_drawdown": round(self._max_drawdown(portfolio_returns), 4),
                }
            )
        if benchmark_returns:
            metrics["benchmark_return"] = round(self._compound_return(benchmark_returns), 4)
        if portfolio_returns and benchmark_returns:
            active_returns = [left - right for left, right in zip(portfolio_returns, benchmark_returns)]
            if active_returns:
                active_return = self._compound_return(portfolio_returns[: len(active_returns)]) - self._compound_return(benchmark_returns[: len(active_returns)])
                metrics["active_return"] = round(active_return, 4)
                active_mean = sum(active_returns) / len(active_returns)
                variance = sum((item - active_mean) ** 2 for item in active_returns) / len(active_returns)
                metrics["information_ratio"] = round(active_mean / (variance**0.5), 4) if variance > 0 else 0.0

        turnover = self._turnover_metric(payload)
        if turnover is not None:
            metrics["turnover"] = round(turnover, 4)
        attribution = payload.get("attribution")
        if isinstance(attribution, Mapping):
            metrics["attribution"] = dict(attribution)
        return metrics

    def _float_series(self, value: Any) -> list[float]:
        if not isinstance(value, list):
            return []
        values: list[float] = []
        for item in value:
            try:
                values.append(float(item))
            except (TypeError, ValueError):
                continue
        return values

    def _returns_from_values(self, value: Any) -> list[float]:
        values = self._float_series(value)
        returns: list[float] = []
        for previous, current in zip(values, values[1:]):
            if previous:
                returns.append((current / previous) - 1)
        return returns

    def _compound_return(self, returns: list[float]) -> float:
        compounded = 1.0
        for value in returns:
            compounded *= 1 + value
        return compounded - 1

    def _max_drawdown(self, returns: list[float]) -> float:
        peak = 1.0
        value = 1.0
        max_drawdown = 0.0
        for item in returns:
            value *= 1 + item
            peak = max(peak, value)
            if peak:
                max_drawdown = max(max_drawdown, (peak - value) / peak)
        return max_drawdown

    def _series_volatility(self, returns: list[float]) -> float:
        if len(returns) < 2:
            return 0.0
        mean_return = sum(returns) / len(returns)
        variance = sum((item - mean_return) ** 2 for item in returns) / (len(returns) - 1)
        return variance ** 0.5

    def _turnover_metric(self, payload: Mapping[str, Any]) -> float | None:
        if "turnover" in payload:
            try:
                return float(payload["turnover"])
            except (TypeError, ValueError):
                return None
        if "traded_value" in payload and ("average_nav" in payload or "average_gross_exposure" in payload):
            try:
                denominator = float(payload.get("average_nav") or payload.get("average_gross_exposure"))
                return float(payload["traded_value"]) / denominator if denominator else None
            except (TypeError, ValueError):
                return None
        positions = payload.get("positions") or payload.get("holdings")
        if isinstance(positions, list):
            total_change = 0.0
            seen = False
            for item in positions:
                if not isinstance(item, Mapping):
                    continue
                try:
                    current = float(item.get("weight", item.get("target_weight", 0.0)))
                    previous = float(item.get("previous_weight", 0.0))
                except (TypeError, ValueError):
                    continue
                total_change += abs(current - previous)
                seen = True
            if seen:
                return total_change / 2
        return None

    def _portfolio_universe(self, payload: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
        universe = payload.get("securities", [])
        if not isinstance(universe, list) or not universe:
            raise ValidationError("portfolio optimizer requires a non-empty securities list")
        securities: dict[str, dict[str, Any]] = {}
        for item in universe:
            if not isinstance(item, Mapping):
                continue
            security_id = str(item.get("security_id", ""))
            security = self.store.securities.get(security_id)
            if security is None:
                raise NotFoundError(f"security {security_id} not found")
            volatility = max(float(item.get("volatility", 0.2)), 0.0001)
            securities[security_id] = {
                "security_id": security_id,
                "market_weight": max(0.0, float(item.get("market_weight", 0.0))),
                "variance": volatility * volatility,
                "volatility": volatility,
                "market": str(item.get("market", security.market or "unknown")),
                "industry": str(item.get("industry", "unclassified")),
                "theme": str(item.get("theme", "")),
                "currency": str(item.get("currency", security.currency or "")),
            }
        if not securities:
            raise ValidationError("portfolio optimizer requires at least one valid security")
        return securities

    def _apply_portfolio_constraints(
        self,
        scores: Mapping[str, float],
        securities: Mapping[str, dict[str, Any]],
        constraints: Mapping[str, Any],
        risk_budget: Mapping[str, Any],
    ) -> dict[str, float]:
        restricted = {str(item) for item in constraints.get("restricted_securities", [])}
        max_weight = float(constraints.get("max_weight", 1.0))
        caps = {security_id: (0.0 if security_id in restricted else max_weight) for security_id in securities}
        weights = self._normalize_scores_with_caps(scores, caps)
        market_budget = self._budget_map(constraints.get("market_budget") or risk_budget.get("market") or risk_budget.get("markets"))
        industry_budget = self._budget_map(constraints.get("industry_budget") or risk_budget.get("industry") or risk_budget.get("industries"))
        theme_budget = self._budget_map(constraints.get("theme_budget") or risk_budget.get("theme") or risk_budget.get("themes"))
        currency_budget = self._budget_map(constraints.get("currency_budget") or risk_budget.get("currency") or risk_budget.get("currencies"))
        weights = self._apply_group_budget(weights, securities, caps, "market", market_budget)
        weights = self._apply_group_budget(weights, securities, caps, "industry", industry_budget)
        weights = self._apply_group_budget(weights, securities, caps, "theme", theme_budget)
        weights = self._apply_group_budget(weights, securities, caps, "currency", currency_budget)
        return weights

    def _normalize_scores_with_caps(self, scores: Mapping[str, float], caps: Mapping[str, float]) -> dict[str, float]:
        result = {security_id: 0.0 for security_id in scores}
        active = {security_id for security_id, cap in caps.items() if cap > 0}
        remaining = min(1.0, sum(caps[security_id] for security_id in active))
        base = {security_id: max(0.0, float(scores.get(security_id, 0.0))) for security_id in scores}
        if sum(base[security_id] for security_id in active) <= 0:
            base = {security_id: 1.0 for security_id in active}
        while active and remaining > 0:
            total = sum(base.get(security_id, 0.0) for security_id in active)
            if total <= 0:
                break
            capped = False
            for security_id in list(active):
                proposed = remaining * base.get(security_id, 0.0) / total
                if proposed > caps[security_id]:
                    result[security_id] = caps[security_id]
                    remaining -= caps[security_id]
                    active.remove(security_id)
                    capped = True
            if not capped:
                for security_id in active:
                    result[security_id] = remaining * base.get(security_id, 0.0) / total
                break
        return result

    def _budget_map(self, value: Any) -> dict[str, float]:
        if not isinstance(value, Mapping):
            return {}
        budget: dict[str, float] = {}
        for key, raw in value.items():
            try:
                budget[str(key)] = max(0.0, float(raw))
            except (TypeError, ValueError):
                continue
        return budget

    def _apply_group_budget(
        self,
        weights: dict[str, float],
        securities: Mapping[str, dict[str, Any]],
        caps: Mapping[str, float],
        group_key: str,
        budgets: Mapping[str, float],
    ) -> dict[str, float]:
        if not budgets:
            return weights
        adjusted = dict(weights)
        for _ in range(4):
            changed = False
            for group, budget in budgets.items():
                group_ids = [security_id for security_id, item in securities.items() if item.get(group_key) == group]
                total = sum(adjusted.get(security_id, 0.0) for security_id in group_ids)
                if total <= budget or total <= 0:
                    continue
                scale = budget / total
                freed = 0.0
                for security_id in group_ids:
                    old_weight = adjusted.get(security_id, 0.0)
                    adjusted[security_id] = old_weight * scale
                    freed += old_weight - adjusted[security_id]
                recipients = [security_id for security_id in adjusted if security_id not in group_ids and adjusted[security_id] < caps.get(security_id, 0.0)]
                self._redistribute_weight(adjusted, recipients, freed, caps)
                changed = True
            if not changed:
                break
        return adjusted

    def _redistribute_weight(self, weights: dict[str, float], recipients: list[str], amount: float, caps: Mapping[str, float]) -> None:
        remaining = amount
        while recipients and remaining > 1e-12:
            slack = {security_id: max(0.0, caps.get(security_id, 0.0) - weights.get(security_id, 0.0)) for security_id in recipients}
            total_slack = sum(slack.values())
            if total_slack <= 0:
                return
            moved = 0.0
            for security_id in list(recipients):
                add = min(slack[security_id], remaining * slack[security_id] / total_slack)
                weights[security_id] += add
                moved += add
                if weights[security_id] >= caps.get(security_id, 0.0) - 1e-12:
                    recipients.remove(security_id)
            remaining -= moved

    def _portfolio_group_exposure(self, weights: Mapping[str, float], securities: Mapping[str, dict[str, Any]], group_key: str) -> dict[str, float]:
        exposure: dict[str, float] = {}
        for security_id, weight in weights.items():
            group = str(securities[security_id].get(group_key, "unknown"))
            exposure[group] = exposure.get(group, 0.0) + float(weight)
        return {key: round(value, 6) for key, value in sorted(exposure.items())}

    def _portfolio_constraint_shadow_prices(
        self,
        unconstrained_weights: Mapping[str, float],
        constrained_weights: Mapping[str, float],
        securities: Mapping[str, dict[str, Any]],
        constraints: Mapping[str, Any],
        risk_budget: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        restricted = {str(item) for item in constraints.get("restricted_securities", [])}
        max_weight = float(constraints.get("max_weight", 1.0))
        for security_id, weight in constrained_weights.items():
            desired = float(unconstrained_weights.get(security_id, 0.0))
            reduction = max(0.0, desired - float(weight))
            if security_id in restricted or (max_weight < 1.0 and abs(float(weight) - max_weight) <= 1e-6) or reduction > 1e-6:
                rows.append(
                    {
                        "constraint": "restricted_security" if security_id in restricted else "max_weight",
                        "scope": security_id,
                        "limit": 0.0 if security_id in restricted else round(max_weight, 6),
                        "exposure": round(float(weight), 6),
                        "unconstrained_exposure": round(desired, 6),
                        "binding": security_id in restricted or abs(float(weight) - max_weight) <= 1e-6,
                        "shadow_price": round(reduction, 6),
                    }
                )
        budget_sources = {
            "market": self._budget_map(constraints.get("market_budget") or risk_budget.get("market") or risk_budget.get("markets")),
            "industry": self._budget_map(constraints.get("industry_budget") or risk_budget.get("industry") or risk_budget.get("industries")),
            "theme": self._budget_map(constraints.get("theme_budget") or risk_budget.get("theme") or risk_budget.get("themes")),
            "currency": self._budget_map(constraints.get("currency_budget") or risk_budget.get("currency") or risk_budget.get("currencies")),
        }
        for group_key, budgets in budget_sources.items():
            if not budgets:
                continue
            constrained_exposure = self._portfolio_group_exposure(constrained_weights, securities, group_key)
            unconstrained_exposure = self._portfolio_group_exposure(unconstrained_weights, securities, group_key)
            for group, limit in budgets.items():
                exposure = float(constrained_exposure.get(group, 0.0))
                desired = float(unconstrained_exposure.get(group, 0.0))
                reduction = max(0.0, desired - exposure)
                binding = abs(exposure - float(limit)) <= 1e-6 and desired > exposure
                if binding or reduction > 1e-6:
                    rows.append(
                        {
                            "constraint": f"{group_key}_budget",
                            "scope": group,
                            "limit": round(float(limit), 6),
                            "exposure": round(exposure, 6),
                            "unconstrained_exposure": round(desired, 6),
                            "binding": binding,
                            "shadow_price": round(reduction, 6),
                        }
                    )
        rows.sort(key=lambda item: (-float(item["shadow_price"]), item["constraint"], item["scope"]))
        return rows

    def _portfolio_risk_contribution(self, weights: Mapping[str, float], securities: Mapping[str, dict[str, Any]]) -> dict[str, float]:
        raw = {
            security_id: max(0.0, float(weight)) * securities[security_id]["volatility"]
            for security_id, weight in weights.items()
        }
        total = sum(raw.values())
        if total <= 0:
            return {security_id: 0.0 for security_id in weights}
        return {security_id: round(value / total, 6) for security_id, value in raw.items()}

    def _portfolio_turnover(self, weights: Mapping[str, float], current_weights: Any) -> float:
        if not isinstance(current_weights, Mapping):
            return 0.0
        all_ids = set(weights) | {str(key) for key in current_weights}
        total = 0.0
        for security_id in all_ids:
            try:
                current = float(current_weights.get(security_id, 0.0))
            except (TypeError, ValueError):
                current = 0.0
            total += abs(float(weights.get(security_id, 0.0)) - current)
        return total / 2

    def _portfolio_stress_report(self, weights: Mapping[str, float], scenarios: Any) -> list[dict[str, Any]]:
        if not isinstance(scenarios, list):
            return []
        report: list[dict[str, Any]] = []
        for scenario in scenarios:
            if not isinstance(scenario, Mapping):
                continue
            shocks = scenario.get("shocks", {})
            if not isinstance(shocks, Mapping):
                continue
            portfolio_return = 0.0
            for security_id, weight in weights.items():
                try:
                    portfolio_return += float(weight) * float(shocks.get(security_id, 0.0))
                except (TypeError, ValueError):
                    continue
            report.append({"name": str(scenario.get("name", "stress")), "portfolio_return": round(portfolio_return, 6)})
        return report

    def _portfolio_walk_forward(self, weights: Mapping[str, float], history: Any) -> dict[str, Any]:
        if not isinstance(history, Mapping):
            return {}
        series = {str(security_id): self._float_series(values) for security_id, values in history.items()}
        lengths = [len(values) for values in series.values() if values]
        if not lengths:
            return {}
        periods = min(lengths)
        portfolio_returns = [
            sum(float(weights.get(security_id, 0.0)) * returns[index] for security_id, returns in series.items() if len(returns) > index)
            for index in range(periods)
        ]
        total_return = self._compound_return(portfolio_returns)
        return {
            "period_count": periods,
            "total_return": round(total_return, 6),
            "max_drawdown": round(self._max_drawdown(portfolio_returns), 6),
        }

    def _portfolio_covariance_diagnostics(self, history: Any, *, shrinkage: float) -> dict[str, Any]:
        if not isinstance(history, Mapping):
            return {}
        series = {str(security_id): self._float_series(values) for security_id, values in history.items()}
        series = {security_id: values for security_id, values in series.items() if len(values) >= 2}
        if len(series) < 2:
            return {}
        periods = min(len(values) for values in series.values())
        if periods < 2:
            return {}
        shrinkage = max(0.0, min(1.0, shrinkage))
        securities = sorted(series)
        aligned = {security_id: series[security_id][-periods:] for security_id in securities}
        means = {security_id: sum(values) / periods for security_id, values in aligned.items()}
        sample: dict[str, dict[str, float]] = {}
        correlation: dict[str, dict[str, float]] = {}
        for left in securities:
            sample[left] = {}
            correlation[left] = {}
            for right in securities:
                covariance = sum((aligned[left][index] - means[left]) * (aligned[right][index] - means[right]) for index in range(periods)) / max(1, periods - 1)
                sample[left][right] = covariance
        diagonal_target = {security_id: sample[security_id][security_id] for security_id in securities}
        shrunk: dict[str, dict[str, float]] = {}
        for left in securities:
            shrunk[left] = {}
            for right in securities:
                target = diagonal_target[left] if left == right else 0.0
                shrunk_value = (1.0 - shrinkage) * sample[left][right] + shrinkage * target
                shrunk[left][right] = shrunk_value
                denom = (sample[left][left] * sample[right][right]) ** 0.5
                correlation[left][right] = sample[left][right] / denom if denom else 0.0
        return {
            "method": "sample_covariance_with_diagonal_shrinkage",
            "period_count": periods,
            "shrinkage": round(shrinkage, 4),
            "securities": securities,
            "sample_covariance": self._round_matrix(sample),
            "shrunk_covariance": self._round_matrix(shrunk),
            "correlation": self._round_matrix(correlation),
        }

    def _round_matrix(self, matrix: Mapping[str, Mapping[str, float]]) -> dict[str, dict[str, float]]:
        return {
            str(row_key): {str(column_key): round(float(value), 8) for column_key, value in row.items()}
            for row_key, row in matrix.items()
        }

    def _portfolio_view_benchmark_evidence(self, evidence_ids: list[str], *, benchmark_id: str = "") -> dict[str, Any]:
        if not evidence_ids:
            return {
                "benchmark_id": benchmark_id,
                "passed": False,
                "passed_evidence_ids": [],
                "failed_evidence_ids": [],
                "missing_result_evidence_ids": [],
            }
        passed_evidence_ids: list[str] = []
        failed_evidence_ids: list[str] = []
        missing_result_evidence_ids: list[str] = []
        for evidence_id in evidence_ids:
            results = [
                result
                for result in self.store.extraction_results.values()
                if result.evidence_id == evidence_id and (not benchmark_id or result.benchmark_id == benchmark_id)
            ]
            if not results:
                missing_result_evidence_ids.append(evidence_id)
                continue
            if any(result.passed for result in results):
                passed_evidence_ids.append(evidence_id)
            else:
                failed_evidence_ids.append(evidence_id)
        passed = bool(passed_evidence_ids) and not failed_evidence_ids and not missing_result_evidence_ids and set(passed_evidence_ids) == set(evidence_ids)
        return {
            "benchmark_id": benchmark_id,
            "passed": passed,
            "passed_evidence_ids": passed_evidence_ids,
            "failed_evidence_ids": failed_evidence_ids,
            "missing_result_evidence_ids": missing_result_evidence_ids,
        }

    def create_strategy_replay(self, payload: Mapping[str, Any], *, actor: str = "system") -> StrategyReplay:
        decision_id = str(payload["decision_id"])
        if decision_id not in self.store.decisions:
            raise NotFoundError(f"decision {decision_id} not found")
        replay = StrategyReplay(
            replay_id=str(payload.get("replay_id", new_id("replay"))),
            decision_id=decision_id,
            expected_outcome=str(payload.get("expected_outcome", "")),
            actual_outcome=str(payload.get("actual_outcome", "")),
            variance_reason=str(payload.get("variance_reason", "")),
            next_action=str(payload.get("next_action", "")),
            version=str(payload.get("version", "v1")),
        )
        if replay.replay_id in self.store.strategy_replays:
            raise ConflictError(f"strategy replay {replay.replay_id} already exists")
        self.store.strategy_replays[replay.replay_id] = replay
        self._audit(actor, "create_strategy_replay", "strategy_replay", replay.replay_id)
        return replay

    def list_strategy_replays(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        decision_id = str(payload.get("decision_id", ""))
        version = str(payload.get("version", ""))
        actual_outcome = str(payload.get("actual_outcome", ""))
        created_from = parse_datetime(payload["created_from"]) if payload.get("created_from") else None
        created_to = parse_datetime(payload["created_to"]) if payload.get("created_to") else None
        replays: list[StrategyReplay] = []
        for replay in self.store.strategy_replays.values():
            if decision_id and replay.decision_id != decision_id:
                continue
            if version and replay.version != version:
                continue
            if actual_outcome and replay.actual_outcome != actual_outcome:
                continue
            if created_from and replay.created_at < created_from:
                continue
            if created_to and replay.created_at > created_to:
                continue
            replays.append(replay)
        replays.sort(key=lambda item: item.created_at, reverse=True)
        return {"count": len(replays), "replays": [to_plain(item) for item in replays]}

    def strategy_replay_compare_report(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        replay_ids = [str(item) for item in filters.get("replay_ids", []) if str(item).strip()]
        decision_id = str(filters.get("decision_id", "")).strip()
        version = str(filters.get("version", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 20), 100)
        replays = list(self.store.strategy_replays.values())
        if replay_ids:
            missing = [item for item in replay_ids if item not in self.store.strategy_replays]
            if missing:
                raise NotFoundError(f"strategy replay not found: {missing[0]}")
            replays = [self.store.strategy_replays[item] for item in replay_ids]
        if decision_id:
            replays = [item for item in replays if item.decision_id == decision_id]
        if version:
            replays = [item for item in replays if item.version == version]
        replays.sort(key=lambda item: item.created_at, reverse=True)
        rows = [self._strategy_replay_compare_row(item) for item in replays[:limit]]
        by_outcome: dict[str, int] = {}
        by_version: dict[str, int] = {}
        action_counts: dict[str, int] = {}
        for row in rows:
            by_outcome[row["actual_outcome"]] = by_outcome.get(row["actual_outcome"], 0) + 1
            by_version[row["version"]] = by_version.get(row["version"], 0) + 1
            action_counts[row["action_bucket"]] = action_counts.get(row["action_bucket"], 0) + 1
        variance_rows = [row for row in rows if row["variance_reason"]]
        latest_row = rows[0] if rows else None
        return {
            "count": len(rows),
            "decision_id": decision_id,
            "version": version,
            "latest_replay_id": latest_row["replay_id"] if latest_row else "",
            "outcome_counts": by_outcome,
            "version_counts": by_version,
            "action_counts": action_counts,
            "variance_count": len(variance_rows),
            "usage_boundary": "strategy_replay_compare_is_post_decision_review_only",
            "replays": rows,
        }

    def run_portfolio_optimizer(self, payload: Mapping[str, Any], *, actor: str = "system") -> PortfolioProposal:
        proposal_id = str(payload.get("proposal_id", new_id("pfp")))
        if proposal_id in self.store.portfolio_proposals:
            raise ConflictError(f"portfolio proposal {proposal_id} already exists")
        securities = self._portfolio_universe(payload)
        risk_aversion = float(payload.get("risk_aversion", 2.5))
        tau = float(payload.get("tau", 0.05))
        constraints = dict(payload.get("constraints", {}))
        risk_budget = dict(payload.get("risk_budget", {}))
        constraints["paper_only"] = True

        total_market_weight = sum(item["market_weight"] for item in securities.values())
        if total_market_weight <= 0:
            total_market_weight = float(len(securities))
            for item in securities.values():
                item["market_weight"] = 1.0
        for item in securities.values():
            item["market_weight"] = item["market_weight"] / total_market_weight

        prior_returns = {
            security_id: risk_aversion * item["variance"] * item["market_weight"]
            for security_id, item in securities.items()
        }
        posterior_returns = dict(prior_returns)
        view_diagnostics: list[dict[str, Any]] = []
        require_benchmark_passed_evidence = self._truthy(payload.get("require_benchmark_passed_evidence", False))
        default_view_benchmark_id = str(payload.get("benchmark_id", "")).strip()
        for view in payload.get("views", []):
            if not isinstance(view, Mapping):
                continue
            security_id = str(view.get("security_id", ""))
            if security_id not in securities:
                raise NotFoundError(f"portfolio view security {security_id} not found in universe")
            evidence_ids = [str(item) for item in view.get("evidence_ids", [])]
            for evidence_id in evidence_ids:
                if evidence_id not in self.store.evidence:
                    raise NotFoundError(f"portfolio view evidence {evidence_id} not found")
            benchmark_id = str(view.get("benchmark_id", default_view_benchmark_id)).strip()
            benchmark_evidence = self._portfolio_view_benchmark_evidence(evidence_ids, benchmark_id=benchmark_id)
            if require_benchmark_passed_evidence and not benchmark_evidence["passed"]:
                raise ComplianceGateError("portfolio view evidence must have passed benchmark extraction before optimization")
            confidence = min(1.0, max(0.01, float(view.get("confidence", 0.5))))
            view_return = float(view.get("expected_return", 0.0))
            variance = securities[security_id]["variance"]
            prior_variance = max(tau * variance, 1e-6)
            omega = max(prior_variance * (1.0 - confidence) / confidence, 1e-6)
            posterior = ((prior_returns[security_id] / prior_variance) + (view_return / omega)) / ((1.0 / prior_variance) + (1.0 / omega))
            posterior_returns[security_id] = posterior
            view_diagnostics.append(
                {
                    "security_id": security_id,
                    "confidence": round(confidence, 4),
                    "omega": round(omega, 8),
                    "prior_return": round(prior_returns[security_id], 6),
                    "view_return": round(view_return, 6),
                    "posterior_return": round(posterior, 6),
                    "evidence_ids": evidence_ids,
                    "benchmark_evidence": benchmark_evidence,
                }
            )

        scores = {
            security_id: max(0.0, posterior_returns[security_id]) / securities[security_id]["variance"]
            for security_id in securities
        }
        if sum(scores.values()) <= 0:
            scores = {security_id: item["market_weight"] for security_id, item in securities.items()}
        max_weight = float(constraints.get("max_weight", 1.0))
        restricted = {str(item) for item in constraints.get("restricted_securities", [])}
        unconstrained_weights = self._normalize_scores_with_caps(scores, {security_id: 0.0 if security_id in restricted else max_weight for security_id in securities})
        weights = self._apply_portfolio_constraints(scores, securities, constraints, risk_budget)
        rounded_weights = {security_id: round(weight, 6) for security_id, weight in weights.items()}
        constraint_shadow_prices = self._portfolio_constraint_shadow_prices(unconstrained_weights, weights, securities, constraints, risk_budget)
        diagnostics = {
            "method": "diagonal_black_litterman",
            "risk_aversion": risk_aversion,
            "tau": tau,
            "paper_only": True,
            "view_diagnostics": view_diagnostics,
            "market_exposure": self._portfolio_group_exposure(rounded_weights, securities, "market"),
            "industry_exposure": self._portfolio_group_exposure(rounded_weights, securities, "industry"),
            "theme_exposure": self._portfolio_group_exposure(rounded_weights, securities, "theme"),
            "currency_exposure": self._portfolio_group_exposure(rounded_weights, securities, "currency"),
            "risk_contribution": self._portfolio_risk_contribution(rounded_weights, securities),
            "security_risk_inputs": {
                security_id: {
                    "volatility": round(float(item["volatility"]), 8),
                    "variance": round(float(item["variance"]), 8),
                    "market": item.get("market", ""),
                    "currency": item.get("currency", ""),
                    "industry": item.get("industry", ""),
                }
                for security_id, item in securities.items()
            },
            "turnover": round(self._portfolio_turnover(rounded_weights, constraints.get("current_weights", payload.get("current_weights", {}))), 6),
            "stress_report": self._portfolio_stress_report(rounded_weights, payload.get("stress_scenarios", [])),
            "walk_forward": self._portfolio_walk_forward(rounded_weights, payload.get("return_history", {})),
            "covariance": self._portfolio_covariance_diagnostics(payload.get("return_history", {}), shrinkage=float(payload.get("covariance_shrinkage", 0.25))),
            "cash_weight": round(max(0.0, 1.0 - sum(rounded_weights.values())), 6),
            "constraint_shadow_prices": constraint_shadow_prices,
        }
        proposal = PortfolioProposal(
            proposal_id=proposal_id,
            universe=list(securities.keys()),
            prior_returns={security_id: round(value, 6) for security_id, value in prior_returns.items()},
            posterior_returns={security_id: round(value, 6) for security_id, value in posterior_returns.items()},
            candidate_weights=rounded_weights,
            constraints=constraints,
            risk_budget=risk_budget,
            diagnostics=diagnostics,
            status=str(payload.get("status", "candidate")),
            created_by=str(payload.get("created_by", actor)),
        )
        self.store.portfolio_proposals[proposal.proposal_id] = proposal
        self._audit(actor, "run_portfolio_optimizer", "portfolio_proposal", proposal.proposal_id, approval_state=proposal.status)
        return proposal

    def portfolio_optimizer_compare_report(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        proposal = self._portfolio_proposal_for_report(payload)
        candidate_weights = {str(key): float(value) for key, value in proposal.candidate_weights.items()}
        if not candidate_weights:
            raise ValidationError("portfolio optimizer compare requires candidate weights")
        universe = [security_id for security_id in proposal.universe if security_id in candidate_weights]
        if not universe:
            universe = list(candidate_weights)
        baseline_method = str(payload.get("baseline_method", "equal_weight")).strip().lower()
        baseline_weights = self._portfolio_baseline_weights(proposal, universe, baseline_method)
        external_solver = self._portfolio_external_solver_result(payload, proposal, universe)
        external_weights = external_solver["weights"]
        comparisons = [
            self._portfolio_weight_comparison_row(
                "candidate",
                candidate_weights,
                baseline_weights,
                proposal,
                reference_label=f"baseline:{baseline_method}",
            )
        ]
        if external_weights:
            comparisons.append(
                self._portfolio_weight_comparison_row(
                    str(external_solver["optimizer"]),
                    external_weights,
                    candidate_weights,
                    proposal,
                    reference_label="candidate",
                )
            )
        constraint_report = self._portfolio_compare_constraint_report(candidate_weights, proposal)
        result = {
            "proposal_id": proposal.proposal_id,
            "status": proposal.status,
            "candidate_weights": {key: round(value, 6) for key, value in sorted(candidate_weights.items())},
            "baseline_method": baseline_method,
            "baseline_weights": {key: round(value, 6) for key, value in sorted(baseline_weights.items())},
            "external_optimizer_supplied": bool(external_weights),
            "external_optimizer": external_solver,
            "comparisons": comparisons,
            "constraint_report": constraint_report,
            "diagnostics": {
                "optimizer_method": proposal.diagnostics.get("method", ""),
                "view_count": len(proposal.diagnostics.get("view_diagnostics", [])),
                "cash_weight": proposal.diagnostics.get("cash_weight", 0.0),
                "constraint_shadow_prices": proposal.diagnostics.get("constraint_shadow_prices", []),
            },
            "simulation_only": True,
            "live_execution_allowed": False,
            "automation_allowed": False,
            "usage_boundary": "portfolio_optimizer_compare_is_paper_research_only_not_trade_signal",
        }
        self._audit(actor, "portfolio_optimizer_compare_report", "portfolio_proposal", proposal.proposal_id, approval_state="paper_compare")
        return result

    def portfolio_optimizer_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        compare_result = dict(payload.get("compare_result", payload.get("comparison", {}))) if isinstance(payload.get("compare_result", payload.get("comparison", {})), Mapping) else {}
        proposal_id = str(payload.get("proposal_id", compare_result.get("proposal_id", ""))).strip()
        external_optimizer = dict(payload.get("external_optimizer", compare_result.get("external_optimizer", {}))) if isinstance(payload.get("external_optimizer", compare_result.get("external_optimizer", {})), Mapping) else {}
        optimizer_name = str(payload.get("external_optimizer_name", external_optimizer.get("optimizer", ""))).strip() or "external_solver"
        solver_status = str(payload.get("solver_status", external_optimizer.get("status", ""))).strip() or "missing"
        diagnostics = dict(external_optimizer.get("diagnostics", {})) if isinstance(external_optimizer.get("diagnostics", {}), Mapping) else {}
        artifact_uris = self._portfolio_optimizer_artifact_uris(payload)
        solver_version = str(payload.get("solver_version", payload.get("version", diagnostics.get("version", "")))).strip()
        solver_parameters = payload.get("solver_parameters", payload.get("parameters", payload.get("params", {})))
        has_solver_parameters = isinstance(solver_parameters, Mapping) and bool(solver_parameters)
        has_weights = bool(external_optimizer.get("weights") or payload.get("solver_weights") or payload.get("external_optimizer_weights"))
        constraint_report = payload.get("constraint_report", compare_result.get("constraint_report", {}))
        has_constraint_report = isinstance(constraint_report, Mapping) and bool(constraint_report)
        simulation_only = bool(compare_result.get("simulation_only", payload.get("simulation_only", True)))
        live_execution_allowed = bool(compare_result.get("live_execution_allowed", payload.get("live_execution_allowed", False)))
        automation_allowed = bool(compare_result.get("automation_allowed", payload.get("automation_allowed", False)))
        accepted_statuses = {"solved", "supplied"}
        gates = [
            self._readiness_bool_gate("proposal_id", bool(proposal_id), "PortfolioProposal identifier for solver comparison"),
            self._readiness_bool_gate("external_solver_status", solver_status in accepted_statuses, "external solver completed or caller supplied production result"),
            self._readiness_bool_gate("solver_weights", has_weights, "external solver weights captured"),
            self._readiness_bool_gate("solver_version", bool(solver_version), "CVXPY/PyPortfolioOpt or external solver version"),
            self._readiness_bool_gate("solver_parameters", has_solver_parameters, "solver parameters and objective settings archived"),
            self._readiness_bool_gate("solver_artifact_uri", bool(artifact_uris.get("solver_artifact_uri")), "solver output artifact URI"),
            self._readiness_bool_gate("comparison_artifact_uri", bool(artifact_uris.get("comparison_artifact_uri")), "candidate/baseline/external comparison artifact URI"),
            self._readiness_bool_gate("constraint_report_artifact_uri", bool(artifact_uris.get("constraint_report_artifact_uri")), "portfolio constraint report artifact URI"),
            self._readiness_bool_gate("constraint_report", has_constraint_report, "constraint report persisted with comparison"),
            self._readiness_bool_gate("paper_only_boundary", simulation_only and not live_execution_allowed and not automation_allowed, "paper-only no-broker execution boundary"),
        ]
        missing = [gate for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "proposal_id": proposal_id,
            "optimizer": optimizer_name,
            "solver_status": solver_status,
            "solver_version": solver_version,
            "solver_parameters": to_plain(solver_parameters) if isinstance(solver_parameters, Mapping) else {},
            "artifact_uris": artifact_uris,
            "diagnostics": diagnostics,
            "gates": gates,
            "missing_requirements": [gate["gate"] for gate in missing],
            "ready_for_production_comparison_archive": ready,
            "simulation_only": True,
            "live_execution_allowed": False,
            "automation_allowed": False,
            "usage_boundary": "portfolio_optimizer_readiness_archives_paper_solver_comparison_not_live_execution",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "portfolio_optimizer_readiness_report", "portfolio_proposal", proposal_id or "portfolio_optimizer", approval_state="ready" if ready else "missing_evidence")
        return report

    def portfolio_forward_report(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        proposal = self._portfolio_proposal_for_report(payload)
        weights = payload.get("weights", proposal.candidate_weights)
        if isinstance(weights, Mapping):
            holdings = [{"security_id": str(security_id), "weight": float(weight)} for security_id, weight in weights.items() if float(weight) > 0]
        else:
            holdings = weights
        if not isinstance(holdings, list) or not holdings:
            raise ValidationError("portfolio forward report requires proposal weights or holdings")
        returns_payload = dict(payload)
        returns_payload["holdings"] = holdings
        if not returns_payload.get("start_date") and payload.get("forward_start_date"):
            returns_payload["start_date"] = payload.get("forward_start_date")
        if not returns_payload.get("end_date") and payload.get("forward_end_date"):
            returns_payload["end_date"] = payload.get("forward_end_date")
        returns_result = self.portfolio_returns_payload(returns_payload)
        benchmark_result: dict[str, Any] = {}
        benchmark_weights = payload.get("benchmark_weights", {})
        if isinstance(benchmark_weights, Mapping) and benchmark_weights:
            benchmark_payload = dict(returns_payload)
            benchmark_payload["holdings"] = [{"security_id": str(security_id), "weight": float(weight)} for security_id, weight in benchmark_weights.items() if float(weight) > 0]
            benchmark_result = self.portfolio_returns_payload(benchmark_payload)
        tracking_metrics = self._portfolio_forward_tracking_metrics(returns_result, benchmark_result)
        review_flags = self._portfolio_forward_review_flags(returns_result, benchmark_result, payload, tracking_metrics)
        result = {
            "proposal_id": proposal.proposal_id,
            "proposal_status": proposal.status,
            "start_date": str(returns_payload.get("start_date", "")),
            "end_date": str(returns_payload.get("end_date", "")),
            "weights": returns_result.get("weights", {}),
            "return_count": returns_result.get("return_count", 0),
            "total_return": returns_result.get("total_return", 0.0),
            "volatility": returns_result.get("volatility", 0.0),
            "max_drawdown": returns_result.get("max_drawdown", 0.0),
            "benchmark_total_return": benchmark_result.get("total_return") if benchmark_result else None,
            "active_return": round(tracking_metrics["active_return"], 8) if tracking_metrics["active_return"] is not None else None,
            "tracking_error": tracking_metrics["tracking_error"],
            "information_ratio": tracking_metrics["information_ratio"],
            "aligned_date_count": tracking_metrics["aligned_date_count"],
            "attribution": returns_result.get("attribution", {}),
            "returns": returns_result.get("returns", []),
            "coverage": returns_result.get("coverage", {}),
            "review_flags": review_flags,
            "simulation_only": True,
            "live_execution_allowed": False,
            "automation_allowed": False,
            "usage_boundary": "portfolio_forward_report_is_simulated_tracking_only_not_live_execution",
        }
        self._audit(actor, "portfolio_forward_report", "portfolio_proposal", proposal.proposal_id, approval_state=f"return_count={result['return_count']};flags={len(review_flags)}")
        return result

    def _portfolio_proposal_for_report(self, payload: Mapping[str, Any]) -> PortfolioProposal:
        proposal_id = str(payload.get("proposal_id") or payload.get("portfolio_proposal_id") or "").strip()
        if not proposal_id:
            raise ValidationError("portfolio report requires proposal_id")
        proposal = self.store.portfolio_proposals.get(proposal_id)
        if proposal is None:
            raise NotFoundError(f"portfolio proposal {proposal_id} not found")
        return proposal

    def _portfolio_baseline_weights(self, proposal: PortfolioProposal, universe: list[str], baseline_method: str) -> dict[str, float]:
        universe = [security_id for security_id in universe if security_id in self.store.securities]
        if not universe:
            raise ValidationError("portfolio baseline requires a non-empty universe")
        method = baseline_method.strip().lower()
        if method in {"equal", "equal_weight", "equal-weight", "market_weight", "market"}:
            return {security_id: round(1.0 / len(universe), 8) for security_id in universe}
        if method in {"candidate", "candidate_weight", "proposal", "proposal_weight"}:
            source = {security_id: float(proposal.candidate_weights.get(security_id, 0.0)) for security_id in universe}
        elif method in {"prior", "prior_return", "prior_returns"}:
            source = {security_id: max(0.0, float(proposal.prior_returns.get(security_id, 0.0))) for security_id in universe}
        elif method in {"posterior", "posterior_return", "posterior_returns"}:
            source = {security_id: max(0.0, float(proposal.posterior_returns.get(security_id, 0.0))) for security_id in universe}
        else:
            raise ValidationError("unsupported baseline_method")
        total = sum(source.values())
        if total <= 0:
            return {security_id: round(1.0 / len(universe), 8) for security_id in universe}
        return {security_id: round(value / total, 8) for security_id, value in source.items()}

    def _optional_external_optimizer_weights(self, raw: Any, universe: list[str]) -> dict[str, float]:
        if not raw:
            return {}
        source: Any = raw
        if isinstance(source, Mapping):
            if isinstance(source.get("weights"), Mapping):
                source = source.get("weights")
            elif isinstance(source.get("candidate_weights"), Mapping):
                source = source.get("candidate_weights")
        weights: dict[str, float] = {}
        if isinstance(source, Mapping):
            for security_id, value in source.items():
                security_id = str(security_id)
                if security_id not in universe:
                    continue
                weight = float(value)
                if weight < 0:
                    raise ValidationError("external optimizer weights must be non-negative")
                weights[security_id] = weight
        elif isinstance(source, list):
            for item in source:
                if not isinstance(item, Mapping):
                    continue
                security_id = str(item.get("security_id", item.get("ticker", item.get("symbol", "")))).strip()
                if not security_id or security_id not in universe:
                    continue
                weight = float(item.get("weight", item.get("target_weight", 0.0)))
                if weight < 0:
                    raise ValidationError("external optimizer weights must be non-negative")
                weights[security_id] = weight
        else:
            return {}
        total = sum(weights.values())
        if total <= 0:
            return {}
        return {security_id: round(weight / total, 8) for security_id, weight in weights.items()}

    def _portfolio_optimizer_artifact_uris(self, payload: Mapping[str, Any]) -> dict[str, str]:
        aliases = {
            "solver_artifact_uri": ["solver_artifact_uri", "external_solver_artifact_uri", "artifact_uri"],
            "comparison_artifact_uri": ["comparison_artifact_uri", "optimizer_compare_artifact_uri", "report_uri"],
            "constraint_report_artifact_uri": ["constraint_report_artifact_uri", "constraint_report_uri", "constraints_artifact_uri", "risk_constraint_report_uri"],
            "parameter_artifact_uri": ["parameter_artifact_uri", "solver_parameters_uri", "params_uri"],
        }
        return self._readiness_artifact_aliases(payload, aliases)

    def _portfolio_external_solver_result(self, payload: Mapping[str, Any], proposal: PortfolioProposal, universe: list[str]) -> dict[str, Any]:
        supplied = self._optional_external_optimizer_weights(payload.get("external_optimizer_weights", payload.get("solver_weights", {})), universe)
        optimizer_name = str(payload.get("external_optimizer_name", payload.get("external_optimizer", ""))).strip()
        if supplied:
            return {
                "optimizer": optimizer_name or "external_solver",
                "status": "supplied",
                "weights": supplied,
                "diagnostics": {"source": "request_payload", "dependency": "caller_supplied"},
            }
        if not self._truthy(payload.get("run_external_optimizer", False)):
            return {
                "optimizer": optimizer_name or "external_solver",
                "status": "not_requested",
                "weights": {},
                "diagnostics": {"source": "not_requested"},
            }
        requested = (optimizer_name or "cvxpy").lower()
        if requested in {"cvxpy", "cvx", "quadratic"}:
            return self._portfolio_cvxpy_solver_result(payload, proposal, universe)
        if requested in {"pypfopt", "pyportfolioopt", "efficientfrontier"}:
            return self._portfolio_pypfopt_solver_result(payload, proposal, universe)
        raise ValidationError("unsupported external_optimizer_name")

    def _portfolio_cvxpy_solver_result(self, payload: Mapping[str, Any], proposal: PortfolioProposal, universe: list[str]) -> dict[str, Any]:
        try:
            import cvxpy as cp  # type: ignore[import-not-found]
        except ImportError:
            return {
                "optimizer": "cvxpy",
                "status": "unavailable",
                "weights": {},
                "diagnostics": {
                    "dependency": "cvxpy",
                    "install_hint": "pip install cvxpy",
                    "reason": "cvxpy_not_installed",
                    "paper_compare_continues": True,
                },
            }
        if len(universe) == 0:
            raise ValidationError("cvxpy external optimizer requires non-empty universe")
        returns = [float(proposal.posterior_returns.get(security_id, proposal.prior_returns.get(security_id, 0.0))) for security_id in universe]
        variances = [self._proposal_security_variance(proposal, security_id) for security_id in universe]
        max_weight = float(proposal.constraints.get("max_weight", 1.0))
        restricted = {str(item) for item in proposal.constraints.get("restricted_securities", [])}
        risk_penalty = float(payload.get("external_risk_penalty", 1.0))
        weights = cp.Variable(len(universe), nonneg=True)
        objective = cp.Maximize(cp.sum(cp.multiply(returns, weights)) - risk_penalty * cp.sum(cp.multiply(variances, cp.square(weights))))
        constraints = [cp.sum(weights) <= 1.0]
        for index, security_id in enumerate(universe):
            constraints.append(weights[index] <= (0.0 if security_id in restricted else max_weight))
        problem = cp.Problem(objective, constraints)
        try:
            solver_name = str(payload.get("cvxpy_solver", "")).strip() or None
            problem.solve(solver=solver_name) if solver_name else problem.solve()
        except Exception as exc:  # pragma: no cover - depends on installed solvers
            return {
                "optimizer": "cvxpy",
                "status": "failed",
                "weights": {},
                "diagnostics": {"dependency": "cvxpy", "error": str(exc), "paper_compare_continues": True},
            }
        if weights.value is None or problem.status not in {"optimal", "optimal_inaccurate"}:
            return {
                "optimizer": "cvxpy",
                "status": str(problem.status or "failed"),
                "weights": {},
                "diagnostics": {"dependency": "cvxpy", "objective_value": problem.value, "paper_compare_continues": True},
            }
        raw = {security_id: max(0.0, float(weights.value[index])) for index, security_id in enumerate(universe)}
        normalized = self._optional_external_optimizer_weights(raw, universe)
        return {
            "optimizer": "cvxpy",
            "status": "solved",
            "weights": normalized,
            "diagnostics": {"dependency": "cvxpy", "problem_status": problem.status, "objective_value": round(float(problem.value or 0.0), 8)},
        }

    def _portfolio_pypfopt_solver_result(self, payload: Mapping[str, Any], proposal: PortfolioProposal, universe: list[str]) -> dict[str, Any]:
        try:
            from pypfopt import EfficientFrontier  # type: ignore[import-not-found]
        except ImportError:
            return {
                "optimizer": "pypfopt",
                "status": "unavailable",
                "weights": {},
                "diagnostics": {
                    "dependency": "PyPortfolioOpt",
                    "install_hint": "pip install PyPortfolioOpt",
                    "reason": "pypfopt_not_installed",
                    "paper_compare_continues": True,
                },
            }
        try:
            import pandas as pd  # type: ignore[import-not-found]
        except ImportError:
            return {
                "optimizer": "pypfopt",
                "status": "unavailable",
                "weights": {},
                "diagnostics": {
                    "dependency": "pandas",
                    "install_hint": "pip install pandas PyPortfolioOpt",
                    "reason": "pandas_not_installed",
                    "paper_compare_continues": True,
                },
            }
        expected_returns = {security_id: float(proposal.posterior_returns.get(security_id, proposal.prior_returns.get(security_id, 0.0))) for security_id in universe}
        covariance = {
            left: {right: (self._proposal_security_variance(proposal, left) if left == right else 0.0) for right in universe}
            for left in universe
        }
        try:
            ef = EfficientFrontier(pd.Series(expected_returns), pd.DataFrame(covariance), weight_bounds=(0.0, float(proposal.constraints.get("max_weight", 1.0))))
            ef.max_sharpe()
            cleaned = ef.clean_weights() if self._truthy(payload.get("pypfopt_clean_weights", True)) else ef.weights
        except Exception as exc:  # pragma: no cover - depends on optional dependency internals
            return {
                "optimizer": "pypfopt",
                "status": "failed",
                "weights": {},
                "diagnostics": {"dependency": "PyPortfolioOpt", "error": str(exc), "paper_compare_continues": True},
            }
        normalized = self._optional_external_optimizer_weights(cleaned, universe)
        return {
            "optimizer": "pypfopt",
            "status": "solved",
            "weights": normalized,
            "diagnostics": {"dependency": "PyPortfolioOpt", "method": "max_sharpe"},
        }

    def _proposal_security_variance(self, proposal: PortfolioProposal, security_id: str) -> float:
        risk_inputs = proposal.diagnostics.get("security_risk_inputs", {})
        if isinstance(risk_inputs, Mapping) and isinstance(risk_inputs.get(security_id), Mapping):
            return max(float(risk_inputs[security_id].get("variance", 0.0)), 1e-8)
        covariance = proposal.diagnostics.get("covariance", {})
        if isinstance(covariance, Mapping):
            shrunk = covariance.get("shrunk_covariance", {})
            if isinstance(shrunk, Mapping) and isinstance(shrunk.get(security_id), Mapping):
                return max(float(shrunk[security_id].get(security_id, 0.0)), 1e-8)
        return 0.04

    def _portfolio_weight_comparison_row(
        self,
        optimizer_label: str,
        weights: Mapping[str, float],
        reference_weights: Mapping[str, float],
        proposal: PortfolioProposal,
        *,
        reference_label: str,
    ) -> dict[str, Any]:
        universe = sorted(set(weights) | set(reference_weights))
        if not universe:
            raise ValidationError("portfolio comparison requires weights")
        candidate = {security_id: max(0.0, float(weights.get(security_id, 0.0))) for security_id in universe}
        reference = {security_id: max(0.0, float(reference_weights.get(security_id, 0.0))) for security_id in universe}
        candidate_total = sum(candidate.values())
        reference_total = sum(reference.values())
        if candidate_total <= 0 or reference_total <= 0:
            raise ValidationError("portfolio comparison requires positive normalized weights")
        candidate = {security_id: value / candidate_total for security_id, value in candidate.items()}
        reference = {security_id: value / reference_total for security_id, value in reference.items()}
        score_source = {
            security_id: float(proposal.posterior_returns.get(security_id, proposal.prior_returns.get(security_id, 0.0)))
            for security_id in universe
        }
        candidate_score = sum(candidate[security_id] * score_source[security_id] for security_id in universe)
        reference_score = sum(reference[security_id] * score_source[security_id] for security_id in universe)
        restricted = {str(item) for item in proposal.constraints.get("restricted_securities", [])}
        max_weight_limit = float(proposal.constraints.get("max_weight", 1.0))
        candidate_restricted_weight = sum(candidate.get(security_id, 0.0) for security_id in restricted)
        candidate_breaches = sorted([security_id for security_id, weight in candidate.items() if weight > max_weight_limit + 1e-6])
        top_security_id = max(candidate, key=candidate.get)
        return {
            "optimizer": optimizer_label,
            "reference": reference_label,
            "security_count": len(candidate),
            "reference_security_count": len(reference),
            "weight_sum": round(sum(candidate.values()), 8),
            "reference_weight_sum": round(sum(reference.values()), 8),
            "top_security_id": top_security_id,
            "top_weight": round(candidate[top_security_id], 8),
            "l1_distance_to_reference": round(sum(abs(candidate[security_id] - reference[security_id]) for security_id in universe) / 2, 8),
            "concentration": round(sum(weight * weight for weight in candidate.values()), 8),
            "expected_return_proxy": round(candidate_score, 8),
            "reference_expected_return_proxy": round(reference_score, 8),
            "expected_return_delta": round(candidate_score - reference_score, 8),
            "restricted_security_weight": round(candidate_restricted_weight, 8),
            "max_weight_limit": round(max_weight_limit, 8),
            "max_weight_breach_count": len(candidate_breaches),
            "max_weight_breach_securities": candidate_breaches,
            "weights": {security_id: round(candidate[security_id], 8) for security_id in universe if candidate[security_id] > 0},
            "reference_weights": {security_id: round(reference[security_id], 8) for security_id in universe if reference[security_id] > 0},
        }

    def _portfolio_compare_constraint_report(self, weights: Mapping[str, float], proposal: PortfolioProposal) -> dict[str, Any]:
        universe = [security_id for security_id in proposal.universe if security_id in self.store.securities] or list(weights)
        candidate = {security_id: max(0.0, float(weights.get(security_id, 0.0))) for security_id in universe}
        total = sum(candidate.values())
        if total <= 0:
            raise ValidationError("portfolio constraint report requires positive weights")
        candidate = {security_id: value / total for security_id, value in candidate.items()}
        securities = {
            security_id: {
                "market": self.store.securities[security_id].market,
                "currency": self.store.securities[security_id].currency,
            }
            for security_id in universe
            if security_id in self.store.securities
        }
        max_weight_limit = float(proposal.constraints.get("max_weight", 1.0))
        restricted = {str(item) for item in proposal.constraints.get("restricted_securities", [])}
        restricted_violations = [security_id for security_id in sorted(restricted) if candidate.get(security_id, 0.0) > 1e-6]
        max_weight_breaches = [security_id for security_id, weight in candidate.items() if weight > max_weight_limit + 1e-6]
        market_budget = self._budget_map(proposal.constraints.get("market_budget") or proposal.risk_budget.get("market") or proposal.risk_budget.get("markets"))
        currency_budget = self._budget_map(proposal.constraints.get("currency_budget") or proposal.risk_budget.get("currency") or proposal.risk_budget.get("currencies"))
        market_exposure = self._portfolio_group_exposure(candidate, securities, "market")
        currency_exposure = self._portfolio_group_exposure(candidate, securities, "currency")
        budget_breaches: list[dict[str, Any]] = []
        for scope, exposures, budgets in [
            ("market", market_exposure, market_budget),
            ("currency", currency_exposure, currency_budget),
        ]:
            for group, limit in budgets.items():
                exposure = float(exposures.get(group, 0.0))
                if exposure > float(limit) + 1e-6:
                    budget_breaches.append(
                        {
                            "scope": scope,
                            "group": group,
                            "limit": round(float(limit), 8),
                            "exposure": round(exposure, 8),
                            "breach": round(exposure - float(limit), 8),
                        }
                    )
        return {
            "max_weight_limit": round(max_weight_limit, 8),
            "restricted_securities": sorted(restricted),
            "restricted_security_violations": restricted_violations,
            "restricted_security_count": len(restricted_violations),
            "max_weight_breach_securities": sorted(max_weight_breaches),
            "market_exposure": market_exposure,
            "currency_exposure": currency_exposure,
            "budget_breaches": budget_breaches,
            "diagnostic_exposure": {
                "market_exposure": proposal.diagnostics.get("market_exposure", {}),
                "industry_exposure": proposal.diagnostics.get("industry_exposure", {}),
                "theme_exposure": proposal.diagnostics.get("theme_exposure", {}),
                "currency_exposure": proposal.diagnostics.get("currency_exposure", {}),
            },
            "constraint_shadow_prices": proposal.diagnostics.get("constraint_shadow_prices", []),
        }

    def _portfolio_forward_tracking_metrics(self, returns_result: Mapping[str, Any], benchmark_result: Mapping[str, Any]) -> dict[str, Any]:
        candidate_map = {
            str(row.get("as_of_date", "")): float(row.get("return", 0.0))
            for row in returns_result.get("returns", [])
            if str(row.get("as_of_date", ""))
        }
        benchmark_map = {
            str(row.get("as_of_date", "")): float(row.get("return", 0.0))
            for row in benchmark_result.get("returns", [])
            if str(row.get("as_of_date", ""))
        }
        aligned_dates = sorted(set(candidate_map) & set(benchmark_map))
        active_series = [candidate_map[as_of_date] - benchmark_map[as_of_date] for as_of_date in aligned_dates]
        active_return = self._compound_return(active_series) if active_series else None
        tracking_error = self._series_volatility(active_series) if active_series else None
        information_ratio = (active_return / tracking_error) if active_return is not None and tracking_error not in {None, 0} else None
        return {
            "aligned_dates": aligned_dates,
            "aligned_date_count": len(aligned_dates),
            "active_return_series": [round(value, 8) for value in active_series],
            "active_return": active_return,
            "tracking_error": round(tracking_error, 8) if tracking_error is not None else None,
            "information_ratio": round(information_ratio, 8) if information_ratio is not None else None,
        }

    def _portfolio_forward_review_flags(
        self,
        returns_result: Mapping[str, Any],
        benchmark_result: Mapping[str, Any],
        payload: Mapping[str, Any],
        tracking_metrics: Mapping[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        metrics = dict(tracking_metrics or self._portfolio_forward_tracking_metrics(returns_result, benchmark_result))
        flags: list[dict[str, Any]] = []
        min_common_dates = int(payload.get("min_common_dates", 2))
        common_dates = int(returns_result.get("coverage", {}).get("common_dates", 0))
        if common_dates < min_common_dates:
            flags.append(
                {
                    "flag": "insufficient_return_overlap",
                    "severity": "medium",
                    "value": common_dates,
                    "threshold": min_common_dates,
                    "message": "Return coverage is too short for a stable forward report.",
                }
            )
        max_drawdown_threshold = float(payload.get("max_drawdown_threshold", 0.2))
        if float(returns_result.get("max_drawdown", 0.0)) > max_drawdown_threshold:
            flags.append(
                {
                    "flag": "drawdown_warning",
                    "severity": "high",
                    "value": round(float(returns_result.get("max_drawdown", 0.0)), 8),
                    "threshold": round(max_drawdown_threshold, 8),
                    "message": "Candidate drawdown exceeds the configured tolerance.",
                }
            )
        max_volatility = float(payload.get("max_volatility", 0.35))
        if float(returns_result.get("volatility", 0.0)) > max_volatility:
            flags.append(
                {
                    "flag": "volatility_warning",
                    "severity": "medium",
                    "value": round(float(returns_result.get("volatility", 0.0)), 8),
                    "threshold": round(max_volatility, 8),
                    "message": "Candidate volatility exceeds the configured tolerance.",
                }
            )
        if benchmark_result:
            max_tracking_error = float(payload.get("max_tracking_error", 0.05))
            tracking_error = metrics.get("tracking_error")
            if tracking_error is not None and float(tracking_error) > max_tracking_error:
                flags.append(
                    {
                        "flag": "tracking_error_warning",
                        "severity": "medium",
                        "value": round(float(tracking_error), 8),
                        "threshold": round(max_tracking_error, 8),
                        "message": "Active return volatility exceeds the configured tolerance.",
                    }
                )
            min_active_return = float(payload.get("min_active_return", 0.0))
            active_return = metrics.get("active_return")
            if active_return is not None and float(active_return) < min_active_return:
                flags.append(
                    {
                        "flag": "active_return_shortfall",
                        "severity": "high",
                        "value": round(float(active_return), 8),
                        "threshold": round(min_active_return, 8),
                        "message": "Candidate underperforms the benchmark over the reporting horizon.",
                    }
                )
        if not returns_result.get("returns"):
            flags.append(
                {
                    "flag": "empty_return_series",
                    "severity": "high",
                    "value": 0,
                    "threshold": 1,
                    "message": "No return series was produced for the supplied holdings.",
                }
            )
        return flags

    def portfolio_attribution_backfill(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        """Backfill simulated portfolio performance attribution to operating reports (T-408).

        Reads portfolio returns for a given period, computes attribution by market/currency/
        industry/style, and attaches the result as a JSON annotation on existing operating
        reports within the covered period. All data is simulation/public-EOD-market-data only.
        No real trading account is accessed.

        Payload fields:
            proposal_id: optional PortfolioProposal to use as holdings source
            holdings: list of {security_id, weight} (alternative to proposal_id)
            start_date, end_date: ISO date range for returns computation
            source_id: market data source (default: public_eod_market_data)
            groups: {security_id: {market, industry, style}} overrides
            target_report_ids: list of operating report IDs to annotate (optional)
            dry_run: if true, compute but do not write (default: false)
        """
        proposal_id = str(payload.get("proposal_id", ""))
        holdings = payload.get("holdings", [])
        if proposal_id:
            proposal = self.store.portfolio_proposals.get(proposal_id)
            if proposal is None:
                raise NotFoundError(f"portfolio proposal {proposal_id} not found")
            if proposal.status not in {"approved", "paper"}:
                raise ComplianceGateError(
                    f"attribution backfill requires an approved/paper proposal; got status={proposal.status}"
                )
            holdings = [
                {"security_id": sec_id, "weight": weight}
                for sec_id, weight in (proposal.candidate_weights or {}).items()
            ]
        if not holdings:
            raise ValidationError("portfolio_attribution_backfill requires holdings or a valid proposal_id")
        dry_run = self._truthy(payload.get("dry_run", False))
        returns_payload = dict(payload)
        returns_payload["holdings"] = holdings
        attribution_result = self.portfolio_returns_payload(returns_payload)
        target_report_ids: list[str] = list(payload.get("target_report_ids") or [])
        covered_start = str(payload.get("start_date", ""))
        covered_end = str(payload.get("end_date", ""))
        annotated: list[str] = []
        if not dry_run:
            for report in self.store.operating_reports.values():
                report_id = report.report_id
                if target_report_ids and report_id not in target_report_ids:
                    continue
                report_period = getattr(report, "period", "")
                if covered_start and report_period and report_period < covered_start[:7]:
                    continue
                if covered_end and report_period and report_period > covered_end[:7]:
                    continue
                attribution_annotation = {
                    "attribution_source": "portfolio_attribution_backfill",
                    "proposal_id": proposal_id,
                    "start_date": covered_start,
                    "end_date": covered_end,
                    "total_return": attribution_result.get("total_return"),
                    "volatility": attribution_result.get("volatility"),
                    "max_drawdown": attribution_result.get("max_drawdown"),
                    "attribution": attribution_result.get("attribution"),
                    "simulation_only": True,
                    "live_execution_allowed": False,
                }
                if hasattr(report, "annotations") and isinstance(getattr(report, "annotations", None), dict):
                    report.annotations["portfolio_attribution"] = attribution_annotation  # type: ignore[attr-defined]
                annotated.append(report_id)
            self._audit(
                actor, "portfolio_attribution_backfill", "operating_report", "batch",
                source=str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)),
                approval_state=f"annotated={len(annotated)};dry_run=false",
            )
        else:
            self._audit(
                actor, "portfolio_attribution_backfill", "operating_report", "batch",
                source=str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)),
                approval_state="dry_run=true",
            )
        return {
            "proposal_id": proposal_id,
            "start_date": covered_start,
            "end_date": covered_end,
            "dry_run": dry_run,
            "total_return": attribution_result.get("total_return"),
            "volatility": attribution_result.get("volatility"),
            "max_drawdown": attribution_result.get("max_drawdown"),
            "attribution": attribution_result.get("attribution"),
            "annotated_report_ids": annotated,
            "annotated_count": len(annotated),
            "simulation_only": True,
            "live_execution_allowed": False,
        }

    def portfolio_attribution_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        self._reject_secret_rotation_payload_values(payload)
        artifacts = self._portfolio_attribution_artifact_uris(payload)
        report_summary = self._portfolio_attribution_report_summary()
        replay_summary = self._portfolio_attribution_replay_summary(payload)
        ledger_summary = self._portfolio_attribution_ledger_summary(payload)
        forward_summary = self._portfolio_attribution_forward_summary(payload)
        min_report_count = int(payload.get("min_report_count", 1))
        min_replay_count = int(payload.get("min_replay_count", 1))
        min_transaction_count = int(payload.get("min_transaction_count", 1))
        gates = [
            self._readiness_numeric_gate("operating_report_count", report_summary["report_count"], min_report_count, ">=", "operating reports exist for attribution review"),
            self._readiness_numeric_gate("attribution_annotation_coverage", report_summary["attribution_annotation_coverage"], 1.0, ">=", "operating reports include portfolio attribution annotations"),
            self._readiness_numeric_gate("published_report_approval_coverage", report_summary["published_approval_coverage"], 1.0, ">=", "published operating reports retain CEO/CIO/risk approval signatures"),
            self._readiness_bool_gate("red_flags_resolved_or_owned", report_summary["red_flags_resolved_or_owned"], "each operating report red flag has owner and due date or is resolved"),
            self._readiness_numeric_gate("strategy_replay_count", replay_summary["replay_count"], min_replay_count, ">=", "strategy replay records exist for post-decision review"),
            self._readiness_bool_gate("strategy_replay_variance_reviewed", replay_summary["variance_reviewed"], "strategy replay variance rows include reason and next action"),
            self._readiness_numeric_gate("simulated_ledger_transaction_count", ledger_summary["transaction_count"], min_transaction_count, ">=", "simulated/backtest portfolio ledger is available"),
            self._readiness_bool_gate("ledger_source_boundary", ledger_summary["source_boundary_ok"], "ledger sources are simulated/public/backtest and not live broker feeds"),
            self._readiness_bool_gate("forward_attribution_evidence", forward_summary["present"], "portfolio forward report is present in readiness payload or records"),
            self._readiness_bool_gate("forward_attribution_artifact_uri", bool(artifacts.get("forward_attribution_uri")), "portfolio forward attribution artifact URI"),
            self._readiness_bool_gate("performance_reconciliation_uri", bool(artifacts.get("performance_reconciliation_uri")), "performance/NAV reconciliation artifact URI"),
            self._readiness_bool_gate("ledger_extract_artifact_uri", bool(artifacts.get("ledger_extract_uri")), "simulated ledger extract artifact URI"),
            self._readiness_bool_gate("strategy_replay_artifact_uri", bool(artifacts.get("strategy_replay_uri")), "strategy replay comparison artifact URI"),
            self._readiness_bool_gate("board_pack_artifact_uri", bool(artifacts.get("board_pack_uri")), "published board pack artifact URI"),
            self._readiness_bool_gate("external_account_blocked", not ledger_summary["live_broker_source_seen"], "no real broker or live trading account source is used"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "ready_for_attribution_production": ready,
            "ready_for_external_acceptance": ready,
            "missing_requirements": missing,
            "gates": gates,
            "artifact_uris": artifacts,
            "operating_reports": report_summary,
            "strategy_replays": replay_summary,
            "ledger": ledger_summary,
            "forward_attribution": forward_summary,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "portfolio_attribution_readiness_report_checks_simulated_ledger_reports_replays_and_external_reconciliation_without_broker_access",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "portfolio_attribution_readiness_report", "portfolio_attribution", "production_readiness", approval_state="ready" if ready else "missing_evidence")
        return report

    def portfolio_simulated_feedback(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        """Investment committee UI approval entry and simulated portfolio feedback (T-409).

        Provides a structured approval entry for the investment committee to review a
        PortfolioProposal, optionally update its status to 'approved' or 'rejected',
        and produce a simulated-position feedback summary driven by public EOD market data.

        This is for PAPER/SIMULATION portfolios ONLY. It does NOT connect to any real
        broker, does NOT execute real trades, and must NOT be used to initiate real orders.

        Payload fields:
            proposal_id: required - PortfolioProposal to review
            decision: 'approved' | 'rejected' | 'pending' (default 'pending')
            rationale: free-text decision rationale (max 2000 chars)
            committee_member: actor identifier for the committee member
            feedback_start_date, feedback_end_date: date range for position feedback
            source_id: market data source for feedback valuation
            include_valuation: if true, compute simulated position valuation
        """
        proposal_id = str(payload.get("proposal_id", ""))
        if not proposal_id:
            raise ValidationError("portfolio_simulated_feedback requires proposal_id")
        proposal = self.store.portfolio_proposals.get(proposal_id)
        if proposal is None:
            raise NotFoundError(f"portfolio proposal {proposal_id} not found")
        decision = str(payload.get("decision", "pending")).strip().lower()
        if decision not in {"approved", "rejected", "pending", "needs_revision"}:
            raise ValidationError("decision must be one of: approved, rejected, pending, needs_revision")
        rationale = str(payload.get("rationale", ""))[:2000]
        committee_member = str(payload.get("committee_member", actor)).strip()
        # Record the committee decision on the proposal
        if decision == "approved":
            proposal.status = "paper"
        elif decision == "rejected":
            proposal.status = "rejected"
        # Produce simulated valuation feedback if requested
        valuation_result: dict[str, Any] = {}
        include_valuation = self._truthy(payload.get("include_valuation", True))
        candidate_weights = proposal.candidate_weights or {}
        if include_valuation and candidate_weights:
            holdings = [
                {"security_id": sec_id, "shares": float(weight * 1_000_000)}
                for sec_id, weight in candidate_weights.items()
                if sec_id in self.store.securities
            ]
            if holdings:
                try:
                    valuation_result = self.portfolio_valuation_payload({
                        "holdings": holdings,
                        "as_of_date": str(payload.get("feedback_end_date", "9999-12-31")),
                        "source_id": str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)),
                        "cash": 0.0,
                    })
                except (ValidationError, NotFoundError) as exc:
                    valuation_result = {"error": str(exc)}
        # Compute returns feedback if start/end dates are provided
        returns_feedback: dict[str, Any] = {}
        feedback_start = str(payload.get("feedback_start_date", ""))
        feedback_end = str(payload.get("feedback_end_date", ""))
        if feedback_start and feedback_end and candidate_weights:
            holdings_for_returns = [
                {"security_id": sec_id, "weight": weight}
                for sec_id, weight in candidate_weights.items()
                if sec_id in self.store.securities
            ]
            if holdings_for_returns:
                try:
                    returns_feedback = self.portfolio_returns_payload({
                        "holdings": holdings_for_returns,
                        "start_date": feedback_start,
                        "end_date": feedback_end,
                        "source_id": str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)),
                    })
                except (ValidationError, NotFoundError) as exc:
                    returns_feedback = {"error": str(exc)}
        self._audit(
            actor, "portfolio_simulated_feedback", "portfolio_proposal", proposal_id,
            source="investment_committee",
            approval_state=f"decision={decision};member={committee_member}",
        )
        return {
            "proposal_id": proposal_id,
            "proposal_status": proposal.status,
            "decision": decision,
            "committee_member": committee_member,
            "rationale": rationale,
            "candidate_weights": candidate_weights,
            "simulated_valuation": valuation_result,
            "returns_feedback": returns_feedback,
            "simulation_only": True,
            "live_execution_allowed": False,
            "automation_allowed": False,
            "usage_boundary": "paper_portfolio_simulation_and_feedback_only",
        }

    def portfolio_returns_payload(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        holdings = payload.get("holdings", payload.get("weights", []))
        if isinstance(holdings, Mapping):
            holdings = [{"security_id": key, "weight": value} for key, value in holdings.items()]
        if not isinstance(holdings, list) or not holdings:
            raise ValidationError("portfolio returns require holdings list or weights object")
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        data_type = str(payload.get("data_type", "eod"))
        adjustment_mode = str(payload.get("adjustment_mode", "backward"))
        total_return_method = str(payload.get("total_return_method", "price_only"))
        start_date = str(payload.get("start_date", ""))
        end_date = str(payload.get("end_date", ""))
        limit = self._bounded_limit(payload.get("limit", 10000), 10000)

        series_by_security: dict[str, dict[str, float]] = {}
        normalized_weights: dict[str, float] = {}
        component_summaries: list[dict[str, Any]] = []
        for item in holdings:
            if not isinstance(item, Mapping):
                raise ValidationError("portfolio holding must be an object")
            security_id = str(item["security_id"])
            weight = float(item.get("weight", 0.0))
            if weight < 0:
                raise ValidationError("portfolio returns do not support short weights in this MVP path")
            if security_id not in self.store.securities:
                raise NotFoundError(f"security {security_id} not found")
            result = self.market_data_returns_payload(
                {
                    "security_id": security_id,
                    "source_id": source_id,
                    "data_type": data_type,
                    "adjustment_mode": adjustment_mode,
                    "total_return_method": total_return_method,
                    "start_date": start_date,
                    "end_date": end_date,
                    "limit": limit,
                }
            )
            series_by_security[security_id] = {str(row["as_of_date"]): float(row["return"]) for row in result["returns"]}
            normalized_weights[security_id] = weight
            component_summaries.append(
                {
                    "security_id": security_id,
                    "weight": weight,
                    "return_count": result["return_count"],
                    "total_return": result["total_return"],
                    "volatility": result["volatility"],
                    "max_drawdown": result["max_drawdown"],
                }
            )
        total_weight = sum(normalized_weights.values())
        if total_weight <= 0:
            raise ValidationError("portfolio total weight must be positive")
        normalized_weights = {security_id: weight / total_weight for security_id, weight in normalized_weights.items()}
        common_dates = sorted(set.intersection(*(set(series.keys()) for series in series_by_security.values()))) if series_by_security else []
        returns = []
        for as_of_date in common_dates:
            component_returns = {security_id: series[as_of_date] for security_id, series in series_by_security.items()}
            portfolio_return = sum(normalized_weights[security_id] * component_returns[security_id] for security_id in normalized_weights)
            returns.append(
                {
                    "as_of_date": as_of_date,
                    "return": round(portfolio_return, 8),
                    "component_returns": {security_id: round(value, 8) for security_id, value in component_returns.items()},
                }
            )
        return_values = [item["return"] for item in returns]
        attribution = self._portfolio_return_attribution(returns, normalized_weights, payload.get("groups", {}))
        return {
            "source_id": source_id,
            "data_type": data_type,
            "adjustment_mode": adjustment_mode,
            "total_return_method": total_return_method,
            "weights": {security_id: round(weight, 8) for security_id, weight in normalized_weights.items()},
            "components": component_summaries,
            "attribution": attribution,
            "return_count": len(returns),
            "total_return": round(self._compound_return(return_values), 8) if return_values else 0.0,
            "volatility": round(self._series_volatility(return_values), 8),
            "max_drawdown": round(self._max_drawdown(return_values), 8) if return_values else 0.0,
            "returns": returns,
            "coverage": {
                "common_dates": len(common_dates),
                "component_count": len(series_by_security),
                "requires_common_return_dates": True,
            },
        }

    def _portfolio_return_attribution(self, returns: list[dict[str, Any]], weights: Mapping[str, float], groups: Any) -> dict[str, Any]:
        group_overrides = groups if isinstance(groups, Mapping) else {}
        group_keys = ["market", "currency", "industry", "style"]
        attribution: dict[str, dict[str, dict[str, float]]] = {key: {} for key in group_keys}
        for security_id, weight in weights.items():
            security = self.store.securities.get(security_id)
            override = group_overrides.get(security_id, {}) if isinstance(group_overrides.get(security_id, {}), Mapping) else {}
            contribution = sum(float(row.get("component_returns", {}).get(security_id, 0.0)) * float(weight) for row in returns)
            for group_key in group_keys:
                if group_key in override:
                    group_value = str(override.get(group_key) or "unknown")
                elif security and hasattr(security, group_key):
                    group_value = str(getattr(security, group_key) or "unknown")
                else:
                    group_value = "unknown"
                row = attribution[group_key].setdefault(group_value, {"weight": 0.0, "period_contribution": 0.0})
                row["weight"] += float(weight)
                row["period_contribution"] += contribution
        return {
            group_key: {
                group_value: {
                    "weight": round(values["weight"], 8),
                    "period_contribution": round(values["period_contribution"], 8),
                }
                for group_value, values in sorted(groups_for_key.items())
            }
            for group_key, groups_for_key in attribution.items()
        }

    def _portfolio_attribution_artifact_uris(self, payload: Mapping[str, Any]) -> dict[str, str]:
        aliases = {
            "performance_reconciliation_uri": ["performance_reconciliation_uri", "nav_reconciliation_uri", "performance_attribution_uri"],
            "forward_attribution_uri": ["forward_attribution_uri", "forward_report_uri", "attribution_report_uri"],
            "board_pack_uri": ["board_pack_uri", "operating_report_board_pack_uri", "board_pack_artifact_uri"],
            "ledger_extract_uri": ["ledger_extract_uri", "portfolio_ledger_uri", "simulated_ledger_uri"],
            "strategy_replay_uri": ["strategy_replay_uri", "replay_compare_uri", "strategy_replay_artifact_uri"],
        }
        return self._readiness_artifact_aliases(payload, aliases)

    def _portfolio_attribution_report_summary(self) -> dict[str, Any]:
        reports = list(self.store.operating_reports.values())
        annotated_ids: set[str] = set()
        for item in reports:
            annotations = getattr(item, "annotations", {})
            if isinstance(annotations, Mapping) and isinstance(annotations.get("portfolio_attribution"), Mapping) and annotations["portfolio_attribution"].get("attribution"):
                annotated_ids.add(item.report_id)
        published = [item for item in reports if item.status == "published"]
        approved_published = [item for item in published if item.approvals]
        red_flags = [flag for item in reports for flag in item.red_flags]
        red_flags_owned = [
            flag
            for flag in red_flags
            if str(flag.get("status", "open")) == "resolved" or (str(flag.get("owner_role") or flag.get("owner") or "").strip() and str(flag.get("due_date") or flag.get("due") or "").strip())
        ]
        board_pack_exports = [
            event
            for event in self.store.audit_log
            if event.action == "export_operating_report_board_pack" and event.resource_type == "operating_report"
        ]
        return {
            "report_count": len(reports),
            "published_count": len(published),
            "attribution_annotated_count": len(annotated_ids),
            "attribution_annotation_coverage": round(len(annotated_ids) / max(1, len(reports)), 4) if reports else 0.0,
            "published_approval_coverage": round(len(approved_published) / max(1, len(published)), 4) if published else 1.0,
            "red_flag_count": len(red_flags),
            "red_flags_resolved_or_owned": len(red_flags_owned) == len(red_flags),
            "board_pack_export_count": len(board_pack_exports),
            "report_ids_missing_attribution": sorted(item.report_id for item in reports if item.report_id not in annotated_ids),
        }

    def _portfolio_attribution_replay_summary(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        compare = self.strategy_replay_compare_report({"limit": payload.get("replay_limit", 100)})
        rows = list(compare.get("replays", []))
        variance_rows = [row for row in rows if str(row.get("variance_reason", "")).strip()]
        reviewed = [
            row
            for row in variance_rows
            if str(row.get("next_action", "")).strip() and str(row.get("actual_outcome", "")).strip()
        ]
        return {
            "replay_count": int(compare["count"]),
            "variance_count": int(compare["variance_count"]),
            "variance_reviewed_count": len(reviewed),
            "variance_reviewed": len(reviewed) == len(variance_rows),
            "latest_replay_id": str(compare.get("latest_replay_id", "")),
            "action_counts": dict(compare.get("action_counts", {})),
        }

    def _portfolio_attribution_ledger_summary(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        account_id = str(payload.get("account_id", "")).strip()
        strategy_id = str(payload.get("strategy_id", "")).strip()
        filters = {"account_id": account_id, "strategy_id": strategy_id, "limit": payload.get("ledger_limit", 1000)}
        ledger = self.portfolio_transactions_payload(filters)
        transactions = list(self.store.portfolio_transactions.values())
        if account_id:
            transactions = [item for item in transactions if item.account_id == account_id]
        if strategy_id:
            transactions = [item for item in transactions if item.strategy_id == strategy_id]
        source_ids = sorted({item.source_id for item in transactions if item.source_id})
        source_types = sorted({self.store.sources[item.source_id].source_type for item in transactions if item.source_id in self.store.sources})
        live_markers = {"broker", "live_broker", "live_trading", "real_account", "execution_broker"}
        live_seen = any(marker in str(value).lower() for value in [*source_ids, *source_types] for marker in live_markers)
        allowed = all(
            (
                not item.source_id
                or item.source_id in {SIMULATED_TRADE_SOURCE_ID, PUBLIC_EOD_MARKET_DATA_SOURCE_ID}
                or (item.source_id in self.store.sources and self.store.sources[item.source_id].source_type in {"simulated", "market_data", "regulatory", "manual_reference"})
            )
            for item in transactions
        )
        return {
            "transaction_count": int(ledger["total"]),
            "source_ids": source_ids,
            "source_types": source_types,
            "source_boundary_ok": allowed and not live_seen,
            "live_broker_source_seen": live_seen,
        }

    def _portfolio_attribution_forward_summary(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        raw = payload.get("forward_report", payload.get("forward_attribution", {}))
        data = dict(raw) if isinstance(raw, Mapping) else {}
        if not data:
            return {
                "present": False,
                "return_count": 0,
                "has_attribution": False,
                "simulation_only": True,
                "live_execution_allowed": False,
            }
        attribution = data.get("attribution", {})
        return {
            "present": True,
            "return_count": int(data.get("return_count", 0) or 0),
            "has_attribution": isinstance(attribution, Mapping) and bool(attribution),
            "simulation_only": self._truthy(data.get("simulation_only", True)),
            "live_execution_allowed": self._truthy(data.get("live_execution_allowed", False)),
            "review_flag_count": len(data.get("review_flags", [])) if isinstance(data.get("review_flags", []), list) else 0,
        }

    def portfolio_valuation_payload(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        holdings = payload.get("holdings", [])
        if not isinstance(holdings, list) or not holdings:
            raise ValidationError("portfolio valuation requires holdings list")
        as_of_date = str(payload.get("as_of_date", "9999-12-31"))
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        data_type = str(payload.get("data_type", "eod"))
        price_field = str(payload.get("price_field", "close"))
        if price_field not in {"close", "adjusted_close"}:
            raise ValidationError("valuation price_field must be close or adjusted_close")
        cash = float(payload.get("cash", 0.0))
        currency = str(payload.get("currency", "CNY"))
        group_overrides = payload.get("groups", {})
        group_overrides = group_overrides if isinstance(group_overrides, Mapping) else {}
        positions: list[dict[str, Any]] = []
        missing_prices: list[dict[str, Any]] = []
        total_market_value = cash
        for item in holdings:
            if not isinstance(item, Mapping):
                raise ValidationError("valuation holding must be an object")
            security_id = str(item["security_id"])
            shares = float(item.get("shares", 0.0))
            if shares < 0:
                raise ValidationError("portfolio valuation does not support short shares in this MVP path")
            if security_id not in self.store.securities:
                raise NotFoundError(f"security {security_id} not found")
            security = self.store.securities[security_id]
            point = self._latest_market_data_point(security_id, source_id=source_id, data_type=data_type, as_of_date=as_of_date)
            if point is None:
                missing_prices.append({"security_id": security_id, "reason": "no_market_data_at_or_before_as_of_date"})
                continue
            price = float(getattr(point, price_field))
            market_value = shares * price
            override = group_overrides.get(security_id, {}) if isinstance(group_overrides.get(security_id, {}), Mapping) else {}
            position_currency = str(item.get("currency") or override.get("currency") or point.currency or security.currency or currency)
            position_market = str(item.get("market") or override.get("market") or point.market or security.market or "unknown")
            total_market_value += market_value
            positions.append(
                {
                    "security_id": security_id,
                    "shares": shares,
                    "price": round(price, 6),
                    "price_date": point.as_of_date,
                    "market_value": round(market_value, 6),
                    "source_id": point.source_id,
                    "data_type": point.data_type,
                    "price_field": price_field,
                    "market": position_market,
                    "currency": position_currency,
                    "industry": str(item.get("industry") or override.get("industry") or "unclassified"),
                    "style": str(item.get("style") or override.get("style") or "unclassified"),
                }
            )
        for position in positions:
            position["weight"] = round(float(position["market_value"]) / total_market_value, 8) if total_market_value else 0.0
        cash_weight = round(cash / total_market_value, 8) if total_market_value else 0.0
        risk_decomposition = self._portfolio_valuation_risk_decomposition(positions, cash=cash, cash_weight=cash_weight, portfolio_currency=currency)
        return {
            "as_of_date": as_of_date,
            "source_id": source_id,
            "data_type": data_type,
            "price_field": price_field,
            "currency": currency,
            "cash": round(cash, 6),
            "cash_weight": cash_weight,
            "gross_market_value": round(sum(float(position["market_value"]) for position in positions), 6),
            "total_market_value": round(total_market_value, 6),
            "positions": positions,
            "missing_prices": missing_prices,
            "position_count": len(positions),
            "missing_price_count": len(missing_prices),
            "risk_decomposition": risk_decomposition,
            "valuation_policy": "Uses latest public/provided market data at or before as_of_date; does not imply execution or tradability.",
        }

    def _portfolio_valuation_risk_decomposition(
        self,
        positions: list[dict[str, Any]],
        *,
        cash: float,
        cash_weight: float,
        portfolio_currency: str,
    ) -> dict[str, Any]:
        group_keys = ["market", "currency", "industry", "style"]
        exposures: dict[str, dict[str, dict[str, Any]]] = {key: {} for key in group_keys}
        for position in positions:
            market_value = float(position.get("market_value", 0.0))
            weight = float(position.get("weight", 0.0))
            for group_key in group_keys:
                group_value = str(position.get(group_key) or "unknown")
                row = exposures[group_key].setdefault(group_value, {"market_value": 0.0, "weight": 0.0, "position_count": 0, "top_position": "", "top_weight": 0.0})
                row["market_value"] += market_value
                row["weight"] += weight
                row["position_count"] += 1
                if weight > float(row["top_weight"]):
                    row["top_position"] = str(position.get("security_id", ""))
                    row["top_weight"] = weight
        rounded_exposures = {
            group_key: {
                group_value: {
                    "market_value": round(values["market_value"], 6),
                    "weight": round(values["weight"], 8),
                    "position_count": values["position_count"],
                    "top_position": values["top_position"],
                    "top_weight": round(values["top_weight"], 8),
                }
                for group_value, values in sorted(group_values.items())
            }
            for group_key, group_values in exposures.items()
        }
        sorted_positions = sorted(positions, key=lambda item: float(item.get("weight", 0.0)), reverse=True)
        weights = [float(item.get("weight", 0.0)) for item in positions]
        foreign_currency_weight = sum(float(item.get("weight", 0.0)) for item in positions if str(item.get("currency", "")) != portfolio_currency)
        unclassified = {
            group_key: round(float(rounded_exposures[group_key].get("unclassified", {}).get("weight", 0.0)), 8)
            for group_key in ["industry", "style"]
        }
        return {
            "by_market": rounded_exposures["market"],
            "by_currency": rounded_exposures["currency"],
            "by_industry": rounded_exposures["industry"],
            "by_style": rounded_exposures["style"],
            "cash": {"market_value": round(cash, 6), "weight": cash_weight, "currency": portfolio_currency},
            "concentration": {
                "position_count": len(positions),
                "top_position_weight": round(weights[0], 8) if weights else 0.0,
                "top_5_weight": round(sum(sorted(weights, reverse=True)[:5]), 8),
                "herfindahl_index": round(sum(weight * weight for weight in weights), 8),
            },
            "foreign_currency_weight": round(foreign_currency_weight, 8),
            "unclassified_weight": unclassified,
        }

    def register_portfolio_transaction(self, payload: Mapping[str, Any], *, actor: str = "system") -> PortfolioTransaction:
        security_id = str(payload["security_id"])
        if security_id not in self.store.securities:
            raise NotFoundError(f"security {security_id} not found")
        trade_date = str(payload["trade_date"])
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", trade_date):
            raise ValidationError("trade_date must use YYYY-MM-DD")
        source_id = self._canonical_source_id(str(payload.get("source_id", PUBLIC_EOD_MARKET_DATA_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id == PUBLIC_EOD_MARKET_DATA_SOURCE_ID:
                self.seed_default_sources(actor=actor)
            else:
                raise NotFoundError(f"source {source_id} not found")
        source = self.store.sources[source_id]
        if source.risk_level == "red":
            raise PermissionDenied("red transaction source cannot enter portfolio ledger")
        transaction = PortfolioTransaction(
            transaction_id=str(payload.get("transaction_id", new_id("ptxn"))),
            security_id=security_id,
            trade_date=trade_date,
            side=str(payload["side"]),
            quantity=float(payload.get("quantity", 0.0)),
            price=float(payload.get("price", 0.0)),
            currency=str(payload.get("currency", self.store.securities[security_id].currency)),
            fees=float(payload.get("fees", 0.0)),
            source_id=source_id,
            account_id=str(payload.get("account_id", "")),
            strategy_id=str(payload.get("strategy_id", "")),
        )
        if transaction.quantity <= 0 or transaction.price < 0 or transaction.fees < 0:
            raise ValidationError("transaction quantity must be positive and price/fees non-negative")
        if transaction.transaction_id in self.store.portfolio_transactions:
            raise ConflictError(f"portfolio transaction {transaction.transaction_id} already exists")
        self.store.portfolio_transactions[transaction.transaction_id] = transaction
        self._audit(actor, "register_portfolio_transaction", "portfolio_transaction", transaction.transaction_id, source=source.source_type, approval_state=transaction.side)
        return transaction

    def import_portfolio_transactions(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        rows = payload.get("rows", payload.get("items", []))
        if not isinstance(rows, list):
            raise ValidationError("portfolio transaction import requires rows list")
        dry_run = self._truthy(payload.get("dry_run", False))
        source_id = self._canonical_source_id(str(payload.get("source_id", SIMULATED_TRADE_SOURCE_ID)))
        if source_id not in self.store.sources:
            if source_id in {SIMULATED_TRADE_SOURCE_ID, PUBLIC_EOD_MARKET_DATA_SOURCE_ID}:
                self.seed_default_sources(actor=actor)
            else:
                raise NotFoundError(f"source {source_id} not found")
        source = self.store.sources[source_id]
        if source.risk_level == "red":
            raise PermissionDenied("red transaction source cannot enter portfolio ledger")
        account_id = str(payload.get("account_id", ""))
        strategy_id = str(payload.get("strategy_id", ""))
        security_map = payload.get("security_map", {})
        if not isinstance(security_map, Mapping):
            raise ValidationError("security_map must be an object when provided")
        created: list[PortfolioTransaction] = []
        normalized_rows: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        errors: list[dict[str, Any]] = []
        for index, row in enumerate(rows):
            if not isinstance(row, Mapping):
                errors.append({"index": index, "error": "row must be an object"})
                continue
            try:
                normalized = self._normalize_portfolio_transaction_row(
                    row,
                    index=index,
                    source_id=source_id,
                    account_id=account_id,
                    strategy_id=str(row.get("strategy_id", strategy_id)),
                    security_map=security_map,
                )
                if normalized["transaction_id"] in self.store.portfolio_transactions and self._truthy(payload.get("skip_existing", True)):
                    skipped.append({"index": index, "transaction_id": normalized["transaction_id"], "reason": "already_exists"})
                    continue
                normalized_rows.append(normalized)
                if not dry_run:
                    created.append(self.register_portfolio_transaction(normalized, actor=actor))
            except (ValidationError, NotFoundError, PermissionDenied, ConflictError) as exc:
                errors.append({"index": index, "error": str(exc), "raw": dict(row)})
        self._audit(
            actor,
            "import_portfolio_transactions",
            "portfolio_transaction",
            str(payload.get("batch_id", "portfolio_transaction_import")),
            source=source.source_type,
            approval_state=f"created={len(created)};normalized={len(normalized_rows)};failed={len(errors)};dry_run={str(dry_run).lower()}",
        )
        return {
            "dry_run": dry_run,
            "source_id": source_id,
            "source_type": source.source_type,
            "source_rows": len(rows),
            "normalized_count": len(normalized_rows),
            "created_count": len(created),
            "skipped_count": len(skipped),
            "failed_count": len(errors),
            "normalized": normalized_rows,
            "created": [to_plain(item) for item in created],
            "skipped": skipped,
            "errors": errors,
            "simulation_only": True,
            "live_execution_allowed": False,
            "usage_boundary": "portfolio_transaction_import_accepts_simulated_or_backtest_ledgers_only_no_broker_execution",
        }

    def portfolio_transactions_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        security_id = str(filters.get("security_id", "")).strip()
        account_id = str(filters.get("account_id", "")).strip()
        strategy_id = str(filters.get("strategy_id", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        transactions = list(self.store.portfolio_transactions.values())
        if security_id:
            transactions = [item for item in transactions if item.security_id == security_id]
        if account_id:
            transactions = [item for item in transactions if item.account_id == account_id]
        if strategy_id:
            transactions = [item for item in transactions if item.strategy_id == strategy_id]
        transactions.sort(key=lambda item: (item.trade_date, item.transaction_id), reverse=True)
        return {"total": len(transactions), "transactions": [to_plain(item) for item in transactions[:limit]]}

    def portfolio_positions_from_transactions(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        as_of_date = str(filters.get("as_of_date", "9999-12-31"))
        account_id = str(filters.get("account_id", "")).strip()
        strategy_id = str(filters.get("strategy_id", "")).strip()
        transactions = [item for item in self.store.portfolio_transactions.values() if item.trade_date <= as_of_date]
        if account_id:
            transactions = [item for item in transactions if item.account_id == account_id]
        if strategy_id:
            transactions = [item for item in transactions if item.strategy_id == strategy_id]
        shares: dict[str, float] = {}
        cost: dict[str, float] = {}
        for transaction in sorted(transactions, key=lambda item: (item.trade_date, item.transaction_id)):
            sign = 1.0 if transaction.side == "buy" else -1.0
            shares[transaction.security_id] = shares.get(transaction.security_id, 0.0) + sign * transaction.quantity
            cash_flow = sign * transaction.quantity * transaction.price + transaction.fees
            cost[transaction.security_id] = cost.get(transaction.security_id, 0.0) + cash_flow
        positions = [
            {
                "security_id": security_id,
                "shares": round(quantity, 8),
                "net_cost": round(cost.get(security_id, 0.0), 6),
            }
            for security_id, quantity in sorted(shares.items())
            if abs(quantity) > 1e-9
        ]
        return {
            "as_of_date": as_of_date,
            "account_id": account_id,
            "strategy_id": strategy_id,
            "positions": positions,
            "position_count": len(positions),
            "transaction_count": len(transactions),
        }

    def portfolio_proposal_payload(self, proposal_id: str) -> dict[str, Any]:
        proposal = self.store.portfolio_proposals.get(proposal_id)
        if proposal is None:
            raise NotFoundError(f"portfolio proposal {proposal_id} not found")
        return to_plain(proposal)

    def list_portfolio_proposals(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        status = str(payload.get("status", ""))
        created_by = str(payload.get("created_by", ""))
        proposals = [
            proposal
            for proposal in self.store.portfolio_proposals.values()
            if (not status or proposal.status == status) and (not created_by or proposal.created_by == created_by)
        ]
        proposals.sort(key=lambda item: item.created_at, reverse=True)
        return {"count": len(proposals), "proposals": [to_plain(item) for item in proposals]}

    def macro_themes_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        trigger_type = str(filters.get("trigger_type", "")).strip()
        query = str(filters.get("q", "")).strip().lower()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        rows = list(self.store.macro_themes.values())
        if trigger_type:
            rows = [item for item in rows if item.trigger_type == trigger_type]
        if query:
            rows = [
                item
                for item in rows
                if query in item.name.lower()
                or query in item.description.lower()
                or any(query in value.lower() for value in item.macro_drivers)
            ]
        rows.sort(key=lambda item: item.created_at, reverse=True)
        return {"count": len(rows), "themes": [to_plain(item) for item in rows[:limit]]}

    def industry_chains_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        root_theme_id = str(filters.get("root_theme_id", "")).strip()
        query = str(filters.get("q", "")).strip().lower()
        template_status = str(filters.get("template_status", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        rows = list(self.store.industry_chains.values())
        if root_theme_id:
            rows = [item for item in rows if item.root_theme_id == root_theme_id]
        if template_status:
            rows = [item for item in rows if getattr(item, "template_status", "published_legacy") == template_status]
        if query:
            rows = [
                item
                for item in rows
                if query in item.name.lower()
                or any(query in str(node.get("name", "")).lower() or query in " ".join(str(value).lower() for value in node.get("keywords", [])) for node in item.nodes)
            ]
        rows.sort(key=lambda item: item.created_at, reverse=True)
        return {"count": len(rows), "chains": [to_plain(item) for item in rows[:limit]]}

    def industry_chain_template_candidates_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        candidate_id = str(filters.get("candidate_id", "")).strip()
        target_chain_id = str(filters.get("target_chain_id", filters.get("chain_id", ""))).strip()
        status = str(filters.get("status", "")).strip()
        query = str(filters.get("q", "")).strip().lower()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        rows = list(self.store.industry_chain_template_candidates.values())
        if candidate_id:
            rows = [item for item in rows if item.candidate_id == candidate_id]
        if target_chain_id:
            rows = [item for item in rows if item.target_chain_id == target_chain_id]
        if status:
            rows = [item for item in rows if item.status == status]
        if query:
            rows = [
                item
                for item in rows
                if query in item.name.lower()
                or query in item.candidate_id.lower()
                or query in item.target_chain_id.lower()
                or any(query in str(node.get("name", "")).lower() or query in " ".join(str(value).lower() for value in node.get("keywords", [])) for node in item.nodes)
            ]
        rows.sort(key=lambda item: (item.updated_at, item.created_at), reverse=True)
        return {
            "count": len(rows),
            "candidates": [to_plain(item) for item in rows[:limit]],
            "automation_allowed": False,
            "usage_boundary": "industry_chain_template_governance_research_only",
        }

    def industry_chain_template_candidate_payload(self, candidate_id: str) -> dict[str, Any]:
        candidate = self.store.industry_chain_template_candidates.get(str(candidate_id).strip())
        if candidate is None:
            raise NotFoundError(f"industry chain template candidate {candidate_id} not found")
        return self._industry_chain_template_candidate_response(candidate)

    def create_industry_chain_template_candidate(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        candidate_payload = self._industry_chain_template_candidate_seed_payload(payload)
        candidate_id = str(candidate_payload.get("candidate_id") or new_id("chain_tpl")).strip()
        if candidate_id in self.store.industry_chain_template_candidates:
            raise ConflictError(f"industry chain template candidate {candidate_id} already exists")
        name = str(candidate_payload.get("name", "")).strip()
        if not name:
            raise ValidationError("industry chain template candidate requires name")
        nodes = [dict(item) for item in candidate_payload.get("nodes", [])]
        edges = [dict(item) for item in candidate_payload.get("edges", [])]
        self._validate_industry_chain_template_graph(nodes, edges)
        candidate = IndustryChainTemplateCandidate(
            candidate_id=candidate_id,
            name=name,
            target_chain_id=str(candidate_payload.get("target_chain_id") or candidate_payload.get("chain_id") or new_id("chain")).strip(),
            root_theme_id=str(candidate_payload.get("root_theme_id", "")),
            nodes=nodes,
            edges=edges,
            taxonomy_version=str(candidate_payload.get("taxonomy_version", "industry-chain-template-v1")),
            source_refs=self._string_list(candidate_payload.get("source_refs", [])),
            evidence_policy=dict(candidate_payload.get("evidence_policy", self._default_industry_chain_template_evidence_policy())),
            status=str(candidate_payload.get("status", "draft")),
            created_by=actor,
        )
        self._refresh_industry_chain_template_candidate(candidate)
        self.store.industry_chain_template_candidates[candidate.candidate_id] = candidate
        self._audit(actor, "create_industry_chain_template_candidate", "industry_chain_template_candidate", candidate.candidate_id)
        return self._industry_chain_template_candidate_response(candidate)

    def submit_industry_chain_template_candidate(self, candidate_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        candidate = self.store.industry_chain_template_candidates.get(str(candidate_id).strip())
        if candidate is None:
            raise NotFoundError(f"industry chain template candidate {candidate_id} not found")
        if candidate.status == "published":
            raise ValidationError("published industry chain template candidate cannot be resubmitted")
        if payload.get("notes"):
            candidate.coverage = {**candidate.coverage, "submit_notes": str(payload.get("notes", ""))}
        candidate.status = "needs_review"
        candidate.submitted_at = utcnow()
        self._refresh_industry_chain_template_candidate(candidate)
        self._audit(actor, "submit_industry_chain_template_candidate", "industry_chain_template_candidate", candidate.candidate_id)
        return self._industry_chain_template_candidate_response(candidate)

    def review_industry_chain_template_candidate(self, candidate_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        candidate = self.store.industry_chain_template_candidates.get(str(candidate_id).strip())
        if candidate is None:
            raise NotFoundError(f"industry chain template candidate {candidate_id} not found")
        decision = str(payload.get("decision", "")).strip()
        if not decision:
            raise ValidationError("industry chain template review requires decision")
        quality = self._refresh_industry_chain_template_candidate(candidate)
        if decision == "approved" and not bool(quality["coverage"].get("publishable", False)):
            raise ValidationError("industry chain template candidate cannot be approved before blocking requirements are resolved")
        review_id = str(payload.get("review_id") or f"tplreview_{safe_source_part(candidate.candidate_id)}_{len(candidate.review_ids) + 1}").strip()
        if review_id in self.store.industry_chain_template_reviews:
            raise ConflictError(f"industry chain template review {review_id} already exists")
        review = IndustryChainTemplateReview(
            review_id=review_id,
            candidate_id=candidate.candidate_id,
            reviewer=str(payload.get("reviewer") or actor),
            decision=decision,
            notes=str(payload.get("notes", "")),
            findings=[str(item) for item in payload.get("findings", [])],
            missing_requirements=[dict(item) for item in quality["missing_requirements"]],
            coverage=dict(quality["coverage"]),
        )
        self.store.industry_chain_template_reviews[review.review_id] = review
        candidate.review_ids = self._unique_strings([*candidate.review_ids, review.review_id])
        candidate.status = "approved" if decision == "approved" else "rejected"
        candidate.updated_at = utcnow()
        self._audit(actor, "review_industry_chain_template_candidate", "industry_chain_template_candidate", candidate.candidate_id, approval_state=decision)
        return {
            **self._industry_chain_template_candidate_response(candidate),
            "review": to_plain(review),
        }

    def publish_industry_chain_template_candidate(self, candidate_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        candidate = self.store.industry_chain_template_candidates.get(str(candidate_id).strip())
        if candidate is None:
            raise NotFoundError(f"industry chain template candidate {candidate_id} not found")
        quality = self._refresh_industry_chain_template_candidate(candidate)
        if not bool(quality["coverage"].get("publishable", False)):
            raise ValidationError("industry chain template candidate has unresolved blocking requirements")
        if candidate.status != "approved" and not self._truthy(payload.get("force", False)):
            raise ValidationError("industry chain template candidate must be approved before publish")
        chain_id = str(payload.get("chain_id") or candidate.target_chain_id or new_id("chain")).strip()
        if chain_id in self.store.industry_chains and not self._truthy(payload.get("replace_existing", True)):
            raise ConflictError(f"industry chain {chain_id} already exists")
        if candidate.root_theme_id and candidate.root_theme_id not in self.store.macro_themes:
            raise NotFoundError(f"macro theme {candidate.root_theme_id} not found")
        now = utcnow()
        chain = IndustryChain(
            chain_id=chain_id,
            name=str(payload.get("name") or candidate.name),
            root_theme_id=candidate.root_theme_id,
            nodes=[dict(item) for item in candidate.nodes],
            edges=[dict(item) for item in candidate.edges],
            taxonomy_version=candidate.taxonomy_version,
            source_refs=list(candidate.source_refs),
            template_status="published",
            template_candidate_id=candidate.candidate_id,
            review_ids=list(candidate.review_ids),
            governance={
                "evidence_policy": dict(candidate.evidence_policy),
                "coverage": dict(candidate.coverage),
                "published_by": actor,
                "legacy_chain_id_compatibility": chain_id,
            },
            published_at=now,
            created_at=now,
        )
        self.store.industry_chains[chain.chain_id] = chain
        candidate.status = "published"
        candidate.published_chain_id = chain.chain_id
        candidate.published_at = now
        candidate.updated_at = now
        created_tasks = self._upsert_industry_chain_template_research_tasks(candidate, actor=actor)
        created_positions = self._upsert_ai_compute_company_positions_from_template(candidate, chain, payload, actor=actor)
        self._audit(actor, "publish_industry_chain_template_candidate", "industry_chain", chain.chain_id, approval_state="published")
        return {
            "candidate": to_plain(candidate),
            "chain": to_plain(chain),
            "created_research_tasks": created_tasks,
            "created_company_positions": created_positions,
            "automation_allowed": False,
            "usage_boundary": "published_industry_chain_template_research_only_not_trade_signal",
        }

    def _industry_chain_template_candidate_response(self, candidate: IndustryChainTemplateCandidate) -> dict[str, Any]:
        reviews = [self.store.industry_chain_template_reviews[review_id] for review_id in candidate.review_ids if review_id in self.store.industry_chain_template_reviews]
        return {
            "candidate": to_plain(candidate),
            "reviews": [to_plain(item) for item in reviews],
            "coverage": dict(candidate.coverage),
            "research_tasks": [dict(item) for item in candidate.research_tasks],
            "automation_allowed": False,
            "usage_boundary": "industry_chain_template_candidate_governance_research_only",
        }

    def _industry_chain_template_candidate_seed_payload(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        template_key = str(
            payload.get("template_id")
            or payload.get("template_key")
            or payload.get("seed_template")
            or payload.get("taxonomy_version")
            or payload.get("candidate_id")
            or ""
        ).strip()
        query_text = " ".join(str(payload.get(key, "")) for key in ["name", "q", "query", "description"]).lower()
        if template_key in {"ai-compute-chain-v1", "ai_compute_v1", "ai-compute-chain"} or "ai compute" in query_text or "ai 算力" in query_text or "算力" in query_text:
            seeded = self._ai_compute_chain_template_candidate_payload(payload)
            return {**seeded, **{key: value for key, value in payload.items() if key in {"status", "created_by"}}}
        return dict(payload)

    def _default_industry_chain_template_evidence_policy(self) -> dict[str, Any]:
        return {
            "fact_layer_allowed_source_types": [
                "regulatory",
                "company_ir",
                "company_official",
                "official_public",
                "exchange_disclosure",
                "issuer_disclosure",
            ],
            "opinion_layer_source_types": ["local_reference", "research", "broker_research", "news"],
            "fact_layer_rule": "facts must cite public official company, regulatory, prospectus, annual report, or official product/business disclosure evidence",
            "economics_missing_policy": "publishable_with_chain_segment_economics_backfill_task",
        }

