    def hotspot_lexicons_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        query = str(filters.get("q", "")).strip().lower()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        rows = list(self.store.hotspot_lexicons.values())
        if query:
            rows = [item for item in rows if self._hotspot_lexicon_matches(item, query)]
        rows.sort(key=lambda item: item.created_at, reverse=True)
        return {"count": len(rows), "lexicons": [to_plain(item) for item in rows[:limit]]}

    def register_research_task(self, payload: Mapping[str, Any], *, actor: str = "system") -> ResearchTask:
        task_id = str(payload.get("task_id") or new_id("rtask")).strip()
        task_type = str(payload.get("task_type", payload.get("type", ""))).strip()
        if not task_type:
            raise ValidationError("research task requires task_type")
        if task_id in self.store.research_tasks:
            raise ConflictError(f"research task {task_id} already exists")
        task = self._build_research_task(task_id, task_type, payload)
        self.store.research_tasks[task.task_id] = task
        self._audit(actor, "register_research_task", "research_task", task.task_id)
        return task

    def research_tasks_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        status = str(filters.get("status", "")).strip()
        task_type = str(filters.get("task_type", filters.get("type", ""))).strip()
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        chain_id = str(filters.get("chain_id", "")).strip()
        node_id = str(filters.get("node_id", "")).strip()
        position_id = str(filters.get("position_id", "")).strip()
        source = str(filters.get("source", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 100), 1000)
        rows = list(self.store.research_tasks.values())
        if status:
            rows = [item for item in rows if item.status == status]
        if task_type:
            rows = [item for item in rows if item.task_type == task_type]
        if issuer_id:
            rows = [item for item in rows if item.issuer_id == issuer_id]
        if security_id:
            rows = [item for item in rows if item.security_id == security_id]
        if chain_id:
            rows = [item for item in rows if item.chain_id == chain_id]
        if node_id:
            rows = [item for item in rows if node_id in item.node_ids]
        if position_id:
            rows = [item for item in rows if item.position_id == position_id]
        if source:
            rows = [item for item in rows if item.source == source]
        rows.sort(key=lambda item: (item.status != "open", -item.priority, item.updated_at), reverse=False)
        return {"count": len(rows), "tasks": [to_plain(item) for item in rows[:limit]]}

    def update_research_task_status(self, task_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> ResearchTask:
        task = self.store.research_tasks.get(task_id)
        if task is None:
            raise NotFoundError(f"research task {task_id} not found")
        status = str(payload.get("status", "")).strip()
        if not status:
            raise ValidationError("research task status update requires status")
        updated = ResearchTask(
            task_id=task.task_id,
            task_type=task.task_type,
            source=task.source,
            issuer_id=task.issuer_id,
            security_id=task.security_id,
            chain_id=task.chain_id,
            node_ids=list(task.node_ids),
            position_id=task.position_id,
            required_slots=list(task.required_slots),
            reason=str(payload.get("reason", task.reason)),
            status=status,
            priority=int(payload.get("priority", task.priority)),
            assignee=str(payload.get("assignee", task.assignee)),
            evidence_ids=[str(item) for item in payload.get("evidence_ids", task.evidence_ids)],
            metadata={**task.metadata, **dict(payload.get("metadata", {}))},
            created_at=task.created_at,
            updated_at=utcnow(),
        )
        self.store.research_tasks[task_id] = updated
        self._audit(actor, "update_research_task_status", "research_task", task_id)
        return updated

    def create_research_tasks_from_hotspot(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        expansion_payload = dict(payload)
        if not self._truthy(payload.get("queue_current_page", False)):
            expansion_payload.pop("page_token", None)
            expansion_payload.pop("offset", None)
        expansion = self.hotspot_expansion(expansion_payload, actor=actor)
        raw_tasks = list(expansion.get("research_tasks", []))
        if not self._truthy(payload.get("queue_current_page", False)):
            next_token = expansion.get("pagination", {}).get("sections", {}).get("research_tasks", {}).get("next_page_token")
            while next_token:
                next_payload = {**expansion_payload, "page_token": next_token}
                next_expansion = self.hotspot_expansion(next_payload, actor=actor)
                raw_tasks.extend(next_expansion.get("research_tasks", []))
                next_token = next_expansion.get("pagination", {}).get("sections", {}).get("research_tasks", {}).get("next_page_token")
        created: list[dict[str, Any]] = []
        existing: list[dict[str, Any]] = []
        for raw_task in raw_tasks:
            normalized = self._normalize_hotspot_research_task(raw_task, payload, expansion)
            task_id = normalized["task_id"]
            if task_id in self.store.research_tasks:
                existing_task = self.store.research_tasks[task_id]
                refreshed = ResearchTask(
                    task_id=existing_task.task_id,
                    task_type=existing_task.task_type,
                    source=existing_task.source,
                    issuer_id=existing_task.issuer_id,
                    security_id=existing_task.security_id,
                    chain_id=existing_task.chain_id,
                    node_ids=list(existing_task.node_ids),
                    position_id=existing_task.position_id,
                    required_slots=sorted(set(existing_task.required_slots) | set(normalized.get("required_slots", []))),
                    reason=existing_task.reason or str(normalized.get("reason", "")),
                    status=existing_task.status,
                    priority=max(existing_task.priority, int(normalized.get("priority", existing_task.priority))),
                    assignee=existing_task.assignee,
                    evidence_ids=list(existing_task.evidence_ids),
                    metadata={**existing_task.metadata, **dict(normalized.get("metadata", {}))},
                    created_at=existing_task.created_at,
                    updated_at=utcnow(),
                )
                self.store.research_tasks[task_id] = refreshed
                existing.append(to_plain(refreshed))
                continue
            task = self._build_research_task(task_id, str(normalized["task_type"]), normalized)
            self.store.research_tasks[task.task_id] = task
            created.append(to_plain(task))
            self._audit(actor, "create_research_task_from_hotspot", "research_task", task.task_id)
        return {
            "query": expansion["query"],
            "created_count": len(created),
            "existing_count": len(existing),
            "created_tasks": created,
            "existing_tasks": existing,
            "source_research_task_count": len(raw_tasks),
            "usage_boundary": "research_task_queue_for_public_analysis_and_simulated_feedback_only",
        }

    def create_research_tasks_from_hotspot_batch(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        raw_queries = payload.get("queries", [])
        if isinstance(raw_queries, str):
            raw_queries = [item.strip() for item in raw_queries.split(",") if item.strip()]
        queries = [str(item).strip() for item in raw_queries if str(item).strip()]
        if not queries:
            raise ValidationError("hotspot batch requires queries")
        batch_limit = self._bounded_limit(payload.get("batch_limit", len(queries)), 100)
        queries = queries[:batch_limit]
        base_request = {key: value for key, value in dict(payload).items() if key not in {"queries", "batch_limit"}}
        results: list[dict[str, Any]] = []
        created_total = 0
        existing_total = 0
        source_total = 0
        for query in queries:
            request = {**base_request, "query": query}
            result = self.create_research_tasks_from_hotspot(request, actor=actor)
            created_total += int(result.get("created_count", 0))
            existing_total += int(result.get("existing_count", 0))
            source_total += int(result.get("source_research_task_count", 0))
            results.append(
                {
                    "query": result.get("query", query),
                    "created_count": result.get("created_count", 0),
                    "existing_count": result.get("existing_count", 0),
                    "source_research_task_count": result.get("source_research_task_count", 0),
                    "created_task_ids": [task.get("task_id", "") for task in result.get("created_tasks", [])],
                    "existing_task_ids": [task.get("task_id", "") for task in result.get("existing_tasks", [])],
                }
            )
        self._audit(actor, "create_research_tasks_from_hotspot_batch", "research_task_batch", f"hotspot_batch_{safe_source_part('|'.join(queries))}")
        return {
            "batch_id": f"hotspot_batch_{safe_source_part('|'.join(queries))}",
            "query_count": len(queries),
            "created_count": created_total,
            "existing_count": existing_total,
            "source_research_task_count": source_total,
            "results": results,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "batch_research_task_queue_for_public_analysis_and_simulated_feedback_only",
        }

    CHOKEPOINT_RESEARCH_STEPS = [
        {"step_id": "sourceLedger", "label": "来源台账", "template_id": "sourceLedger", "gate": True},
        {"step_id": "factAudit", "label": "事实审计", "template_id": "factAudit", "gate": True},
        {"step_id": "scopeNarrowing", "label": "问题窄化", "template_id": "scopeNarrowing", "gate": False},
        {"step_id": "mappingTable", "label": "价值链映射", "template_id": "mappingTable", "gate": False},
        {"step_id": "analysisCore", "label": "Chokepoint 排名", "template_id": "analysisCore", "gate": False},
        {"step_id": "thesisFull", "label": "Thesis 草稿", "template_id": "thesisFull", "gate": False},
        {"step_id": "verification", "label": "验证与证伪", "template_id": "verification", "gate": True},
    ]

    CHOKEPOINT_STEP_PROMPTS = {
        "sourceLedger": "建立来源台账。只输出可核验来源、事实、URL、发布日期、来源类型、confirmed/inferred/speculative/unknown、置信度和下一步验证。无 URL 的事实不得标为 confirmed。",
        "factAudit": "审计当前研究草稿和历史步骤，剔除幻觉、过期事实、无 URL 事实、日期不一致和把推断写成 confirmed 的问题。",
        "scopeNarrowing": "把宽泛主题拆成 2-4 个可执行 chokepoint 子问题。每个子题只能包含一个主瓶颈，并给出必查 P0 来源和证伪条件。",
        "mappingTable": "用表格构建多层价值链/供应链地图，区分终端需求、付费方、产品/服务、关键环节、资源/设备/渠道/监管和上游输入。",
        "analysisCore": "基于已通过门禁的事实识别 3-5 个 chokepoint，比较集中度、切换成本、供给弹性、客户依赖、估值/利润池错配和催化剂。",
        "thesisFull": "生成研究 thesis 草稿。必须包含来源台账摘要、价值链地图、核心论点、催化剂、主要风险、证伪条件和下一步验证任务。",
        "verification": "作为魔鬼代言人验证 thesis，列出致命漏洞、反方证据、竞争威胁、替代路径、监管风险和 P0/P1/P2 验证任务。",
    }

    def create_chokepoint_research_run(self, payload: Mapping[str, Any], *, actor: str = "system") -> ChokepointResearchRun:
        topic = str(payload.get("topic") or payload.get("target") or payload.get("theme") or "").strip()
        if not topic:
            raise ValidationError("chokepoint research run requires topic")
        run_id = str(payload.get("run_id") or new_id("cprun")).strip()
        if run_id in self.store.chokepoint_research_runs:
            raise ConflictError(f"chokepoint research run {run_id} already exists")
        mode = str(payload.get("mode", "strict")).strip() or "strict"
        steps = [self._new_chokepoint_step(item) for item in self.CHOKEPOINT_RESEARCH_STEPS]
        run = ChokepointResearchRun(
            run_id=run_id,
            topic=topic,
            ticker=str(payload.get("ticker", "")).strip(),
            theme=str(payload.get("theme", topic)).strip(),
            chokepoint_node=str(payload.get("chokepoint_node", payload.get("node", ""))).strip(),
            playbook=str(payload.get("playbook", "generic")).strip() or "generic",
            mode=mode,
            status="draft",
            current_step=steps[0]["step_id"],
            steps=steps,
            validation_context=self._chokepoint_validation_context(payload),
            review_snapshot={
                "boundary": "research_only_not_investment_advice",
                "fact_layers": ["confirmed", "inferred", "speculative", "unknown"],
                "methodology": "Serenity-style bottom-up chokepoint research",
            },
        )
        self.store.chokepoint_research_runs[run.run_id] = run
        self._audit(actor, "create_chokepoint_research_run", "chokepoint_research_run", run.run_id, source="chokepoint_workbench", approval_state=run.status)
        return run

    def chokepoint_research_runs_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        status = str(filters.get("status", "")).strip()
        topic = str(filters.get("topic", filters.get("q", ""))).strip().lower()
        ticker = str(filters.get("ticker", "")).strip().lower()
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        rows = list(self.store.chokepoint_research_runs.values())
        if status:
            rows = [item for item in rows if item.status == status]
        if topic:
            rows = [item for item in rows if topic in item.topic.lower() or topic in item.theme.lower() or topic in item.chokepoint_node.lower()]
        if ticker:
            rows = [item for item in rows if ticker == item.ticker.lower()]
        rows.sort(key=lambda item: item.updated_at, reverse=True)
        return {"count": len(rows), "runs": [to_plain(item) for item in rows[:limit]]}

    def get_chokepoint_research_run(self, run_id: str) -> ChokepointResearchRun:
        run = self.store.chokepoint_research_runs.get(run_id)
        if run is None:
            raise NotFoundError(f"chokepoint research run {run_id} not found")
        return run

    def run_chokepoint_research_step(self, run_id: str, step_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> ChokepointResearchRun:
        payload = payload or {}
        run = self.get_chokepoint_research_run(run_id)
        step_index = self._chokepoint_step_index(run, step_id)
        step = dict(run.steps[step_index])
        started_at = utcnow()
        input_prompt = str(payload.get("input_prompt") or self._chokepoint_step_prompt(run, step)).strip()
        prior_outputs = self._chokepoint_prior_outputs(run, step_index)
        if "llmtpl_chokepoint_step_v1" not in self.store.llm_task_templates:
            self.seed_default_llm_task_templates(actor=actor)
        llm_run = self.run_llm_task(
            {
                "run_id": str(payload.get("llm_run_id") or f"llmrun_{run_id}_{step_id}_{int(time.time() * 1000)}"),
                "template_id": "llmtpl_chokepoint_step_v1",
                "role": str(payload.get("role", "分析师")),
                "variables": {
                    "step_label": step["label"],
                    "topic": run.topic,
                    "research_context": json.dumps(self._chokepoint_research_context(run), ensure_ascii=False, default=str),
                    "validation_context": json.dumps(run.validation_context, ensure_ascii=False, default=str),
                    "prior_outputs": prior_outputs,
                    "step_prompt": input_prompt,
                },
                "temperature": float(payload.get("temperature", 0.2)),
                "max_tokens": int(payload.get("max_tokens", 900)),
                "timeout_seconds": int(payload.get("timeout_seconds", payload.get("timeout", 45)) or 45),
                "human_review_required": True,
            },
            actor=actor,
        )
        output_text = self._llm_output_text(llm_run.output).strip()
        analysis = self._analyze_chokepoint_step_output(step, output_text, llm_run=llm_run)
        updated_step = {
            **step,
            "status": analysis["status"],
            "input_prompt": input_prompt,
            "llm_run_id": llm_run.run_id,
            "output_text": output_text,
            "summary": analysis["summary"],
            "evidence_quality": analysis["evidence_quality"],
            "issues": analysis["issues"],
            "started_at": started_at,
            "completed_at": utcnow(),
            "tuning_notes": str(payload.get("tuning_notes", step.get("tuning_notes", ""))),
        }
        steps = list(run.steps)
        steps[step_index] = updated_step
        issues = self._merge_chokepoint_issues(run.issues, analysis["issues"], step["label"])
        has_block = any(item.get("severity") == "block" for item in analysis["issues"])
        next_step = self._next_chokepoint_step_id(steps, step_index)
        status = "review" if has_block else ("completed" if self._chokepoint_completed(steps) else "paused")
        if llm_run.status == "failed":
            status = "failed"
        updated = self._replace_chokepoint_run(
            run,
            steps=steps,
            issues=issues,
            current_step=step["step_id"] if has_block else next_step,
            status=status,
            validation_context=self._chokepoint_validation_context(self._chokepoint_research_context(run)),
        )
        self._audit(actor, "run_chokepoint_research_step", "chokepoint_research_run", run_id, source=step_id, approval_state=status, model_version=llm_run.model, prompt_version=llm_run.prompt_version)
        return updated

    def run_chokepoint_research_pipeline(self, run_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> ChokepointResearchRun:
        payload = payload or {}
        run = self.get_chokepoint_research_run(run_id)
        limit = self._bounded_limit(payload.get("step_limit", len(run.steps)), len(run.steps))
        start_index = self._chokepoint_step_index(run, str(payload.get("start_step", run.current_step)))
        current = self._replace_chokepoint_run(run, status="running", current_step=run.steps[start_index]["step_id"])
        end_index = min(start_index + limit, len(current.steps))
        for index in range(start_index, end_index):
            step = current.steps[index]
            current = self.run_chokepoint_research_step(run_id, str(step["step_id"]), payload, actor=actor)
            refreshed_step = current.steps[index]
            if current.status == "failed" or str(refreshed_step.get("status")) == "failed":
                return self._replace_chokepoint_run(current, status="failed", current_step=str(step["step_id"]))
        final_status = "completed" if self._chokepoint_completed(current.steps) else "paused"
        current = self._replace_chokepoint_run(current, status=final_status)
        if final_status == "completed":
            return self.finalize_chokepoint_research_run(run_id, payload, actor=actor)
        return current

    def finalize_chokepoint_research_run(self, run_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> ChokepointResearchRun:
        payload = payload or {}
        run = self.get_chokepoint_research_run(run_id)
        validation_context = self._chokepoint_validation_context(self._chokepoint_research_context(run))
        verification_tasks = self.create_chokepoint_verification_tasks(
            run_id,
            {"limit": payload.get("verification_task_limit", payload.get("limit", 30))},
            actor=actor,
        )
        run = self.get_chokepoint_research_run(run_id)
        validation_context = self._chokepoint_validation_context(self._chokepoint_research_context(run))
        rule_conclusion = self._chokepoint_rule_conclusion(run, validation_context, verification_tasks)
        llm_run_id = ""
        fallback_used = ""
        llm_summary = ""
        if "llmtpl_chokepoint_conclusion_v1" not in self.store.llm_task_templates:
            self.seed_default_llm_task_templates(actor=actor)
        try:
            llm_run = self.run_llm_task(
                {
                    "run_id": str(payload.get("conclusion_llm_run_id") or f"llmrun_{run_id}_conclusion_{int(time.time() * 1000)}"),
                    "template_id": "llmtpl_chokepoint_conclusion_v1",
                    "role": str(payload.get("role", "分析师")),
                    "variables": {
                        "topic": run.topic,
                        "research_context": json.dumps(self._chokepoint_research_context(run), ensure_ascii=False, default=str),
                        "rule_conclusion": json.dumps(rule_conclusion, ensure_ascii=False, default=str),
                        "steps_summary": json.dumps(self._chokepoint_steps_summary(run), ensure_ascii=False, default=str),
                        "issues": json.dumps(run.issues, ensure_ascii=False, default=str),
                        "validation_context": json.dumps(validation_context, ensure_ascii=False, default=str),
                    },
                    "temperature": float(payload.get("temperature", 0.1)),
                    "max_tokens": int(payload.get("max_tokens", 900)),
                    "timeout_seconds": int(payload.get("timeout_seconds", payload.get("timeout", 45)) or 45),
                    "human_review_required": True,
                },
                actor=actor,
            )
            llm_run_id = llm_run.run_id
            fallback_used = llm_run.fallback_used
            llm_summary = self._sanitize_chokepoint_conclusion_text(self._llm_output_text(llm_run.output).strip())
        except Exception as exc:
            fallback_used = "rule_conclusion"
            llm_summary = self._sanitize_chokepoint_conclusion_text(f"AI 综合未完成：{exc}")
        conclusion = {
            **rule_conclusion,
            "llm_run_id": llm_run_id,
            "fallback_used": fallback_used,
            "llm_summary": llm_summary,
            "generated_at": utcnow(),
            "usage_boundary": "research_only_not_investment_advice",
        }
        review_snapshot = {
            **run.review_snapshot,
            "last_conclusion_at": conclusion["generated_at"],
            "conclusion_generation": "rule_summary_plus_optional_llm",
        }
        status = "completed" if self._chokepoint_completed(run.steps) and run.status != "failed" else run.status
        updated = self._replace_chokepoint_run(
            run,
            status=status,
            conclusion=conclusion,
            validation_context=validation_context,
            review_snapshot=review_snapshot,
        )
        self._audit(actor, "finalize_chokepoint_research_run", "chokepoint_research_run", run_id, approval_state=str(conclusion.get("status", "")))
        return updated

    def review_chokepoint_research_run(self, run_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> ChokepointResearchRun:
        run = self.get_chokepoint_research_run(run_id)
        step_id = str(payload.get("step_id", run.current_step)).strip()
        steps = list(run.steps)
        if step_id:
            index = self._chokepoint_step_index(run, step_id)
            step = dict(steps[index])
            notes = [str(item) for item in step.get("tuning_notes", [])] if isinstance(step.get("tuning_notes"), list) else ([str(step.get("tuning_notes"))] if step.get("tuning_notes") else [])
            if payload.get("tuning_notes"):
                notes.append(str(payload.get("tuning_notes")))
            if payload.get("status"):
                step["status"] = str(payload["status"])
            step["tuning_notes"] = notes
            step["reviewed_by"] = actor
            step["reviewed_at"] = utcnow()
            steps[index] = step
        closed = {str(item) for item in payload.get("close_issue_ids", [])}
        issues = []
        for item in run.issues:
            issue = dict(item)
            if closed and str(issue.get("issue_id", "")) in closed:
                issue["status"] = "closed"
                issue["closed_by"] = actor
                issue["closed_at"] = utcnow()
            issues.append(issue)
        review_snapshot = {**run.review_snapshot, **dict(payload.get("review_snapshot", {})), "last_reviewed_by": actor, "last_reviewed_at": utcnow()}
        updated_status = str(payload.get("run_status", run.status))
        updated = self._replace_chokepoint_run(run, steps=steps, issues=issues, review_snapshot=review_snapshot, status=updated_status)
        self._audit(actor, "review_chokepoint_research_run", "chokepoint_research_run", run_id, approval_state=updated.status)
        return updated

    def create_chokepoint_verification_tasks(self, run_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        run = self.get_chokepoint_research_run(run_id)
        candidates = self._chokepoint_verification_candidates(run)
        max_tasks = self._bounded_limit(payload.get("limit", 20), 100)
        created: list[dict[str, Any]] = []
        existing: list[dict[str, Any]] = []
        for candidate in candidates[:max_tasks]:
            task_id = str(candidate["task_id"])
            if task_id in self.store.research_tasks:
                existing.append(to_plain(self.store.research_tasks[task_id]))
                continue
            task = self._build_research_task(task_id, str(candidate["task_type"]), candidate)
            self.store.research_tasks[task.task_id] = task
            created.append(to_plain(task))
            self._audit(actor, "create_chokepoint_verification_task", "research_task", task.task_id, source=run_id)
        return {
            "run_id": run_id,
            "created_count": len(created),
            "existing_count": len(existing),
            "created_tasks": created,
            "existing_tasks": existing,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "chokepoint_verification_tasks_are_research_only_not_trade_signal",
        }

    def _new_chokepoint_step(self, item: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "step_id": str(item["step_id"]),
            "label": str(item["label"]),
            "template_id": str(item["template_id"]),
            "gate": bool(item.get("gate", False)),
            "status": "pending",
            "input_prompt": "",
            "llm_run_id": "",
            "output_text": "",
            "summary": "等待运行",
            "evidence_quality": {},
            "issues": [],
            "started_at": None,
            "completed_at": None,
            "tuning_notes": [],
        }

    def _replace_chokepoint_run(self, run: ChokepointResearchRun, **updates: Any) -> ChokepointResearchRun:
        data = to_plain(run)
        data.update(updates)
        data["automation_allowed"] = False
        data["live_execution_allowed"] = False
        data["updated_at"] = utcnow()
        updated = ChokepointResearchRun(**data)
        self.store.chokepoint_research_runs[updated.run_id] = updated
        return updated

    def _chokepoint_step_index(self, run: ChokepointResearchRun, step_id: str) -> int:
        for index, step in enumerate(run.steps):
            if step.get("step_id") == step_id:
                return index
        raise NotFoundError(f"chokepoint research step {step_id} not found")

    def _next_chokepoint_step_id(self, steps: list[dict[str, Any]], index: int) -> str:
        if index + 1 < len(steps):
            return str(steps[index + 1]["step_id"])
        return str(steps[index]["step_id"])

    def _chokepoint_completed(self, steps: list[dict[str, Any]]) -> bool:
        return all(str(step.get("status")) in {"done", "review"} for step in steps)

    def _chokepoint_research_context(self, run: ChokepointResearchRun | Mapping[str, Any]) -> dict[str, Any]:
        if isinstance(run, ChokepointResearchRun):
            return {
                "topic": run.topic,
                "ticker": run.ticker,
                "theme": run.theme,
                "chokepoint_node": run.chokepoint_node,
                "playbook": run.playbook,
                "mode": run.mode,
            }
        return {
            "topic": str(run.get("topic", run.get("theme", ""))),
            "ticker": str(run.get("ticker", "")),
            "theme": str(run.get("theme", "")),
            "chokepoint_node": str(run.get("chokepoint_node", run.get("node", ""))),
            "playbook": str(run.get("playbook", "generic")),
            "mode": str(run.get("mode", "strict")),
        }

    def _chokepoint_validation_context(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        context = self._chokepoint_research_context(payload)
        ticker = str(context.get("ticker", "")).strip().lower()
        topic_terms = [term.lower() for term in re.findall(r"[\w\u4e00-\u9fff]+", " ".join(str(context.get(key, "")) for key in ["topic", "theme", "chokepoint_node"])) if len(term) >= 2]
        securities = [item for item in self.store.securities.values() if ticker and (item.ticker.lower() == ticker or item.security_id.lower() == ticker)]
        security_ids = {item.security_id for item in securities}
        issuer_ids = {item.issuer_id for item in securities if item.issuer_id}
        market_rows = [item for item in self.store.market_data.values() if item.security_id in security_ids]
        market_rows.sort(key=lambda item: str(item.as_of_date), reverse=True)
        document_ids = {
            document.document_id
            for document in self.store.documents.values()
            if (security_ids and document.security_id in security_ids) or (issuer_ids and document.issuer_id in issuer_ids)
        }
        evidence_rows: list[Evidence] = []
        max_scan = 600 if document_ids else 120
        for evidence in self.store.evidence.values():
            if document_ids and evidence.document_id in document_ids:
                evidence_rows.append(evidence)
            elif not document_ids and topic_terms and self._chokepoint_light_evidence_match(evidence, topic_terms[:6]):
                evidence_rows.append(evidence)
            if len(evidence_rows) >= 30:
                break
            max_scan -= 1
            if max_scan <= 0:
                break
        facts = [self._chokepoint_evidence_row(item) for item in evidence_rows if item.section != "research_report_citation"]
        opinions = [self._chokepoint_evidence_row(item) for item in evidence_rows if item.section == "research_report_citation"]
        tasks = []
        for task in self.store.research_tasks.values():
            if task.source not in {"chokepoint_research", "hotspot_expansion"}:
                continue
            if not topic_terms or any(term in (task.reason + json.dumps(task.metadata, ensure_ascii=False)).lower() for term in topic_terms[:6]):
                tasks.append(to_plain(task))
            if len(tasks) >= 20:
                break
        return {
            "market_data": {
                "role": "market_pricing_validation_only",
                "count": len(market_rows),
                "latest": [to_plain(item) for item in market_rows[:10]],
            },
            "facts": {
                "role": "confirmed_candidate_only_if_public_filing_or_regulatory_source",
                "count": len(facts),
                "items": facts[:12],
            },
            "opinions": {
                "role": "research_reports_and_secondary_views_not_core_facts",
                "count": len(opinions),
                "items": opinions[:12],
            },
            "knowledge_graph": {
                "role": "traceability_context",
                "security_ids": sorted(security_ids),
                "issuer_ids": sorted(issuer_ids),
                "document_ids": sorted(document_ids)[:20],
            },
            "needs_verification": {
                "role": "open_research_tasks",
                "count": len(tasks),
                "items": tasks,
            },
        }

    def _chokepoint_light_evidence_match(self, evidence: Evidence, topic_terms: list[str]) -> bool:
        haystack = " ".join(
            [
                evidence.section,
                evidence.document_id,
                evidence.security_id,
                evidence.issuer_id,
                evidence.chain_id,
                " ".join(evidence.evidence_topics[:8]),
                " ".join(evidence.risk_tags[:8]),
                " ".join(evidence.financial_metric_tags[:8]),
            ]
        ).lower()
        return any(term in haystack for term in topic_terms)

    def _chokepoint_evidence_row(self, evidence: Evidence) -> dict[str, Any]:
        document = self.store.documents.get(evidence.document_id)
        return {
            "evidence_id": evidence.evidence_id,
            "document_id": evidence.document_id,
            "section": evidence.section,
            "source_uri": document.source_uri if document else "",
            "page_no": evidence.page_no,
            "snippet": (evidence.canonical_text or evidence.span_text)[:240],
            "confidence": evidence.confidence,
        }

    def _chokepoint_step_prompt(self, run: ChokepointResearchRun, step: Mapping[str, Any]) -> str:
        mode_notes = {
            "strict": "严格证据模式：宁可输出 unknown，也不要把未核验内容写成结论；门禁不过时停止并提出调优建议。",
            "balanced": "平衡推进模式：可以继续形成结构化草稿，但任何无 URL 数字和时间线必须保留为待验证。",
            "exploratory": "探索发散模式：允许提出更多候选，但未核验内容必须标为 speculative/unknown。",
        }
        base = self.CHOKEPOINT_STEP_PROMPTS.get(str(step.get("step_id")), "")
        return f"{mode_notes.get(run.mode, mode_notes['strict'])}\n{base}"

    def _chokepoint_prior_outputs(self, run: ChokepointResearchRun, step_index: int) -> str:
        blocks = []
        for step in run.steps[:step_index]:
            output = str(step.get("output_text", "")).strip()
            if output:
                blocks.append(f"## {step.get('label')}\n{output[:2500]}")
        return "\n\n".join(blocks) if blocks else "无"

    def _chokepoint_steps_summary(self, run: ChokepointResearchRun) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for step in run.steps:
            quality = dict(step.get("evidence_quality") or {})
            rows.append(
                {
                    "step_id": step.get("step_id", ""),
                    "label": step.get("label", ""),
                    "status": step.get("status", "pending"),
                    "summary": step.get("summary", ""),
                    "llm_run_id": step.get("llm_run_id", ""),
                    "url_count": quality.get("url_count", 0),
                    "confirmed_count": quality.get("confirmed_count", 0),
                    "inferred_count": quality.get("inferred_count", 0),
                    "speculative_count": quality.get("speculative_count", 0),
                    "unknown_count": quality.get("unknown_count", 0),
                    "fallback_used": quality.get("fallback_used", ""),
                    "issue_count": len(step.get("issues") or []),
                }
            )
        return rows

    def _chokepoint_rule_conclusion(
        self,
        run: ChokepointResearchRun,
        validation_context: Mapping[str, Any],
        verification_tasks: Mapping[str, Any],
    ) -> dict[str, Any]:
        summaries = self._chokepoint_steps_summary(run)
        completed_count = sum(1 for item in summaries if str(item.get("status")) in {"done", "review"})
        review_count = sum(1 for item in summaries if str(item.get("status")) == "review")
        failed_count = sum(1 for item in summaries if str(item.get("status")) == "failed")
        url_count = sum(int(item.get("url_count") or 0) for item in summaries)
        confirmed_count = sum(int(item.get("confirmed_count") or 0) for item in summaries)
        inferred_count = sum(int(item.get("inferred_count") or 0) for item in summaries)
        speculative_count = sum(int(item.get("speculative_count") or 0) for item in summaries)
        unknown_count = sum(int(item.get("unknown_count") or 0) for item in summaries)
        fallback_count = sum(1 for item in summaries if item.get("fallback_used"))
        open_issues = [dict(item) for item in run.issues if item.get("status", "open") == "open"]
        block_count = sum(1 for item in open_issues if item.get("severity") == "block")
        market_count = int((validation_context.get("market_data") or {}).get("count") or 0)
        facts_count = int((validation_context.get("facts") or {}).get("count") or 0)
        opinion_count = int((validation_context.get("opinions") or {}).get("count") or 0)
        task_count = int((validation_context.get("needs_verification") or {}).get("count") or 0)
        status = "failed" if failed_count or run.status == "failed" else "ready_for_review"
        if status != "failed" and (block_count or review_count or fallback_count or unknown_count or url_count == 0 or confirmed_count == 0 or facts_count == 0):
            status = "needs_evidence"
        score = 5.0
        score += min(2.0, confirmed_count / 4)
        score += min(1.0, facts_count / 3)
        score += min(1.0, completed_count / max(1, len(run.steps)))
        score -= min(2.0, block_count * 0.7)
        score -= min(1.5, fallback_count * 0.5)
        score -= min(1.0, unknown_count * 0.12)
        score -= min(0.8, opinion_count * 0.05)
        score = round(max(1.0, min(10.0, score)), 1)
        confidence = "low" if status in {"failed", "needs_evidence"} or score < 4.5 else ("medium" if score < 7.5 else "high")
        if status == "failed":
            one_line = f"{run.topic} 的瓶颈研究流水线未完成，当前只能作为失败 run 的排障记录。"
        elif status == "needs_evidence":
            one_line = f"{run.topic} 已形成瓶颈研究草稿，但证据缺口仍高，需要先补来源和事实验证。"
        else:
            one_line = f"{run.topic} 已形成可人工复核的瓶颈研究结论，可进入验证任务和模拟组合前审查。"
        verification_compact = {
            "created_count": int(verification_tasks.get("created_count", 0) or 0),
            "existing_count": int(verification_tasks.get("existing_count", 0) or 0),
            "created_tasks": [
                {"task_id": item.get("task_id", ""), "reason": self._sanitize_chokepoint_conclusion_text(str(item.get("reason", ""))[:180]), "priority": item.get("priority")}
                for item in verification_tasks.get("created_tasks", [])[:8]
            ],
            "existing_tasks": [
                {"task_id": item.get("task_id", ""), "reason": self._sanitize_chokepoint_conclusion_text(str(item.get("reason", ""))[:180]), "priority": item.get("priority")}
                for item in verification_tasks.get("existing_tasks", [])[:8]
            ],
            "usage_boundary": verification_tasks.get("usage_boundary", "research_only_not_trade_signal"),
        }
        next_actions = [
            "人工复核来源台账，补齐 P0 官方/监管/公司原始链接。",
            "把 unknown、needs_verification 和反方问题逐条关闭或降级。",
            "用公告/财报/监管 evidence 校验核心事实，研报只保留为 opinions。",
            "复核 K线/行情只作为市场定价与催化剂反应验证，不作为事实来源。",
        ]
        if fallback_count:
            next_actions.insert(0, "LLM 曾使用 fallback，需重跑相关步骤或人工确认后再进入 thesis。")
        if facts_count == 0:
            next_actions.insert(0, "当前没有公告/财报/监管 fact evidence，必须先补证据层。")
        return {
            "status": status,
            "one_line_conclusion": one_line,
            "thesis_strength_score": score,
            "confidence": confidence,
            "evidence_quality_summary": {
                "completed_steps": completed_count,
                "total_steps": len(run.steps),
                "review_steps": review_count,
                "failed_steps": failed_count,
                "url_count": url_count,
                "confirmed_count": confirmed_count,
                "inferred_count": inferred_count,
                "speculative_count": speculative_count,
                "unknown_count": unknown_count,
                "fallback_step_count": fallback_count,
                "open_issue_count": len(open_issues),
                "block_issue_count": block_count,
                "facts_count": facts_count,
                "opinions_count": opinion_count,
                "market_data_count": market_count,
                "verification_task_count": task_count,
            },
            "confirmed_summary": self._chokepoint_layer_summary(run, "confirmed", confirmed_count),
            "inferred_summary": self._chokepoint_layer_summary(run, "inferred", inferred_count),
            "speculative_summary": self._chokepoint_layer_summary(run, "speculative", speculative_count),
            "unknowns": self._chokepoint_extract_lines(run, r"unknown|未知|待验证|无法确认|needs_verification|P0", limit=8)
            or [item.get("message", "") for item in open_issues[:5]],
            "key_chokepoints": self._chokepoint_extract_lines(run, r"chokepoint|瓶颈|咽喉|卡点|Strait", limit=8)
            or ([run.chokepoint_node] if run.chokepoint_node else []),
            "catalysts": self._chokepoint_extract_lines(run, r"催化|里程碑|合同|订单|审批|许可|qualification|ramp|M&A|政策", limit=8),
            "falsification_conditions": self._chokepoint_extract_lines(run, r"证伪|反方|风险|替代|失败|推迟|取消|falsification|bear case", limit=8),
            "validation_summary": {
                "market_data": {"count": market_count, "role": (validation_context.get("market_data") or {}).get("role", "")},
                "facts": {"count": facts_count, "role": (validation_context.get("facts") or {}).get("role", "")},
                "opinions": {"count": opinion_count, "role": (validation_context.get("opinions") or {}).get("role", "")},
                "knowledge_graph": validation_context.get("knowledge_graph", {}),
                "needs_verification": {"count": task_count},
            },
            "open_issues": [
                {
                    "issue_id": item.get("issue_id", ""),
                    "step": item.get("step", ""),
                    "severity": item.get("severity", ""),
                    "message": self._sanitize_chokepoint_conclusion_text(str(item.get("message", ""))),
                    "suggestion": self._sanitize_chokepoint_conclusion_text(str(item.get("suggestion", ""))),
                }
                for item in open_issues[:12]
            ],
            "next_actions": next_actions,
            "verification_tasks": verification_compact,
            "llm_run_id": "",
            "fallback_used": "",
            "usage_boundary": "research_only_not_investment_advice",
        }

    def _chokepoint_layer_summary(self, run: ChokepointResearchRun, layer: str, count: int) -> str:
        if count <= 0:
            return f"暂无 {layer} 标记进入流水线结论。"
        examples = self._chokepoint_extract_lines(run, rf"\b{re.escape(layer)}\b", limit=3)
        suffix = f" 示例：{'；'.join(examples)}" if examples else ""
        return f"步骤输出中出现 {count} 处 {layer} 标记，仍需按来源台账逐条回链复核。{suffix}"[:900]

    def _chokepoint_extract_lines(self, run: ChokepointResearchRun, pattern: str, *, limit: int = 6) -> list[str]:
        rows: list[str] = []
        seen: set[str] = set()
        compiled = re.compile(pattern, flags=re.I)
        for step in run.steps:
            for line in str(step.get("output_text", "")).splitlines():
                normalized = " ".join(line.strip().split())
                if len(normalized) < 12 or not compiled.search(normalized):
                    continue
                normalized = self._sanitize_chokepoint_conclusion_text(normalized[:260])
                key = normalized.lower()
                if key in seen:
                    continue
                seen.add(key)
                rows.append(normalized)
                if len(rows) >= limit:
                    return rows
        return rows

    def _sanitize_chokepoint_conclusion_text(self, text: str) -> str:
        sanitized = str(text or "")
        replacements = {
            "买入": "研究边界",
            "卖出": "研究边界",
            "目标价": "估值待验证",
            "仓位": "风险敞口待验证",
            "配置": "模拟组合输入待验证",
            "投资建议": "研究辅助",
        }
        for source, target in replacements.items():
            sanitized = sanitized.replace(source, target)
        return sanitized

    def _analyze_chokepoint_step_output(self, step: Mapping[str, Any], output: str, *, llm_run: LLMTaskRun) -> dict[str, Any]:
        text = output or ""
        lower = text.lower()
        issues: list[dict[str, Any]] = []
        has_url = bool(re.search(r"https?://", text))
        if step.get("step_id") == "sourceLedger" and not has_url:
            issues.append(self._chokepoint_issue(step, "block", "来源台账没有可点击 URL。", "缩小范围，先补 3-5 个官方/公司/监管来源后重跑。"))
        if re.search(r"投资建议|买入|卖出|目标价|仓位|配置", text):
            issues.append(self._chokepoint_issue(step, "warn", "输出含投资建议或仓位表达。", "提交事实审计或人工复核，删除或降级为研究边界说明。"))
        if re.search(r"deep thinking|思维链|内部推理", text, flags=re.I):
            issues.append(self._chokepoint_issue(step, "block", "输出包含思维链或内部推理。", "重跑当前步骤，只允许输出表格和可审计结论。"))
        if re.search(r"无法实时核验|unknown|未知|待验证|无法确认|needs_verification", text, flags=re.I):
            issues.append(self._chokepoint_issue(step, "warn", "存在 unknown 或待验证事实。", "进入事实审计，或生成 ResearchTask 补证。"))
        if llm_run.status != "succeeded" or llm_run.fallback_used:
            issues.append(self._chokepoint_issue(step, "block", "LLM 使用 fallback 或运行未成功。", "需要人工复核，不得把 fallback 文本当作 confirmed 研究成果。"))
        confirmed_count = len(re.findall(r"\bconfirmed\b", lower))
        inferred_count = len(re.findall(r"\binferred\b", lower))
        speculative_count = len(re.findall(r"\bspeculative\b", lower))
        unknown_count = len(re.findall(r"\bunknown\b|未知|待验证|无法确认", lower))
        if inferred_count + speculative_count > confirmed_count + 3:
            issues.append(self._chokepoint_issue(step, "warn", "推断/猜测显著多于已确认事实。", "补来源台账后再推进 thesis。"))
        lines = [line.strip() for line in text.splitlines() if len(line.strip()) > 20]
        summary = (lines[0] if lines else "已生成步骤产物")[:180]
        quality = {
            "has_url": has_url,
            "url_count": len(re.findall(r"https?://", text)),
            "confirmed_count": confirmed_count,
            "inferred_count": inferred_count,
            "speculative_count": speculative_count,
            "unknown_count": unknown_count,
            "research_opinion_mentions": len(re.findall(r"研报|research report|opinion", text, flags=re.I)),
            "contains_investment_advice": bool(re.search(r"投资建议|买入|卖出|目标价|仓位|配置", text)),
            "fallback_used": llm_run.fallback_used,
            "llm_status": llm_run.status,
        }
        status = "review" if any(item["severity"] == "block" for item in issues) else "done"
        return {"status": status, "summary": summary, "issues": issues, "evidence_quality": quality}

    def _chokepoint_issue(self, step: Mapping[str, Any], severity: str, message: str, suggestion: str) -> dict[str, Any]:
        basis = f"{step.get('step_id')}|{severity}|{message}"
        return {
            "issue_id": f"cpissue_{safe_source_part(basis)}",
            "step_id": str(step.get("step_id", "")),
            "step": str(step.get("label", step.get("step_id", ""))),
            "severity": severity,
            "message": message,
            "suggestion": suggestion,
            "status": "open",
            "created_at": utcnow(),
        }

    def _merge_chokepoint_issues(self, existing: list[dict[str, Any]], new_issues: list[dict[str, Any]], step_label: str) -> list[dict[str, Any]]:
        retained = [dict(item) for item in existing if item.get("step") != step_label]
        by_id = {str(item.get("issue_id")): item for item in retained}
        for issue in new_issues:
            by_id[str(issue.get("issue_id"))] = dict(issue)
        return list(by_id.values())

    def _chokepoint_verification_candidates(self, run: ChokepointResearchRun) -> list[dict[str, Any]]:
        candidates: dict[str, dict[str, Any]] = {}
        for issue in run.issues:
            if issue.get("status") == "closed":
                continue
            reason = f"{issue.get('step')}: {issue.get('message')} {issue.get('suggestion')}"
            task_type = "chokepoint_verification"
            task_id = f"rtask_{safe_source_part(run.run_id + '|' + str(issue.get('issue_id', reason)))}"
            candidates[task_id] = {
                "task_id": task_id,
                "task_type": task_type,
                "source": "chokepoint_research",
                "reason": reason,
                "status": "open",
                "priority": 80 if issue.get("severity") == "block" else 60,
                "required_slots": ["source_url", "published_date", "source_type", "confidence", "fact_layer"],
                "metadata": {
                    "run_id": run.run_id,
                    "topic": run.topic,
                    "step_id": issue.get("step_id", ""),
                    "usage_boundary": "research_only_not_trade_signal",
                    "automation_allowed": False,
                    "live_execution_allowed": False,
                },
            }
        for step in run.steps:
            text = str(step.get("output_text", ""))
            for index, line in enumerate([line.strip() for line in text.splitlines() if re.search(r"unknown|未知|待验证|无法确认|needs_verification|P0", line, re.I)][:8]):
                task_id = f"rtask_{safe_source_part(run.run_id + '|' + str(step.get('step_id')) + '|' + str(index) + '|' + line[:80])}"
                candidates.setdefault(
                    task_id,
                    {
                        "task_id": task_id,
                        "task_type": "chokepoint_verification",
                        "source": "chokepoint_research",
                        "reason": line[:500],
                        "status": "open",
                        "priority": 70,
                        "required_slots": ["official_source", "source_url", "published_date", "verification_result"],
                        "metadata": {
                            "run_id": run.run_id,
                            "topic": run.topic,
                            "step_id": step.get("step_id", ""),
                            "usage_boundary": "research_only_not_trade_signal",
                            "automation_allowed": False,
                            "live_execution_allowed": False,
                        },
                    },
                )
        if not candidates:
            task_id = f"rtask_{safe_source_part(run.run_id + '|manual_review')}"
            candidates[task_id] = {
                "task_id": task_id,
                "task_type": "chokepoint_verification",
                "source": "chokepoint_research",
                "reason": "人工复核瓶颈研究来源台账、事实分层和证伪条件。",
                "status": "open",
                "priority": 50,
                "required_slots": ["source_ledger_review", "falsification_review"],
                "metadata": {"run_id": run.run_id, "topic": run.topic, "usage_boundary": "research_only_not_trade_signal"},
            }
        return list(candidates.values())

    def _build_research_task(self, task_id: str, task_type: str, payload: Mapping[str, Any]) -> ResearchTask:
        if task_type == "company_position_backfill":
            position_id = str(payload.get("position_id", "")).strip()
            if position_id and position_id not in self.store.company_positions:
                raise NotFoundError(f"company position {position_id} not found")
        chain_id = str(payload.get("chain_id", "")).strip()
        if chain_id and chain_id not in self.store.industry_chains and not chain_id.startswith("chain_synthetic_"):
            raise NotFoundError(f"industry chain {chain_id} not found")
        issuer_id = str(payload.get("issuer_id", "")).strip()
        if issuer_id and issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {issuer_id} not found")
        evidence_ids = [str(item) for item in payload.get("evidence_ids", [])]
        missing_evidence = [item for item in evidence_ids if item not in self.store.evidence]
        if missing_evidence:
            raise NotFoundError(f"evidence records not found: {missing_evidence}")
        return ResearchTask(
            task_id=task_id,
            task_type=task_type,
            source=str(payload.get("source", "manual")),
            issuer_id=issuer_id,
            security_id=str(payload.get("security_id", "")).strip(),
            chain_id=chain_id,
            node_ids=[str(item) for item in payload.get("node_ids", [payload.get("node_id")]) if item],
            position_id=str(payload.get("position_id", "")).strip(),
            required_slots=[str(item) for item in payload.get("required_slots", [])],
            reason=str(payload.get("reason", "")),
            status=str(payload.get("status", "open")),
            priority=int(payload.get("priority", 50)),
            assignee=str(payload.get("assignee", "")),
            evidence_ids=evidence_ids,
            metadata=dict(payload.get("metadata", {})),
        )

    def _normalize_hotspot_research_task(self, raw_task: Mapping[str, Any], request: Mapping[str, Any], expansion: Mapping[str, Any]) -> dict[str, Any]:
        task_type = str(raw_task.get("task_type", raw_task.get("type", "hotspot_research_backfill"))).strip()
        chain_id = str(raw_task.get("chain_id", request.get("seed_chain_id", ""))).strip()
        node_ids = [str(item) for item in raw_task.get("node_ids", [raw_task.get("node_id")]) if item]
        position_id = str(raw_task.get("position_id", "")).strip()
        issuer_id = str(raw_task.get("issuer_id", "")).strip()
        basis = "|".join([task_type, chain_id, position_id, issuer_id, ",".join(node_ids), str(expansion.get("query", ""))])
        task_id = str(raw_task.get("task_id") or f"rtask_{safe_source_part(basis)}").strip()
        return {
            "task_id": task_id,
            "task_type": task_type,
            "source": "hotspot_expansion",
            "issuer_id": issuer_id,
            "chain_id": chain_id,
            "node_ids": node_ids,
            "position_id": position_id,
            "required_slots": [str(item) for item in raw_task.get("required_slots", [])],
            "reason": str(raw_task.get("reason", "")),
            "status": "open",
            "priority": int(raw_task.get("priority", 70 if task_type == "company_position_backfill" else 55)),
            "metadata": {
                "query": expansion.get("query", ""),
                "seed_theme_id": request.get("seed_theme_id", ""),
                "seed_chain_id": request.get("seed_chain_id", ""),
                "usage_boundary": "macro_industry_chain_research_only_not_trade_signal",
            },
        }

    def _matching_hotspot_lexicons(self, query: str) -> list[HotspotLexicon]:
        lowered = query.lower()
        return [item for item in self.store.hotspot_lexicons.values() if self._hotspot_lexicon_matches(item, lowered)]

    def _hotspot_lexicon_matches(self, lexicon: HotspotLexicon, query: str) -> bool:
        terms = [lexicon.name, *lexicon.terms]
        for key, values in lexicon.synonyms.items():
            terms.append(key)
            terms.extend(values)
        lowered_terms = [str(item).lower() for item in terms]
        return any(query in item or item in query for item in lowered_terms if item)

    def hotspot_expansion(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        query = str(payload.get("query", "")).strip()
        if not query:
            raise ValidationError("hotspot expansion requires query")
        max_depth = max(1, int(payload.get("max_depth", 3) or 3))
        seed_chain_id = str(payload.get("seed_chain_id", "")).strip()
        seed_theme_id = str(payload.get("seed_theme_id", "")).strip()
        include_restricted = self._truthy(payload.get("include_restricted", False))
        recall_limit = self._bounded_limit(payload.get("recall_limit", 20), 100)
        page_size = self._bounded_limit(payload.get("page_size", payload.get("limit", 50)), 200)
        page_token = str(payload.get("page_token", payload.get("offset", "0")) or "0").strip()
        try:
            offset = max(0, int(page_token))
        except ValueError as exc:
            raise ValidationError("hotspot expansion page_token must be a non-negative integer offset") from exc
        matched_lexicons = self._matching_hotspot_lexicons(query)
        default_slots = matched_lexicons[0].default_data_slots if matched_lexicons else ["revenue_exposure", "profit_exposure", "capacity", "customers", "suppliers", "valuation_metrics"]
        required_slots = [str(item) for item in payload.get("required_data_slots", default_slots)]

        theme = self.store.macro_themes.get(seed_theme_id) if seed_theme_id else None
        matching_chains = [self.store.industry_chains[seed_chain_id]] if seed_chain_id and seed_chain_id in self.store.industry_chains else []
        if not matching_chains:
            lowered = query.lower()
            matching_chains = [
                chain for chain in self.store.industry_chains.values()
                if lowered in chain.name.lower()
                or any(lowered in str(node.get("name", "")).lower() or lowered in " ".join(str(item).lower() for item in node.get("keywords", [])) for node in chain.nodes)
            ]
        if not matching_chains:
            nodes = matched_lexicons[0].related_chain_nodes if matched_lexicons and matched_lexicons[0].related_chain_nodes else self._default_chain_nodes_for_query(query)
            matching_chains = [IndustryChain(chain_id=f"chain_synthetic_{safe_source_part(query)}", name=f"{query} industry chain", nodes=[dict(item) for item in nodes], taxonomy_version="industry-chain-rule-template")]
        if theme is None:
            for chain in matching_chains:
                root_theme_id = str(chain.root_theme_id).strip()
                if root_theme_id and root_theme_id in self.store.macro_themes:
                    theme = self.store.macro_themes[root_theme_id]
                    break

        chain_nodes: list[dict[str, Any]] = []
        chain_edges: list[dict[str, Any]] = []
        company_positions: list[dict[str, Any]] = []
        data_coverage: list[dict[str, Any]] = []
        missing_evidence: list[dict[str, Any]] = []
        research_tasks: list[dict[str, Any]] = []
        for chain in matching_chains:
            allowed_nodes = [node for node in chain.nodes if int(node.get("level", 1) or 1) <= max_depth]
            allowed_node_ids = {str(node.get("node_id")) for node in allowed_nodes}
            chain_nodes.extend([{**node, "chain_id": chain.chain_id} for node in allowed_nodes])
            chain_edges.extend([{**edge, "chain_id": chain.chain_id} for edge in chain.edges if str(edge.get("source_node_id")) in allowed_node_ids and str(edge.get("target_node_id")) in allowed_node_ids])
            for position in self.store.company_positions.values():
                if position.chain_id != chain.chain_id or not (set(position.node_ids) & allowed_node_ids):
                    continue
                row = to_plain(position)
                company_positions.append(row)
                present_slots = [slot for slot in required_slots if row.get(slot)]
                missing_slots = [slot for slot in required_slots if not row.get(slot)]
                linked_evidence = [evidence_id for evidence_id in position.evidence_ids if evidence_id in self.store.evidence]
                coverage = {
                    "position_id": position.position_id,
                    "issuer_id": position.issuer_id,
                    "node_ids": position.node_ids,
                    "present_slots": present_slots,
                    "missing_slots": missing_slots,
                    "linked_evidence_ids": linked_evidence,
                    "coverage_ratio": round((len(present_slots) + (1 if linked_evidence else 0)) / max(1, len(required_slots) + 1), 4),
                }
                data_coverage.append(coverage)
                if missing_slots or not linked_evidence:
                    missing_evidence.append({"position_id": position.position_id, "issuer_id": position.issuer_id, "missing_slots": missing_slots, "missing_evidence": not linked_evidence})
                    research_tasks.append(
                        {
                            "task_id": f"research_{position.position_id}",
                            "type": "company_position_backfill",
                            "position_id": position.position_id,
                            "issuer_id": position.issuer_id,
                            "chain_id": chain.chain_id,
                            "node_ids": position.node_ids,
                            "required_slots": missing_slots,
                            "reason": "missing company positioning data or evidence link",
                        }
                    )
        node_ids_with_company = {node_id for row in company_positions for node_id in row.get("node_ids", [])}
        for node in chain_nodes:
            node_id = str(node.get("node_id", ""))
            if node_id and node_id not in node_ids_with_company:
                research_tasks.append(
                    {
                        "task_id": f"research_node_{node_id}",
                        "type": "chain_node_company_mapping",
                        "chain_id": node.get("chain_id", ""),
                        "node_id": node_id,
                        "required_slots": required_slots,
                        "reason": "no mapped company position for chain node",
                    }
                )
        retrieval_recall = self._hotspot_retrieval_recall(query, include_restricted=include_restricted, limit=recall_limit)
        evidence_layers = self._hotspot_evidence_layers(
            theme=theme,
            chain_nodes=chain_nodes,
            chain_edges=chain_edges,
            company_positions=company_positions,
            data_coverage=data_coverage,
            missing_evidence=missing_evidence,
            research_tasks=research_tasks,
            matched_lexicons=matched_lexicons,
            retrieval_recall=retrieval_recall,
        )
        ranked_candidates = self._hotspot_rank_candidates(
            query=query,
            company_positions=company_positions,
            data_coverage=data_coverage,
            retrieval_recall=retrieval_recall,
            matched_lexicons=matched_lexicons,
        )
        paged_nodes, nodes_page = self._page_rows(chain_nodes, offset=offset, page_size=page_size)
        paged_edges, edges_page = self._page_rows(chain_edges, offset=offset, page_size=page_size)
        paged_positions, positions_page = self._page_rows(company_positions, offset=offset, page_size=page_size)
        paged_coverage, coverage_page = self._page_rows(data_coverage, offset=offset, page_size=page_size)
        paged_missing_evidence, missing_page = self._page_rows(missing_evidence, offset=offset, page_size=page_size)
        paged_research_tasks, tasks_page = self._page_rows(research_tasks, offset=offset, page_size=page_size)
        paged_candidates, candidates_page = self._page_rows(ranked_candidates.get("candidates", []), offset=offset, page_size=page_size)
        paged_ranked_candidates = {
            **ranked_candidates,
            "candidates": paged_candidates,
        }
        has_more = any(page["has_more"] for page in [nodes_page, edges_page, positions_page, coverage_page, candidates_page, missing_page, tasks_page])
        next_page_token = str(offset + page_size) if has_more else None
        return {
            "query": query,
            "theme": to_plain(theme) if theme else {"name": query, "source": "ad_hoc_hotspot", "seed_theme_id": seed_theme_id},
            "matched_lexicons": [to_plain(item) for item in matched_lexicons],
            "chain_nodes": paged_nodes,
            "chain_edges": paged_edges,
            "company_positions": paged_positions,
            "data_coverage": paged_coverage,
            "retrieval_recall": retrieval_recall,
            "ranked_candidates": paged_ranked_candidates,
            "missing_evidence": paged_missing_evidence,
            "counter_theses": [{"type": "supply_chain_overreach", "question": "Does the hotspot materially affect this node's revenue/profit exposure?"}],
            "research_tasks": paged_research_tasks,
            "evidence_layers": evidence_layers,
            "pagination": {
                "page_token": str(offset),
                "page_size": page_size,
                "next_page_token": next_page_token,
                "has_more": has_more,
                "sections": {
                    "chain_nodes": nodes_page,
                    "chain_edges": edges_page,
                    "company_positions": positions_page,
                    "data_coverage": coverage_page,
                    "ranked_candidates": candidates_page,
                    "missing_evidence": missing_page,
                    "research_tasks": tasks_page,
                },
            },
            "automation_allowed": False,
            "usage_boundary": "macro_industry_chain_research_only_not_trade_signal",
        }

    def hotspot_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        expansion = self.hotspot_expansion(payload, actor=actor)
        chain_ids = self._hotspot_readiness_chain_ids(expansion, payload)
        coverage_filter: dict[str, Any] = {}
        if len(chain_ids) == 1:
            coverage_filter["chain_id"] = chain_ids[0]
        if payload.get("issuer_id"):
            coverage_filter["issuer_id"] = payload.get("issuer_id")
        if payload.get("security_id"):
            coverage_filter["security_id"] = payload.get("security_id")
        if payload.get("node_id"):
            coverage_filter["node_id"] = payload.get("node_id")
        required_slots = self._hotspot_expansion_required_slots(expansion, payload)
        if required_slots:
            coverage_filter["required_data_slots"] = required_slots
        coverage = self.company_positions_coverage_report(coverage_filter)
        research_queue = self._hotspot_research_queue_summary(expansion)
        layer_summary = self._hotspot_layer_summary(expansion)
        boundary_summary = self._hotspot_boundary_summary(expansion)
        graph_summary = self._hotspot_graph_summary(chain_ids, payload, actor=actor)
        rerank_summary = self._hotspot_rerank_eval_summary(payload)
        artifacts = self._hotspot_readiness_artifact_uris(payload)
        min_depth = int(payload.get("min_chain_depth", 3))
        min_positions = int(payload.get("min_company_positions", 1))
        min_slot_coverage = float(payload.get("min_slot_coverage", 1.0))
        min_evidence_coverage = float(payload.get("min_evidence_coverage", 1.0))
        min_recall_facts = int(payload.get("min_public_fact_count", 1))
        min_rerank_samples = int(payload.get("min_rerank_samples", 1))
        min_rerank_top1 = float(payload.get("min_rerank_top1_accuracy", 0.8))
        gates = [
            self._readiness_numeric_gate("matched_lexicon_count", float(len(expansion.get("matched_lexicons", []))), float(payload.get("min_matched_lexicons", 1)), ">=", "hotspot query maps to maintained lexicon terms/synonyms"),
            self._readiness_numeric_gate("chain_depth", float(graph_summary["max_chain_depth"]), float(min_depth), ">=", "hotspot expansion reaches required industry-chain depth"),
            self._readiness_numeric_gate("chain_node_count", float(graph_summary["chain_node_count"]), float(payload.get("min_chain_node_count", min_depth)), ">=", "industry chain nodes available for diffusion map"),
            self._readiness_numeric_gate("chain_edge_count", float(graph_summary["chain_edge_count"]), float(payload.get("min_chain_edge_count", 1)), ">=", "industry chain relationships available for path traversal"),
            self._readiness_numeric_gate("company_position_count", float(coverage["coverage"]["positions_total"]), float(min_positions), ">=", "mapped company positions for candidate universe"),
            self._readiness_numeric_gate("company_position_slot_coverage", float(coverage["coverage"]["slot_coverage"]), min_slot_coverage, ">=", "required company positioning data slots populated"),
            self._readiness_numeric_gate("company_position_evidence_coverage", float(coverage["coverage"]["evidence_coverage"]), min_evidence_coverage, ">=", "company positions link to evidence records"),
            self._readiness_numeric_gate("coverage_issue_count", float(coverage["coverage"]["positions_with_issues"]), 0.0, "==", "no unresolved company positioning coverage issues"),
            self._readiness_numeric_gate("public_fact_count", float(layer_summary["facts"]), float(min_recall_facts), ">=", "public facts/evidence recall supports hotspot map"),
            self._readiness_numeric_gate("evidence_layer_count", float(layer_summary["present_layer_count"]), 4.0, ">=", "facts, opinions, inferences, and needs_verification layers are explicit"),
            self._readiness_bool_gate("facts_opinions_inferences_separated", boundary_summary["separated_layers"], "facts/opinions/inferences/needs_verification are not collapsed into conclusions"),
            self._readiness_bool_gate("needs_verification_queue_present", research_queue["source_research_task_count"] > 0, "missing evidence or mapping gaps produce research tasks"),
            self._readiness_bool_gate("research_tasks_persisted_or_reviewed", research_queue["open_or_reviewed_count"] >= research_queue["source_research_task_count"], "hotspot research tasks are persisted or explicitly reviewed"),
            self._readiness_bool_gate("automation_boundary_disabled", expansion.get("automation_allowed") is False, "hotspot expansion is research only and cannot trade"),
            self._readiness_bool_gate("no_live_execution_boundary", not self._truthy(expansion.get("live_execution_allowed", False)), "hotspot readiness does not enable live execution"),
            self._readiness_numeric_gate("graph_edge_metadata_coverage", float(graph_summary["edge_metadata_coverage"]), float(payload.get("min_edge_metadata_coverage", 1.0)), ">=", "chain graph edges retain source/timestamp/version/confidence"),
            self._readiness_numeric_gate("llm_rerank_eval_samples", float(rerank_summary["valid_samples"]), float(min_rerank_samples), ">=", "LLM rerank/local fallback evaluated on gold query refs"),
            self._readiness_numeric_gate("llm_rerank_top1_accuracy", float(rerank_summary["top1_accuracy"]), min_rerank_top1, ">=", "LLM rerank/local fallback top1 quality threshold"),
            self._readiness_bool_gate("llm_rerank_eval_artifact_uri", bool(artifacts.get("llm_rerank_eval_uri")), "real large-sample LLM rerank quality evaluation artifact URI"),
            self._readiness_bool_gate("hotspot_gold_refs_uri", bool(artifacts.get("hotspot_gold_refs_uri")), "hotspot query/gold refs artifact URI"),
            self._readiness_bool_gate("company_position_review_uri", bool(artifacts.get("company_position_review_uri")), "company positioning review/acceptance artifact URI"),
            self._readiness_bool_gate("chain_taxonomy_review_uri", bool(artifacts.get("chain_taxonomy_review_uri")), "industry-chain taxonomy review artifact URI"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "ready_for_hotspot_research_production": ready,
            "ready_for_external_acceptance": ready,
            "missing_requirements": missing,
            "gates": gates,
            "query": expansion["query"],
            "expansion_summary": {
                "matched_lexicons": len(expansion.get("matched_lexicons", [])),
                "chain_nodes": len(expansion.get("chain_nodes", [])),
                "chain_edges": len(expansion.get("chain_edges", [])),
                "company_positions": len(expansion.get("company_positions", [])),
                "ranked_candidate_count": expansion.get("ranked_candidates", {}).get("candidate_count", 0),
                "usage_boundary": expansion.get("usage_boundary", ""),
            },
            "coverage_report": {
                "count": coverage["count"],
                "coverage": coverage["coverage"],
                "issue_count": len(coverage["issues"]),
                "research_task_count": len(coverage["research_tasks"]),
            },
            "layer_summary": layer_summary,
            "boundary_summary": boundary_summary,
            "research_queue": research_queue,
            "graph_summary": graph_summary,
            "rerank_evaluation": rerank_summary,
            "artifact_uris": artifacts,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "hotspot_readiness_report_validates_chain_depth_position_evidence_layer_boundaries_research_tasks_and_offline_rerank_artifacts_without_calling_models_or_trading",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "hotspot_readiness_report", "hotspot", expansion["query"], source="macro_industry_chain_governance", approval_state="ready" if ready else "missing_evidence")
        return report

    def _hotspot_readiness_chain_ids(self, expansion: Mapping[str, Any], payload: Mapping[str, Any]) -> list[str]:
        raw = payload.get("chain_ids", [])
        if isinstance(raw, str):
            chain_ids = self._unique_strings(part for part in re.split(r"[,;/\s]+", raw) if part.strip())
        elif isinstance(raw, list):
            chain_ids = self._unique_strings(raw)
        else:
            chain_ids = []
        seed_chain_id = str(payload.get("seed_chain_id", "")).strip()
        if seed_chain_id:
            chain_ids.append(seed_chain_id)
        for section in ["chain_nodes", "chain_edges", "company_positions", "data_coverage", "missing_evidence", "research_tasks"]:
            for row in expansion.get(section, []):
                if isinstance(row, Mapping):
                    chain_id = str(row.get("chain_id", "")).strip()
                    if chain_id:
                        chain_ids.append(chain_id)
        return self._unique_strings(chain_ids)

    def _hotspot_layer_summary(self, expansion: Mapping[str, Any]) -> dict[str, Any]:
        layers = expansion.get("evidence_layers", {})
        if not isinstance(layers, Mapping):
            layers = {}
        counts = {
            "facts": len(layers.get("facts", [])) if isinstance(layers.get("facts", []), list) else 0,
            "opinions": len(layers.get("opinions", [])) if isinstance(layers.get("opinions", []), list) else 0,
            "inferences": len(layers.get("inferences", [])) if isinstance(layers.get("inferences", []), list) else 0,
            "needs_verification": len(layers.get("needs_verification", [])) if isinstance(layers.get("needs_verification", []), list) else 0,
        }
        counts["present_layer_count"] = sum(1 for value in counts.values() if value > 0)
        recall = expansion.get("retrieval_recall", {})
        if isinstance(recall, Mapping):
            counts["public_recall_count"] = len(recall.get("public_facts", [])) if isinstance(recall.get("public_facts", []), list) else 0
            counts["research_opinion_recall_count"] = len(recall.get("research_opinions", [])) if isinstance(recall.get("research_opinions", []), list) else 0
            counts["inference_recall_count"] = len(recall.get("inferences", [])) if isinstance(recall.get("inferences", []), list) else 0
            counts["market_signal_recall_count"] = len(recall.get("market_signals", [])) if isinstance(recall.get("market_signals", []), list) else 0
        return counts

    def _hotspot_expansion_required_slots(self, expansion: Mapping[str, Any], payload: Mapping[str, Any]) -> list[str]:
        raw = payload.get("required_data_slots", [])
        if isinstance(raw, str):
            return self._unique_strings(part for part in re.split(r"[,;/\s]+", raw) if part.strip())
        if isinstance(raw, list) and raw:
            return self._unique_strings(raw)
        slots: list[str] = []
        for row in expansion.get("data_coverage", []):
            if not isinstance(row, Mapping):
                continue
            slots.extend(str(item) for item in row.get("present_slots", []) if str(item).strip())
            slots.extend(str(item) for item in row.get("missing_slots", []) if str(item).strip())
        return self._unique_strings(slots)

    def _hotspot_boundary_summary(self, expansion: Mapping[str, Any]) -> dict[str, Any]:
        layers = expansion.get("evidence_layers", {})
        if not isinstance(layers, Mapping):
            layers = {}
        facts = [item for item in layers.get("facts", []) if isinstance(item, Mapping)]
        opinions = [item for item in layers.get("opinions", []) if isinstance(item, Mapping)]
        inferences = [item for item in layers.get("inferences", []) if isinstance(item, Mapping)]
        needs_verification = [item for item in layers.get("needs_verification", []) if isinstance(item, Mapping)]
        inference_flags = [
            item
            for item in inferences
            if item.get("needs_verification") is True
            or item.get("automation_allowed") is False
            or "not_fact" in str(item.get("source_boundary", ""))
        ]
        fact_resources = {str(item.get("resource_id", "")) for item in facts if item.get("resource_id")}
        inference_resources = {str(item.get("resource_id", "")) for item in inferences if item.get("resource_id")}
        overlap = sorted(fact_resources & inference_resources)
        return {
            "facts_have_source_or_evidence": all(item.get("evidence_ids") or item.get("source_uri") or item.get("resource_type") in {"document", "evidence"} for item in facts),
            "opinions_have_boundary": all(item.get("source_refs") or item.get("source_boundary") or item.get("resource_type") == "macro_theme" for item in opinions),
            "inferences_need_verification": len(inference_flags) == len(inferences) if inferences else False,
            "needs_verification_count": len(needs_verification),
            "fact_inference_overlap": overlap,
            "separated_layers": bool(facts) and bool(opinions) and bool(inferences) and bool(needs_verification) and not overlap,
        }

    def _hotspot_research_queue_summary(self, expansion: Mapping[str, Any]) -> dict[str, Any]:
        source_tasks = [item for item in expansion.get("research_tasks", []) if isinstance(item, Mapping)]
        expected_ids = {str(item.get("task_id", "")).strip() for item in source_tasks if str(item.get("task_id", "")).strip()}
        persisted = [task for task in self.store.research_tasks.values() if task.task_id in expected_ids]
        persisted_ids = {task.task_id for task in persisted}
        reviewed = [task for task in persisted if task.status in {"open", "in_progress", "done", "dismissed"}]
        return {
            "source_research_task_count": len(source_tasks),
            "persisted_count": len(persisted),
            "open_or_reviewed_count": len(reviewed),
            "missing_task_ids": sorted(expected_ids - persisted_ids),
            "statuses": {status: sum(1 for task in persisted if task.status == status) for status in sorted({task.status for task in persisted})},
        }

    def _hotspot_graph_summary(self, chain_ids: list[str], payload: Mapping[str, Any], *, actor: str) -> dict[str, Any]:
        if not chain_ids:
            chain_id = str(payload.get("seed_chain_id", "")).strip()
            if chain_id:
                chain_ids = [chain_id]
        node_count = 0
        edge_count = 0
        relationship_count = 0
        max_depth = 0
        all_edges: list[dict[str, Any]] = []
        content_hashes: list[str] = []
        for chain_id in chain_ids:
            chain = self.store.industry_chains.get(chain_id)
            if chain is not None:
                node_count += len(chain.nodes)
                edge_count += len(chain.edges)
                for node in chain.nodes:
                    try:
                        max_depth = max(max_depth, int(node.get("level", 1) or 1))
                    except (TypeError, ValueError):
                        max_depth = max(max_depth, 1)
            graph = self.query_graph({"chain_id": chain_id})
            all_edges.extend([dict(edge) for edge in graph.get("edges", []) if isinstance(edge, Mapping)])
            export = self.graph_neo4j_export({"chain_id": chain_id}, actor=actor)
            relationship_count += int(export.get("relationship_count", 0))
            content_hashes.append(str(export.get("content_sha256", "")))
        required_fields = ["source", "timestamp", "version", "confidence"]
        missing_counts = {field: 0 for field in required_fields}
        issues = 0
        for edge in all_edges:
            missing = [field for field in required_fields if edge.get(field) in {"", None}]
            if missing:
                issues += 1
                for field in missing:
                    missing_counts[field] += 1
        total_edges = len(all_edges)
        complete_edges = total_edges - issues
        return {
            "chain_ids": chain_ids,
            "chain_node_count": node_count,
            "chain_edge_count": edge_count,
            "max_chain_depth": max_depth,
            "graph_edge_count": total_edges,
            "neo4j_relationship_count": relationship_count,
            "edge_metadata_coverage": round(complete_edges / max(1, total_edges), 4) if total_edges else 1.0,
            "edge_missing_counts": missing_counts,
            "content_sha256": self._payload_sha256({"chain_ids": chain_ids, "hashes": content_hashes}),
        }

    def _hotspot_rerank_eval_summary(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        supplied = payload.get("rerank_evaluation", payload.get("llm_rerank_evaluation", {}))
        if isinstance(supplied, Mapping) and supplied:
            return {
                "benchmark_id": str(supplied.get("benchmark_id", "external_llm_rerank_evaluation")),
                "valid_samples": int(supplied.get("valid_samples", supplied.get("samples", 0)) or 0),
                "top1_accuracy": float(supplied.get("top1_accuracy", 0.0) or 0.0),
                "coverage_at_k": float(supplied.get("coverage_at_k", 0.0) or 0.0),
                "mrr": float(supplied.get("mrr", 0.0) or 0.0),
                "fallback_rate": float(supplied.get("fallback_rate", 0.0) or 0.0),
                "parse_error_rate": float(supplied.get("parse_error_rate", 0.0) or 0.0),
                "source": "provided_summary",
            }
        samples = payload.get("rerank_samples", payload.get("llm_rerank_samples", []))
        if isinstance(samples, list) and samples:
            report = self.semantic_llm_rerank_benchmark(
                {
                    "benchmark_id": str(payload.get("rerank_benchmark_id", "hotspot_llm_rerank_readiness")),
                    "samples": samples,
                    "run_model": self._truthy(payload.get("run_rerank_model", False)),
                    "sample_limit": payload.get("rerank_sample_limit", len(samples)),
                    "candidate_limit": payload.get("candidate_limit", 20),
                    "limit": payload.get("rerank_limit", 10),
                },
                actor="hotspot_readiness",
            )
            return {
                "benchmark_id": report["benchmark_id"],
                "valid_samples": int(report["valid_samples"]),
                "top1_accuracy": float(report["top1_accuracy"]),
                "coverage_at_k": float(report["coverage_at_k"]),
                "mrr": float(report["mrr"]),
                "fallback_rate": float(report["fallback_rate"]),
                "parse_error_rate": float(report["parse_error_rate"]),
                "source": "local_offline_benchmark",
            }
        return {
            "benchmark_id": "",
            "valid_samples": 0,
            "top1_accuracy": 0.0,
            "coverage_at_k": 0.0,
            "mrr": 0.0,
            "fallback_rate": 0.0,
            "parse_error_rate": 0.0,
            "source": "missing",
        }

    def _hotspot_readiness_artifact_uris(self, payload: Mapping[str, Any]) -> dict[str, str]:
        aliases = {
            "llm_rerank_eval_uri": ["llm_rerank_eval_uri", "rerank_quality_uri", "rerank_evaluation_uri", "llm_rerank_report_uri"],
            "hotspot_gold_refs_uri": ["hotspot_gold_refs_uri", "gold_refs_uri", "query_gold_refs_uri", "hotspot_query_gold_uri"],
            "company_position_review_uri": ["company_position_review_uri", "position_review_uri", "company_position_acceptance_uri"],
            "chain_taxonomy_review_uri": ["chain_taxonomy_review_uri", "taxonomy_review_uri", "industry_chain_review_uri"],
        }
        return self._readiness_artifact_aliases(payload, aliases)

    def _hotspot_evidence_layers(
        self,
        *,
        theme: MacroTheme | None,
        chain_nodes: list[dict[str, Any]],
        chain_edges: list[dict[str, Any]],
        company_positions: list[dict[str, Any]],
        data_coverage: list[dict[str, Any]],
        missing_evidence: list[dict[str, Any]],
        research_tasks: list[dict[str, Any]],
        matched_lexicons: list[HotspotLexicon],
        retrieval_recall: dict[str, list[dict[str, Any]]],
    ) -> dict[str, list[dict[str, Any]]]:
        facts: list[dict[str, Any]] = []
        opinions: list[dict[str, Any]] = []
        inferences: list[dict[str, Any]] = []
        for position in company_positions:
            linked_evidence = [evidence_id for evidence_id in position.get("evidence_ids", []) if evidence_id in self.store.evidence]
            layer = facts if linked_evidence else inferences
            layer.append(
                {
                    "resource_type": "company_position",
                    "resource_id": position.get("position_id", ""),
                    "issuer_id": position.get("issuer_id", ""),
                    "statement": position.get("positioning_summary", "") or position.get("role", ""),
                    "evidence_ids": linked_evidence,
                    "confidence": 0.85 if linked_evidence else 0.45,
                }
            )
        for node in chain_nodes:
            source = "lexicon" if any(node.get("node_id") in {str(item.get("node_id", "")) for item in lexicon.related_chain_nodes} for lexicon in matched_lexicons) else "chain_registry"
            inferences.append(
                {
                    "resource_type": "chain_node",
                    "resource_id": node.get("node_id", ""),
                    "statement": f"{node.get('name', '')} is part of the hotspot diffusion map",
                    "source": source,
                    "confidence": 0.6 if source == "lexicon" else 0.7,
                }
            )
        if theme is not None:
            opinions.append(
                {
                    "resource_type": "macro_theme",
                    "resource_id": theme.theme_id,
                    "statement": theme.description or theme.name,
                    "source_refs": list(theme.source_refs),
                    "confidence": theme.confidence,
                }
            )
        for coverage in data_coverage:
            if coverage.get("missing_slots") or not coverage.get("linked_evidence_ids"):
                inferences.append(
                    {
                        "resource_type": "data_gap",
                        "resource_id": coverage.get("position_id", ""),
                        "statement": "Company positioning is incomplete and must be backfilled before use as a conclusion",
                        "missing_slots": coverage.get("missing_slots", []),
                        "confidence": 0.4,
                    }
                )
        for row in retrieval_recall.get("public_facts", []):
            facts.append(
                {
                    "resource_type": row.get("resource_type", ""),
                    "resource_id": row.get("resource_id", ""),
                    "statement": row.get("snippet", ""),
                    "source_uri": row.get("source_uri", ""),
                    "confidence": 0.75,
                }
            )
        for row in retrieval_recall.get("research_opinions", []):
            opinions.append(
                {
                    "resource_type": row.get("resource_type", ""),
                    "resource_id": row.get("resource_id", ""),
                    "statement": row.get("snippet", ""),
                    "source_boundary": row.get("source_boundary", ""),
                    "confidence": 0.55,
                }
            )
        for row in retrieval_recall.get("market_signals", []):
            if not isinstance(row, dict):
                continue
            inferences.append(
                {
                    "resource_type": row.get("resource_type", ""),
                    "resource_id": row.get("resource_id", ""),
                    "statement": row.get("snippet", ""),
                    "confidence": 0.5,
                }
            )
        # T-406A: thesis/signal inferences from retrieval_recall
        for row in retrieval_recall.get("inferences", []):
            if not isinstance(row, dict):
                continue
            inferences.append(
                {
                    "resource_type": row.get("resource_type", ""),
                    "resource_id": row.get("resource_id", ""),
                    "statement": row.get("snippet", ""),
                    "source_boundary": row.get("source_boundary", "inference_derived_from_evidence_not_fact"),
                    "needs_verification": True,
                    "automation_allowed": False,
                    "confidence": 0.4,
                }
            )
        return {
            "facts": facts,
            "opinions": opinions,
            "inferences": inferences,
            "needs_verification": [*missing_evidence, *research_tasks],
        }

    def _hotspot_rank_candidates(
        self,
        *,
        query: str,
        company_positions: list[dict[str, Any]],
        data_coverage: list[dict[str, Any]],
        retrieval_recall: dict[str, list[dict[str, Any]]],
        matched_lexicons: list[HotspotLexicon],
    ) -> dict[str, Any]:
        terms = {term.lower() for term in re.findall(r"[\w\u4e00-\u9fff]+", query)}
        for lexicon in matched_lexicons:
            terms.update(term.lower() for term in lexicon.terms)
            for key, values in lexicon.synonyms.items():
                terms.add(str(key).lower())
                terms.update(str(value).lower() for value in values)
        coverage_by_position = {row["position_id"]: row for row in data_coverage}
        recall_by_issuer: dict[str, int] = {}
        for bucket in retrieval_recall.values():
            if not isinstance(bucket, list):
                continue
            for row in bucket:
                issuer_id = str(row.get("issuer_id", ""))
                if issuer_id:
                    recall_by_issuer[issuer_id] = recall_by_issuer.get(issuer_id, 0) + 1

        candidates: list[dict[str, Any]] = []
        for position in company_positions:
            text = " ".join(
                [
                    str(position.get("role", "")),
                    str(position.get("positioning_summary", "")),
                    " ".join(str(item) for item in position.get("technology_tags", [])),
                ]
            ).lower()
            term_hits = sorted(term for term in terms if term and term in text)
            term_score = min(1.0, len(term_hits) / max(1, min(len(terms), 6)))
            coverage = coverage_by_position.get(position.get("position_id", ""), {})
            coverage_score = float(coverage.get("coverage_ratio", 0.0) or 0.0)
            evidence_score = 1.0 if coverage.get("linked_evidence_ids") else 0.0
            recall_score = min(1.0, recall_by_issuer.get(str(position.get("issuer_id", "")), 0) / 3)
            data_quality = str(position.get("data_quality", "needs_review"))
            quality_score = {"verified": 1.0, "complete": 0.9, "partial": 0.55, "needs_review": 0.25}.get(data_quality, 0.35)
            rank_score = round(term_score * 0.25 + coverage_score * 0.25 + evidence_score * 0.2 + recall_score * 0.2 + quality_score * 0.1, 6)
            candidates.append(
                {
                    "position_id": position.get("position_id", ""),
                    "issuer_id": position.get("issuer_id", ""),
                    "security_id": position.get("security_id", ""),
                    "chain_id": position.get("chain_id", ""),
                    "node_ids": position.get("node_ids", []),
                    "rank_score": rank_score,
                    "score_components": {
                        "term_score": round(term_score, 4),
                        "coverage_score": round(coverage_score, 4),
                        "evidence_score": round(evidence_score, 4),
                        "recall_score": round(recall_score, 4),
                        "quality_score": round(quality_score, 4),
                    },
                    "matched_terms": term_hits,
                    "explanation": "term match + data coverage + evidence link + public recall + data quality",
                }
            )
        candidates.sort(key=lambda item: item["rank_score"], reverse=True)
        return {
            "ranker": "local_hotspot_chain_coverage_evidence_score",
            "candidate_count": len(candidates),
            "candidates": candidates,
            "adapter_recommendation": {
                "llm_rerank_trigger": "use LLM rerank only after public recall, evidence layers, and company positioning coverage are available",
                "inputs": ["matched_lexicons", "retrieval_recall", "evidence_layers", "data_coverage"],
            },
        }

    def _hotspot_retrieval_recall(self, query: str, *, include_restricted: bool, limit: int) -> dict[str, list[dict[str, Any]]]:
        """T-406A: Enhanced hotspot retrieval recall.

        Supports four recall layers:
          - public_facts:      document / evidence facts from public filings
          - research_opinions: research report and research answer opinion snippets
          - inferences:        thesis / signal derived conclusions (not facts, must be labelled)
          - market_signals:    EOD/adjusted market data price signals

        Query expansion:
          - Tokenizes the query (unicode word + CJK chars)
          - Expands terms from matching HotspotLexicon.synonyms and keywords
          - Computes a term_coverage score for downstream ranking
        """
        base_terms = [term for term in re.findall(r"[\w\u4e00-\u9fff]+", query.lower()) if term]

        # Synonym / lexicon keyword expansion (T-406A requirement)
        expanded_terms: set[str] = set(base_terms)
        for lexicon in self.store.hotspot_lexicons.values():
            for synonym_list in lexicon.synonyms.values() if isinstance(lexicon.synonyms, dict) else []:
                for syn in (synonym_list if isinstance(synonym_list, list) else []):
                    if any(base_term in str(syn).lower() for base_term in base_terms):
                        expanded_terms.update(re.findall(r"[\w\u4e00-\u9fff]+", str(syn).lower()))
            for node in lexicon.related_chain_nodes if isinstance(lexicon.related_chain_nodes, list) else []:
                for kw in node.get("keywords", []) if isinstance(node, dict) else []:
                    if any(base_term in str(kw).lower() for base_term in base_terms):
                        expanded_terms.update(re.findall(r"[\w\u4e00-\u9fff]+", str(kw).lower()))

        all_terms = list(expanded_terms)

        def term_coverage(text: str) -> float:
            lowered = text.lower()
            hit = sum(1 for term in all_terms if term in lowered)
            return round(hit / max(1, len(all_terms)), 4)

        def matches(text: str) -> bool:
            lowered = text.lower()
            return any(term in lowered for term in all_terms)

        def snippet(text: str) -> str:
            compact = " ".join(text.split())
            return compact[:240]

        public_facts: list[dict[str, Any]] = []
        research_opinions: list[dict[str, Any]] = []
        inferences: list[dict[str, Any]] = []
        market_signals: list[dict[str, Any]] = []

        # Layer 1: documents (public filings → facts) and research reports (→ opinions)
        for document in self.store.documents.values():
            search_text = f"{document.title} {document.body} {document.document_type}"
            if not matches(search_text):
                continue
            source = self.store.sources.get(document.source_id)
            restricted = bool(source and source.risk_level == "red") or document.rights_tag.display_use == "restricted"
            if restricted and not include_restricted:
                continue
            row = {
                "resource_type": "document",
                "resource_id": document.document_id,
                "issuer_id": document.issuer_id,
                "security_id": document.security_id,
                "title": document.title,
                "snippet": snippet(document.body or document.title),
                "source_uri": document.source_uri,
                "source_boundary": source.usage_scope if source else "",
                "term_coverage": term_coverage(search_text),
                "expanded_terms_used": len(expanded_terms) > len(base_terms),
            }
            if document.document_type == "research" or (source and source.source_id == LOCAL_RESEARCH_REPORT_SOURCE_ID):
                research_opinions.append(row)
            else:
                public_facts.append(row)

        # Layer 2: evidence (public facts with locators)
        for evidence in self.store.evidence.values():
            evidence_text = evidence.canonical_text or evidence.span_text
            if not matches(evidence_text):
                continue
            document = self.store.documents.get(evidence.document_id)
            source = self.store.sources.get(document.source_id) if document else None
            row = {
                "resource_type": "evidence",
                "resource_id": evidence.evidence_id,
                "document_id": evidence.document_id,
                "issuer_id": document.issuer_id if document else "",
                "security_id": document.security_id if document else "",
                "snippet": snippet(evidence_text),
                "source_uri": document.source_uri if document else "",
                "term_coverage": term_coverage(evidence_text),
                "expanded_terms_used": len(expanded_terms) > len(base_terms),
            }
            is_research_reference = (
                evidence.section == "research_report_citation"
                or bool(document and document.document_type == "research")
                or bool(source and source.source_id == LOCAL_RESEARCH_REPORT_SOURCE_ID)
                or bool(source and source.usage_scope == "local_reference_citation_tracking_only")
            )
            if is_research_reference:
                research_opinions.append({**row, "source_boundary": "local_reference_research_report"})
            else:
                public_facts.append({**row, "source_boundary": "evidence_backed_public_or_governed_source"})

        # Layer 3: research reports (→ opinions)
        for report in self.store.research_reports.values():
            text = f"{report.title} {report.file_name} {report.broker} {report.industry}"
            if not matches(text):
                continue
            research_opinions.append(
                {
                    "resource_type": "research_report",
                    "resource_id": report.report_id,
                    "title": report.title,
                    "snippet": snippet(text),
                    "source_uri": report.file_path,
                    "source_boundary": "local_reference_research_report",
                    "term_coverage": term_coverage(text),
                    "expanded_terms_used": len(expanded_terms) > len(base_terms),
                }
            )

        # Layer 4 (NEW T-406A): research answers → opinions
        for answer in self.store.research_answers.values():
            text = f"{answer.question} {answer.english_source_text} {answer.chinese_summary}"
            if not matches(text):
                continue
            restricted = answer.source_publicness != "public"
            if restricted and not include_restricted:
                continue
            reviewed = answer.human_review_status == "approved"
            research_opinions.append(
                {
                    "resource_type": "research_answer",
                    "resource_id": answer.answer_id,
                    "issuer_id": answer.issuer_id,
                    "snippet": snippet(text),
                    "source_boundary": "public_research_answer_opinion" if answer.source_publicness == "public" else "research_answer_opinion_not_fact",
                    "human_reviewed": reviewed,
                    "pending_review": answer.human_review_status == "pending",
                    "term_coverage": term_coverage(text),
                    "expanded_terms_used": len(expanded_terms) > len(base_terms),
                    "needs_verification": not reviewed,
                }
            )

        # Layer 5 (NEW T-406A): theses → inferences (must be labelled as derived, not fact)
        for thesis in self.store.theses.values():
            text = f"{thesis.hypothesis} {' '.join(thesis.catalyst)} {' '.join(thesis.falsifiers)} {' '.join(thesis.risk_factors)}"
            if not matches(text):
                continue
            inferences.append(
                {
                    "resource_type": "thesis",
                    "resource_id": thesis.thesis_id,
                    "issuer_id": thesis.issuer_id,
                    "snippet": snippet(text),
                    "source_boundary": "inference_derived_from_evidence_not_fact",
                    "evidence_ids": thesis.evidence_ids,
                    "term_coverage": term_coverage(text),
                    "expanded_terms_used": len(expanded_terms) > len(base_terms),
                    "needs_verification": True,
                    "automation_allowed": False,
                }
            )

        # Layer 6 (NEW T-406A): signals → inferences
        for signal in self.store.signals.values():
            thesis = self.store.theses.get(signal.thesis_id)
            text = f"{signal.signal_type} {signal.direction} {signal.rationale} {thesis.hypothesis if thesis else ''}"
            if not matches(text):
                continue
            inferences.append(
                {
                    "resource_type": "signal",
                    "resource_id": signal.signal_id,
                    "issuer_id": thesis.issuer_id if thesis else "",
                    "snippet": snippet(text),
                    "source_boundary": "signal_inference_not_fact_not_tradeable",
                    "thesis_id": signal.thesis_id,
                    "term_coverage": term_coverage(text),
                    "expanded_terms_used": len(expanded_terms) > len(base_terms),
                    "needs_verification": True,
                    "automation_allowed": False,
                }
            )

        # Layer 7: market data signals
        for point in self.store.market_data.values():
            security = self.store.securities.get(point.security_id)
            text = f"{point.security_id} {security.ticker if security else ''} {point.data_type}"
            if matches(text):
                market_signals.append(
                    {
                        "resource_type": "market_data",
                        "resource_id": point.data_id,
                        "security_id": point.security_id,
                        "snippet": f"{point.as_of_date} {point.data_type} close={point.close} volume={point.volume}",
                        "source_boundary": "public_or_provided_market_data_signal_not_fact_conclusion",
                        "term_coverage": term_coverage(text),
                    }
                )

        # Sort each layer by term_coverage desc for higher quality recall at top
        def _sort_layer(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
            return sorted(items, key=lambda r: r.get("term_coverage", 0.0), reverse=True)

        return {
            "public_facts": _sort_layer(public_facts)[:limit],
            "research_opinions": _sort_layer(research_opinions)[:limit],
            "inferences": _sort_layer(inferences)[:limit],
            "market_signals": _sort_layer(market_signals)[:limit],
            "query_expansion": {
                "base_terms": base_terms,
                "expanded_terms_count": len(expanded_terms),
                "synonyms_applied": len(expanded_terms) > len(base_terms),
            },
        }


    def _default_chain_nodes_for_query(self, query: str) -> list[dict[str, Any]]:
        names = ["U盘", "硬盘", "内存条", "CPU", "GPU", "蓝牙", "射频", "WiFi", "电源", "IGBT", "封装", "设备", "材料", "电子化学", "代工", "硅晶", "金属新材料", "非金属材料"]
        categories = ["storage", "storage", "memory", "compute", "compute", "connectivity", "connectivity", "connectivity", "power", "power_semiconductor", "packaging", "equipment", "materials", "electronic_chemicals", "foundry", "wafer", "advanced_materials", "non_metal_materials"]
        return [
            {
                "node_id": f"node_{index + 1}_{safe_source_part(name)}",
                "name": name,
                "level": 1 + index // 6,
                "category": categories[index],
                "parent_id": "",
                "keywords": [name, query],
                "supply_demand_factors": [],
                "data_slots": ["revenue_exposure", "profit_exposure", "capacity", "customers", "suppliers", "valuation_metrics"],
            }
            for index, name in enumerate(names)
        ]

    def register_company_profile(self, payload: Mapping[str, Any], *, actor: str = "system") -> CompanyProfile:
        issuer_id = str(payload["issuer_id"])
        if issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {issuer_id} not found")
        profile = self._company_profile_from_existing_records(issuer_id, payload)
        self.store.company_profiles[issuer_id] = profile
        self.store.commit()
        self._audit(actor, "register_company_profile", "company_profile", issuer_id)
        return profile

    def company_profiles_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        profiles = list(self.store.company_profiles.values())
        if issuer_id:
            profiles = [item for item in profiles if item.issuer_id == issuer_id]
        if security_id:
            profiles = [item for item in profiles if security_id in item.security_ids]
        if issuer_id and not profiles and issuer_id in self.store.issuers:
            profiles = [self._company_profile_from_existing_records(issuer_id, {})]
        profiles.sort(key=lambda item: str(item.updated_at), reverse=True)
        return {"count": len(profiles), "profiles": [to_plain(item) for item in profiles[:limit]]}

    def company_profile_schema_payload(self, _filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        return {
            "primary_key": "issuer_id",
            "required_fields": ["issuer_id", "display_name", "security_ids", "coverage_summary", "data_quality"],
            "source_priority": ["official_disclosure", "company_ir", "public_market_data", "local_reference", "manual_reference"],
            "quality_metrics": ["profile_coverage", "event_backlink_rate", "relationship_backlink_rate", "research_viewpoint_coverage"],
            "compatibility_inputs": ["Issuer", "Security", "MarketDataPoint", "ResearchReportAsset", "DisclosureEvent", "CompanyPosition"],
        }

    def company_profile_coverage_audit(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        limit = self._bounded_limit(payload.get("limit", 100), 5000)
        issuers = self._company_database_target_issuers(payload, limit=limit)
        default_fields = self._company_profile_deep_coverage_fields(include_optional=self._truthy(payload.get("include_optional", False)))
        requested_fields = self._string_list(payload.get("required_fields"))
        required_fields = [field for field in requested_fields if field in default_fields] if requested_fields else default_fields
        if requested_fields and not required_fields:
            raise ValidationError("required_fields did not match any supported company profile audit fields")
        require_evidence = self._truthy(payload.get("require_evidence", False))
        include_research_opinion_slots = self._truthy(payload.get("include_research_opinion_slots", True))
        rows = [
            self._company_profile_deep_coverage_row(
                issuer,
                required_fields=required_fields,
                require_evidence=require_evidence,
                include_research_opinion_slots=include_research_opinion_slots,
            )
            for issuer in issuers
        ]
        missing_counts = {
            field: sum(1 for row in rows if field in row["missing_fields"])
            for field in required_fields
        }
        average_score = round(sum(row["field_coverage_score"] for row in rows) / len(rows), 4) if rows else 0.0
        self._audit(
            actor,
            "company_profile_coverage_audit",
            "company_profile",
            "deep_field_coverage",
            approval_state=f"issuers={len(rows)};average={average_score};require_evidence={require_evidence}",
        )
        return {
            "status": "ready",
            "schema_id": "company-profile-deep-field-coverage-v1",
            "issuer_count": len(rows),
            "average_field_coverage_score": average_score,
            "required_fields": required_fields,
            "field_missing_counts": missing_counts,
            "companies": rows,
            "source_plan": self._company_profile_deep_source_plan(),
            "rules": {
                "fact_fields": "official_disclosure_company_ir_public_market_or_governed_local_records_only",
                "research_reports": "opinion_and_attention_slots_only_not_fact_source",
                "require_evidence": require_evidence,
                "include_research_opinion_slots": include_research_opinion_slots,
            },
            "usage_boundary": "company_profile_deep_field_coverage_uses_public_local_authorized_records_only_research_reports_opinion_only_no_live_trading",
        }

    def _company_profile_deep_coverage_fields(self, *, include_optional: bool = False) -> list[str]:
        required = [
            "legal_name",
            "display_name",
            "aliases",
            "country",
            "region",
            "sector",
            "industry",
            "identifiers",
            "security_ids",
            "tickers",
            "exchange",
            "market",
            "currency",
            "security_type",
            "status",
            "business_summary",
            "products",
            "company_details",
            "as_of_date",
            "close",
            "volume",
            "amount",
            "valuation_metrics",
            "period",
            "revenue",
            "net_income",
            "source_ids",
            "authorized_documents",
            "field_evidence_ids",
            "evidence_backlinks",
            "research_report_count",
            "structured_report_count",
            "report_viewpoint_count",
            "analyst_count",
            "latest_report_at",
            "latest_event_at",
            "company_event_count",
            "relationship_count",
            "open_observation_count",
            "analysis_conclusion_count",
            "profile_coverage",
            "missing_fields",
            "event_backlink_rate",
            "relationship_backlink_rate",
        ]
        optional = ["figi", "isin", "listing_date", "gross_margin", "cash", "debt"]
        return required + optional if include_optional else required

    def _company_profile_deep_source_plan(self) -> dict[str, Any]:
        return {
            "source_priority": ["official_disclosure", "company_ir", "company_official", "public_market_data", "local_reference", "manual_reference"],
            "field_groups": {
                "identity": ["official_disclosure", "exchange_disclosure", "company_ir", "SEC EDGAR", "HKEXnews", "CNINFO"],
                "listing": ["exchange_disclosure", "public_market_data", "SEC/Nasdaq directories", "TDX/AkShare/official exchange directories"],
                "business": ["annual_report", "10-K/20-F", "company_ir", "official_business_overview"],
                "market_snapshot": ["public_eod_market_data", "TDX vipdoc", "Yahoo/Stooq fallback where governed"],
                "financial_snapshot": ["annual_report", "quarterly_report", "SEC companyfacts", "public financial summary connectors"],
                "source_evidence": ["document", "evidence", "source_governance_review"],
                "coverage_opinion": ["local_research_reports", "structured_research_reports", "analyst_profiles"],
                "workflow_feedback": ["company_events", "company_relationships", "observation_items", "analysis_conclusions", "simulation_feedback"],
            },
            "research_report_boundary": "research_reports_can_fill_coverage_opinion_fields_only_not_fact_truth_fields",
            "manual_reference_boundary": "manual_reference_requires_review_before_any_fact_field_can_be_marked_present",
        }

    def _company_profile_document_is_fact_source(self, document: Document) -> bool:
        source = self.store.sources.get(document.source_id)
        source_type = str(document.source_type or (source.source_type if source else "")).strip().lower()
        document_type = str(document.document_type).strip().lower()
        if document_type == "research_report" or "research" in source_type or "research" in str(document.source_id).lower():
            return False
        disallowed_source_types = {"local_reference", "manual_reference", "broker_research", "research", "news", "curated_public_profile"}
        if source_type in disallowed_source_types:
            return False
        allowed_source_types = {"regulatory", "company_ir", "company_official", "official_public", "exchange_disclosure", "issuer_disclosure", "public_company_disclosure"}
        allowed_document_types = {"annual_report", "10-k", "10-q", "8-k", "20-f", "6-k", "prospectus", "registration_statement", "company_announcement", "official_product_page", "official_business_overview"}
        return source_type in allowed_source_types or (document_type in allowed_document_types and (source is None or source.risk_level != "red"))

    def _company_profile_deep_coverage_row(
        self,
        issuer: Issuer,
        *,
        required_fields: list[str],
        require_evidence: bool,
        include_research_opinion_slots: bool,
    ) -> dict[str, Any]:
        securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
        security_ids = {security.security_id for security in securities}
        profile = self.store.company_profiles.get(issuer.issuer_id) or self._company_profile_from_existing_records(issuer.issuer_id, {})
        documents = [document for document in self.store.documents.values() if document.issuer_id == issuer.issuer_id or document.security_id in security_ids]
        fact_documents = [document for document in documents if self._company_profile_document_is_fact_source(document)]
        research_documents = [document for document in documents if document.document_type == "research_report" or "research" in document.source_id.lower() or "research" in document.source_type.lower()]
        evidence_rows = [
            evidence
            for evidence in self.store.evidence.values()
            if evidence.issuer_id == issuer.issuer_id
            or evidence.security_id in security_ids
            or (evidence.document_id in {document.document_id for document in documents})
        ]
        official_evidence_ids = [evidence.evidence_id for evidence in evidence_rows if self._evidence_is_official_public(evidence.evidence_id)]
        research_evidence_ids = [
            evidence.evidence_id
            for evidence in evidence_rows
            if evidence.section == "research_report_citation"
            or (self.store.documents.get(evidence.document_id) is not None and self.store.documents[evidence.document_id].document_type == "research_report")
        ]
        latest_market = next((point for point in [self._latest_market_point_for_security(security.security_id) for security in securities] if point is not None), None)
        reports = [report for report in self.store.research_reports.values() if report.issuer_id == issuer.issuer_id or report.security_id in security_ids]
        structured_reports = [report for report in self.store.structured_research_reports.values() if report.issuer_id == issuer.issuer_id or report.security_id in security_ids]
        structured_report_ids = {report.research_report_id for report in structured_reports}
        viewpoints = [
            viewpoint
            for viewpoint in self.store.report_viewpoints.values()
            if viewpoint.issuer_id == issuer.issuer_id
            or viewpoint.security_id in security_ids
            or viewpoint.research_report_id in structured_report_ids
        ]
        analyst_ids = self._unique_strings([analyst_id for report in structured_reports for analyst_id in report.analyst_ids])
        events = [event for event in self.store.company_events.values() if event.issuer_id == issuer.issuer_id or event.security_id in security_ids]
        relationships = [
            relationship
            for relationship in self.store.company_relationships.values()
            if relationship.issuer_id == issuer.issuer_id
            or relationship.security_id in security_ids
            or relationship.subject_id == issuer.issuer_id
            or relationship.object_id == issuer.issuer_id
        ]
        observations = [item for item in self.store.observation_items.values() if item.issuer_id == issuer.issuer_id or item.security_id in security_ids]
        conclusions = [item for item in self.store.analysis_conclusions.values() if item.issuer_id == issuer.issuer_id or item.security_id in security_ids]
        source_ids = self._unique_strings(
            [
                *issuer.data_sources,
                *profile.source_ids,
                *(document.source_id for document in fact_documents),
                *(point.source_id for point in [latest_market] if point is not None),
            ]
        )
        fundamentals = dict(issuer.fundamentals or profile.latest_financial_snapshot or {})
        company_details = dict(issuer.company_details or {})
        latest_report_at = max([str(to_plain(report.published_at)) for report in structured_reports] + [f"{report.year}-{report.month or '01'}" for report in reports if report.year], default="")
        field_defs = {
            "legal_name": ("identity", bool(issuer.legal_name), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "display_name": ("identity", bool(profile.display_name or issuer.legal_name), [{"resource_type": "company_profile", "resource_id": issuer.issuer_id}]),
            "aliases": ("identity", bool(issuer.aliases), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "country": ("identity", bool(issuer.country), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "region": ("identity", bool(issuer.region), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "sector": ("identity", bool(issuer.sector or profile.sector), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "industry": ("identity", bool(issuer.industry or profile.industry), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "identifiers": ("identity", bool(issuer.lei or issuer.cik or profile.identifiers), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "security_ids": ("listing", bool(securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities]),
            "tickers": ("listing", any(security.ticker for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.ticker]),
            "exchange": ("listing", any(security.exchange for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.exchange]),
            "market": ("listing", bool(issuer.market or [security.market for security in securities if security.market]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "currency": ("listing", any(security.currency for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.currency]),
            "figi": ("listing", any(security.figi for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.figi]),
            "isin": ("listing", any(security.isin for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.isin]),
            "security_type": ("listing", any(security.security_type for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.security_type]),
            "status": ("listing", bool(issuer.status or any(security.status for security in securities)), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "listing_date": ("listing", any(security.listing_date for security in securities), [{"resource_type": "security", "resource_id": security.security_id} for security in securities if security.listing_date]),
            "business_summary": ("business", bool(profile.business_summary or company_details.get("business_summary") or company_details.get("description")), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}, *[{"resource_type": "document", "resource_id": document.document_id} for document in fact_documents]]),
            "products": ("business", bool(profile.products or company_details.get("products")), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}, *[{"resource_type": "document", "resource_id": document.document_id} for document in fact_documents]]),
            "company_details": ("business", bool(company_details), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "as_of_date": ("market_snapshot", latest_market is not None and bool(latest_market.as_of_date), [{"resource_type": "market_data", "resource_id": latest_market.data_id}] if latest_market else []),
            "close": ("market_snapshot", latest_market is not None and float(latest_market.close or 0) != 0, [{"resource_type": "market_data", "resource_id": latest_market.data_id}] if latest_market else []),
            "volume": ("market_snapshot", latest_market is not None and float(latest_market.volume or 0) != 0, [{"resource_type": "market_data", "resource_id": latest_market.data_id}] if latest_market else []),
            "amount": ("market_snapshot", latest_market is not None and float(latest_market.amount or 0) != 0, [{"resource_type": "market_data", "resource_id": latest_market.data_id}] if latest_market else []),
            "valuation_metrics": ("market_snapshot", bool(issuer.valuation_metrics), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "period": ("financial_snapshot", any(fundamentals.get(key) for key in ["period", "report_period", "fiscal_period", "date"]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "revenue": ("financial_snapshot", any(fundamentals.get(key) for key in ["revenue", "operating_revenue", "total_revenue"]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "net_income": ("financial_snapshot", any(fundamentals.get(key) for key in ["net_income", "net_profit", "profit"]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "gross_margin": ("financial_snapshot", bool(fundamentals.get("gross_margin")), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "cash": ("financial_snapshot", any(fundamentals.get(key) for key in ["cash", "cash_and_equivalents"]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "debt": ("financial_snapshot", any(fundamentals.get(key) for key in ["debt", "total_debt"]), [{"resource_type": "issuer", "resource_id": issuer.issuer_id}]),
            "source_ids": ("source_evidence", bool(source_ids), [{"resource_type": "source", "resource_id": source_id} for source_id in source_ids]),
            "authorized_documents": ("source_evidence", bool(fact_documents), [{"resource_type": "document", "resource_id": document.document_id} for document in fact_documents]),
            "field_evidence_ids": ("source_evidence", bool(official_evidence_ids), [{"resource_type": "evidence", "resource_id": evidence_id} for evidence_id in official_evidence_ids[:10]]),
            "evidence_backlinks": ("source_evidence", bool(official_evidence_ids), [{"resource_type": "evidence", "resource_id": evidence_id} for evidence_id in official_evidence_ids[:10]]),
            "research_report_count": ("coverage_opinion", include_research_opinion_slots and bool(reports), [{"resource_type": "research_report", "resource_id": report.report_id} for report in reports[:10]]),
            "structured_report_count": ("coverage_opinion", include_research_opinion_slots and bool(structured_reports), [{"resource_type": "structured_research_report", "resource_id": report.research_report_id} for report in structured_reports[:10]]),
            "report_viewpoint_count": ("coverage_opinion", include_research_opinion_slots and bool(viewpoints), [{"resource_type": "report_viewpoint", "resource_id": viewpoint.viewpoint_id} for viewpoint in viewpoints[:10]]),
            "analyst_count": ("coverage_opinion", include_research_opinion_slots and bool(analyst_ids), [{"resource_type": "analyst_profile", "resource_id": analyst_id} for analyst_id in analyst_ids[:10]]),
            "latest_report_at": ("coverage_opinion", include_research_opinion_slots and bool(latest_report_at), [{"resource_type": "research_report", "resource_id": reports[0].report_id}] if reports else []),
            "latest_event_at": ("workflow_feedback", bool(events), [{"resource_type": "company_event", "resource_id": event.event_id} for event in events[:10]]),
            "company_event_count": ("workflow_feedback", bool(events), [{"resource_type": "company_event", "resource_id": event.event_id} for event in events[:10]]),
            "relationship_count": ("workflow_feedback", bool(relationships), [{"resource_type": "company_relationship", "resource_id": relationship.relationship_id} for relationship in relationships[:10]]),
            "open_observation_count": ("workflow_feedback", any(item.status in {"open", "in_progress", "waiting"} for item in observations), [{"resource_type": "observation_item", "resource_id": item.observation_id} for item in observations[:10]]),
            "analysis_conclusion_count": ("workflow_feedback", bool(conclusions), [{"resource_type": "analysis_conclusion", "resource_id": item.analysis_conclusion_id} for item in conclusions[:10]]),
            "profile_coverage": ("quality", profile.data_quality.get("profile_coverage") is not None, [{"resource_type": "company_profile", "resource_id": issuer.issuer_id}]),
            "missing_fields": ("quality", profile.data_quality.get("missing_fields") is not None, [{"resource_type": "company_profile", "resource_id": issuer.issuer_id}]),
            "event_backlink_rate": ("quality", profile.data_quality.get("event_backlink_rate") is not None, [{"resource_type": "company_profile", "resource_id": issuer.issuer_id}]),
            "relationship_backlink_rate": ("quality", profile.data_quality.get("relationship_backlink_rate") is not None, [{"resource_type": "company_profile", "resource_id": issuer.issuer_id}]),
        }
        fields: dict[str, dict[str, Any]] = {}
        for field_name in required_fields:
            group, present, source_records = field_defs[field_name]
            evidence_ids = official_evidence_ids if group in {"identity", "business", "financial_snapshot", "source_evidence"} else []
            if require_evidence and group not in {"coverage_opinion", "workflow_feedback", "quality", "listing", "market_snapshot"}:
                present = bool(present and evidence_ids)
            missing_reason = ""
            if not present:
                if group != "coverage_opinion" and (reports or research_documents or research_evidence_ids):
                    missing_reason = "research_report_or_local_reference_is_not_fact_source"
                elif group == "source_evidence" and documents and not fact_documents:
                    missing_reason = "no_authorized_fact_source_document"
                else:
                    missing_reason = "no_underlying_record"
            fields[field_name] = {
                "group": group,
                "present": bool(present),
                "source_records": source_records if present else [],
                "evidence_ids": evidence_ids[:10] if present else [],
                "missing_reason": missing_reason,
                "source_policy": "opinion_slot" if group == "coverage_opinion" else "fact_or_governed_record",
            }
        missing_fields = [field_name for field_name, field in fields.items() if not field["present"]]
        score = round((len(fields) - len(missing_fields)) / len(fields), 4) if fields else 0.0
        research_tasks = [
            {
                "task_type": "company_profile_field_backfill",
                "field": field_name,
                "reason": fields[field_name]["missing_reason"],
                "recommended_sources": self._company_profile_deep_source_plan()["field_groups"].get(fields[field_name]["group"], []),
            }
            for field_name in missing_fields[:12]
        ]
        return {
            "issuer_id": issuer.issuer_id,
            "display_name": profile.display_name or issuer.legal_name,
            "field_coverage_score": score,
            "coverage_level": "complete" if score >= 0.9 else ("partial" if score >= 0.5 else "sparse"),
            "missing_fields": missing_fields,
            "fields": fields,
            "counts": {
                "securities": len(securities),
                "authorized_documents": len(fact_documents),
                "official_evidence": len(official_evidence_ids),
                "research_reports": len(reports),
                "structured_reports": len(structured_reports),
                "company_events": len(events),
                "company_relationships": len(relationships),
                "open_observations": sum(1 for item in observations if item.status in {"open", "in_progress", "waiting"}),
                "analysis_conclusions": len(conclusions),
            },
            "research_tasks": research_tasks,
        }

    def company_database_coverage_audit(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        limit = self._bounded_limit(payload.get("limit", 100), 5000)
        issuers = self._company_database_target_issuers(payload, limit=limit)
        rows = [self._company_database_coverage_row(issuer) for issuer in issuers]
        required_sections = [
            "company_profile",
            "security",
            "market_data",
            "financial_snapshot",
            "documents",
            "disclosure_events",
            "company_events",
            "company_relationships",
            "research_reports",
            "structured_viewpoints",
            "observation_items",
            "analysis_conclusions",
            "simulation_feedback",
        ]
        missing_counts = {
            section: sum(1 for row in rows if section in row["missing_sections"])
            for section in required_sections
        }
        rows.sort(key=lambda item: (item["coverage_score"], item["issuer_id"]))
        average_score = round(sum(row["coverage_score"] for row in rows) / len(rows), 4) if rows else 0.0
        self._audit(
            actor,
            "company_database_coverage_audit",
            "company_database",
            "coverage",
            approval_state=f"issuers={len(rows)};average={average_score}",
        )
        return {
            "status": "ready",
            "issuer_count": len(rows),
            "average_coverage_score": average_score,
            "missing_counts": missing_counts,
            "required_sections": required_sections,
            "companies": rows,
            "usage_boundary": "company_database_coverage_audit_uses_local_records_only_no_live_trading",
        }

    def _company_database_coverage_row(self, issuer: Issuer) -> dict[str, Any]:
        securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
        security_ids = {security.security_id for security in securities}
        has_market_data = any(self._latest_market_point_for_security(security.security_id) is not None for security in securities)
        documents = [
            document
            for document in self.store.documents.values()
            if document.issuer_id == issuer.issuer_id or document.security_id in security_ids
        ]
        disclosure_events = [
            event
            for event in self.store.disclosure_events.values()
            if event.issuer_id == issuer.issuer_id or event.security_id in security_ids
        ]
        company_events = [
            event
            for event in self.store.company_events.values()
            if event.issuer_id == issuer.issuer_id or event.security_id in security_ids
        ]
        relationships = [
            relationship
            for relationship in self.store.company_relationships.values()
            if relationship.issuer_id == issuer.issuer_id
            or relationship.security_id in security_ids
            or relationship.subject_id == issuer.issuer_id
            or relationship.object_id == issuer.issuer_id
        ]
        reports = [
            report
            for report in self.store.research_reports.values()
            if report.issuer_id == issuer.issuer_id or report.security_id in security_ids
        ]
        structured_reports = [
            report
            for report in self.store.structured_research_reports.values()
            if report.issuer_id == issuer.issuer_id or report.security_id in security_ids
        ]
        structured_report_ids = {report.research_report_id for report in structured_reports}
        viewpoints = [
            viewpoint
            for viewpoint in self.store.report_viewpoints.values()
            if viewpoint.issuer_id == issuer.issuer_id
            or viewpoint.security_id in security_ids
            or viewpoint.research_report_id in structured_report_ids
        ]
        observations = [
            item
            for item in self.store.observation_items.values()
            if item.issuer_id == issuer.issuer_id or item.security_id in security_ids
        ]
        conclusions = [
            item
            for item in self.store.analysis_conclusions.values()
            if item.issuer_id == issuer.issuer_id or item.security_id in security_ids
        ]
        feedback = [
            item
            for item in self.store.simulation_feedback.values()
            if item.issuer_id == issuer.issuer_id or item.security_id in security_ids
        ]
        section_available = {
            "company_profile": issuer.issuer_id in self.store.company_profiles,
            "security": bool(securities),
            "market_data": has_market_data,
            "financial_snapshot": bool(issuer.fundamentals),
            "documents": bool(documents),
            "disclosure_events": bool(disclosure_events),
            "company_events": bool(company_events),
            "company_relationships": bool(relationships),
            "research_reports": bool(reports),
            "structured_viewpoints": bool(viewpoints),
            "observation_items": bool(observations),
            "analysis_conclusions": bool(conclusions),
            "simulation_feedback": bool(feedback),
        }
        missing = [section for section, available in section_available.items() if not available]
        score = round(sum(1 for available in section_available.values() if available) / len(section_available), 4)
        return {
            "issuer_id": issuer.issuer_id,
            "display_name": issuer.legal_name,
            "coverage_score": score,
            "coverage_level": "complete" if score >= 0.9 else ("partial" if score >= 0.5 else "sparse"),
            "missing_sections": missing,
            "section_available": section_available,
            "counts": {
                "securities": len(securities),
                "documents": len(documents),
                "disclosure_events": len(disclosure_events),
                "company_events": len(company_events),
                "company_relationships": len(relationships),
                "research_reports": len(reports),
                "structured_research_reports": len(structured_reports),
                "report_viewpoints": len(viewpoints),
                "observation_items": len(observations),
                "analysis_conclusions": len(conclusions),
                "simulation_feedback": len(feedback),
            },
        }

    def build_company_database_batch(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        resume_run_id = str(payload.get("resume_run_id", "")).strip()
        if resume_run_id:
            retry_payload = dict(payload)
            retry_payload.pop("resume_run_id", None)
            if "resume_mode" not in retry_payload:
                retry_payload["resume_mode"] = "remaining" if self._truthy(payload.get("retry_failed", True)) else "all"
            return self.retry_company_database_build_run(resume_run_id, retry_payload, actor=actor)
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 100), 5000)
        batch_size = self._bounded_limit(payload.get("batch_size", 20), 500)
        report_match_limit = self._bounded_limit(payload.get("report_match_limit", 100), 2000)
        structure_reports = self._truthy(payload.get("structure_reports", False))
        structure_report_limit = self._bounded_limit(payload.get("structure_report_limit", 20), 500)
        force_structure = self._truthy(payload.get("force_structure", False))
        build_events = self._truthy(payload.get("build_events", True))
        build_relationships = self._truthy(payload.get("build_relationships", True))
        build_workflow = self._truthy(payload.get("build_workflow", True))
        include_market_data = self._truthy(payload.get("include_market_data", True))
        include_research_coverage = self._truthy(payload.get("include_research_coverage", True))
        include_disclosures = self._truthy(payload.get("include_disclosures", True))
        include_structured_disclosures = self._truthy(payload.get("include_structured_disclosures", True))
        include_listings = self._truthy(payload.get("include_listings", True))
        include_institution_coverage = self._truthy(payload.get("include_institution_coverage", True))
        include_disclosure_candidates = self._truthy(payload.get("include_disclosure_candidates", True))
        event_limit = self._bounded_limit(payload.get("event_limit", 100), 2000)
        relationship_limit = self._bounded_limit(payload.get("relationship_limit", 100), 2000)
        workflow_link_limit = self._bounded_limit(payload.get("workflow_link_limit", 5), 100)
        record_run = execute or self._truthy(payload.get("record_run", False))
        retry_of = str(payload.get("retry_of", "")).strip()
        resume_of = str(payload.get("resume_of", "")).strip()
        resume_mode = str(payload.get("resume_mode", "")).strip()
        attempt = self._company_database_batch_attempt(payload.get("attempt", 1))
        raw_skipped_issuer_ids = payload.get("skipped_issuer_ids", [])
        if isinstance(raw_skipped_issuer_ids, str):
            skipped_issuer_ids = [raw_skipped_issuer_ids]
        else:
            skipped_issuer_ids = list(raw_skipped_issuer_ids or [])
        skipped_issuer_ids = [str(item).strip() for item in skipped_issuer_ids if str(item).strip()]
        raw_completed_issuer_ids = payload.get("completed_issuer_ids", [])
        if isinstance(raw_completed_issuer_ids, str):
            completed_issuer_ids = [raw_completed_issuer_ids]
        else:
            completed_issuer_ids = list(raw_completed_issuer_ids or [])
        completed_issuer_ids = [str(item).strip() for item in completed_issuer_ids if str(item).strip()]
        started_at = utcnow()
        issuers = self._company_database_target_issuers(payload, limit=limit)
        target_issuer_ids = [issuer.issuer_id for issuer in issuers]
        if isinstance(payload.get("target_symbols"), list):
            target_symbols = [str(item) for item in payload.get("target_symbols", []) if str(item).strip()]
        else:
            target_symbols = [str(item) for item in payload.get("symbols", [])] if isinstance(payload.get("symbols"), list) else ([str(payload.get("symbol") or payload.get("ticker"))] if payload.get("symbol") or payload.get("ticker") else [])
        coverage_filter = {"issuer_ids": target_issuer_ids, "limit": len(target_issuer_ids)}
        coverage_before = self.company_database_coverage_audit(coverage_filter, actor=actor) if issuers else {}
        batches: list[dict[str, Any]] = []
        totals = {
            "profiles_saved": 0,
            "profiles_planned": 0,
            "research_reports_matched": 0,
            "research_reports_bound": 0,
            "events_created": 0,
            "events_planned": 0,
            "relationships_created": 0,
            "relationships_planned": 0,
            "observations_created": 0,
            "observations_planned": 0,
            "conclusions_created": 0,
            "conclusions_planned": 0,
            "feedback_created": 0,
            "feedback_planned": 0,
        }
        options = self._company_database_batch_options(
            limit=limit,
            batch_size=batch_size,
            report_match_limit=report_match_limit,
            structure_reports=structure_reports,
            structure_report_limit=structure_report_limit,
            force_structure=force_structure,
            build_events=build_events,
            build_relationships=build_relationships,
            build_workflow=build_workflow,
            include_market_data=include_market_data,
            include_research_coverage=include_research_coverage,
            include_disclosures=include_disclosures,
            include_structured_disclosures=include_structured_disclosures,
            include_listings=include_listings,
            include_institution_coverage=include_institution_coverage,
            include_disclosure_candidates=include_disclosure_candidates,
            event_limit=event_limit,
            relationship_limit=relationship_limit,
            workflow_link_limit=workflow_link_limit,
        )
        run_id = str(payload.get("run_id") or self._company_database_batch_run_id(actor, target_issuer_ids, started_at))
        idempotency_key = str(payload.get("idempotency_key", "")).strip() or self._company_database_batch_idempotency_key(
            actor,
            target_issuer_ids,
            options,
            retry_of=retry_of,
            resume_of=resume_of,
            attempt=attempt,
        )
        run_record: CompanyDatabaseBuildRun | None = None
        coverage: dict[str, Any] = {}
        try:
            for index in range(0, len(issuers), batch_size):
                batch_issuers = issuers[index : index + batch_size]
                batch_issuer_ids = [issuer.issuer_id for issuer in batch_issuers]
                database_result = self.build_company_database(
                    {
                        "issuer_ids": batch_issuer_ids,
                        "limit": len(batch_issuer_ids),
                        "report_match_limit": report_match_limit,
                        "structure_reports": structure_reports,
                        "structure_report_limit": structure_report_limit,
                        "force_structure": force_structure,
                        "execute": execute,
                        "dry_run": dry_run,
                    },
                    actor=actor,
                )
                events_result: dict[str, Any] = {}
                if build_events:
                    events_result = self.build_company_events(
                        {
                            "issuer_ids": batch_issuer_ids,
                            "limit": len(batch_issuer_ids),
                            "event_limit": event_limit,
                            "include_market_data": include_market_data,
                            "include_research_coverage": include_research_coverage,
                            "include_disclosures": include_disclosures,
                            "include_structured_disclosures": include_structured_disclosures,
                            "execute": execute,
                            "dry_run": dry_run,
                        },
                        actor=actor,
                    )
                relationships_result: dict[str, Any] = {}
                if build_relationships:
                    relationships_result = self.build_company_relationships(
                        {
                            "issuer_ids": batch_issuer_ids,
                            "limit": len(batch_issuer_ids),
                            "relationship_limit": relationship_limit,
                            "include_listings": include_listings,
                            "include_institution_coverage": include_institution_coverage,
                            "include_disclosure_candidates": include_disclosure_candidates,
                            "execute": execute,
                            "dry_run": dry_run,
                        },
                        actor=actor,
                    )
                workflow_result: dict[str, Any] = {}
                if build_workflow:
                    workflow_result = self.build_company_workflow(
                        {
                            "issuer_ids": batch_issuer_ids,
                            "limit": len(batch_issuer_ids),
                            "link_limit": workflow_link_limit,
                            "execute": execute,
                            "dry_run": dry_run,
                        },
                        actor=actor,
                    )
                totals["profiles_saved"] += int(database_result.get("profiles_saved", 0))
                totals["profiles_planned"] += int(database_result.get("profiles_planned", 0))
                totals["research_reports_matched"] += int(database_result.get("research_reports_matched", 0))
                totals["research_reports_bound"] += int(database_result.get("research_reports_bound", 0))
                totals["events_created"] += int(events_result.get("events_created", 0) or 0)
                totals["events_planned"] += int(events_result.get("events_planned", 0) or 0)
                totals["relationships_created"] += int(relationships_result.get("relationships_created", 0) or 0)
                totals["relationships_planned"] += int(relationships_result.get("relationships_planned", 0) or 0)
                totals["observations_created"] += int(workflow_result.get("observations_created", 0) or 0)
                totals["observations_planned"] += int(workflow_result.get("observations_planned", 0) or 0)
                totals["conclusions_created"] += int(workflow_result.get("conclusions_created", 0) or 0)
                totals["conclusions_planned"] += int(workflow_result.get("conclusions_planned", 0) or 0)
                totals["feedback_created"] += int(workflow_result.get("feedback_created", 0) or 0)
                totals["feedback_planned"] += int(workflow_result.get("feedback_planned", 0) or 0)
                completed_issuer_ids.extend(issuer_id for issuer_id in batch_issuer_ids if issuer_id not in completed_issuer_ids)
                batches.append(
                    {
                        "batch_index": len(batches) + 1,
                        "issuer_ids": batch_issuer_ids,
                        "database_result": database_result,
                        "events_result": events_result,
                        "relationships_result": relationships_result,
                        "workflow_result": workflow_result,
                    }
                )
            coverage = self.company_database_coverage_audit(coverage_filter, actor=actor) if issuers else {}
        except Exception as exc:
            try:
                coverage = self.company_database_coverage_audit(coverage_filter, actor=actor) if issuers else {}
            except Exception:
                coverage = {}
            if record_run:
                run_record = self._record_company_database_build_run(
                    run_id=run_id,
                    actor=actor,
                    status="partial" if batches else "failed",
                    execute=execute,
                    dry_run=dry_run,
                    retry_of=retry_of,
                    resume_of=resume_of,
                    resume_mode=resume_mode,
                    attempt=attempt,
                    idempotency_key=idempotency_key,
                    target_issuer_ids=target_issuer_ids,
                    target_symbols=target_symbols,
                    completed_issuer_ids=completed_issuer_ids,
                    skipped_issuer_ids=skipped_issuer_ids,
                    batch_size=batch_size,
                    totals=totals,
                    coverage_before=coverage_before,
                    coverage_after=coverage,
                    options=options,
                    batches=batches,
                    error=str(exc),
                    started_at=started_at,
                )
            self._audit(
                actor,
                "build_company_database_batch",
                "company_database",
                "batch",
                approval_state=f"failed;execute={execute};issuers={len(issuers)};batches={len(batches)}",
            )
            raise
        if record_run:
            run_record = self._record_company_database_build_run(
                run_id=run_id,
                actor=actor,
                status="executed" if execute else "dry_run",
                execute=execute,
                dry_run=dry_run,
                retry_of=retry_of,
                resume_of=resume_of,
                resume_mode=resume_mode,
                attempt=attempt,
                idempotency_key=idempotency_key,
                target_issuer_ids=target_issuer_ids,
                target_symbols=target_symbols,
                completed_issuer_ids=completed_issuer_ids,
                skipped_issuer_ids=skipped_issuer_ids,
                batch_size=batch_size,
                totals=totals,
                coverage_before=coverage_before,
                coverage_after=coverage,
                options=options,
                batches=batches,
                error="",
                started_at=started_at,
            )
        self._audit(
            actor,
            "build_company_database_batch",
            "company_database",
            "batch",
            approval_state=f"execute={execute};issuers={len(issuers)};batches={len(batches)}",
        )
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "issuer_count": len(issuers),
            "batch_count": len(batches),
            "batch_size": batch_size,
            "totals": totals,
            "coverage_before": coverage_before,
            "coverage_after": coverage,
            "run_id": run_id,
            "run_recorded": record_run,
            "run": to_plain(run_record) if run_record else {},
            "batches": batches,
            "usage_boundary": "company_database_batch_build_uses_local_records_only_no_live_trading",
        }

    def retry_company_database_build_run(self, run_id: str, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        source_run = self.store.company_database_build_runs.get(str(run_id))
        if source_run is None:
            raise NotFoundError(f"company database build run not found: {run_id}")
        resume_mode = str(payload.get("resume_mode") or ("remaining" if source_run.status in {"failed", "partial"} else "all")).strip()
        if resume_mode not in {"all", "remaining"}:
            raise ValidationError("resume_mode must be one of ['all', 'remaining']")
        completed_issuer_ids = self._company_database_build_run_completed_issuer_ids(source_run)
        if resume_mode == "remaining":
            retry_issuer_ids = [issuer_id for issuer_id in source_run.target_issuer_ids if issuer_id not in set(completed_issuer_ids)]
            skipped_issuer_ids = [issuer_id for issuer_id in source_run.target_issuer_ids if issuer_id in set(completed_issuer_ids)]
        else:
            retry_issuer_ids = list(source_run.target_issuer_ids)
            skipped_issuer_ids = []
        if not retry_issuer_ids:
            self._audit(
                actor,
                "retry_company_database_build_run",
                "company_database_build_run",
                source_run.run_id,
                approval_state=f"nothing_to_retry;resume_mode={resume_mode}",
            )
            return {
                "status": "nothing_to_retry",
                "source_run_id": source_run.run_id,
                "resume_mode": resume_mode,
                "retry_issuer_ids": [],
                "skipped_issuer_ids": skipped_issuer_ids,
                "usage_boundary": "company_database_build_retry_uses_local_run_history_no_live_trading",
            }
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        attempt = self._company_database_batch_attempt(payload.get("attempt", int(source_run.attempt or 1) + 1))
        replay_payload: dict[str, Any] = dict(source_run.options)
        replay_payload.update(
            {
                "issuer_ids": retry_issuer_ids,
                "limit": len(retry_issuer_ids),
                "target_symbols": list(source_run.target_symbols),
                "execute": execute,
                "dry_run": dry_run,
                "record_run": self._truthy(payload.get("record_run", True)),
                "retry_of": source_run.run_id,
                "resume_of": source_run.run_id if resume_mode == "remaining" else str(payload.get("resume_of", "")).strip(),
                "resume_mode": resume_mode,
                "attempt": attempt,
                "completed_issuer_ids": [] if resume_mode == "all" else completed_issuer_ids,
                "skipped_issuer_ids": skipped_issuer_ids,
            }
        )
        override_keys = {
            "run_id",
            "idempotency_key",
            "batch_size",
            "report_match_limit",
            "structure_reports",
            "structure_report_limit",
            "force_structure",
            "build_events",
            "build_relationships",
            "build_workflow",
            "include_market_data",
            "include_research_coverage",
            "include_disclosures",
            "include_structured_disclosures",
            "include_listings",
            "include_institution_coverage",
            "include_disclosure_candidates",
            "event_limit",
            "relationship_limit",
            "workflow_link_limit",
        }
        for key in override_keys:
            if key in payload:
                replay_payload[key] = payload[key]
        result = self.build_company_database_batch(replay_payload, actor=actor)
        self._audit(
            actor,
            "retry_company_database_build_run",
            "company_database_build_run",
            source_run.run_id,
            approval_state=f"new_run={result.get('run_id')};resume_mode={resume_mode};execute={execute}",
        )
        return {
            "status": result.get("status", "dry_run"),
            "source_run_id": source_run.run_id,
            "new_run_id": result.get("run_id", ""),
            "resume_mode": resume_mode,
            "attempt": attempt,
            "retry_issuer_ids": retry_issuer_ids,
            "skipped_issuer_ids": skipped_issuer_ids,
            "result": result,
            "usage_boundary": "company_database_build_retry_uses_local_run_history_no_live_trading",
        }

    def _record_company_database_build_run(
        self,
        *,
        run_id: str,
        actor: str,
        status: str,
        execute: bool,
        dry_run: bool,
        retry_of: str,
        resume_of: str,
        resume_mode: str,
        attempt: int,
        idempotency_key: str,
        target_issuer_ids: list[str],
        target_symbols: list[str],
        completed_issuer_ids: list[str],
        skipped_issuer_ids: list[str],
        batch_size: int,
        totals: dict[str, Any],
        coverage_before: dict[str, Any],
        coverage_after: dict[str, Any],
        options: dict[str, Any],
        batches: list[dict[str, Any]],
        error: str,
        started_at: Any,
    ) -> CompanyDatabaseBuildRun:
        run_record = CompanyDatabaseBuildRun(
            run_id=run_id,
            actor=actor,
            status=status,
            execute=execute,
            dry_run=dry_run,
            retry_of=retry_of,
            resume_of=resume_of,
            resume_mode=resume_mode,
            attempt=attempt,
            idempotency_key=idempotency_key,
            target_issuer_ids=list(target_issuer_ids),
            target_symbols=list(target_symbols),
            completed_issuer_ids=list(completed_issuer_ids),
            skipped_issuer_ids=list(skipped_issuer_ids),
            batch_count=len(batches),
            batch_size=batch_size,
            totals=dict(totals),
            coverage_before=dict(coverage_before),
            coverage_after=dict(coverage_after),
            options=dict(options),
            batches=list(batches),
            error=error,
            started_at=started_at,
            completed_at=utcnow(),
        )
        self.store.company_database_build_runs[run_id] = run_record
        marker = getattr(self.store, "mark_dirty_for_resource", None)
        if callable(marker):
            marker("company_database_build_run")
        self.store.commit()
        return run_record

    def _company_database_build_run_completed_issuer_ids(self, run: CompanyDatabaseBuildRun) -> list[str]:
        completed: list[str] = []
        for issuer_id in run.completed_issuer_ids:
            if issuer_id not in completed:
                completed.append(issuer_id)
        for batch in run.batches:
            if not isinstance(batch, Mapping):
                continue
            for issuer_id in batch.get("issuer_ids", []) or []:
                issuer_id = str(issuer_id)
                if issuer_id and issuer_id not in completed:
                    completed.append(issuer_id)
        return completed

    def _company_database_batch_attempt(self, value: Any) -> int:
        try:
            return max(1, int(value or 1))
        except (TypeError, ValueError):
            raise ValidationError("attempt must be an integer") from None

    def _company_database_batch_run_id(self, actor: str, issuer_ids: list[str], started_at: Any) -> str:
        raw = f"{actor}:{','.join(issuer_ids)}:{to_plain(started_at)}:{time.time()}"
        return f"cdb_run_{utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:10]}"

    def _company_database_batch_idempotency_key(self, actor: str, issuer_ids: list[str], options: Mapping[str, Any], *, retry_of: str = "", resume_of: str = "", attempt: int = 1) -> str:
        raw = {
            "actor": actor,
            "issuer_ids": issuer_ids,
            "options": options,
            "retry_of": retry_of,
            "resume_of": resume_of,
            "attempt": attempt,
        }
        digest = hashlib.sha256(json.dumps(to_plain(raw), ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        return f"cdb_batch_{digest}"

    def _company_database_batch_options(self, **kwargs: Any) -> dict[str, Any]:
        return {key: value for key, value in kwargs.items()}

    def company_database_build_runs_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        limit = self._bounded_limit(filters.get("limit", 20), 200)
        run_id = str(filters.get("run_id", "")).strip()
        issuer_id = str(filters.get("issuer_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        include_batches = self._truthy(filters.get("include_batches", False))
        runs = list(self.store.company_database_build_runs.values())
        if run_id:
            runs = [run for run in runs if run.run_id == run_id]
        if issuer_id:
            runs = [run for run in runs if issuer_id in run.target_issuer_ids]
        if status:
            runs = [run for run in runs if run.status == status]
        runs.sort(key=lambda item: (str(to_plain(item.completed_at)), item.run_id), reverse=True)
        rows: list[dict[str, Any]] = []
        for run in runs[:limit]:
            row = to_plain(run)
            if not include_batches:
                row["batch_details_omitted"] = bool(row.get("batches"))
                row["batches"] = []
            rows.append(row)
        return {
            "count": len(runs),
            "include_batches": include_batches,
            "runs": rows,
            "usage_boundary": "company_database_build_runs_are_local_operations_history_no_live_trading",
        }

    def company_database_coverage_trends(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        limit = self._bounded_limit(payload.get("limit", 50), 500)
        issuer_id = str(payload.get("issuer_id", "")).strip()
        status = str(payload.get("status", "")).strip()
        write_artifact = self._truthy(payload.get("write_artifact", payload.get("record_artifact", False)))
        runs = list(self.store.company_database_build_runs.values())
        if issuer_id:
            runs = [run for run in runs if issuer_id in run.target_issuer_ids]
        if status:
            runs = [run for run in runs if run.status == status]
        runs.sort(key=lambda item: (str(to_plain(item.completed_at)), item.run_id), reverse=True)
        selected = list(reversed(runs[:limit]))
        rows = [self._company_database_coverage_trend_row(run) for run in selected]
        latest = rows[-1] if rows else {}
        first = rows[0] if rows else {}
        improved_runs = sum(1 for row in rows if float(row["coverage_delta"]) > 0 or int(row["missing_delta"]) < 0)
        worsened_runs = sum(1 for row in rows if float(row["coverage_delta"]) < 0 or int(row["missing_delta"]) > 0)
        unchanged_runs = max(0, len(rows) - improved_runs - worsened_runs)
        summary = {
            "run_count": len(rows),
            "latest_run_id": latest.get("run_id", ""),
            "first_run_id": first.get("run_id", ""),
            "first_coverage_score": first.get("coverage_before_score", 0.0),
            "latest_coverage_score": latest.get("coverage_after_score", 0.0),
            "cumulative_coverage_delta": round(float(latest.get("coverage_after_score", 0.0)) - float(first.get("coverage_before_score", 0.0)), 4) if rows else 0.0,
            "latest_missing_count": latest.get("missing_after_count", 0),
            "cumulative_missing_delta": int(latest.get("missing_after_count", 0)) - int(first.get("missing_before_count", 0)) if rows else 0,
            "improved_runs": improved_runs,
            "worsened_runs": worsened_runs,
            "unchanged_runs": unchanged_runs,
        }
        artifact: dict[str, Any] = {}
        result = {
            "status": "ready",
            "issuer_id": issuer_id,
            "run_count": len(rows),
            "summary": summary,
            "trend_rows": rows,
            "artifact": artifact,
            "generated_at": utcnow(),
            "usage_boundary": "company_database_coverage_trends_are_local_research_operations_history_no_live_trading",
        }
        if write_artifact:
            artifact_path = Path(str(payload.get("artifact_path") or "artifacts/company-database-coverage-trends.json"))
            artifact_path.parent.mkdir(parents=True, exist_ok=True)
            artifact.update(
                {
                    "path": str(artifact_path),
                    "classification": "local-only",
                    "producer": "SystemService.company_database_coverage_trends",
                    "contains_sensitive_data": False,
                    "acceptable_for_non_local_release_gate": False,
                    "usage_boundary": "local_research_operations_report_not_production_release_evidence",
                }
            )
            artifact_path.write_text(json.dumps(to_plain(result), ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
        self._audit(
            actor,
            "company_database_coverage_trends",
            "company_database",
            "coverage_trends",
            approval_state=f"runs={len(rows)};artifact={bool(artifact)}",
        )
        return result

    def _company_database_coverage_score(self, summary: Mapping[str, Any] | None) -> float:
        if not summary:
            return 0.0
        if summary.get("average_coverage_score") is not None:
            return round(float(summary.get("average_coverage_score") or 0.0), 4)
        companies = summary.get("companies", [])
        if isinstance(companies, list) and companies:
            return round(sum(float(item.get("coverage_score", 0.0) or 0.0) for item in companies if isinstance(item, Mapping)) / len(companies), 4)
        return 0.0

    def _company_database_missing_counts(self, summary: Mapping[str, Any] | None) -> dict[str, int]:
        if not summary:
            return {}
        raw_counts = summary.get("missing_counts", {})
        if isinstance(raw_counts, Mapping):
            return {str(key): int(value or 0) for key, value in raw_counts.items()}
        counts: dict[str, int] = {}
        companies = summary.get("companies", [])
        if isinstance(companies, list):
            for company in companies:
                if not isinstance(company, Mapping):
                    continue
                for section in company.get("missing_sections", []) or []:
                    key = str(section)
                    counts[key] = counts.get(key, 0) + 1
        return counts

    def _company_database_coverage_trend_row(self, run: CompanyDatabaseBuildRun) -> dict[str, Any]:
        before_score = self._company_database_coverage_score(run.coverage_before)
        after_score = self._company_database_coverage_score(run.coverage_after)
        before_missing = self._company_database_missing_counts(run.coverage_before)
        after_missing = self._company_database_missing_counts(run.coverage_after)
        sections = sorted(set(before_missing) | set(after_missing))
        missing_delta_by_section = {section: int(after_missing.get(section, 0)) - int(before_missing.get(section, 0)) for section in sections}
        missing_before_count = sum(before_missing.values())
        missing_after_count = sum(after_missing.values())
        return {
            "run_id": run.run_id,
            "actor": run.actor,
            "status": run.status,
            "execute": run.execute,
            "dry_run": run.dry_run,
            "target_issuer_ids": list(run.target_issuer_ids),
            "target_symbols": list(run.target_symbols),
            "batch_count": run.batch_count,
            "batch_size": run.batch_size,
            "completed_at": run.completed_at,
            "coverage_before_score": before_score,
            "coverage_after_score": after_score,
            "coverage_delta": round(after_score - before_score, 4),
            "missing_before_count": missing_before_count,
            "missing_after_count": missing_after_count,
            "missing_delta": missing_after_count - missing_before_count,
            "missing_delta_by_section": missing_delta_by_section,
            "improved_sections": [section for section, delta in missing_delta_by_section.items() if delta < 0],
            "worsened_sections": [section for section, delta in missing_delta_by_section.items() if delta > 0],
            "totals": dict(run.totals),
            "usage_boundary": run.usage_boundary,
        }

    def build_company_database(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 20), 500)
        report_match_limit = self._bounded_limit(payload.get("report_match_limit", 100), 2000)
        structure_reports = self._truthy(payload.get("structure_reports", False))
        structure_report_limit = self._bounded_limit(payload.get("structure_report_limit", 20), 500)
        force_structure = self._truthy(payload.get("force_structure", False))
        issuers = self._company_database_target_issuers(payload, limit=limit)
        rows: list[dict[str, Any]] = []
        profiles_saved = 0
        profiles_planned = 0
        reports_matched = 0
        reports_bound = 0
        report_ids_for_structure: list[str] = []
        for issuer in issuers:
            securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
            existing_profile = issuer.issuer_id in self.store.company_profiles
            matched_reports = self._company_database_match_research_reports(
                issuer,
                securities,
                limit=report_match_limit,
            )
            bound_report_ids: list[str] = []
            for match in matched_reports:
                reports_matched += 1
                report = match["report"]
                if report.report_id not in report_ids_for_structure:
                    report_ids_for_structure.append(report.report_id)
                if not match["needs_binding"]:
                    continue
                bound_report_ids.append(report.report_id)
                if execute:
                    self._company_database_bind_research_report(
                        report,
                        issuer=issuer,
                        security=match.get("security"),
                        matched_token=str(match.get("matched_token", "")),
                        confidence=float(match.get("confidence", 0.7)),
                    )
                    reports_bound += 1
            profile = self._company_profile_from_existing_records(issuer.issuer_id, {})
            if execute:
                self.store.company_profiles[issuer.issuer_id] = profile
                profiles_saved += 1
            else:
                profiles_planned += 1
            rows.append(
                {
                    "issuer_id": issuer.issuer_id,
                    "display_name": profile.display_name,
                    "security_ids": [security.security_id for security in securities],
                    "tickers": [security.ticker for security in securities],
                    "profile_status": "saved" if execute else ("would_update" if existing_profile else "would_create"),
                    "profile_coverage": profile.data_quality.get("profile_coverage", 0.0),
                    "missing_fields": profile.data_quality.get("missing_fields", []),
                    "research_reports_matched": len(matched_reports),
                    "research_reports_bound": len(bound_report_ids) if execute else sum(1 for item in matched_reports if item["needs_binding"]),
                    "sample_report_ids": [match["report"].report_id for match in matched_reports[:5]],
                }
            )
        structure_payload: dict[str, Any] = {}
        if structure_reports and report_ids_for_structure:
            structure_payload = self.structure_research_reports(
                {
                    "report_ids": report_ids_for_structure[:structure_report_limit],
                    "execute": execute,
                    "dry_run": dry_run,
                    "force": force_structure,
                },
                actor=actor,
            )
        self._audit(
            actor,
            "build_company_database",
            "company_database",
            "batch",
            approval_state=f"execute={execute};profiles={profiles_saved};bound={reports_bound}",
        )
        if execute and issuers:
            self._mark_company_database_dirty()
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "target_count": len(issuers),
            "profiles_saved": profiles_saved,
            "profiles_planned": profiles_planned,
            "research_reports_matched": reports_matched,
            "research_reports_bound": reports_bound,
            "structure_reports": structure_reports,
            "structure_result": structure_payload,
            "companies": rows,
            "usage_boundary": "company_database_builder_uses_public_and_local_reference_data_only_no_live_trading",
        }

    def build_company_events(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 20), 500)
        event_limit = self._bounded_limit(payload.get("event_limit", 100), 5000)
        include_market_data = self._truthy(payload.get("include_market_data", True))
        include_research_coverage = self._truthy(payload.get("include_research_coverage", True))
        include_disclosures = self._truthy(payload.get("include_disclosures", True))
        include_structured_disclosures = self._truthy(payload.get("include_structured_disclosures", True))
        issuers = self._company_database_target_issuers(payload, limit=limit)
        planned_events: list[CompanyEvent] = []
        rows: list[dict[str, Any]] = []
        for issuer in issuers:
            securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
            company_events: list[CompanyEvent] = []
            if include_market_data:
                for point in self._company_database_latest_market_points(securities):
                    event_id = f"ce_market_{safe_source_part(point.security_id)}_{point.as_of_date.replace('-', '')}"
                    if event_id in self.store.company_events:
                        continue
                    security = self.store.securities.get(point.security_id)
                    title = f"Market data update: {(security.ticker if security else point.security_id)} {point.as_of_date}"
                    company_events.append(
                        CompanyEvent(
                            event_id=event_id,
                            issuer_id=issuer.issuer_id,
                            security_id=point.security_id,
                            event_type="market_data",
                            title=title,
                            summary=f"Public {point.data_type} market data close={point.close:g}, volume={point.volume:g}.",
                            occurred_at=parse_datetime(f"{point.as_of_date}T00:00:00+00:00"),
                            detected_at=utcnow(),
                            source_ids=[point.source_id],
                            evidence_ids=[],
                            impact_tags=["market_price"],
                            confidence=1.0,
                            fact_status="verified",
                            review_status="auto_generated",
                            metadata={"data_id": point.data_id, "close": point.close, "volume": point.volume, "data_type": point.data_type},
                        )
                    )
            if include_research_coverage:
                reports = [
                    report
                    for report in self.store.research_reports.values()
                    if report.issuer_id == issuer.issuer_id or report.security_id in {security.security_id for security in securities}
                ]
                reports.sort(key=lambda item: (str(item.year), str(item.month), item.report_id), reverse=True)
                for report in reports[:event_limit]:
                    event_id = f"ce_research_{safe_source_part(report.report_id)}"
                    if event_id in self.store.company_events:
                        continue
                    event_title = report.title or report.file_name or report.report_id
                    company_events.append(
                        CompanyEvent(
                            event_id=event_id,
                            issuer_id=issuer.issuer_id,
                            security_id=report.security_id,
                            event_type="research_coverage",
                            title=f"Research coverage: {event_title[:120]}",
                            summary=f"{report.broker or report.source_id} research report indexed for this company; opinion layer only, not a fact source.",
                            occurred_at=self._research_report_published_at(report),
                            detected_at=parse_datetime(report.indexed_at) if report.indexed_at else utcnow(),
                            source_ids=[report.source_id],
                            document_ids=[report.document_id] if report.document_id else [],
                            evidence_ids=self._research_report_citation_ids(report),
                            impact_tags=["research_attention", "opinion_signal"],
                            confidence=0.7,
                            fact_status="opinion_signal",
                            review_status="needs_review",
                            metadata={"report_id": report.report_id, "broker": report.broker, "rights_boundary": "opinion_only_not_fact_source"},
                        )
                    )
                    if len(company_events) >= event_limit:
                        break
            if include_disclosures and len(company_events) < event_limit:
                disclosure_rows = [
                    event
                    for event in self.store.disclosure_events.values()
                    if event.issuer_id == issuer.issuer_id or event.security_id in {security.security_id for security in securities}
                ]
                disclosure_rows.sort(key=lambda item: (str(to_plain(item.occurred_at)), item.event_id), reverse=True)
                for disclosure in disclosure_rows[:event_limit]:
                    if len(company_events) >= event_limit:
                        break
                    event_id = f"ce_disclosure_{safe_source_part(disclosure.event_id)}"
                    if event_id not in self.store.company_events:
                        title = disclosure.item_title or disclosure.item_code or disclosure.event_type or "Official disclosure"
                        company_events.append(
                            CompanyEvent(
                                event_id=event_id,
                                issuer_id=issuer.issuer_id,
                                security_id=disclosure.security_id,
                                event_type="official_disclosure",
                                title=f"Official disclosure: {title[:120]}",
                                summary=disclosure.summary or title,
                                occurred_at=parse_datetime(disclosure.occurred_at),
                                detected_at=parse_datetime(disclosure.created_at),
                                source_ids=[disclosure.source_id] if disclosure.source_id else [],
                                document_ids=[disclosure.document_id] if disclosure.document_id else [],
                                evidence_ids=list(disclosure.evidence_ids),
                                impact_tags=list(dict.fromkeys(["official_disclosure", disclosure.event_type, disclosure.severity])),
                                confidence=0.95,
                                fact_status="verified",
                                review_status="auto_generated",
                                metadata={
                                    "disclosure_event_id": disclosure.event_id,
                                    "document_id": disclosure.document_id,
                                    "item_code": disclosure.item_code,
                                    "severity": disclosure.severity,
                                    "source_layer": "disclosure_event",
                                },
                            )
                        )
                    if include_structured_disclosures and len(company_events) < event_limit:
                        detailed_events = self._company_events_from_disclosure_text(
                            issuer,
                            disclosure,
                            limit=max(0, event_limit - len(company_events)),
                        )
                        existing_ids = {event.event_id for event in company_events}
                        for detailed_event in detailed_events:
                            if detailed_event.event_id in self.store.company_events or detailed_event.event_id in existing_ids:
                                continue
                            company_events.append(detailed_event)
                            existing_ids.add(detailed_event.event_id)
                            if len(company_events) >= event_limit:
                                break
            if execute:
                for event in company_events[:event_limit]:
                    self.store.company_events[event.event_id] = event
            planned_events.extend(company_events[:event_limit])
            rows.append(
                {
                    "issuer_id": issuer.issuer_id,
                    "display_name": issuer.legal_name,
                    "planned_or_created_events": len(company_events[:event_limit]),
                    "market_event_count": sum(1 for event in company_events[:event_limit] if event.event_type == "market_data"),
                    "research_coverage_event_count": sum(1 for event in company_events[:event_limit] if event.event_type == "research_coverage"),
                    "official_disclosure_event_count": sum(1 for event in company_events[:event_limit] if event.event_type == "official_disclosure"),
                    "structured_disclosure_event_count": sum(1 for event in company_events[:event_limit] if event.metadata.get("source_layer") == "official_disclosure_text_classification"),
                    "sample_event_ids": [event.event_id for event in company_events[:5]],
                }
            )
        self._audit(
            actor,
            "build_company_events",
            "company_event",
            "batch",
            approval_state=f"execute={execute};events={len(planned_events)}",
        )
        if execute and planned_events:
            marker = getattr(self.store, "mark_dirty_for_resource", None)
            if callable(marker):
                marker("company_event")
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "target_count": len(issuers),
            "events_planned": 0 if execute else len(planned_events),
            "events_created": len(planned_events) if execute else 0,
            "include_market_data": include_market_data,
            "include_research_coverage": include_research_coverage,
            "include_disclosures": include_disclosures,
            "include_structured_disclosures": include_structured_disclosures,
            "companies": rows,
            "usage_boundary": "company_events_from_public_disclosures_market_data_and_research_attention_only_no_live_trading",
        }

    def _company_events_from_disclosure_text(
        self,
        issuer: Issuer,
        disclosure: DisclosureEvent,
        *,
        limit: int,
    ) -> list[CompanyEvent]:
        if limit <= 0:
            return []
        document = self.store.documents.get(disclosure.document_id) if disclosure.document_id else None
        text_parts = [disclosure.item_title, disclosure.summary]
        evidence_ids = list(disclosure.evidence_ids)
        for evidence_id in disclosure.evidence_ids:
            evidence = self.store.evidence.get(evidence_id)
            if evidence is not None:
                text_parts.append(evidence.span_text)
                text_parts.append(evidence.canonical_text)
        document_ids = [disclosure.document_id] if disclosure.document_id else []
        source_ids = [disclosure.source_id] if disclosure.source_id else []
        if document is not None:
            if document.document_type == "research_report" or "research" in document.source_id.lower():
                return []
            text_parts.append(document.title)
            text_parts.append(document.body[:6000])
            if document.source_id and document.source_id not in source_ids:
                source_ids.append(document.source_id)
        text = "\n".join(str(part) for part in text_parts if str(part).strip())
        events: list[CompanyEvent] = []
        for event_type, match in self._extract_company_event_mentions(text):
            event_id = f"ce_disclosure_detail_{safe_source_part(disclosure.event_id)}_{event_type}"
            if event_id in self.store.company_events:
                continue
            title = self._company_event_type_label(event_type)
            matched_terms = match["matched_terms"]
            summary = match["snippet"] or disclosure.summary or disclosure.item_title or title
            events.append(
                CompanyEvent(
                    event_id=event_id,
                    issuer_id=issuer.issuer_id,
                    security_id=disclosure.security_id,
                    event_type=event_type,
                    title=f"{title}: {(disclosure.item_title or disclosure.event_type or disclosure.event_id)[:100]}",
                    summary=summary[:600],
                    occurred_at=parse_datetime(disclosure.occurred_at),
                    detected_at=parse_datetime(disclosure.created_at),
                    source_ids=source_ids,
                    document_ids=document_ids,
                    evidence_ids=evidence_ids[:20],
                    impact_tags=list(dict.fromkeys(["official_disclosure", event_type, *match["impact_tags"]])),
                    confidence=float(match["confidence"]),
                    fact_status="verified",
                    review_status="needs_review",
                    metadata={
                        "disclosure_event_id": disclosure.event_id,
                        "document_id": disclosure.document_id,
                        "item_code": disclosure.item_code,
                        "severity": disclosure.severity,
                        "source_layer": "official_disclosure_text_classification",
                        "classification_status": "candidate_needs_review",
                        "classification_rule": match["rule_name"],
                        "matched_terms": matched_terms,
                        "rights_boundary": "official_disclosure_fact_with_classification_review",
                    },
                )
            )
            if len(events) >= limit:
                break
        return events

    def _extract_company_event_mentions(self, text: str) -> list[tuple[str, dict[str, Any]]]:
        patterns: list[tuple[str, str, str, list[str], float]] = [
            ("earnings_result", r"\b(revenue|sales|net income|earnings|gross margin|operating income)\b|营收|收入|净利润|毛利率|业绩|归母净利润", "financial_result_terms", ["financial_result"], 0.82),
            ("management_change", r"\b(resign(?:ed|ation)?|appoint(?:ed|ment)?|chief executive|chief financial officer|director|management change)\b|任命|辞任|辞职|董事长|总经理|高管|首席执行官|财务总监", "management_change_terms", ["governance"], 0.8),
            ("litigation_regulatory", r"\b(litigation|lawsuit|investigation|regulatory|penalty|fine|settlement|subpoena)\b|诉讼|仲裁|调查|处罚|罚款|监管|立案|和解", "litigation_regulatory_terms", ["risk", "regulatory"], 0.78),
            ("major_order_contract", r"\b(order|contract|purchase agreement|supply agreement|award(?:ed)?|backlog)\b|订单|合同|协议|中标|采购|供货|框架协议", "order_contract_terms", ["commercial"], 0.76),
            ("capacity_supply_demand", r"\b(capacity|production|plant|factory|fab|supply|demand|inventory|utilization)\b|产能|投产|扩产|产量|供需|库存|开工率|利用率", "capacity_supply_terms", ["supply_demand"], 0.74),
            ("policy_impact", r"\b(policy|tariff|subsidy|export control|sanction|regulation)\b|政策|关税|补贴|出口管制|制裁|监管规则", "policy_impact_terms", ["policy"], 0.72),
        ]
        mentions: list[tuple[str, dict[str, Any]]] = []
        seen: set[str] = set()
        for event_type, pattern, rule_name, impact_tags, confidence in patterns:
            matches = list(re.finditer(pattern, text, flags=re.IGNORECASE))
            if not matches or event_type in seen:
                continue
            seen.add(event_type)
            matched_terms = list(dict.fromkeys(match.group(0).strip() for match in matches[:5] if match.group(0).strip()))
            snippet = self._company_event_snippet(text, matches[0])
            mentions.append(
                (
                    event_type,
                    {
                        "rule_name": rule_name,
                        "matched_terms": matched_terms,
                        "snippet": snippet,
                        "impact_tags": impact_tags,
                        "confidence": confidence,
                    },
                )
            )
        return mentions

    def _company_event_snippet(self, text: str, match: re.Match[str]) -> str:
        start = max(0, match.start() - 140)
        end = min(len(text), match.end() + 220)
        snippet = re.sub(r"\s+", " ", text[start:end]).strip(" \t\r\n,.;:：，。；、")
        return snippet

    def _company_event_type_label(self, event_type: str) -> str:
        labels = {
            "earnings_result": "Earnings or financial result",
            "management_change": "Management change",
            "litigation_regulatory": "Litigation or regulatory matter",
            "major_order_contract": "Major order or contract",
            "capacity_supply_demand": "Capacity, supply or demand change",
            "policy_impact": "Policy or regulatory impact",
        }
        return labels.get(event_type, event_type.replace("_", " ").title())

    def build_company_relationships(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 20), 500)
        relationship_limit = self._bounded_limit(payload.get("relationship_limit", 100), 5000)
        include_listings = self._truthy(payload.get("include_listings", True))
        include_institution_coverage = self._truthy(payload.get("include_institution_coverage", True))
        include_disclosure_candidates = self._truthy(payload.get("include_disclosure_candidates", True))
        issuers = self._company_database_target_issuers(payload, limit=limit)
        planned_relationships: list[CompanyRelationship] = []
        rows: list[dict[str, Any]] = []
        for issuer in issuers:
            securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
            relationships: list[CompanyRelationship] = []
            if include_listings:
                for security in securities:
                    relationship_id = f"rel_listing_{self._company_database_id_part(issuer.issuer_id)}_{self._company_database_id_part(security.security_id)}"
                    if relationship_id in self.store.company_relationships:
                        continue
                    relationships.append(
                        CompanyRelationship(
                            relationship_id=relationship_id,
                            issuer_id=issuer.issuer_id,
                            security_id=security.security_id,
                            subject_type="company",
                            subject_id=issuer.issuer_id,
                            object_type="security",
                            object_id=security.security_id,
                            relationship_type="listed_security",
                            direction="directed",
                            weight=1.0,
                            source_ids=list(issuer.data_sources),
                            confidence=1.0,
                            relationship_status="active",
                            review_status="auto_generated",
                            metadata={"ticker": security.ticker, "exchange": security.exchange, "market": security.market},
                        )
                    )
            if include_institution_coverage:
                reports = [
                    report
                    for report in self.store.research_reports.values()
                    if report.issuer_id == issuer.issuer_id or report.security_id in {security.security_id for security in securities}
                ]
                grouped_reports: dict[str, list[ResearchReportAsset]] = {}
                for report in reports:
                    institution_name = report.broker or report.source_id or "local_research_unknown"
                    grouped_reports.setdefault(institution_name, []).append(report)
                for institution_name, institution_reports in sorted(grouped_reports.items()):
                    institution_part = self._company_database_id_part(institution_name)
                    object_id = f"institution_{institution_part}"
                    relationship_id = f"rel_coverage_{self._company_database_id_part(issuer.issuer_id)}_{institution_part}"
                    if relationship_id in self.store.company_relationships:
                        continue
                    source_ids = sorted({report.source_id for report in institution_reports if report.source_id})
                    document_ids = [report.document_id for report in institution_reports if report.document_id][:20]
                    evidence_ids: list[str] = []
                    for report in institution_reports[:5]:
                        evidence_ids.extend(self._research_report_citation_ids(report, limit=2))
                    relationships.append(
                        CompanyRelationship(
                            relationship_id=relationship_id,
                            issuer_id=issuer.issuer_id,
                            security_id=institution_reports[0].security_id if institution_reports else "",
                            subject_type="company",
                            subject_id=issuer.issuer_id,
                            object_type="institution",
                            object_id=object_id,
                            relationship_type="institution_coverage",
                            direction="directed",
                            weight=float(len(institution_reports)),
                            source_ids=source_ids,
                            document_ids=document_ids,
                            evidence_ids=list(dict.fromkeys(evidence_ids)),
                            confidence=0.75,
                            relationship_status="active",
                            review_status="needs_review",
                            metadata={
                                "institution_name": institution_name,
                                "report_count": len(institution_reports),
                                "sample_report_ids": [report.report_id for report in institution_reports[:5]],
                                "rights_boundary": "opinion_coverage_relationship_not_company_fact",
                            },
                        )
                    )
                    if len(relationships) >= relationship_limit:
                        break
            if include_disclosure_candidates and len(relationships) < relationship_limit:
                relationships.extend(
                    self._company_relationship_candidates_from_disclosures(
                        issuer,
                        securities,
                        limit=max(0, relationship_limit - len(relationships)),
                    )
                )
            relationships = relationships[:relationship_limit]
            if execute:
                for relationship in relationships:
                    self.store.company_relationships[relationship.relationship_id] = relationship
            planned_relationships.extend(relationships)
            rows.append(
                {
                    "issuer_id": issuer.issuer_id,
                    "display_name": issuer.legal_name,
                    "planned_or_created_relationships": len(relationships),
                    "listing_relationship_count": sum(1 for relationship in relationships if relationship.relationship_type == "listed_security"),
                    "institution_coverage_relationship_count": sum(1 for relationship in relationships if relationship.relationship_type == "institution_coverage"),
                    "disclosure_candidate_relationship_count": sum(1 for relationship in relationships if str(relationship.relationship_type).endswith("_candidate")),
                    "sample_relationship_ids": [relationship.relationship_id for relationship in relationships[:5]],
                }
            )
        self._audit(
            actor,
            "build_company_relationships",
            "company_relationship",
            "batch",
            approval_state=f"execute={execute};relationships={len(planned_relationships)}",
        )
        if execute and planned_relationships:
            marker = getattr(self.store, "mark_dirty_for_resource", None)
            if callable(marker):
                marker("company_relationship")
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "target_count": len(issuers),
            "relationships_planned": 0 if execute else len(planned_relationships),
            "relationships_created": len(planned_relationships) if execute else 0,
            "include_listings": include_listings,
            "include_institution_coverage": include_institution_coverage,
            "include_disclosure_candidates": include_disclosure_candidates,
            "companies": rows,
            "usage_boundary": "company_relationships_from_listings_research_coverage_and_public_disclosure_candidates_only_no_live_trading",
        }

    def _company_relationship_candidates_from_disclosures(
        self,
        issuer: Issuer,
        securities: list[Security],
        *,
        limit: int,
    ) -> list[CompanyRelationship]:
        if limit <= 0:
            return []
        security_ids = {security.security_id for security in securities}
        disclosure_rows = [
            event
            for event in self.store.disclosure_events.values()
            if event.issuer_id == issuer.issuer_id or event.security_id in security_ids
        ]
        disclosure_rows.sort(key=lambda item: (str(to_plain(item.occurred_at)), item.event_id), reverse=True)
        candidates: list[CompanyRelationship] = []
        seen_keys: set[tuple[str, str]] = set()
        for disclosure in disclosure_rows:
            document = self.store.documents.get(disclosure.document_id) if disclosure.document_id else None
            text_parts = [disclosure.summary, disclosure.item_title]
            evidence_ids = list(disclosure.evidence_ids)
            for evidence_id in disclosure.evidence_ids:
                evidence = self.store.evidence.get(evidence_id)
                if evidence is not None:
                    text_parts.append(evidence.span_text)
                    text_parts.append(evidence.canonical_text)
            if document is not None:
                if document.document_type == "research_report" or "research" in document.source_id.lower():
                    continue
                text_parts.append(document.title)
                text_parts.append(document.body[:4000])
            text = "\n".join(str(part) for part in text_parts if str(part).strip())
            for relationship_type, entity_name, rule_name in self._extract_relationship_mentions(text):
                key = (relationship_type, entity_name.lower())
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                entity_part = self._company_database_id_part(entity_name)
                relationship_id = f"rel_disclosure_{self._company_database_id_part(issuer.issuer_id)}_{relationship_type}_{entity_part}"
                if relationship_id in self.store.company_relationships:
                    continue
                source_ids = [disclosure.source_id] if disclosure.source_id else []
                if document is not None and document.source_id and document.source_id not in source_ids:
                    source_ids.append(document.source_id)
                candidates.append(
                    CompanyRelationship(
                        relationship_id=relationship_id,
                        issuer_id=issuer.issuer_id,
                        security_id=disclosure.security_id,
                        subject_type="company",
                        subject_id=issuer.issuer_id,
                        object_type="company",
                        object_id=f"external_company_{entity_part}",
                        relationship_type=relationship_type,
                        direction="directed",
                        weight=0.5,
                        source_ids=source_ids,
                        document_ids=[disclosure.document_id] if disclosure.document_id else [],
                        evidence_ids=evidence_ids[:10],
                        confidence=0.55,
                        relationship_status="unknown",
                        review_status="needs_review",
                        metadata={
                            "entity_name": entity_name,
                            "disclosure_event_id": disclosure.event_id,
                            "source_layer": "official_disclosure_candidate",
                            "candidate_status": "candidate",
                            "extraction_rule": rule_name,
                            "rights_boundary": "public_disclosure_candidate_needs_review",
                        },
                    )
                )
                if len(candidates) >= limit:
                    return candidates
        return candidates

    def _extract_relationship_mentions(self, text: str) -> list[tuple[str, str, str]]:
        patterns: list[tuple[str, str, str]] = [
            ("customer_candidate", r"\bcustomer\s+(?:named\s+|including\s+|is\s+)?([A-Z][A-Za-z0-9&.,'()\- ]{2,80}?)(?:,|;|\.|\sand\s|$)", "en_customer"),
            ("supplier_candidate", r"\bsupplier\s+(?:named\s+|including\s+|is\s+)?([A-Z][A-Za-z0-9&.,'()\- ]{2,80}?)(?:,|;|\.|\sand\s|$)", "en_supplier"),
            ("partner_candidate", r"\bpartner(?:ship)?(?:\s+with)?\s+([A-Z][A-Za-z0-9&.,'()\- ]{2,80}?)(?:,|;|\.|\sand\s|$)", "en_partner"),
            ("subsidiary_candidate", r"\bsubsidiary\s+([A-Z][A-Za-z0-9&.,'()\- ]{2,80}?)(?:,|;|\.|\sand\s|$)", "en_subsidiary"),
            ("customer_candidate", r"(?:客户|主要客户)[:：\s]*([\u4e00-\u9fffA-Za-z0-9（）()&·\-]{2,40})", "zh_customer"),
            ("supplier_candidate", r"(?:供应商|主要供应商)[:：\s]*([\u4e00-\u9fffA-Za-z0-9（）()&·\-]{2,40})", "zh_supplier"),
            ("partner_candidate", r"(?:合作方|合作伙伴)[:：\s]*([\u4e00-\u9fffA-Za-z0-9（）()&·\-]{2,40})", "zh_partner"),
            ("subsidiary_candidate", r"(?:子公司)[:：\s]*([\u4e00-\u9fffA-Za-z0-9（）()&·\-]{2,40})", "zh_subsidiary"),
        ]
        mentions: list[tuple[str, str, str]] = []
        for relationship_type, pattern, rule_name in patterns:
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                entity_name = self._normalize_relationship_entity_name(match.group(1))
                if not entity_name:
                    continue
                mentions.append((relationship_type, entity_name, rule_name))
        return mentions

    def _normalize_relationship_entity_name(self, value: str) -> str:
        cleaned = re.sub(r"\s+", " ", str(value)).strip(" \t\r\n,.;:：，。；、()（）")
        cleaned = re.sub(r"\b(the|a|an|our|its|their|major|key)\b\s+", "", cleaned, flags=re.IGNORECASE).strip()
        if len(cleaned) < 2 or len(cleaned) > 80:
            return ""
        blocked = {"customer", "supplier", "partner", "subsidiary", "company", "group", "客户", "供应商", "合作伙伴", "子公司"}
        if cleaned.lower() in blocked:
            return ""
        return cleaned

    def build_company_workflow(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 20), 500)
        link_limit = self._bounded_limit(payload.get("link_limit", 5), 50)
        include_observations = self._truthy(payload.get("include_observations", True))
        include_conclusions = self._truthy(payload.get("include_conclusions", True))
        include_feedback = self._truthy(payload.get("include_feedback", True))
        refresh_existing = self._truthy(payload.get("refresh_existing", True))
        issuers = self._company_database_target_issuers(payload, limit=limit)
        rows: list[dict[str, Any]] = []
        observations_created = 0
        observations_planned = 0
        observations_updated = 0
        conclusions_created = 0
        conclusions_planned = 0
        conclusions_updated = 0
        feedback_created = 0
        feedback_planned = 0
        feedback_updated = 0
        for issuer in issuers:
            issuer_part = self._company_database_id_part(issuer.issuer_id)
            securities = [item for item in self.store.securities.values() if item.issuer_id == issuer.issuer_id]
            security_ids = {security.security_id for security in securities}
            primary_security = securities[0] if securities else None
            market_points = self._company_database_latest_market_points(securities)
            latest_market = market_points[0] if market_points else None
            events = [
                item
                for item in self.store.company_events.values()
                if item.issuer_id == issuer.issuer_id or item.security_id in security_ids
            ]
            events.sort(key=lambda item: (str(to_plain(item.occurred_at)), item.event_id), reverse=True)
            relationships = [
                item
                for item in self.store.company_relationships.values()
                if item.issuer_id == issuer.issuer_id
                or item.security_id in security_ids
                or item.subject_id == issuer.issuer_id
                or item.object_id == issuer.issuer_id
            ]
            relationships.sort(key=lambda item: (str(item.valid_from), item.relationship_id), reverse=True)
            structured_report_ids = {
                report.research_report_id
                for report in self.store.structured_research_reports.values()
                if report.issuer_id == issuer.issuer_id or report.security_id in security_ids
            }
            viewpoints = [
                item
                for item in self.store.report_viewpoints.values()
                if item.issuer_id == issuer.issuer_id
                or item.security_id in security_ids
                or item.research_report_id in structured_report_ids
            ]
            viewpoints.sort(key=lambda item: item.created_at, reverse=True)
            viewpoint_ids = [item.viewpoint_id for item in viewpoints[:link_limit]]
            event_ids = [item.event_id for item in events[:link_limit]]
            relationship_ids = [item.relationship_id for item in relationships[:link_limit]]
            evidence_ids: list[str] = []
            for event in events[:link_limit]:
                evidence_ids.extend(event.evidence_ids[:2])
            for viewpoint in viewpoints[:link_limit]:
                evidence_ids.extend(viewpoint.evidence_ids[:2])
            evidence_ids = list(dict.fromkeys(evidence_ids))[: link_limit * 2]
            observation_id = f"obs_company_{issuer_part}_baseline"
            conclusion_id = f"ac_company_{issuer_part}_baseline"
            feedback_id = f"sf_company_{issuer_part}_baseline_watch"
            evidence_gap: list[str] = []
            if not events:
                evidence_gap.append("company_events")
            if not relationships:
                evidence_gap.append("company_relationships")
            if not viewpoints:
                evidence_gap.append("structured_report_viewpoints")
            observation_payload = {
                "observation_id": observation_id,
                "issuer_id": issuer.issuer_id,
                "security_id": primary_security.security_id if primary_security else "",
                "title": f"{issuer.legal_name} 公司情报跟踪任务",
                "question": "研报关注点、公开事件、关系变化和后续行情/财务表现是否互相验证？",
                "observation_type": "company_intelligence_follow_up",
                "trigger_conditions": [
                    {"type": "new_verified_event", "description": "出现公告、财报、监管披露或行情显著变化时复核"},
                    {"type": "research_viewpoint_realization", "description": "研报评级、目标价、催化剂或风险有兑现迹象时复核"},
                ],
                "related_event_ids": event_ids,
                "related_relationship_ids": relationship_ids,
                "related_viewpoint_ids": viewpoint_ids,
                "evidence_gap": evidence_gap,
                "priority": "high" if viewpoints or events else "medium",
                "status": "open",
                "owner": actor,
                "due_at": utcnow() + timedelta(days=30),
            }
            facts = [
                f"本地公司数据库已匹配主体 {issuer.issuer_id}。",
                f"已关联证券 {len(securities)} 个、公司事件 {len(events)} 条、公司关系 {len(relationships)} 条。",
            ]
            if latest_market is not None:
                facts.append(f"最新本地行情 {latest_market.as_of_date} close={latest_market.close:g}。")
            inferences = [
                f"已结构化研报观点 {len(viewpoints)} 条，可作为市场关注度和观点样本跟踪。",
                "研报观点只进入观点层；事实判断需要回链公告、财报、监管披露或公开行情。",
            ]
            conclusion_payload = {
                "analysis_conclusion_id": conclusion_id,
                "issuer_id": issuer.issuer_id,
                "security_id": primary_security.security_id if primary_security else "",
                "title": f"{issuer.legal_name} 公司情报基线结论",
                "conclusion": "当前仅形成公司情报基线：继续观察公开事实、事件关系和研报观点兑现情况，不构成买卖建议。",
                "conclusion_type": "company_intelligence_baseline",
                "horizon": "30-90d",
                "hypothesis": "公司后续判断应由公开事实、事件时间线、关系变化、研报观点兑现和模拟反馈共同验证。",
                "facts": facts,
                "inferences": inferences,
                "forecasts": [f"待复核研报观点/预测 {viewpoint_id}" for viewpoint_id in viewpoint_ids],
                "subjective_judgments": ["暂不形成交易方向；先进入观察池和纸面反馈验证。"],
                "supporting_evidence_ids": evidence_ids,
                "related_event_ids": event_ids,
                "related_relationship_ids": relationship_ids,
                "related_viewpoint_ids": viewpoint_ids,
                "related_observation_ids": [observation_id],
                "confidence": 0.55 if (events and relationships and viewpoints) else 0.4,
                "review_plan": {
                    "next_review_days": 30,
                    "checks": ["official_disclosure_update", "market_price_update", "research_viewpoint_realization", "relationship_change"],
                    "paper_only": True,
                },
                "status": "draft",
                "created_by": actor,
            }
            feedback_payload = {
                "simulation_feedback_id": feedback_id,
                "analysis_conclusion_id": conclusion_id,
                "observation_id": observation_id,
                "issuer_id": issuer.issuer_id,
                "security_id": primary_security.security_id if primary_security else "",
                "feedback_type": "watch_only",
                "paper_only": True,
                "live_execution_allowed": False,
                "broker_connected": False,
                "simulated_action": "watch",
                "simulated_size": {"weight": 0.0, "unit": "watchlist", "rationale": "验证研究结论，不做真实交易"},
                "entry_price": latest_market.close if latest_market is not None else 0.0,
                "benchmark_security_id": primary_security.security_id if primary_security else "",
                "performance": {"status": "pending", "baseline_price": latest_market.close if latest_market is not None else 0.0},
                "validation": {
                    "goal": "validate_company_intelligence_baseline",
                    "metrics": ["event_realization", "viewpoint_realization", "relative_market_performance"],
                    "source_boundary": "research_only_paper_feedback",
                },
                "review_result": {"status": "pending", "next_review_days": 30},
            }
            row = {
                "issuer_id": issuer.issuer_id,
                "display_name": issuer.legal_name,
                "observation_id": observation_id,
                "analysis_conclusion_id": conclusion_id,
                "simulation_feedback_id": feedback_id,
                "related_event_count": len(event_ids),
                "related_relationship_count": len(relationship_ids),
                "related_viewpoint_count": len(viewpoint_ids),
                "evidence_gap": evidence_gap,
            }
            existing_observation = self.store.observation_items.get(observation_id)
            if include_observations and existing_observation is None:
                if execute:
                    self.register_observation_item(observation_payload, actor=actor)
                    observations_created += 1
                else:
                    observations_planned += 1
            elif include_observations and execute and refresh_existing and existing_observation is not None:
                existing_observation.related_event_ids = event_ids
                existing_observation.related_relationship_ids = relationship_ids
                existing_observation.related_viewpoint_ids = viewpoint_ids
                existing_observation.evidence_gap = evidence_gap
                existing_observation.trigger_conditions = list(observation_payload["trigger_conditions"])
                observations_updated += 1
            existing_conclusion = self.store.analysis_conclusions.get(conclusion_id)
            if include_conclusions and existing_conclusion is None:
                if execute:
                    self.create_analysis_conclusion(conclusion_payload, actor=actor)
                    conclusions_created += 1
                else:
                    conclusions_planned += 1
            elif include_conclusions and execute and refresh_existing and existing_conclusion is not None:
                existing_conclusion.facts = list(conclusion_payload["facts"])
                existing_conclusion.inferences = list(conclusion_payload["inferences"])
                existing_conclusion.forecasts = list(conclusion_payload["forecasts"])
                existing_conclusion.supporting_evidence_ids = evidence_ids
                existing_conclusion.related_event_ids = event_ids
                existing_conclusion.related_relationship_ids = relationship_ids
                existing_conclusion.related_viewpoint_ids = viewpoint_ids
                existing_conclusion.related_observation_ids = [observation_id]
                existing_conclusion.confidence = float(conclusion_payload["confidence"])
                existing_conclusion.review_plan = dict(conclusion_payload["review_plan"])
                existing_conclusion.updated_at = utcnow()
                conclusions_updated += 1
            existing_feedback = self.store.simulation_feedback.get(feedback_id)
            if include_feedback and existing_feedback is None:
                if execute:
                    if conclusion_id not in self.store.analysis_conclusions:
                        self.create_analysis_conclusion(conclusion_payload, actor=actor)
                        conclusions_created += 1
                    if observation_id not in self.store.observation_items:
                        self.register_observation_item(observation_payload, actor=actor)
                        observations_created += 1
                    self.record_simulation_feedback(feedback_payload, actor=actor)
                    feedback_created += 1
                else:
                    feedback_planned += 1
            elif include_feedback and execute and refresh_existing and existing_feedback is not None:
                existing_feedback.entry_price = float(feedback_payload["entry_price"])
                existing_feedback.benchmark_security_id = str(feedback_payload["benchmark_security_id"])
                existing_feedback.performance = dict(feedback_payload["performance"])
                existing_feedback.validation = dict(feedback_payload["validation"])
                existing_feedback.review_result = dict(feedback_payload["review_result"])
                existing_feedback.updated_at = utcnow()
                feedback_updated += 1
            row["status"] = "executed" if execute else "planned"
            row["observation_exists"] = observation_id in self.store.observation_items
            row["conclusion_exists"] = conclusion_id in self.store.analysis_conclusions
            row["feedback_exists"] = feedback_id in self.store.simulation_feedback
            rows.append(row)
        self._audit(
            actor,
            "build_company_workflow",
            "company_workflow",
            "batch",
            approval_state=f"execute={execute};observations={observations_created};conclusions={conclusions_created};feedback={feedback_created}",
        )
        if execute and (
            observations_created
            or observations_updated
            or conclusions_created
            or conclusions_updated
            or feedback_created
            or feedback_updated
        ):
            marker = getattr(self.store, "mark_dirty_for_resource", None)
            if callable(marker):
                marker("observation_item")
                marker("analysis_conclusion")
                marker("simulation_feedback")
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "target_count": len(issuers),
            "observations_planned": observations_planned,
            "observations_created": observations_created,
            "observations_updated": observations_updated,
            "conclusions_planned": conclusions_planned,
            "conclusions_created": conclusions_created,
            "conclusions_updated": conclusions_updated,
            "feedback_planned": feedback_planned,
            "feedback_created": feedback_created,
            "feedback_updated": feedback_updated,
            "include_observations": include_observations,
            "include_conclusions": include_conclusions,
            "include_feedback": include_feedback,
            "refresh_existing": refresh_existing,
            "companies": rows,
            "usage_boundary": "analysis_workflow_builder_creates_observation_conclusion_and_paper_feedback_only_no_live_trading",
        }

    def _company_database_latest_market_points(self, securities: list[Security]) -> list[MarketDataPoint]:
        if self._market_data_direct_query_enabled():
            rows: list[MarketDataPoint] = []
            for security in securities:
                rows.extend(self._query_market_data_points(security_id=security.security_id, limit=1, descending=True))
            return rows
        latest: list[MarketDataPoint] = []
        for security in securities:
            rows = [item for item in self.store.market_data.values() if item.security_id == security.security_id]
            rows.sort(key=lambda item: (str(item.as_of_date), item.data_id), reverse=True)
            if rows:
                latest.append(rows[0])
        return latest

    def _company_database_id_part(self, value: str) -> str:
        safe = safe_source_part(str(value))
        if safe != "unknown" or not str(value).strip():
            return safe
        return hashlib.sha256(str(value).encode("utf-8")).hexdigest()[:12]

    def _company_database_target_issuers(self, payload: Mapping[str, Any], *, limit: int) -> list[Issuer]:
        issuer_ids: list[str] = []
        raw_issuer_ids = payload.get("issuer_ids", [])
        if isinstance(raw_issuer_ids, str):
            raw_issuer_ids = [raw_issuer_ids]
        else:
            raw_issuer_ids = list(raw_issuer_ids or [])
        issuer_ids.extend(str(item).strip() for item in raw_issuer_ids if str(item).strip())
        raw_symbols = payload.get("symbols", [])
        if isinstance(raw_symbols, str):
            raw_symbols = [raw_symbols]
        else:
            raw_symbols = list(raw_symbols or [])
        for field_name in ["symbol", "ticker", "q"]:
            value = str(payload.get(field_name, "")).strip()
            if value:
                raw_symbols.append(value)
        for symbol in raw_symbols:
            tokens = self._company_intelligence_symbol_tokens(str(symbol))
            for security in self.store.securities.values():
                if self._company_intelligence_security_matches(security, tokens) and security.issuer_id:
                    issuer_ids.append(security.issuer_id)
            for mapping in self.store.entity_mappings.values():
                if self._company_intelligence_mapping_matches(mapping, tokens) and mapping.issuer_id:
                    issuer_ids.append(mapping.issuer_id)
            for issuer in self.store.issuers.values():
                if self._company_intelligence_issuer_matches(issuer, tokens):
                    issuer_ids.append(issuer.issuer_id)
        if not issuer_ids:
            issuer_ids = [
                issuer.issuer_id
                for issuer in sorted(self.store.issuers.values(), key=lambda item: item.issuer_id)
                if any(security.issuer_id == issuer.issuer_id for security in self.store.securities.values())
            ]
        seen: set[str] = set()
        issuers: list[Issuer] = []
        for issuer_id in issuer_ids:
            if issuer_id in seen:
                continue
            seen.add(issuer_id)
            issuer = self.store.issuers.get(issuer_id)
            if issuer is not None:
                issuers.append(issuer)
            if len(issuers) >= limit:
                break
        return issuers

    def _company_database_report_tokens(self, issuer: Issuer, securities: list[Security]) -> list[tuple[str, Security | None, float]]:
        stopwords = {"A", "H", "U", "US", "USA", "THE", "INC", "LTD", "CO", "CORP", "GROUP", "HOLDINGS", "ETF", "AI"}
        tokens: list[tuple[str, Security | None, float]] = []
        for security in securities:
            ticker = str(security.ticker).strip().upper()
            if len(ticker) >= 2 and ticker not in stopwords:
                tokens.append((ticker, security, 0.86))
        for name in [issuer.legal_name, *issuer.aliases]:
            for part in re.split(r"[\s,，/()（）._-]+", str(name)):
                normalized = part.strip().upper()
                if len(normalized) >= 4 and normalized not in stopwords:
                    tokens.append((normalized, securities[0] if len(securities) == 1 else None, 0.72))
        deduped: list[tuple[str, Security | None, float]] = []
        seen: set[str] = set()
        for token, security, confidence in tokens:
            if token in seen:
                continue
            seen.add(token)
            deduped.append((token, security, confidence))
        return deduped

    def _company_database_match_research_reports(self, issuer: Issuer, securities: list[Security], *, limit: int) -> list[dict[str, Any]]:
        security_ids = {security.security_id for security in securities}
        tokens = self._company_database_report_tokens(issuer, securities)
        rows: list[dict[str, Any]] = []
        for report in self.store.research_reports.values():
            if report.issuer_id == issuer.issuer_id or report.security_id in security_ids:
                rows.append({"report": report, "security": self.store.securities.get(report.security_id), "matched_token": "existing_binding", "confidence": 1.0, "needs_binding": False})
            elif report.issuer_id or report.security_id:
                continue
            else:
                haystack = f"{report.title} {report.file_name} {report.file_path}".upper()
                for token, security, confidence in tokens:
                    if re.search(rf"(?<![A-Z0-9]){re.escape(token)}(?![A-Z0-9])", haystack):
                        rows.append({"report": report, "security": security, "matched_token": token, "confidence": confidence, "needs_binding": True})
                        break
            if len(rows) >= limit:
                break
        rows.sort(key=lambda item: (item["needs_binding"], str(item["report"].year), str(item["report"].month), item["report"].report_id), reverse=True)
        return rows[:limit]

    def _company_database_bind_research_report(
        self,
        report: ResearchReportAsset,
        *,
        issuer: Issuer,
        security: Security | None,
        matched_token: str,
        confidence: float,
    ) -> None:
        report.issuer_id = issuer.issuer_id
        if security is not None:
            report.security_id = security.security_id
        binding = {
            "issuer_id": issuer.issuer_id,
            "security_id": security.security_id if security is not None else "",
            "matched_token": matched_token,
            "matched_by": "company_database_builder",
            "confidence": round(confidence, 4),
            "review_status": "needs_review",
        }
        report.asset_binding = binding
        if not any(item.get("matched_by") == "company_database_builder" and item.get("issuer_id") == issuer.issuer_id for item in report.asset_matches):
            report.asset_matches.append(dict(binding))

    def _mark_company_database_dirty(self) -> None:
        marker = getattr(self.store, "mark_dirty_for_resource", None)
        if not callable(marker):
            return
        for resource_type in [
            "company_profile",
            "company_event",
            "company_relationship",
            "research_report",
            "structured_research_report",
            "report_viewpoint",
            "report_forecast",
            "analyst_profile",
            "observation_item",
            "analysis_conclusion",
            "simulation_feedback",
        ]:
            marker(resource_type)

    def _company_profile_from_existing_records(self, issuer_id: str, overlay: Mapping[str, Any]) -> CompanyProfile:
        issuer = self.store.issuers[issuer_id]
        securities = [item for item in self.store.securities.values() if item.issuer_id == issuer_id]
        security_ids = [item.security_id for item in securities]
        if self._market_data_direct_query_enabled() and security_ids:
            market_rows_by_id: dict[str, MarketDataPoint] = {}
            for security_id in security_ids:
                for point in self._query_market_data_points(security_id=security_id, limit=5, descending=True):
                    market_rows_by_id[point.data_id] = point
            market_rows = list(market_rows_by_id.values())
        else:
            market_rows = [item for item in self.store.market_data.values() if item.security_id in set(security_ids)]
        market_rows.sort(key=lambda item: (str(item.as_of_date), item.data_id), reverse=True)
        reports = [item for item in self.store.research_reports.values() if item.issuer_id == issuer_id or item.security_id in set(security_ids)]
        viewpoints = [item for item in self.store.report_viewpoints.values() if item.issuer_id == issuer_id or item.security_id in set(security_ids)]
        events = [item for item in self.store.company_events.values() if item.issuer_id == issuer_id]
        relationships = [item for item in self.store.company_relationships.values() if item.issuer_id == issuer_id or item.subject_id == issuer_id or item.object_id == issuer_id]
        missing = []
        if not securities:
            missing.append("security_ids")
        if not market_rows:
            missing.append("latest_market_snapshot")
        if not reports and not viewpoints:
            missing.append("research_coverage")
        if not events:
            missing.append("company_events")
        if not relationships:
            missing.append("company_relationships")
        profile = CompanyProfile(
            issuer_id=issuer_id,
            display_name=str(overlay.get("display_name") or issuer.legal_name),
            legal_name=str(overlay.get("legal_name") or issuer.legal_name),
            security_ids=[str(item) for item in overlay.get("security_ids", security_ids)],
            markets=[str(item) for item in overlay.get("markets", issuer.market)],
            sector=str(overlay.get("sector", issuer.sector)),
            industry=str(overlay.get("industry", issuer.industry)),
            business_summary=str(overlay.get("business_summary", issuer.company_details.get("business_summary", ""))),
            products=[str(item) for item in overlay.get("products", [])],
            identifiers=dict(overlay.get("identifiers", {"lei": issuer.lei, "cik": issuer.cik, "tickers": [item.ticker for item in securities]})),
            latest_market_snapshot=dict(overlay.get("latest_market_snapshot", to_plain(market_rows[0]) if market_rows else {})),
            latest_financial_snapshot=dict(overlay.get("latest_financial_snapshot", issuer.fundamentals)),
            coverage_summary=dict(
                overlay.get(
                    "coverage_summary",
                    {
                        "research_report_count": len(reports),
                        "report_viewpoint_count": len(viewpoints),
                        "analyst_count": len({analyst_id for report in self.store.structured_research_reports.values() if report.issuer_id == issuer_id for analyst_id in report.analyst_ids}),
                    },
                )
            ),
            event_summary=dict(overlay.get("event_summary", {"company_event_count": len(events), "relationship_count": len(relationships)})),
            data_quality=dict(
                overlay.get(
                    "data_quality",
                    {
                        "profile_coverage": round((5 - min(len(missing), 5)) / 5, 4),
                        "missing_fields": missing,
                        "event_backlink_rate": self._backlink_rate(events),
                        "relationship_backlink_rate": self._backlink_rate(relationships),
                    },
                )
            ),
            source_ids=[str(item) for item in overlay.get("source_ids", issuer.data_sources)],
            evidence_ids=[str(item) for item in overlay.get("evidence_ids", [])],
            updated_at=utcnow(),
        )
        return profile

    def _backlink_rate(self, rows: list[Any]) -> float:
        if not rows:
            return 0.0
        linked = sum(1 for item in rows if getattr(item, "evidence_ids", []) or getattr(item, "source_ids", []) or getattr(item, "document_ids", []))
        return round(linked / len(rows), 4)

    def register_company_event(self, payload: Mapping[str, Any], *, actor: str = "system") -> CompanyEvent:
        issuer_id = str(payload["issuer_id"])
        if issuer_id not in self.store.issuers:
            raise NotFoundError(f"issuer {issuer_id} not found")
        event = CompanyEvent(
            event_id=str(payload.get("event_id", new_id("ce"))),
            issuer_id=issuer_id,
            security_id=str(payload.get("security_id", "")),
            event_type=str(payload.get("event_type", "other")),
            title=str(payload.get("title", payload.get("summary", ""))),
            summary=str(payload.get("summary", "")),
            occurred_at=parse_datetime(payload.get("occurred_at")) if payload.get("occurred_at") else utcnow(),
            detected_at=parse_datetime(payload.get("detected_at")) if payload.get("detected_at") else utcnow(),
            source_ids=[str(item) for item in payload.get("source_ids", [])],
            document_ids=[str(item) for item in payload.get("document_ids", [])],
            evidence_ids=[str(item) for item in payload.get("evidence_ids", [])],
            impact_tags=[str(item) for item in payload.get("impact_tags", [])],
            affected_entities=[dict(item) for item in payload.get("affected_entities", [])],
            confidence=float(payload.get("confidence", 0.5)),
            fact_status=str(payload.get("fact_status", "unknown")),
            review_status=str(payload.get("review_status", "unreviewed")),
            metadata=dict(payload.get("metadata", {})),
        )
        if event.event_id in self.store.company_events:
            raise ConflictError(f"company event {event.event_id} already exists")
        self.store.company_events[event.event_id] = event
        self._audit(actor, "register_company_event", "company_event", event.event_id, approval_state=event.fact_status)
        return event

    def company_events_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        rows = list(self.store.company_events.values())
        for field_name in ["issuer_id", "security_id", "event_type", "fact_status", "review_status"]:
            value = str(filters.get(field_name, "")).strip()
            if value:
                rows = [item for item in rows if str(getattr(item, field_name, "")) == value]
        rows.sort(key=lambda item: item.occurred_at, reverse=True)
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        return {"count": len(rows), "events": [to_plain(item) for item in rows[:limit]]}

    def register_company_relationship(self, payload: Mapping[str, Any], *, actor: str = "system") -> CompanyRelationship:
        relationship = CompanyRelationship(
            relationship_id=str(payload.get("relationship_id", new_id("rel"))),
            issuer_id=str(payload.get("issuer_id", payload.get("subject_id", ""))),
            security_id=str(payload.get("security_id", "")),
            subject_type=str(payload["subject_type"]),
            subject_id=str(payload["subject_id"]),
            object_type=str(payload["object_type"]),
            object_id=str(payload["object_id"]),
            relationship_type=str(payload["relationship_type"]),
            direction=str(payload.get("direction", "directed")),
            weight=float(payload.get("weight", 1.0)),
            valid_from=parse_datetime(payload.get("valid_from")) if payload.get("valid_from") else None,
            valid_to=parse_datetime(payload.get("valid_to")) if payload.get("valid_to") else None,
            source_ids=[str(item) for item in payload.get("source_ids", [])],
            document_ids=[str(item) for item in payload.get("document_ids", [])],
            evidence_ids=[str(item) for item in payload.get("evidence_ids", [])],
            confidence=float(payload.get("confidence", 0.5)),
            relationship_status=str(payload.get("relationship_status", "active")),
            review_status=str(payload.get("review_status", "unreviewed")),
            metadata=dict(payload.get("metadata", {})),
        )
        if relationship.relationship_id in self.store.company_relationships:
            raise ConflictError(f"company relationship {relationship.relationship_id} already exists")
        self.store.company_relationships[relationship.relationship_id] = relationship
        self._audit(actor, "register_company_relationship", "company_relationship", relationship.relationship_id, approval_state=relationship.relationship_status)
        return relationship

    def company_relationships_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        rows = list(self.store.company_relationships.values())
        issuer_id = str(filters.get("issuer_id", "")).strip()
        if issuer_id:
            rows = [item for item in rows if item.issuer_id == issuer_id or item.subject_id == issuer_id or item.object_id == issuer_id]
        for field_name in ["security_id", "relationship_type", "subject_type", "object_type", "relationship_status"]:
            value = str(filters.get(field_name, "")).strip()
            if value:
                rows = [item for item in rows if str(getattr(item, field_name, "")) == value]
        rows.sort(key=lambda item: (str(item.valid_from), item.relationship_id), reverse=True)
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        return {"count": len(rows), "relationships": [to_plain(item) for item in rows[:limit]]}

    def review_company_relationship(self, relationship_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> CompanyRelationship:
        relationship = self.store.company_relationships.get(str(relationship_id))
        if relationship is None:
            raise NotFoundError(f"company relationship {relationship_id} not found")
        action = str(payload.get("action", payload.get("review_action", "approve"))).strip().lower()
        if action not in {"approve", "reject", "merge"}:
            raise ValidationError("relationship review action must be approve, reject, or merge")
        now = utcnow()
        review_record = {
            "action": action,
            "reviewed_by": str(payload.get("reviewed_by", actor)),
            "reviewed_at": now.isoformat(),
            "reason": str(payload.get("reason", "")),
            "confidence_before": relationship.confidence,
        }
        relationship.metadata.setdefault("review_history", [])
        if isinstance(relationship.metadata["review_history"], list):
            relationship.metadata["review_history"].append(dict(review_record))
        if action == "approve":
            relationship.review_status = "approved"
            relationship.relationship_status = "active"
            relationship.confidence = max(float(relationship.confidence), float(payload.get("confidence", 0.8) or 0.8))
            relationship.metadata["candidate_status"] = "approved"
            relationship.metadata["verified_by"] = review_record["reviewed_by"]
            relationship.metadata["verified_at"] = review_record["reviewed_at"]
        elif action == "reject":
            relationship.review_status = "rejected"
            relationship.relationship_status = "inactive"
            relationship.metadata["candidate_status"] = "rejected"
            relationship.metadata["rejected_by"] = review_record["reviewed_by"]
            relationship.metadata["rejected_at"] = review_record["reviewed_at"]
        else:
            target_id = str(payload.get("target_relationship_id", "")).strip()
            if not target_id:
                raise ValidationError("merge review requires target_relationship_id")
            target = self.store.company_relationships.get(target_id)
            if target is None:
                raise NotFoundError(f"target company relationship {target_id} not found")
            relationship.review_status = "merged"
            relationship.relationship_status = "inactive"
            relationship.metadata["candidate_status"] = "merged"
            relationship.metadata["merged_into"] = target_id
            target.metadata.setdefault("merged_from", [])
            if isinstance(target.metadata["merged_from"], list) and relationship.relationship_id not in target.metadata["merged_from"]:
                target.metadata["merged_from"].append(relationship.relationship_id)
            target.evidence_ids = list(dict.fromkeys([*target.evidence_ids, *relationship.evidence_ids]))
            target.document_ids = list(dict.fromkeys([*target.document_ids, *relationship.document_ids]))
            target.source_ids = list(dict.fromkeys([*target.source_ids, *relationship.source_ids]))
            target.review_status = target.review_status if target.review_status == "approved" else "needs_review"
        self._audit(
            actor,
            "review_company_relationship",
            "company_relationship",
            relationship.relationship_id,
            approval_state=f"{action}:{relationship.review_status}",
        )
        marker = getattr(self.store, "mark_dirty_for_resource", None)
        if callable(marker):
            marker("company_relationship")
        self.store.commit()
        return relationship

    def _stable_research_child_id(self, prefix: str, *parts: str) -> str:
        raw = "_".join(str(part) for part in parts if str(part).strip())
        safe = re.sub(r"[^A-Za-z0-9_-]+", "_", raw).strip("_").lower()
        if not safe:
            safe = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]
        if len(safe) > 96:
            safe = f"{safe[:72]}_{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:16]}"
        return f"{prefix}_{safe}"

    def _research_report_published_at(self, report: ResearchReportAsset) -> datetime:
        try:
            year = int(report.year)
            month = int(report.month or 1)
            if not 1 <= month <= 12:
                month = 1
            return datetime(year, month, 1, tzinfo=timezone.utc)
        except (TypeError, ValueError):
            return utcnow()

    def _research_report_structure_text(self, report: ResearchReportAsset) -> str:
        document = self.store.documents.get(report.document_id) if report.document_id else None
        text = document.body.strip() if document and document.body else ""
        if not text:
            text = self._read_research_report_text(report).strip()
        return text

    def _research_report_citation_ids(self, report: ResearchReportAsset, *, limit: int = 5) -> list[str]:
        if not report.document_id:
            return []
        rows = [
            item.evidence_id
            for item in self.store.evidence.values()
            if item.document_id == report.document_id and item.section == "research_report_citation"
        ]
        return rows[:limit]

    def _analyst_slug(self, source_id: str, name: str) -> str:
        source_slug = safe_source_part(source_id)
        name_slug = safe_source_part(name)
        if name_slug == "unknown":
            name_slug = hashlib.sha256(name.encode("utf-8")).hexdigest()[:10]
        return f"analyst_{source_slug}_{name_slug}"

    def _ensure_report_analyst_profiles(
        self,
        *,
        analyst_names: list[str],
        report: ResearchReportAsset,
        issuer_id: str,
        industry: str,
        actor: str,
    ) -> list[str]:
        analyst_ids: list[str] = []
        for name in analyst_names:
            analyst_id = self._analyst_slug(report.source_id, name)
            analyst_ids.append(analyst_id)
            existing = self.store.analyst_profiles.get(analyst_id)
            if existing:
                if issuer_id and issuer_id not in existing.covered_issuer_ids:
                    existing.covered_issuer_ids.append(issuer_id)
                if report.source_id and report.source_id not in existing.source_ids:
                    existing.source_ids.append(report.source_id)
                if industry and industry not in existing.coverage_industries:
                    existing.coverage_industries.append(industry)
                existing.report_count = max(existing.report_count, 1)
                existing.last_seen_at = utcnow()
                continue
            self.register_analyst_profile(
                {
                    "analyst_id": analyst_id,
                    "name": name,
                    "institution_id": report.source_id,
                    "coverage_industries": [industry] if industry else [],
                    "covered_issuer_ids": [issuer_id] if issuer_id else [],
                    "report_count": 1,
                    "source_ids": [report.source_id],
                },
                actor=actor,
            )
        return analyst_ids

    def _research_report_structure_candidates(self, filters: Mapping[str, Any]) -> list[ResearchReportAsset]:
        report_ids = [str(item).strip() for item in filters.get("report_ids", [])] if isinstance(filters.get("report_ids"), list) else []
        single_report_id = str(filters.get("report_id", "")).strip()
        if single_report_id:
            report_ids.append(single_report_id)
        broker = str(filters.get("broker", "")).strip().lower()
        source_id = str(filters.get("source_id", "")).strip()
        issuer_id = str(filters.get("issuer_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        status = str(filters.get("status", "")).strip()
        query = str(filters.get("q", "")).strip().lower()
        rows = list(self.store.research_reports.values())
        if report_ids:
            wanted = set(report_ids)
            rows = [item for item in rows if item.report_id in wanted]
        if broker:
            rows = [item for item in rows if broker in item.broker.lower()]
        if source_id:
            rows = [item for item in rows if item.source_id == source_id]
        if issuer_id:
            rows = [item for item in rows if item.issuer_id == issuer_id]
        if security_id:
            rows = [item for item in rows if item.security_id == security_id]
        if status:
            rows = [item for item in rows if item.status == status]
        if query:
            rows = [item for item in rows if query in f"{item.title} {item.file_name} {item.broker} {item.year} {item.month}".lower()]
        rows.sort(key=lambda item: (item.year, item.month, item.broker, item.file_name), reverse=True)
        return rows

    def structure_research_reports(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        dry_run = self._truthy(payload.get("dry_run", False))
        execute = self._truthy(payload.get("execute", not dry_run)) and not dry_run
        force = self._truthy(payload.get("force", False))
        limit = self._bounded_limit(payload.get("limit", 50), 1000)
        reports = self._research_report_structure_candidates(payload)[:limit]
        rows: list[dict[str, Any]] = []
        structured_count = 0
        viewpoint_count = 0
        forecast_count = 0
        analyst_count = 0
        skipped_count = 0
        metadata_only_count = 0
        for report in reports:
            text = self._research_report_structure_text(report)
            fields = infer_structured_report_fields(
                title=report.title or report.file_name,
                broker=report.broker,
                year=report.year,
                month=report.month,
                text=text,
                industry=report.industry,
                metadata={
                    "industry": report.industry,
                    "evidence_topics": report.evidence_topics,
                    "risk_tags": report.risk_tags,
                    "financial_metric_tags": report.financial_metric_tags,
                    "viewpoint": report.viewpoint,
                },
            )
            metadata_only_count += 1 if fields["parser_status"] == "metadata_only" else 0
            structured_id = report.report_id
            viewpoint_id = self._stable_research_child_id("vp", report.report_id, "main")
            existing = self.store.structured_research_reports.get(structured_id)
            if existing and not force:
                skipped_count += 1
                rows.append(
                    {
                        "report_id": report.report_id,
                        "structured_report_id": structured_id,
                        "status": "skipped_existing",
                        "parser_status": existing.parser_status,
                        "report_type": existing.report_type,
                        "rating": existing.rating,
                        "target_price": existing.target_price,
                        "viewpoint_ids": list(existing.viewpoint_ids),
                        "forecast_ids": list(existing.forecast_ids),
                        "usage_boundary": existing.rights_boundary,
                    }
                )
                continue
            if execute and force:
                self.store.structured_research_reports.pop(structured_id, None)
                for key in list(self.store.report_viewpoints):
                    if key.startswith(f"{viewpoint_id}_") or key == viewpoint_id:
                        self.store.report_viewpoints.pop(key, None)
                forecast_prefix = self._stable_research_child_id("fc", report.report_id, "")
                for key in list(self.store.report_forecasts):
                    if key.startswith(forecast_prefix):
                        self.store.report_forecasts.pop(key, None)
            evidence_ids = self._research_report_citation_ids(report)
            issuer_id = report.issuer_id
            security_id = report.security_id
            analyst_ids = []
            if execute:
                analyst_ids = self._ensure_report_analyst_profiles(
                    analyst_names=[str(item) for item in fields["analyst_names"]],
                    report=report,
                    issuer_id=issuer_id,
                    industry=str(fields["industry"]),
                    actor=actor,
                )
                analyst_count += len(analyst_ids)
                structured = self.register_structured_research_report(
                    {
                        "research_report_id": structured_id,
                        "document_id": report.document_id,
                        "title": report.title,
                        "institution_id": report.source_id,
                        "institution_name": report.broker,
                        "analyst_ids": analyst_ids,
                        "analyst_names": fields["analyst_names"],
                        "issuer_id": issuer_id,
                        "security_id": security_id,
                        "covered_entities": [{"issuer_id": issuer_id, "security_id": security_id}] if issuer_id or security_id else [],
                        "report_type": fields["report_type"],
                        "language": fields["language"],
                        "source_id": report.source_id,
                        "source_uri": f"research-report://{report.report_id}",
                        "rights_boundary": "opinion_only_not_fact_source",
                        "published_at": self._research_report_published_at(report),
                        "current_price_at_publication": fields["current_price"],
                        "rating": fields["rating"],
                        "target_price": fields["target_price"],
                        "target_price_currency": fields["target_price_currency"],
                        "target_price_horizon": fields["target_price_horizon"],
                        "summary": fields["statement"],
                        "parser_status": fields["parser_status"],
                        "realization_status": "pending",
                    },
                    actor=actor,
                )
                structured_count += 1
                viewpoint = self.register_report_viewpoint(
                    {
                        "viewpoint_id": viewpoint_id,
                        "research_report_id": structured.research_report_id,
                        "issuer_id": issuer_id,
                        "security_id": security_id,
                        "viewpoint_type": fields["viewpoint_type"],
                        "stance": fields["sentiment"],
                        "statement": fields["statement"],
                        "rating": fields["rating"],
                        "target_price": fields["target_price"],
                        "current_price": fields["current_price"],
                        "upside_downside_pct": fields["upside_downside_pct"],
                        "valuation_method": fields["valuation_method"],
                        "core_assumptions": fields["core_assumptions"],
                        "catalysts": fields["catalysts"],
                        "risks": fields["risks"],
                        "evidence_ids": evidence_ids,
                        "source_quote_locator": f"research-report://{report.report_id}",
                        "view_status": "active",
                        "realization_status": "pending",
                        "notes": "Auto-structured from local research report metadata/text; opinion layer only.",
                    },
                    actor=actor,
                )
                viewpoint_count += 1
                forecast_ids: list[str] = []
                for index, forecast in enumerate(fields["forecasts"], start=1):
                    forecast_id = self._stable_research_child_id("fc", report.report_id, forecast["forecast_type"], str(index))
                    saved_forecast = self.register_report_forecast(
                        {
                            "forecast_id": forecast_id,
                            "research_report_id": structured.research_report_id,
                            "viewpoint_id": viewpoint.viewpoint_id,
                            "issuer_id": issuer_id,
                            "security_id": security_id,
                            "forecast_type": forecast["forecast_type"],
                            "period": forecast["period"],
                            "forecast_value": forecast["forecast_value"],
                            "unit": forecast.get("unit", ""),
                            "currency": forecast.get("currency", ""),
                            "realization_status": "pending",
                        },
                        actor=actor,
                    )
                    forecast_ids.append(saved_forecast.forecast_id)
                    forecast_count += 1
                row_status = "structured"
                row_viewpoint_ids = [viewpoint.viewpoint_id]
                row_forecast_ids = forecast_ids
            else:
                row_status = "planned"
                row_viewpoint_ids = [viewpoint_id]
                row_forecast_ids = [
                    self._stable_research_child_id("fc", report.report_id, forecast["forecast_type"], str(index))
                    for index, forecast in enumerate(fields["forecasts"], start=1)
                ]
            rows.append(
                {
                    "report_id": report.report_id,
                    "structured_report_id": structured_id,
                    "document_id": report.document_id,
                    "title": report.title,
                    "broker": report.broker,
                    "issuer_id": issuer_id,
                    "security_id": security_id,
                    "status": row_status,
                    "parser_status": fields["parser_status"],
                    "report_type": fields["report_type"],
                    "industry": fields["industry"],
                    "topic_terms": fields["topic_terms"],
                    "risk_tags": fields["risk_tags"],
                    "financial_metric_tags": fields["financial_metric_tags"],
                    "rating": fields["rating"],
                    "target_price": fields["target_price"],
                    "current_price": fields["current_price"],
                    "target_price_currency": fields["target_price_currency"],
                    "target_price_horizon": fields["target_price_horizon"],
                    "valuation_method": fields["valuation_method"],
                    "analyst_names": fields["analyst_names"],
                    "viewpoint_ids": row_viewpoint_ids,
                    "forecast_ids": row_forecast_ids,
                    "forecast_count": len(row_forecast_ids),
                    "usage_boundary": "opinion_only_not_fact_source",
                }
            )
        self._audit(
            actor,
            "structure_research_reports",
            "research_report",
            "batch",
            approval_state=f"execute={execute};structured={structured_count};skipped={skipped_count}",
        )
        if execute and reports:
            self.store.commit()
        return {
            "count": len(rows),
            "execute": execute,
            "dry_run": dry_run,
            "force": force,
            "structured_count": structured_count,
            "viewpoint_count": viewpoint_count,
            "forecast_count": forecast_count,
            "analyst_count": analyst_count,
            "skipped_count": skipped_count,
            "metadata_only_count": metadata_only_count,
            "usage_boundary": "research_reports_are_viewpoint_signal_only_not_fact_source_or_training_data",
            "reports": rows,
        }

    def update_research_report_realization(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 500), 5000)
        recompute_analyst_scores = self._truthy(payload.get("recompute_analyst_scores", True))
        issuer_ids = set()
        raw_issuer_ids = payload.get("issuer_ids", [])
        if isinstance(raw_issuer_ids, str):
            raw_issuer_ids = [raw_issuer_ids]
        if isinstance(raw_issuer_ids, list):
            issuer_ids.update(str(item).strip() for item in raw_issuer_ids if str(item).strip())
        has_company_filter = bool(
            issuer_ids
            or payload.get("symbols")
            or str(payload.get("symbol", "")).strip()
            or str(payload.get("ticker", "")).strip()
            or str(payload.get("q", "")).strip()
        )
        if not issuer_ids and has_company_filter:
            issuer_ids.update(issuer.issuer_id for issuer in self._company_database_target_issuers(payload, limit=limit))
        security_ids = {security.security_id for security in self.store.securities.values() if security.issuer_id in issuer_ids} if issuer_ids else set()
        forecast_rows = list(self.store.report_forecasts.values())
        viewpoint_rows = list(self.store.report_viewpoints.values())
        if issuer_ids:
            forecast_rows = [item for item in forecast_rows if item.issuer_id in issuer_ids or item.security_id in security_ids]
            viewpoint_rows = [item for item in viewpoint_rows if item.issuer_id in issuer_ids or item.security_id in security_ids]
        forecast_rows = [item for item in forecast_rows if item.forecast_type == "target_price" and item.forecast_value > 0][:limit]
        viewpoint_rows = [item for item in viewpoint_rows if item.target_price > 0][:limit]
        updated_forecasts = 0
        planned_forecasts = 0
        skipped_forecasts = 0
        updated_viewpoints = 0
        planned_viewpoints = 0
        skipped_viewpoints = 0
        analyst_ids: set[str] = set()
        forecast_results: list[dict[str, Any]] = []
        for forecast in forecast_rows:
            latest = self._latest_market_point_for_security(forecast.security_id)
            if latest is None:
                skipped_forecasts += 1
                forecast_results.append({"forecast_id": forecast.forecast_id, "status": "skipped_no_market_data"})
                continue
            actual = float(latest.close or 0.0)
            error_abs = actual - float(forecast.forecast_value)
            error_pct = error_abs / float(forecast.forecast_value) if forecast.forecast_value else 0.0
            realization_status = "realized" if actual >= float(forecast.forecast_value) else "missed"
            if execute:
                forecast.actual_value = actual
                forecast.actual_source_id = latest.source_id
                forecast.actual_evidence_ids = []
                forecast.error_abs = round(error_abs, 6)
                forecast.error_pct = round(error_pct, 6)
                forecast.realization_status = realization_status
                forecast.checked_at = utcnow()
                updated_forecasts += 1
                structured = self.store.structured_research_reports.get(forecast.research_report_id)
                if structured:
                    analyst_ids.update(structured.analyst_ids)
            else:
                planned_forecasts += 1
            forecast_results.append(
                {
                    "forecast_id": forecast.forecast_id,
                    "research_report_id": forecast.research_report_id,
                    "issuer_id": forecast.issuer_id,
                    "security_id": forecast.security_id,
                    "forecast_value": forecast.forecast_value,
                    "actual_value": actual,
                    "latest_date": latest.as_of_date,
                    "error_pct": round(error_pct, 6),
                    "realization_status": realization_status,
                    "status": "updated" if execute else "planned",
                }
            )
        viewpoint_results: list[dict[str, Any]] = []
        for viewpoint in viewpoint_rows:
            latest = self._latest_market_point_for_security(viewpoint.security_id)
            if latest is None:
                skipped_viewpoints += 1
                viewpoint_results.append({"viewpoint_id": viewpoint.viewpoint_id, "status": "skipped_no_market_data"})
                continue
            actual = float(latest.close or 0.0)
            realization_status = "realized" if actual >= float(viewpoint.target_price) else "missed"
            if execute:
                viewpoint.realization_status = realization_status
                viewpoint.realization_checked_at = utcnow()
                viewpoint.notes = (viewpoint.notes + "\n" if viewpoint.notes else "") + f"Realization checked against latest close {actual:g} on {latest.as_of_date}."
                updated_viewpoints += 1
                structured = self.store.structured_research_reports.get(viewpoint.research_report_id)
                if structured:
                    analyst_ids.update(structured.analyst_ids)
            else:
                planned_viewpoints += 1
            viewpoint_results.append(
                {
                    "viewpoint_id": viewpoint.viewpoint_id,
                    "research_report_id": viewpoint.research_report_id,
                    "issuer_id": viewpoint.issuer_id,
                    "security_id": viewpoint.security_id,
                    "target_price": viewpoint.target_price,
                    "actual_value": actual,
                    "latest_date": latest.as_of_date,
                    "realization_status": realization_status,
                    "status": "updated" if execute else "planned",
                }
            )
        analyst_scores: list[dict[str, Any]] = []
        if execute and recompute_analyst_scores:
            for analyst_id in sorted(analyst_ids):
                score = self.compute_analyst_reliability_score(
                    {
                        "analyst_id": analyst_id,
                        "issuer_id": next((issuer_id for issuer_id in issuer_ids), ""),
                        "period": "latest",
                        "notes": "Auto recomputed after research report realization update.",
                    },
                    actor=actor,
                )
                analyst_scores.append(to_plain(score))
        self._audit(
            actor,
            "update_research_report_realization",
            "research_report",
            "batch",
            approval_state=f"execute={execute};forecasts={updated_forecasts};viewpoints={updated_viewpoints}",
        )
        if execute and (updated_forecasts or updated_viewpoints):
            marker = getattr(self.store, "mark_dirty_for_resource", None)
            if callable(marker):
                marker("report_forecast")
                marker("report_viewpoint")
                marker("analyst_reliability_score")
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "forecast_planned": planned_forecasts,
            "forecast_updated": updated_forecasts,
            "forecast_skipped": skipped_forecasts,
            "viewpoint_planned": planned_viewpoints,
            "viewpoint_updated": updated_viewpoints,
            "viewpoint_skipped": skipped_viewpoints,
            "analyst_scores_recomputed": len(analyst_scores),
            "forecasts": forecast_results,
            "viewpoints": viewpoint_results,
            "analyst_scores": analyst_scores,
            "usage_boundary": "research_report_realization_uses_local_market_data_only_opinion_layer_not_fact_source_or_trading_signal",
        }

    def register_structured_research_report(self, payload: Mapping[str, Any], *, actor: str = "system") -> ResearchReport:
        report = ResearchReport(
            research_report_id=str(payload.get("research_report_id", payload.get("report_id", new_id("srr")))),
            document_id=str(payload.get("document_id", "")),
            title=str(payload.get("title", "")),
            institution_id=str(payload.get("institution_id", "")),
            institution_name=str(payload.get("institution_name", payload.get("broker", ""))),
            analyst_ids=[str(item) for item in payload.get("analyst_ids", [])],
            analyst_names=[str(item) for item in payload.get("analyst_names", [])],
            issuer_id=str(payload.get("issuer_id", "")),
            security_id=str(payload.get("security_id", "")),
            covered_entities=[dict(item) for item in payload.get("covered_entities", [])],
            report_type=str(payload.get("report_type", "other")),
            language=str(payload.get("language", "unknown")),
            source_id=str(payload.get("source_id", LOCAL_RESEARCH_REPORT_SOURCE_ID)),
            source_uri=str(payload.get("source_uri", "")),
            rights_boundary=str(payload.get("rights_boundary", "opinion_only_not_fact_source")),
            published_at=parse_datetime(payload.get("published_at")) if payload.get("published_at") else utcnow(),
            current_price_at_publication=float(payload.get("current_price_at_publication", payload.get("current_price", 0.0)) or 0.0),
            rating=str(payload.get("rating", "not_rated")),
            target_price=float(payload.get("target_price", 0.0) or 0.0),
            target_price_currency=str(payload.get("target_price_currency", "")),
            target_price_horizon=str(payload.get("target_price_horizon", "unknown")),
            summary=str(payload.get("summary", "")),
            parser_status=str(payload.get("parser_status", "parsed")),
            viewpoint_ids=[str(item) for item in payload.get("viewpoint_ids", [])],
            forecast_ids=[str(item) for item in payload.get("forecast_ids", [])],
            realization_status=str(payload.get("realization_status", "pending")),
        )
        if report.research_report_id in self.store.structured_research_reports:
            raise ConflictError(f"structured research report {report.research_report_id} already exists")
        self.store.structured_research_reports[report.research_report_id] = report
        self._audit(actor, "register_structured_research_report", "structured_research_report", report.research_report_id, approval_state=report.rights_boundary)
        return report

    def structured_research_reports_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        rows = self._filter_company_layer_rows(self.store.structured_research_reports.values(), filters or {})
        rows.sort(key=lambda item: item.published_at, reverse=True)
        limit = self._bounded_limit((filters or {}).get("limit", 50), 500)
        return {"count": len(rows), "reports": [to_plain(item) for item in rows[:limit]]}

    def register_report_viewpoint(self, payload: Mapping[str, Any], *, actor: str = "system") -> ReportViewpoint:
        report_id = str(payload["research_report_id"])
        if report_id not in self.store.structured_research_reports and report_id not in self.store.research_reports:
            raise NotFoundError(f"research report {report_id} not found")
        viewpoint = ReportViewpoint(
            viewpoint_id=str(payload.get("viewpoint_id", new_id("vp"))),
            research_report_id=report_id,
            issuer_id=str(payload.get("issuer_id", "")),
            security_id=str(payload.get("security_id", "")),
            viewpoint_type=str(payload.get("viewpoint_type", "other")),
            stance=str(payload.get("stance", "uncertain")),
            statement=str(payload.get("statement", "")),
            rating=str(payload.get("rating", "")),
            target_price=float(payload.get("target_price", 0.0) or 0.0),
            current_price=float(payload.get("current_price", 0.0) or 0.0),
            upside_downside_pct=float(payload.get("upside_downside_pct", 0.0) or 0.0),
            valuation_method=str(payload.get("valuation_method", "")),
            core_assumptions=[str(item) for item in payload.get("core_assumptions", [])],
            catalysts=[str(item) for item in payload.get("catalysts", [])],
            risks=[str(item) for item in payload.get("risks", [])],
            evidence_ids=[str(item) for item in payload.get("evidence_ids", [])],
            source_quote_locator=str(payload.get("source_quote_locator", "")),
            view_status=str(payload.get("view_status", "active")),
            realization_status=str(payload.get("realization_status", "pending")),
            realization_checked_at=parse_datetime(payload.get("realization_checked_at")) if payload.get("realization_checked_at") else None,
            notes=str(payload.get("notes", "")),
        )
        if viewpoint.viewpoint_id in self.store.report_viewpoints:
            raise ConflictError(f"report viewpoint {viewpoint.viewpoint_id} already exists")
        self.store.report_viewpoints[viewpoint.viewpoint_id] = viewpoint
        report = self.store.structured_research_reports.get(report_id)
        if report and viewpoint.viewpoint_id not in report.viewpoint_ids:
            report.viewpoint_ids.append(viewpoint.viewpoint_id)
            report.updated_at = utcnow()
        self._audit(actor, "register_report_viewpoint", "report_viewpoint", viewpoint.viewpoint_id, approval_state=viewpoint.realization_status)
        return viewpoint

    def report_viewpoints_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        rows = self._filter_company_layer_rows(self.store.report_viewpoints.values(), filters)
        report_id = str(filters.get("research_report_id", "")).strip()
        if report_id:
            rows = [item for item in rows if item.research_report_id == report_id]
        for field_name in ["viewpoint_type", "stance", "realization_status"]:
            value = str(filters.get(field_name, "")).strip()
            if value:
                rows = [item for item in rows if str(getattr(item, field_name, "")) == value]
        rows.sort(key=lambda item: item.created_at, reverse=True)
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        return {"count": len(rows), "viewpoints": [to_plain(item) for item in rows[:limit]]}

    def register_report_forecast(self, payload: Mapping[str, Any], *, actor: str = "system") -> ReportForecast:
        report_id = str(payload["research_report_id"])
        if report_id not in self.store.structured_research_reports and report_id not in self.store.research_reports:
            raise NotFoundError(f"research report {report_id} not found")
        forecast = ReportForecast(
            forecast_id=str(payload.get("forecast_id", new_id("fc"))),
            research_report_id=report_id,
            viewpoint_id=str(payload.get("viewpoint_id", "")),
            issuer_id=str(payload["issuer_id"]),
            security_id=str(payload.get("security_id", "")),
            forecast_type=str(payload.get("forecast_type", "other")),
            period=str(payload.get("period", "")),
            forecast_value=float(payload.get("forecast_value", 0.0) or 0.0),
            unit=str(payload.get("unit", "")),
            currency=str(payload.get("currency", "")),
            base_value=float(payload.get("base_value", 0.0) or 0.0),
            actual_value=float(payload.get("actual_value", 0.0) or 0.0),
            actual_source_id=str(payload.get("actual_source_id", "")),
            actual_evidence_ids=[str(item) for item in payload.get("actual_evidence_ids", [])],
            error_abs=float(payload.get("error_abs", 0.0) or 0.0),
            error_pct=float(payload.get("error_pct", 0.0) or 0.0),
            realization_status=str(payload.get("realization_status", "pending")),
            checked_at=parse_datetime(payload.get("checked_at")) if payload.get("checked_at") else None,
        )
        if forecast.actual_value and not forecast.error_abs:
            forecast.error_abs = abs(forecast.actual_value - forecast.forecast_value)
            if forecast.forecast_value:
                forecast.error_pct = round(forecast.error_abs / abs(forecast.forecast_value), 6)
        if forecast.forecast_id in self.store.report_forecasts:
            raise ConflictError(f"report forecast {forecast.forecast_id} already exists")
        self.store.report_forecasts[forecast.forecast_id] = forecast
        report = self.store.structured_research_reports.get(report_id)
        if report and forecast.forecast_id not in report.forecast_ids:
            report.forecast_ids.append(forecast.forecast_id)
            report.updated_at = utcnow()
        self._audit(actor, "register_report_forecast", "report_forecast", forecast.forecast_id, approval_state=forecast.realization_status)
        return forecast

    def report_forecasts_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        rows = self._filter_company_layer_rows(self.store.report_forecasts.values(), filters or {})
        rows.sort(key=lambda item: (str(item.period), item.created_at), reverse=True)
        limit = self._bounded_limit((filters or {}).get("limit", 50), 500)
        return {"count": len(rows), "forecasts": [to_plain(item) for item in rows[:limit]]}

    def register_analyst_profile(self, payload: Mapping[str, Any], *, actor: str = "system") -> AnalystProfile:
        analyst = AnalystProfile(
            analyst_id=str(payload.get("analyst_id", new_id("analyst"))),
            name=str(payload["name"]),
            institution_id=str(payload.get("institution_id", "")),
            person_id=str(payload.get("person_id", "")),
            coverage_markets=[str(item) for item in payload.get("coverage_markets", [])],
            coverage_industries=[str(item) for item in payload.get("coverage_industries", [])],
            covered_issuer_ids=[str(item) for item in payload.get("covered_issuer_ids", [])],
            report_count=int(payload.get("report_count", 0)),
            active=bool(payload.get("active", True)),
            source_ids=[str(item) for item in payload.get("source_ids", [])],
            first_seen_at=parse_datetime(payload.get("first_seen_at")) if payload.get("first_seen_at") else utcnow(),
            last_seen_at=parse_datetime(payload.get("last_seen_at")) if payload.get("last_seen_at") else utcnow(),
        )
        if analyst.analyst_id in self.store.analyst_profiles:
            raise ConflictError(f"analyst {analyst.analyst_id} already exists")
        self.store.analyst_profiles[analyst.analyst_id] = analyst
        self._audit(actor, "register_analyst_profile", "analyst_profile", analyst.analyst_id)
        return analyst

    def analyst_profiles_payload(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        rows = list(self.store.analyst_profiles.values())
        institution_id = str(filters.get("institution_id", "")).strip()
        issuer_id = str(filters.get("issuer_id", "")).strip()
        if institution_id:
            rows = [item for item in rows if item.institution_id == institution_id]
        if issuer_id:
            rows = [item for item in rows if issuer_id in item.covered_issuer_ids]
        rows.sort(key=lambda item: item.last_seen_at, reverse=True)
        limit = self._bounded_limit(filters.get("limit", 50), 500)
        return {"count": len(rows), "analysts": [to_plain(item) for item in rows[:limit]]}

    def compute_analyst_reliability_score(self, payload: Mapping[str, Any], *, actor: str = "system") -> AnalystReliabilityScore:
        analyst_id = str(payload["analyst_id"])
        if analyst_id not in self.store.analyst_profiles:
            raise NotFoundError(f"analyst {analyst_id} not found")
        issuer_id = str(payload.get("issuer_id", ""))
        report_ids = [
            report.research_report_id
            for report in self.store.structured_research_reports.values()
            if analyst_id in report.analyst_ids and (not issuer_id or report.issuer_id == issuer_id)
        ]
        forecasts = [item for item in self.store.report_forecasts.values() if item.research_report_id in set(report_ids)]
        reviewed = [item for item in forecasts if item.realization_status in {"realized", "missed", "not_available", "not_measurable"} or item.actual_value]
        target_forecasts = [item for item in reviewed if item.forecast_type == "target_price"]
        target_hits = [item for item in target_forecasts if item.realization_status == "realized" or (item.actual_value and item.forecast_value and item.actual_value >= item.forecast_value)]
        error_values = [abs(item.error_pct) for item in reviewed if item.error_pct]
        coverage = len(reviewed) / len(forecasts) if forecasts else 0.0
        mape = sum(error_values) / len(error_values) if error_values else 0.0
        hit_rate = len(target_hits) / len(target_forecasts) if target_forecasts else 0.0
        overall = round((hit_rate * 0.4) + (coverage * 0.3) + (max(0.0, 1.0 - min(mape, 1.0)) * 0.3), 4)
        analyst = self.store.analyst_profiles[analyst_id]
        score = AnalystReliabilityScore(
            score_id=str(payload.get("score_id", f"ars_{analyst_id}_{payload.get('period', 'all')}_{len(self.store.analyst_reliability_scores) + 1}")),
            analyst_id=analyst_id,
            institution_id=str(payload.get("institution_id", analyst.institution_id)),
            issuer_id=issuer_id,
            period=str(payload.get("period", "all")),
            sample_count=len(forecasts),
            target_price_hit_rate=round(hit_rate, 4),
            rating_direction_accuracy=float(payload.get("rating_direction_accuracy", 0.0) or 0.0),
            earnings_forecast_mape=round(mape, 6),
            forecast_review_coverage=round(coverage, 4),
            timeliness_score=float(payload.get("timeliness_score", 0.0) or 0.0),
            revision_quality_score=float(payload.get("revision_quality_score", 0.0) or 0.0),
            overall_score=overall,
            methodology_version=str(payload.get("methodology_version", "analyst-reliability-v1")),
            input_forecast_ids=[item.forecast_id for item in forecasts],
            notes=str(payload.get("notes", "")),
        )
        self.store.analyst_reliability_scores[score.score_id] = score
        self._audit(actor, "compute_analyst_reliability_score", "analyst_reliability_score", score.score_id)
        return score

