    def update_simulation_feedback_performance(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        execute = self._truthy(payload.get("execute", False))
        dry_run = self._truthy(payload.get("dry_run", not execute))
        if dry_run:
            execute = False
        limit = self._bounded_limit(payload.get("limit", 100), 1000)
        feedback_ids = [str(item).strip() for item in payload.get("feedback_ids", [])] if isinstance(payload.get("feedback_ids"), list) else []
        if str(payload.get("feedback_id", "")).strip():
            feedback_ids.append(str(payload["feedback_id"]).strip())
        raw_issuer_ids = payload.get("issuer_ids", [])
        if isinstance(raw_issuer_ids, str):
            raw_issuer_ids = [raw_issuer_ids]
        issuer_ids = {str(item).strip() for item in raw_issuer_ids if str(item).strip()} if isinstance(raw_issuer_ids, list) else set()
        has_company_filter = bool(
            issuer_ids
            or payload.get("symbols")
            or str(payload.get("symbol", "")).strip()
            or str(payload.get("ticker", "")).strip()
            or str(payload.get("q", "")).strip()
        )
        if not issuer_ids and has_company_filter:
            issuer_ids.update(issuer.issuer_id for issuer in self._company_database_target_issuers(payload, limit=limit))
        rows = list(self.store.simulation_feedback.values())
        if feedback_ids:
            wanted = set(feedback_ids)
            rows = [item for item in rows if item.simulation_feedback_id in wanted]
        if issuer_ids:
            rows = [item for item in rows if item.issuer_id in issuer_ids]
        rows.sort(key=lambda item: item.created_at, reverse=True)
        rows = rows[:limit]
        updated = 0
        planned = 0
        skipped = 0
        result_rows: list[dict[str, Any]] = []
        for feedback in rows:
            latest = self._latest_market_point_for_security(feedback.security_id)
            if latest is None:
                skipped += 1
                result_rows.append(
                    {
                        "simulation_feedback_id": feedback.simulation_feedback_id,
                        "issuer_id": feedback.issuer_id,
                        "security_id": feedback.security_id,
                        "status": "skipped_no_market_data",
                    }
                )
                continue
            entry_price = float(feedback.entry_price or 0.0)
            latest_price = float(latest.close or 0.0)
            initialized_entry = False
            if entry_price <= 0 and latest_price > 0:
                entry_price = latest_price
                initialized_entry = True
            if entry_price <= 0:
                skipped += 1
                result_rows.append(
                    {
                        "simulation_feedback_id": feedback.simulation_feedback_id,
                        "issuer_id": feedback.issuer_id,
                        "security_id": feedback.security_id,
                        "status": "skipped_invalid_entry_price",
                        "latest_market_data_id": latest.data_id,
                    }
                )
                continue
            start_at = parse_datetime(feedback.start_at)
            try:
                latest_date = date.fromisoformat(str(latest.as_of_date))
                holding_days = max(0, (latest_date - start_at.date()).days)
            except ValueError:
                holding_days = 0
            return_abs = latest_price - entry_price
            return_pct = return_abs / entry_price if entry_price else 0.0
            performance = dict(feedback.performance)
            performance.update(
                {
                    "status": "baseline_initialized" if initialized_entry else "measured",
                    "entry_price": round(entry_price, 6),
                    "latest_price": round(latest_price, 6),
                    "latest_date": latest.as_of_date,
                    "latest_market_data_id": latest.data_id,
                    "return_abs": round(return_abs, 6),
                    "return_pct": round(return_pct, 6),
                    "holding_days": holding_days,
                    "updated_at": utcnow().isoformat(),
                }
            )
            validation = dict(feedback.validation)
            validation.update(
                {
                    "performance_measured": True,
                    "paper_only": True,
                    "live_execution_allowed": False,
                    "market_data_source_id": latest.source_id,
                    "metric": "latest_close_vs_entry_price",
                }
            )
            review_result = dict(feedback.review_result)
            review_result.update(
                {
                    "status": "pending_review",
                    "summary": "Paper feedback performance updated from latest local market data.",
                    "requires_human_review": True,
                }
            )
            if execute:
                feedback.entry_price = entry_price
                feedback.performance = performance
                feedback.validation = validation
                feedback.review_result = review_result
                feedback.updated_at = utcnow()
                updated += 1
            else:
                planned += 1
            result_rows.append(
                {
                    "simulation_feedback_id": feedback.simulation_feedback_id,
                    "issuer_id": feedback.issuer_id,
                    "security_id": feedback.security_id,
                    "status": "updated" if execute else "planned",
                    "entry_price": round(entry_price, 6),
                    "latest_price": round(latest_price, 6),
                    "latest_date": latest.as_of_date,
                    "return_pct": round(return_pct, 6),
                    "holding_days": holding_days,
                    "paper_only": True,
                    "live_execution_allowed": False,
                }
            )
        self._audit(
            actor,
            "update_simulation_feedback_performance",
            "simulation_feedback",
            "batch",
            approval_state=f"execute={execute};updated={updated};planned={planned};skipped={skipped}",
        )
        if execute and updated:
            marker = getattr(self.store, "mark_dirty_for_resource", None)
            if callable(marker):
                marker("simulation_feedback")
            self.store.commit()
        return {
            "status": "executed" if execute else "dry_run",
            "execute": execute,
            "dry_run": dry_run,
            "target_count": len(rows),
            "feedback_planned": planned,
            "feedback_updated": updated,
            "feedback_skipped": skipped,
            "feedback": result_rows,
            "paper_only": True,
            "live_execution_allowed": False,
            "usage_boundary": "simulation_feedback_performance_update_uses_local_market_data_only_no_broker_execution",
        }

    def _latest_market_point_for_security(self, security_id: str) -> MarketDataPoint | None:
        if not security_id:
            return None
        if self._market_data_direct_query_enabled():
            rows = self._query_market_data_points(security_id=security_id, limit=1, descending=True)
            return rows[0] if rows else None
        rows = [item for item in self.store.market_data.values() if item.security_id == security_id]
        rows.sort(key=lambda item: (str(item.as_of_date), item.data_id), reverse=True)
        return rows[0] if rows else None

    def _filter_company_layer_rows(self, rows_iter: Any, filters: Mapping[str, Any]) -> list[Any]:
        rows = list(rows_iter)
        for field_name in ["issuer_id", "security_id"]:
            value = str(filters.get(field_name, "")).strip()
            if value:
                rows = [item for item in rows if str(getattr(item, field_name, "")) == value]
        return rows

    def company_intelligence(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        raw_symbol = str(filters.get("symbol") or filters.get("ticker") or filters.get("q") or "").strip()
        if not raw_symbol:
            raise ValidationError("company intelligence query requires symbol")
        limit = self._bounded_limit(filters.get("limit", 20), 100)
        symbol_tokens = self._company_intelligence_symbol_tokens(raw_symbol)
        symbol = sorted(symbol_tokens, key=lambda item: (item != raw_symbol.upper(), len(item)))[0] if symbol_tokens else raw_symbol.upper()

        def limited(rows: list[Any], max_rows: int | None = None) -> list[Any]:
            return rows[: max_rows or limit]

        def plain_rows(rows: list[Any], max_rows: int | None = None) -> list[dict[str, Any]]:
            return [to_plain(item) for item in limited(rows, max_rows)]

        def text_matches(value: Any) -> bool:
            text = json.dumps(to_plain(value), ensure_ascii=False, default=str).lower()
            return any(token.lower() in text for token in symbol_tokens)

        securities = [
            security
            for security in self.store.securities.values()
            if self._company_intelligence_security_matches(security, symbol_tokens)
        ]
        security_ids = {security.security_id for security in securities}
        issuer_ids = {security.issuer_id for security in securities if security.issuer_id}

        mappings = [
            mapping
            for mapping in self.store.entity_mappings.values()
            if self._company_intelligence_mapping_matches(mapping, symbol_tokens)
            or (mapping.issuer_id and mapping.issuer_id in issuer_ids)
        ]
        issuer_ids.update(mapping.issuer_id for mapping in mappings if mapping.issuer_id)

        issuers = [
            issuer
            for issuer in self.store.issuers.values()
            if issuer.issuer_id in issuer_ids or self._company_intelligence_issuer_matches(issuer, symbol_tokens)
        ]
        issuer_ids.update(issuer.issuer_id for issuer in issuers)
        if issuer_ids:
            for security in self.store.securities.values():
                if security.issuer_id in issuer_ids and security.security_id not in security_ids:
                    securities.append(security)
                    security_ids.add(security.security_id)

        if self._market_data_direct_query_enabled() and security_ids:
            market_data_by_id: dict[str, MarketDataPoint] = {}
            per_security_limit = max(1, min(limit, 20))
            for scoped_security_id in sorted(security_ids):
                for point in self._query_market_data_points(security_id=scoped_security_id, limit=per_security_limit, descending=True):
                    market_data_by_id[point.data_id] = point
            market_data = list(market_data_by_id.values())
        else:
            market_data = [
                point
                for point in self.store.market_data.values()
                if point.security_id in security_ids or text_matches(point)
            ]
        market_data.sort(key=lambda item: (str(item.as_of_date), item.data_id), reverse=True)
        corporate_actions = [
            action
            for action in self.store.corporate_actions.values()
            if action.security_id in security_ids or text_matches(action)
        ]
        corporate_actions.sort(key=lambda item: (str(item.ex_date), item.action_id), reverse=True)

        documents = [
            document
            for document in self.store.documents.values()
            if document.issuer_id in issuer_ids
            or document.security_id in security_ids
            or text_matches({"title": document.title, "source_uri": document.source_uri, "document_type": document.document_type})
        ]
        documents.sort(key=lambda item: (str(to_plain(item.published_at)), item.document_id), reverse=True)
        document_ids = {document.document_id for document in documents}
        evidence = [
            item
            for item in self.store.evidence.values()
            if item.document_id in document_ids or text_matches(item)
        ]
        evidence.sort(key=lambda item: (item.document_id, item.page_no, item.evidence_id))

        research_reports = [
            report
            for report in self.store.research_reports.values()
            if report.issuer_id in issuer_ids
            or report.security_id in security_ids
            or text_matches(
                {
                    "title": report.title,
                    "file_name": report.file_name,
                    "broker": report.broker,
                    "asset_matches": report.asset_matches,
                    "viewpoint": report.viewpoint,
                    "evidence_topics": report.evidence_topics,
                    "risk_tags": report.risk_tags,
                }
            )
        ]
        research_reports.sort(key=lambda item: (str(item.year), str(item.month), item.report_id), reverse=True)
        structured_research_reports = [
            report
            for report in self.store.structured_research_reports.values()
            if report.issuer_id in issuer_ids or report.security_id in security_ids or text_matches(report)
        ]
        structured_research_reports.sort(key=lambda item: item.published_at, reverse=True)
        structured_report_ids = {report.research_report_id for report in structured_research_reports}
        report_viewpoints = [
            viewpoint
            for viewpoint in self.store.report_viewpoints.values()
            if viewpoint.issuer_id in issuer_ids
            or viewpoint.security_id in security_ids
            or viewpoint.research_report_id in structured_report_ids
            or text_matches(viewpoint)
        ]
        report_viewpoints.sort(key=lambda item: item.created_at, reverse=True)
        viewpoint_ids = {viewpoint.viewpoint_id for viewpoint in report_viewpoints}
        report_forecasts = [
            forecast
            for forecast in self.store.report_forecasts.values()
            if forecast.issuer_id in issuer_ids
            or forecast.security_id in security_ids
            or forecast.research_report_id in structured_report_ids
            or forecast.viewpoint_id in viewpoint_ids
            or text_matches(forecast)
        ]
        report_forecasts.sort(key=lambda item: (str(item.period), item.created_at), reverse=True)
        analyst_ids = {analyst_id for report in structured_research_reports for analyst_id in report.analyst_ids}
        analyst_profiles = [
            analyst
            for analyst in self.store.analyst_profiles.values()
            if analyst.analyst_id in analyst_ids or issuer_ids.intersection(set(analyst.covered_issuer_ids)) or text_matches(analyst)
        ]
        analyst_reliability_scores = [
            score
            for score in self.store.analyst_reliability_scores.values()
            if score.analyst_id in analyst_ids or score.issuer_id in issuer_ids or text_matches(score)
        ]
        research_answers = [
            answer
            for answer in self.store.research_answers.values()
            if answer.issuer_id in issuer_ids or text_matches(answer)
        ]
        research_answers.sort(key=lambda item: (str(to_plain(item.created_at)), item.answer_id), reverse=True)
        theses = [thesis for thesis in self.store.theses.values() if thesis.issuer_id in issuer_ids or text_matches(thesis)]
        thesis_ids = {thesis.thesis_id for thesis in theses}
        signals = [
            signal
            for signal in self.store.signals.values()
            if signal.thesis_id in thesis_ids or text_matches(signal)
        ]
        signal_ids = {signal.signal_id for signal in signals}
        challengers = [
            challenger
            for challenger in self.store.challengers.values()
            if challenger.thesis_id in thesis_ids or text_matches(challenger)
        ]
        research_cards = [
            card
            for card in self.store.research_cards.values()
            if card.issuer_id in issuer_ids or card.thesis_id in thesis_ids or text_matches(card)
        ]
        research_tasks = [
            task
            for task in self.store.research_tasks.values()
            if task.issuer_id in issuer_ids
            or task.security_id in security_ids
            or text_matches({"task_id": task.task_id, "reason": task.reason, "metadata": task.metadata, "source": task.source})
        ]
        research_tasks.sort(key=lambda item: (item.priority, str(to_plain(item.updated_at))), reverse=True)

        disclosure_events = [
            event
            for event in self.store.disclosure_events.values()
            if event.issuer_id in issuer_ids or event.security_id in security_ids or text_matches(event)
        ]
        disclosure_events.sort(key=lambda item: (str(to_plain(item.occurred_at)), item.event_id), reverse=True)
        company_events = [
            event
            for event in self.store.company_events.values()
            if event.issuer_id in issuer_ids or event.security_id in security_ids or text_matches(event)
        ]
        company_events.sort(key=lambda item: (str(to_plain(item.occurred_at)), item.event_id), reverse=True)
        company_relationships = [
            relationship
            for relationship in self.store.company_relationships.values()
            if relationship.issuer_id in issuer_ids
            or relationship.security_id in security_ids
            or relationship.subject_id in issuer_ids
            or relationship.object_id in issuer_ids
            or text_matches(relationship)
        ]
        company_relationships.sort(key=lambda item: (str(item.valid_from), item.relationship_id), reverse=True)
        company_positions = [
            position
            for position in self.store.company_positions.values()
            if position.issuer_id in issuer_ids or position.security_id in security_ids or text_matches(position)
        ]
        institutional_holdings = [
            holding
            for holding in self.store.institutional_holdings.values()
            if holding.issuer_id in issuer_ids or holding.security_id in security_ids or text_matches(holding)
        ]
        crowding = [
            snapshot
            for snapshot in self.store.crowding.values()
            if snapshot.issuer_id in issuer_ids or text_matches(snapshot)
        ]

        decisions = [
            decision
            for decision in self.store.decisions.values()
            if any(signal_id in signal_ids for signal_id in decision.signal_ids) or text_matches(decision)
        ]
        decision_ids = {decision.decision_id for decision in decisions}
        execution_intents = [
            intent
            for intent in self.store.execution_intents.values()
            if intent.security_id in security_ids or intent.decision_id in decision_ids or text_matches(intent)
        ]
        intent_ids = {intent.intent_id for intent in execution_intents}
        simulated_executions = [
            execution
            for execution in self.store.simulated_executions.values()
            if execution.intent_id in intent_ids or text_matches(execution)
        ]
        transaction_ids = {execution.transaction_id for execution in simulated_executions if execution.transaction_id}
        portfolio_transactions = [
            transaction
            for transaction in self.store.portfolio_transactions.values()
            if transaction.security_id in security_ids or transaction.transaction_id in transaction_ids or text_matches(transaction)
        ]
        portfolio_transactions.sort(key=lambda item: (str(item.trade_date), item.transaction_id), reverse=True)
        observation_items = [
            item
            for item in self.store.observation_items.values()
            if item.issuer_id in issuer_ids or item.security_id in security_ids or set(item.related_viewpoint_ids) & viewpoint_ids or text_matches(item)
        ]
        observation_items.sort(key=lambda item: (item.status != "open", item.due_at or item.created_at))
        observation_ids = {item.observation_id for item in observation_items}
        analysis_conclusions = [
            conclusion
            for conclusion in self.store.analysis_conclusions.values()
            if conclusion.issuer_id in issuer_ids
            or conclusion.security_id in security_ids
            or set(conclusion.related_observation_ids) & observation_ids
            or set(conclusion.related_viewpoint_ids) & viewpoint_ids
            or text_matches(conclusion)
        ]
        analysis_conclusions.sort(key=lambda item: item.updated_at, reverse=True)
        conclusion_ids = {item.analysis_conclusion_id for item in analysis_conclusions}
        first_class_simulation_feedback = [
            feedback
            for feedback in self.store.simulation_feedback.values()
            if feedback.issuer_id in issuer_ids
            or feedback.security_id in security_ids
            or feedback.analysis_conclusion_id in conclusion_ids
            or feedback.observation_id in observation_ids
            or text_matches(feedback)
        ]
        first_class_simulation_feedback.sort(key=lambda item: item.created_at, reverse=True)

        primary_issuer = issuers[0] if issuers else None
        primary_security = securities[0] if securities else None
        company_profiles = [
            profile for profile in self.store.company_profiles.values() if profile.issuer_id in issuer_ids or text_matches(profile)
        ]
        if not company_profiles and primary_issuer is not None:
            company_profiles = [self._company_profile_from_existing_records(primary_issuer.issuer_id, {})]
        company_profiles.sort(key=lambda item: item.updated_at, reverse=True)
        primary_profile = company_profiles[0] if company_profiles else None
        graph_filters: dict[str, Any] = {"limit": limit, "market_data_limit": limit}
        if primary_issuer:
            graph_filters["issuer_id"] = primary_issuer.issuer_id
        if primary_security:
            graph_filters["security_id"] = primary_security.security_id
        graph = self.query_graph(graph_filters) if (primary_issuer or primary_security) else {"issuers": [], "securities": [], "edges": []}
        search_filter: dict[str, Any] = {"q": raw_symbol, "limit": limit}
        if primary_issuer:
            search_filter["issuer_id"] = primary_issuer.issuer_id
        search_results = self.search(search_filter)

        section_counts = {
            "issuers": len(issuers),
            "securities": len(securities),
            "market_data": len(market_data),
            "corporate_actions": len(corporate_actions),
            "documents": len(documents),
            "evidence": len(evidence),
            "research_reports": len(research_reports),
            "structured_research_reports": len(structured_research_reports),
            "report_viewpoints": len(report_viewpoints),
            "report_forecasts": len(report_forecasts),
            "analyst_profiles": len(analyst_profiles),
            "analyst_reliability_scores": len(analyst_reliability_scores),
            "research_answers": len(research_answers),
            "theses": len(theses),
            "signals": len(signals),
            "challengers": len(challengers),
            "research_cards": len(research_cards),
            "research_tasks": len(research_tasks),
            "company_profiles": len(company_profiles),
            "company_events": len(company_events),
            "company_relationships": len(company_relationships),
            "disclosure_events": len(disclosure_events),
            "company_positions": len(company_positions),
            "institutional_holdings": len(institutional_holdings),
            "crowding": len(crowding),
            "observation_items": len(observation_items),
            "analysis_conclusions": len(analysis_conclusions),
            "simulation_feedback_records": len(first_class_simulation_feedback),
            "execution_intents": len(execution_intents),
            "simulated_executions": len(simulated_executions),
            "portfolio_transactions": len(portfolio_transactions),
            "graph_edges": len(graph.get("edges", [])) if isinstance(graph.get("edges"), list) else 0,
            "search_results": len(search_results.get("results", [])),
        }
        has_profile = bool(issuers or securities)
        has_research = any(
            section_counts[key] > 0
            for key in [
                "research_reports",
                "structured_research_reports",
                "report_viewpoints",
                "research_answers",
                "theses",
                "signals",
                "research_cards",
                "research_tasks",
            ]
        )
        has_events = bool(disclosure_events or company_events)
        has_relationships = bool(section_counts["graph_edges"] or company_relationships or company_positions or institutional_holdings or mappings)
        has_feedback = bool(first_class_simulation_feedback or simulated_executions or portfolio_transactions)
        data_quality = {
            "profile_available": has_profile,
            "market_data_available": bool(market_data),
            "event_timeline_available": has_events,
            "relationship_graph_available": has_relationships,
            "research_results_available": has_research,
            "simulation_feedback_available": has_feedback,
            "profile_coverage": (primary_profile.data_quality or {}).get("profile_coverage", 0.0) if primary_profile else 0.0,
            "event_backlink_rate": self._backlink_rate(company_events + disclosure_events),
            "relationship_backlink_rate": self._backlink_rate(company_relationships),
            "research_viewpoint_structured_rate": round(len(report_viewpoints) / len(structured_research_reports), 4) if structured_research_reports else 0.0,
            "analysis_feedback_backlink_rate": round(
                sum(1 for item in first_class_simulation_feedback if item.analysis_conclusion_id in conclusion_ids) / len(first_class_simulation_feedback),
                4,
            )
            if first_class_simulation_feedback
            else 0.0,
            "missing_sections": [
                label
                for label, available in [
                    ("company_profile", has_profile),
                    ("market_data", bool(market_data)),
                    ("events", has_events),
                    ("relationships", has_relationships),
                    ("research_results", has_research),
                    ("simulation_feedback", has_feedback),
                ]
                if not available
            ],
        }

        return {
            "status": "available" if any(section_counts.values()) else "not_found",
            "symbol": symbol,
            "input_symbol": raw_symbol,
            "resolution": {
                "issuer_ids": sorted(issuer_ids),
                "security_ids": sorted(security_ids),
                "mapping_ids": [mapping.mapping_id for mapping in mappings[:limit]],
                "matched": bool(issuer_ids or security_ids or mappings),
                "source": "local_store_symbol_resolution",
            },
            "company_profile": {
                "profile": to_plain(primary_profile) if primary_profile else {},
                "profiles": plain_rows(company_profiles),
                "issuer": to_plain(primary_issuer) if primary_issuer else {},
                "primary_security": to_plain(primary_security) if primary_security else {},
                "issuers": plain_rows(issuers),
                "securities": plain_rows(securities),
                "entity_mappings": plain_rows(mappings),
                "coverage_summary": {
                    "research_report_count": len(research_reports),
                    "structured_research_report_count": len(structured_research_reports),
                    "report_viewpoint_count": len(report_viewpoints),
                    "research_answer_count": len(research_answers),
                    "event_count": len(disclosure_events) + len(company_events),
                    "evidence_count": len(evidence),
                    "simulation_feedback_count": len(first_class_simulation_feedback) + len(simulated_executions) + len(portfolio_transactions),
                },
            },
            "facts_and_events": {
                "market_data": plain_rows(market_data),
                "latest_market_snapshot": to_plain(market_data[0]) if market_data else {},
                "corporate_actions": plain_rows(corporate_actions),
                "documents": plain_rows(documents),
                "evidence": plain_rows(evidence),
                "company_events": plain_rows(company_events),
                "disclosure_events": plain_rows(disclosure_events),
            },
            "relationships": {
                "company_relationships": plain_rows(company_relationships),
                "company_positions": plain_rows(company_positions),
                "institutional_holdings": plain_rows(institutional_holdings),
                "crowding": plain_rows(crowding),
                "graph": graph,
            },
            "research_results": {
                "research_reports": plain_rows(research_reports),
                "structured_research_reports": plain_rows(structured_research_reports),
                "report_viewpoints": plain_rows(report_viewpoints),
                "report_forecasts": plain_rows(report_forecasts),
                "analyst_profiles": plain_rows(analyst_profiles),
                "analyst_reliability_scores": plain_rows(analyst_reliability_scores),
                "research_answers": plain_rows(research_answers),
                "theses": plain_rows(theses),
                "signals": plain_rows(signals),
                "challengers": plain_rows(challengers),
                "research_cards": plain_rows(research_cards),
                "research_tasks": plain_rows(research_tasks),
                "search": search_results,
            },
            "analysis_workflow": {
                "observation_items": plain_rows(observation_items),
                "analysis_conclusions": plain_rows(analysis_conclusions),
                "feedback_records": plain_rows(first_class_simulation_feedback),
            },
            "simulation_feedback": {
                "feedback_records": plain_rows(first_class_simulation_feedback),
                "execution_intents": plain_rows(execution_intents),
                "simulated_executions": plain_rows(simulated_executions),
                "portfolio_transactions": plain_rows(portfolio_transactions),
                "paper_only": True,
                "live_execution_allowed": False,
                "compatibility_legacy_sources": ["ExecutionIntent", "SimulatedExecution", "PortfolioTransaction"],
            },
            "data_quality": data_quality,
            "section_counts": section_counts,
            "next_actions": self._company_intelligence_next_actions(raw_symbol, data_quality),
            "usage_boundary": "company_intelligence_research_only_simulation_feedback_only_no_broker_execution",
        }

    def _company_intelligence_symbol_tokens(self, symbol: str) -> set[str]:
        raw = str(symbol or "").strip()
        if not raw:
            return set()
        upper = raw.upper()
        tokens = {raw, upper}
        us_symbol = self._normalize_us_backfill_symbol(raw)
        if us_symbol:
            tokens.add(us_symbol)
        tdx_symbol = self._normalize_tdx_symbol(raw)
        if tdx_symbol:
            tokens.add(tdx_symbol)
            tokens.add(f"SH{tdx_symbol}")
            tokens.add(f"SZ{tdx_symbol}")
            tokens.add(f"{tdx_symbol}.SH")
            tokens.add(f"{tdx_symbol}.SZ")
        return {token for token in tokens if token}

    def _company_intelligence_security_matches(self, security: Security, symbol_tokens: set[str]) -> bool:
        values = {
            security.security_id,
            security.ticker,
            security.figi,
            security.isin,
        }
        return any(str(value).strip().upper() in symbol_tokens for value in values if str(value).strip())

    def _company_intelligence_mapping_matches(self, mapping: EntityMapping, symbol_tokens: set[str]) -> bool:
        values = {mapping.mapping_id, mapping.ticker, mapping.figi, mapping.isin, mapping.cik, mapping.lei}
        return any(str(value).strip().upper() in symbol_tokens for value in values if str(value).strip())

    def _company_intelligence_issuer_matches(self, issuer: Issuer, symbol_tokens: set[str]) -> bool:
        values = {issuer.issuer_id, issuer.legal_name, issuer.cik, issuer.lei, *issuer.aliases}
        return any(str(value).strip().upper() in symbol_tokens for value in values if str(value).strip())

    def _company_intelligence_next_actions(self, symbol: str, data_quality: Mapping[str, Any]) -> list[dict[str, str]]:
        actions: list[dict[str, str]] = []
        if not data_quality.get("profile_available"):
            actions.append(
                {
                    "action": "run_single_name_research",
                    "label": f"为 {symbol.upper()} 建立最小公司情报档案",
                    "endpoint": "/api/research/tasks/sec-single-name/run",
                    "reason": "本地还没有匹配的 issuer/security；先运行单标的研究或手工登记主体。",
                }
            )
        if not data_quality.get("research_results_available"):
            actions.append(
                {
                    "action": "collect_research_views",
                    "label": "补充研报观点和研究答案",
                    "endpoint": "/api/research-reports 或 /api/research/answers/filing-qa",
                    "reason": "当前没有可展示的结构化研究结果。",
                }
            )
        if not data_quality.get("simulation_feedback_available"):
            actions.append(
                {
                    "action": "record_simulation_feedback",
                    "label": "记录模拟反馈",
                    "endpoint": "/api/research/tasks/sec-single-name/run",
                    "reason": "模拟反馈仅用于验证分析结论，不连接券商。",
                }
            )
        return actions

    def query_graph(self, filters: Mapping[str, Any] | None = None) -> dict[str, Any]:
        filters = filters or {}
        issuer_id = str(filters.get("issuer_id", "")).strip()
        thesis_id = str(filters.get("thesis_id", "")).strip()
        evidence_id = str(filters.get("evidence_id", "")).strip()
        security_id = str(filters.get("security_id", "")).strip()
        decision_id = str(filters.get("decision_id", "")).strip()
        theme_id = str(filters.get("theme_id", "")).strip()
        chain_id = str(filters.get("chain_id", "")).strip()
        chain_node_id = str(filters.get("chain_node_id", "")).strip()
        graph_limit = self._bounded_limit(filters["limit"], 1000) if str(filters.get("limit", "")).strip() else 0
        market_data_limit = self._bounded_limit(filters.get("market_data_limit", 20), 200)
        security_filter_ids: set[str] = {security_id} if security_id else set()
        data = {
            "issuers": [],
            "securities": [],
            "market_data": [],
            "corporate_actions": [],
            "documents": [],
            "evidence": [],
            "manual_reviews": [],
            "theses": [],
            "signals": [],
            "decisions": [],
            "execution_intents": [],
            "reviews": [],
            "strategy_replays": [],
            "exceptions": [],
            "entity_mappings": [],
            "research_cards": [],
            "macro_themes": [],
            "industry_chains": [],
            "chain_nodes": [],
            "company_positions": [],
            "company_profiles": [],
            "company_events": [],
            "company_relationships": [],
            "research_tasks": [],
            "structured_research_reports": [],
            "report_viewpoints": [],
            "report_forecasts": [],
            "analyst_profiles": [],
            "analyst_reliability_scores": [],
            "observation_items": [],
            "analysis_conclusions": [],
            "simulation_feedback": [],
            "crowding": [],
            "institutional_holdings": [],
            "disclosure_events": [],
            "challengers": [],
            "portfolio_proposals": [],
            "portfolio_positions": [],
            "edges": [],
        }
        seen: dict[str, set[str]] = {key: set() for key in data if key not in {"edges", "portfolio_positions"}}
        edge_keys: set[tuple[str, str, str]] = set()

        def add_node(collection: str, object_id: str, value: Any) -> None:
            if object_id and object_id not in seen[collection]:
                data[collection].append(to_plain(value))
                seen[collection].add(object_id)

        def add_edge(edge_type: str, from_id: str, to_id: str, **attrs: Any) -> None:
            if not from_id or not to_id:
                return
            edge_key = (edge_type, from_id, to_id)
            if edge_key in edge_keys:
                return
            edge = {"type": edge_type, "from": from_id, "to": to_id}
            edge.update(attrs)
            edge.setdefault("source", edge.get("source_id") or "system_graph")
            edge.setdefault(
                "timestamp",
                edge.get("timestamp")
                or edge.get("as_of")
                or edge.get("as_of_date")
                or edge.get("valid_from")
                or edge.get("report_period")
                or edge.get("ex_date")
                or to_plain(utcnow()),
            )
            edge.setdefault("version", str(edge.get("version") or edge.get("parser_version") or edge.get("data_type") or edge.get("source_id") or "v1"))
            edge.setdefault("confidence", float(edge.get("confidence", edge.get("score", 1.0)) or 0.0))
            data["edges"].append(edge)
            edge_keys.add(edge_key)

        def security_in_scope(candidate_security_id: str) -> bool:
            return not security_filter_ids or candidate_security_id in security_filter_ids

        def position_in_scope(position: CompanyPosition) -> bool:
            return not security_filter_ids or position.security_id in security_filter_ids

        def task_in_scope(task: ResearchTask) -> bool:
            if not security_filter_ids:
                return True
            if task.security_id and task.security_id in security_filter_ids:
                return True
            if task.position_id:
                position = self.store.company_positions.get(task.position_id)
                return bool(position and position_in_scope(position))
            return False

        def add_security_facts(security: Security) -> None:
            if self._market_data_direct_query_enabled():
                points = self._query_market_data_points(security_id=security.security_id, limit=market_data_limit, descending=True)
            else:
                points = [
                    point
                    for point in sorted(self.store.market_data.values(), key=lambda item: (item.as_of_date, item.data_id), reverse=True)
                    if point.security_id == security.security_id
                ][:market_data_limit]
            for point in points:
                add_node("market_data", point.data_id, point)
                add_edge("HAS_MARKET_DATA", security.security_id, point.data_id, as_of_date=point.as_of_date, data_type=point.data_type)
            for action in self.store.corporate_actions.values():
                if action.security_id == security.security_id:
                    add_node("corporate_actions", action.action_id, action)
                    add_edge("HAS_CORPORATE_ACTION", security.security_id, action.action_id, action_type=action.action_type, ex_date=action.ex_date)
            for intent in self.store.execution_intents.values():
                if intent.security_id == security.security_id:
                    add_node("execution_intents", intent.intent_id, intent)
                    add_edge("INTENT_ON", intent.intent_id, security.security_id, action=intent.action, target_weight=intent.target_weight)
            for proposal in self.store.portfolio_proposals.values():
                if security.security_id in proposal.universe or security.security_id in proposal.candidate_weights:
                    add_node("portfolio_proposals", proposal.proposal_id, proposal)
                    add_edge("PROPOSES_WEIGHT", proposal.proposal_id, security.security_id, weight=proposal.candidate_weights.get(security.security_id, 0.0))
            for event in self.store.disclosure_events.values():
                if event.security_id == security.security_id:
                    add_node("disclosure_events", event.event_id, event)
                    add_edge("EVENT_ON_SECURITY", event.event_id, security.security_id)

        def add_document_graph(document: Document) -> None:
            if security_filter_ids and document.security_id and document.security_id not in security_filter_ids:
                return
            add_node("documents", document.document_id, document)
            add_edge("DISCLOSES", document.issuer_id, document.document_id, as_of=to_plain(document.published_at), source_id=document.source_id)
            if document.security_id:
                add_edge("DISCLOSURE_FOR", document.document_id, document.security_id)
            for evidence in self.store.evidence.values():
                if evidence.document_id == document.document_id:
                    add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("HAS_EVIDENCE", document.document_id, evidence.evidence_id, page_no=evidence.page_no, bbox=evidence.bbox)
            for review in self.store.manual_reviews.values():
                if review.document_id == document.document_id:
                    add_node("manual_reviews", review.review_id, review)
                    add_edge("NEEDS_REVIEW", document.document_id, review.review_id, issue_type=review.issue_type, severity=review.severity, status=review.status)

        def add_thesis_graph(thesis: ThesisCard) -> None:
            add_node("theses", thesis.thesis_id, thesis)
            add_edge("HAS_THESIS", thesis.issuer_id, thesis.thesis_id, valid_from=to_plain(thesis.valid_from), valid_to=to_plain(thesis.valid_to))
            for supported_evidence_id in thesis.evidence_ids:
                evidence = self.store.evidence.get(supported_evidence_id)
                if evidence is None:
                    continue
                add_node("evidence", evidence.evidence_id, evidence)
                document = self.store.documents.get(evidence.document_id)
                if document is not None:
                    add_document_graph(document)
                add_edge("SUPPORTS", evidence.evidence_id, thesis.thesis_id, confidence=evidence.confidence)
            for signal in self.store.signals.values():
                if signal.thesis_id == thesis.thesis_id:
                    add_node("signals", signal.signal_id, signal)
                    add_edge("GENERATES_SIGNAL", thesis.thesis_id, signal.signal_id, score=signal.score, direction=signal.direction)
            for card in self.store.research_cards.values():
                if card.thesis_id == thesis.thesis_id:
                    add_node("research_cards", card.card_id, card)
                    add_edge("SUMMARIZED_BY", thesis.thesis_id, card.card_id, template_type=card.template_type)
            for challenger in self.store.challengers.values():
                if challenger.thesis_id == thesis.thesis_id:
                    add_node("challengers", challenger.challenger_id, challenger)
                    add_edge("CHALLENGES", challenger.challenger_id, thesis.thesis_id, conflict_score=challenger.conflict_score, verdict=challenger.verdict)

        def add_decision_graph(decision: DecisionPack) -> None:
            add_node("decisions", decision.decision_id, decision)
            thesis_ids: set[str] = set()
            evidence_ids: set[str] = set()
            for signal_id in decision.signal_ids:
                signal = self.store.signals.get(signal_id)
                if signal is None:
                    continue
                add_node("signals", signal.signal_id, signal)
                add_edge("INCLUDED_IN_DECISION", signal.signal_id, decision.decision_id, approval_state=decision.approval_state)
                thesis = self.store.theses.get(signal.thesis_id)
                if thesis is not None:
                    thesis_ids.add(thesis.thesis_id)
                    evidence_ids.update(thesis.evidence_ids)
                    add_thesis_graph(thesis)
            for intent in self.store.execution_intents.values():
                if intent.decision_id != decision.decision_id:
                    continue
                if security_filter_ids and intent.security_id and intent.security_id not in security_filter_ids:
                    continue
                add_node("execution_intents", intent.intent_id, intent)
                add_edge("CREATES_INTENT", decision.decision_id, intent.intent_id, approval_state=decision.approval_state)
                if intent.security_id:
                    add_edge("INTENT_ON", intent.intent_id, intent.security_id, action=intent.action, target_weight=intent.target_weight)
                    data["portfolio_positions"].append(
                        {
                            "intent_id": intent.intent_id,
                            "decision_id": decision.decision_id,
                            "security_id": intent.security_id,
                            "action": intent.action,
                            "target_weight": intent.target_weight,
                            "approval_state": decision.approval_state,
                            "thesis_ids": sorted(thesis_ids),
                            "evidence_ids": sorted(evidence_ids),
                            "risk_checks": list(decision.risk_checks),
                        }
                    )
            for review in self.store.reviews.values():
                if review.decision_id == decision.decision_id:
                    add_node("reviews", review.review_id, review)
                    add_edge("REVIEW_OF", review.review_id, decision.decision_id)
            for replay in self.store.strategy_replays.values():
                if replay.decision_id == decision.decision_id:
                    add_node("strategy_replays", replay.replay_id, replay)
                    add_edge("REPLAY_OF", replay.replay_id, decision.decision_id)
            for exception in self.store.exceptions.values():
                if exception.decision_id == decision.decision_id:
                    add_node("exceptions", exception.exception_id, exception)
                    add_edge("HAS_EXCEPTION", decision.decision_id, exception.exception_id, severity=exception.severity, status=exception.status)

        def add_research_task_graph(task: ResearchTask) -> None:
            if not task_in_scope(task):
                return
            add_node("research_tasks", task.task_id, task)
            if task.chain_id:
                add_edge("CHAIN_HAS_RESEARCH_TASK", task.chain_id, task.task_id, task_type=task.task_type, status=task.status, priority=task.priority)
            for node_id in task.node_ids:
                if task.chain_id:
                    add_edge("TASK_FOR_CHAIN_NODE", task.task_id, f"{task.chain_id}:{node_id}", task_type=task.task_type, status=task.status)
            if task.position_id:
                position = self.store.company_positions.get(task.position_id)
                if position is not None:
                    add_node("company_positions", position.position_id, position)
                    add_edge("TASK_FOR_COMPANY_POSITION", task.task_id, position.position_id, task_type=task.task_type, status=task.status)
            if task.issuer_id:
                issuer = self.store.issuers.get(task.issuer_id)
                if issuer is not None:
                    add_node("issuers", issuer.issuer_id, issuer)
                    add_edge("ISSUER_HAS_RESEARCH_TASK", issuer.issuer_id, task.task_id, task_type=task.task_type, status=task.status)
            for evidence_id in task.evidence_ids:
                evidence = self.store.evidence.get(evidence_id)
                if evidence is not None:
                    add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("TASK_BACKED_BY_EVIDENCE", task.task_id, evidence.evidence_id, confidence=evidence.confidence)

        def add_chain_graph(chain: IndustryChain, *, only_node_id: str = "") -> None:
            add_node("industry_chains", chain.chain_id, chain)
            if chain.root_theme_id:
                theme = self.store.macro_themes.get(chain.root_theme_id)
                if theme is not None:
                    add_node("macro_themes", theme.theme_id, theme)
                    add_edge("HAS_INDUSTRY_CHAIN", theme.theme_id, chain.chain_id, source="industry_chain_registry", confidence=theme.confidence)
            scoped_node_ids: set[str] = set()
            if security_filter_ids:
                for position in self.store.company_positions.values():
                    if position.chain_id != chain.chain_id or not position_in_scope(position):
                        continue
                    scoped_node_ids.update(str(node_id).strip() for node_id in position.node_ids if str(node_id).strip())
                if only_node_id:
                    scoped_node_ids &= {only_node_id}
            node_ids: set[str] = set()
            for node in chain.nodes:
                node_id = str(node.get("node_id", "")).strip()
                if only_node_id and node_id != only_node_id:
                    continue
                if scoped_node_ids and node_id not in scoped_node_ids:
                    continue
                if not node_id:
                    continue
                node_payload = {**node, "chain_id": chain.chain_id}
                add_node("chain_nodes", f"{chain.chain_id}:{node_id}", node_payload)
                add_edge("HAS_CHAIN_NODE", chain.chain_id, f"{chain.chain_id}:{node_id}", level=node.get("level", ""), category=node.get("category", ""))
                node_ids.add(node_id)
            for edge in chain.edges:
                source_node_id = str(edge.get("source_node_id", "")).strip()
                target_node_id = str(edge.get("target_node_id", "")).strip()
                if source_node_id in node_ids and target_node_id in node_ids:
                    add_edge(
                        str(edge.get("relation_type", "CHAIN_LINK")),
                        f"{chain.chain_id}:{source_node_id}",
                        f"{chain.chain_id}:{target_node_id}",
                        direction=edge.get("direction", ""),
                        strength=edge.get("strength", ""),
                        source="industry_chain_registry",
                        confidence=float(edge.get("confidence", 0.7) or 0.0),
                    )
            for position in self.store.company_positions.values():
                if position.chain_id != chain.chain_id:
                    continue
                if only_node_id and only_node_id not in position.node_ids:
                    continue
                if not position_in_scope(position):
                    continue
                add_node("company_positions", position.position_id, position)
                add_edge("HAS_COMPANY_POSITION", chain.chain_id, position.position_id, role=position.role, data_quality=position.data_quality)
                issuer = self.store.issuers.get(position.issuer_id)
                if issuer is not None:
                    add_node("issuers", issuer.issuer_id, issuer)
                    add_edge("POSITIONED_AS", issuer.issuer_id, position.position_id, role=position.role, data_quality=position.data_quality)
                if position.security_id:
                    security = self.store.securities.get(position.security_id)
                    if security is not None:
                        add_node("securities", security.security_id, security)
                        add_edge("SECURITY_FOR_POSITION", position.position_id, security.security_id)
                for node_id in position.node_ids:
                    if not only_node_id or node_id == only_node_id:
                        add_edge("POSITION_IN_CHAIN_NODE", position.position_id, f"{chain.chain_id}:{node_id}", role=position.role, confidence=0.8)
                for linked_evidence_id in position.evidence_ids:
                    evidence = self.store.evidence.get(linked_evidence_id)
                    if evidence is not None:
                        add_node("evidence", evidence.evidence_id, evidence)
                        add_edge("POSITION_EVIDENCE", linked_evidence_id, position.position_id, confidence=evidence.confidence)
            for task in self.store.research_tasks.values():
                if task.chain_id != chain.chain_id:
                    continue
                if only_node_id and only_node_id not in task.node_ids:
                    continue
                if not task_in_scope(task):
                    continue
                add_research_task_graph(task)

        def add_issuer_graph(issuer: Issuer) -> None:
            add_node("issuers", issuer.issuer_id, issuer)
            for mapping in self.store.entity_mappings.values():
                if mapping.issuer_id == issuer.issuer_id:
                    add_node("entity_mappings", mapping.mapping_id, mapping)
                    add_edge(
                        "HAS_MAPPING",
                        issuer.issuer_id,
                        mapping.mapping_id,
                        market=mapping.market,
                        ticker=mapping.ticker,
                        source=mapping.source,
                        version=mapping.version,
                        valid_from=to_plain(mapping.valid_from),
                        valid_to=to_plain(mapping.valid_to),
                        recorded_at=to_plain(mapping.recorded_at),
                        status=mapping.status,
                        confidence=mapping.confidence,
                    )
            issuer_security_ids: set[str] = set()
            for security in self.store.securities.values():
                if security.issuer_id == issuer.issuer_id:
                    if not security_in_scope(security.security_id):
                        continue
                    issuer_security_ids.add(security.security_id)
                    add_node("securities", security.security_id, security)
                    add_edge("ISSUES", issuer.issuer_id, security.security_id, market=security.market, ticker=security.ticker)
            for scoped_security_id in sorted(issuer_security_ids):
                security = self.store.securities.get(scoped_security_id)
                if security is not None:
                    add_security_facts(security)
            for document in self.store.documents.values():
                if document.issuer_id == issuer.issuer_id:
                    add_document_graph(document)
            for event in self.store.disclosure_events.values():
                if event.issuer_id == issuer.issuer_id:
                    if security_filter_ids and event.security_id and event.security_id not in security_filter_ids:
                        continue
                    add_node("disclosure_events", event.event_id, event)
                    add_edge("HAS_DISCLOSURE_EVENT", issuer.issuer_id, event.event_id, event_type=event.event_type, severity=event.severity)
                    add_edge("EVENT_FROM_DOCUMENT", event.event_id, event.document_id, source_id=event.source_id)
                    if event.security_id:
                        add_edge("EVENT_ON_SECURITY", event.event_id, event.security_id)
                    for event_evidence_id in event.evidence_ids:
                        add_edge("EVENT_EVIDENCE", event.event_id, event_evidence_id)
            profile = self.store.company_profiles.get(issuer.issuer_id)
            if profile is not None:
                add_node("company_profiles", profile.issuer_id, profile)
                add_edge("HAS_COMPANY_PROFILE", issuer.issuer_id, profile.issuer_id, source="company_profile", confidence=1.0)
            for company_event in self.store.company_events.values():
                if company_event.issuer_id != issuer.issuer_id:
                    continue
                if security_filter_ids and company_event.security_id and company_event.security_id not in security_filter_ids:
                    continue
                add_node("company_events", company_event.event_id, company_event)
                add_edge("HAS_COMPANY_EVENT", issuer.issuer_id, company_event.event_id, event_type=company_event.event_type, confidence=company_event.confidence)
                if company_event.security_id:
                    add_edge("EVENT_ON_SECURITY", company_event.event_id, company_event.security_id)
                for document_id in company_event.document_ids:
                    add_edge("EVENT_FROM_DOCUMENT", company_event.event_id, document_id)
                for evidence_id in company_event.evidence_ids:
                    evidence = self.store.evidence.get(evidence_id)
                    if evidence is not None:
                        add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("EVENT_EVIDENCE", company_event.event_id, evidence_id, confidence=company_event.confidence)
            for relationship in self.store.company_relationships.values():
                if relationship.issuer_id != issuer.issuer_id and relationship.subject_id != issuer.issuer_id and relationship.object_id != issuer.issuer_id:
                    continue
                if security_filter_ids and relationship.security_id and relationship.security_id not in security_filter_ids:
                    continue
                add_node("company_relationships", relationship.relationship_id, relationship)
                add_edge("HAS_COMPANY_RELATIONSHIP", issuer.issuer_id, relationship.relationship_id, relationship_type=relationship.relationship_type, confidence=relationship.confidence)
                add_edge("RELATIONSHIP_SUBJECT", relationship.relationship_id, relationship.subject_id, subject_type=relationship.subject_type, confidence=relationship.confidence)
                add_edge("RELATIONSHIP_OBJECT", relationship.relationship_id, relationship.object_id, object_type=relationship.object_type, confidence=relationship.confidence)
                for evidence_id in relationship.evidence_ids:
                    evidence = self.store.evidence.get(evidence_id)
                    if evidence is not None:
                        add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("RELATIONSHIP_EVIDENCE", relationship.relationship_id, evidence_id, confidence=relationship.confidence)
            structured_report_ids: set[str] = set()
            viewpoint_ids: set[str] = set()
            for report in self.store.structured_research_reports.values():
                if report.issuer_id != issuer.issuer_id:
                    continue
                if security_filter_ids and report.security_id and report.security_id not in security_filter_ids:
                    continue
                structured_report_ids.add(report.research_report_id)
                add_node("structured_research_reports", report.research_report_id, report)
                add_edge("COVERED_BY_REPORT", issuer.issuer_id, report.research_report_id, source=report.source_id, confidence=0.7)
                for analyst_id in report.analyst_ids:
                    analyst = self.store.analyst_profiles.get(analyst_id)
                    if analyst is not None:
                        add_node("analyst_profiles", analyst.analyst_id, analyst)
                    add_edge("ANALYST_COVERS", analyst_id, issuer.issuer_id, source=report.source_id, confidence=0.7)
            for viewpoint in self.store.report_viewpoints.values():
                if viewpoint.issuer_id != issuer.issuer_id and viewpoint.research_report_id not in structured_report_ids:
                    continue
                if security_filter_ids and viewpoint.security_id and viewpoint.security_id not in security_filter_ids:
                    continue
                viewpoint_ids.add(viewpoint.viewpoint_id)
                add_node("report_viewpoints", viewpoint.viewpoint_id, viewpoint)
                add_edge("REPORT_HAS_VIEWPOINT", viewpoint.research_report_id, viewpoint.viewpoint_id, stance=viewpoint.stance, confidence=0.6)
                add_edge("VIEWPOINT_ON_COMPANY", viewpoint.viewpoint_id, issuer.issuer_id, stance=viewpoint.stance, target_price=viewpoint.target_price)
                for evidence_id in viewpoint.evidence_ids:
                    evidence = self.store.evidence.get(evidence_id)
                    if evidence is not None:
                        add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("VIEWPOINT_EVIDENCE", viewpoint.viewpoint_id, evidence_id, confidence=0.6)
            for forecast in self.store.report_forecasts.values():
                if forecast.issuer_id != issuer.issuer_id and forecast.research_report_id not in structured_report_ids and forecast.viewpoint_id not in viewpoint_ids:
                    continue
                if security_filter_ids and forecast.security_id and forecast.security_id not in security_filter_ids:
                    continue
                add_node("report_forecasts", forecast.forecast_id, forecast)
                if forecast.viewpoint_id:
                    add_edge("VIEWPOINT_HAS_FORECAST", forecast.viewpoint_id, forecast.forecast_id, forecast_type=forecast.forecast_type, confidence=0.6)
                add_edge("FORECAST_ON_COMPANY", forecast.forecast_id, issuer.issuer_id, forecast_type=forecast.forecast_type, realization_status=forecast.realization_status)
            for score in self.store.analyst_reliability_scores.values():
                if score.issuer_id and score.issuer_id != issuer.issuer_id:
                    continue
                if not score.issuer_id and score.analyst_id not in {analyst_id for report in self.store.structured_research_reports.values() if report.issuer_id == issuer.issuer_id for analyst_id in report.analyst_ids}:
                    continue
                add_node("analyst_reliability_scores", score.score_id, score)
                add_edge("SCORES_ANALYST", score.score_id, score.analyst_id, period=score.period, confidence=score.forecast_review_coverage)
            observation_ids: set[str] = set()
            for observation in self.store.observation_items.values():
                if observation.issuer_id != issuer.issuer_id:
                    continue
                observation_ids.add(observation.observation_id)
                add_node("observation_items", observation.observation_id, observation)
                add_edge("OBSERVES_COMPANY", observation.observation_id, issuer.issuer_id, status=observation.status, priority=observation.priority)
                for event_id in observation.related_event_ids:
                    add_edge("OBSERVES_EVENT", observation.observation_id, event_id, status=observation.status)
                for related_viewpoint_id in observation.related_viewpoint_ids:
                    add_edge("OBSERVES_VIEWPOINT", observation.observation_id, related_viewpoint_id, status=observation.status)
            conclusion_ids: set[str] = set()
            for conclusion in self.store.analysis_conclusions.values():
                if conclusion.issuer_id != issuer.issuer_id and not set(conclusion.related_observation_ids).intersection(observation_ids):
                    continue
                conclusion_ids.add(conclusion.analysis_conclusion_id)
                add_node("analysis_conclusions", conclusion.analysis_conclusion_id, conclusion)
                add_edge("CONCLUSION_ON_COMPANY", conclusion.analysis_conclusion_id, issuer.issuer_id, status=conclusion.status, confidence=conclusion.confidence)
                for evidence_id in conclusion.supporting_evidence_ids:
                    evidence = self.store.evidence.get(evidence_id)
                    if evidence is not None:
                        add_node("evidence", evidence.evidence_id, evidence)
                    add_edge("CONCLUSION_USES_EVIDENCE", conclusion.analysis_conclusion_id, evidence_id, confidence=conclusion.confidence)
                for related_viewpoint_id in conclusion.related_viewpoint_ids:
                    add_edge("CONCLUSION_REFERENCES_VIEWPOINT", conclusion.analysis_conclusion_id, related_viewpoint_id, confidence=conclusion.confidence)
            for feedback in self.store.simulation_feedback.values():
                if feedback.issuer_id != issuer.issuer_id and feedback.analysis_conclusion_id not in conclusion_ids:
                    continue
                if security_filter_ids and feedback.security_id and feedback.security_id not in security_filter_ids:
                    continue
                add_node("simulation_feedback", feedback.simulation_feedback_id, feedback)
                add_edge("FEEDBACK_FOR_CONCLUSION", feedback.simulation_feedback_id, feedback.analysis_conclusion_id, feedback_type=feedback.feedback_type, confidence=1.0)
                if feedback.observation_id:
                    add_edge("FEEDBACK_REFERENCES_OBSERVATION", feedback.simulation_feedback_id, feedback.observation_id, feedback_type=feedback.feedback_type)
                if feedback.security_id:
                    add_edge("FEEDBACK_ON_SECURITY", feedback.simulation_feedback_id, feedback.security_id, simulated_action=feedback.simulated_action)
            for thesis in self.store.theses.values():
                if thesis.issuer_id == issuer.issuer_id:
                    add_thesis_graph(thesis)
            for decision in self.store.decisions.values():
                for signal_id in decision.signal_ids:
                    signal = self.store.signals.get(signal_id)
                    thesis = self.store.theses.get(signal.thesis_id) if signal else None
                    if thesis and thesis.issuer_id == issuer.issuer_id:
                        add_decision_graph(decision)
                        break
            for intent in self.store.execution_intents.values():
                if intent.security_id in issuer_security_ids:
                    decision = self.store.decisions.get(intent.decision_id)
                    if decision is not None:
                        add_decision_graph(decision)
                    else:
                        add_node("execution_intents", intent.intent_id, intent)
                        add_edge("INTENT_ON", intent.intent_id, intent.security_id, action=intent.action, target_weight=intent.target_weight)
            for holding in self.store.institutional_holdings.values():
                if holding.issuer_id == issuer.issuer_id:
                    if security_filter_ids and holding.security_id not in security_filter_ids:
                        continue
                    add_node("institutional_holdings", holding.holding_id, holding)
                    add_edge("HAS_13F_HOLDING", issuer.issuer_id, holding.holding_id, report_period=holding.report_period, value_usd=holding.value_usd)
                    add_edge("HOLDS_SECURITY", holding.holding_id, holding.security_id, shares=holding.shares, value_usd=holding.value_usd)
            for snapshot in self.store.crowding.values():
                if snapshot.issuer_id == issuer.issuer_id:
                    add_node("crowding", snapshot.snapshot_id, snapshot)
                    add_edge("HAS_CROWDING", issuer.issuer_id, snapshot.snapshot_id, source=snapshot.source, score=snapshot.score)
                    if snapshot.source.upper() == "13F":
                        for holding in self.store.institutional_holdings.values():
                            if holding.issuer_id == issuer.issuer_id:
                                if security_filter_ids and holding.security_id not in security_filter_ids:
                                    continue
                                add_edge("CONTRIBUTES_TO_CROWDING", holding.holding_id, snapshot.snapshot_id, report_period=holding.report_period)
            for proposal in self.store.portfolio_proposals.values():
                proposal_security_ids = set(proposal.universe) | set(proposal.candidate_weights)
                if proposal_security_ids & issuer_security_ids:
                    add_node("portfolio_proposals", proposal.proposal_id, proposal)
                    add_edge("HAS_PORTFOLIO_PROPOSAL", issuer.issuer_id, proposal.proposal_id, status=proposal.status)
                    for proposal_security_id, weight in proposal.candidate_weights.items():
                        if proposal_security_id in issuer_security_ids:
                            add_edge("PROPOSES_WEIGHT", proposal.proposal_id, proposal_security_id, weight=weight)
            for position in self.store.company_positions.values():
                if position.issuer_id == issuer.issuer_id:
                    if not position_in_scope(position):
                        continue
                    chain = self.store.industry_chains.get(position.chain_id)
                    if chain is not None:
                        add_chain_graph(chain)
            for task in self.store.research_tasks.values():
                if task.issuer_id == issuer.issuer_id:
                    if not task_in_scope(task):
                        continue
                    add_research_task_graph(task)

        if issuer_id:
            issuer = self.store.issuers.get(issuer_id)
            if issuer:
                add_issuer_graph(issuer)
        if security_id:
            security = self.store.securities.get(security_id)
            if security:
                add_node("securities", security.security_id, security)
                issuer = self.store.issuers.get(security.issuer_id)
                if issuer:
                    add_issuer_graph(issuer)
                else:
                    add_security_facts(security)
        if evidence_id:
            evidence = self.store.evidence.get(evidence_id)
            if evidence:
                add_node("evidence", evidence.evidence_id, evidence)
                document = self.store.documents.get(evidence.document_id)
                if document is not None:
                    add_document_graph(document)
                    issuer = self.store.issuers.get(document.issuer_id)
                    if issuer:
                        add_node("issuers", issuer.issuer_id, issuer)
                for thesis in self.store.theses.values():
                    if evidence.evidence_id in thesis.evidence_ids:
                        add_thesis_graph(thesis)
        if thesis_id:
            thesis = self.store.theses.get(thesis_id)
            if thesis:
                add_thesis_graph(thesis)
                issuer = self.store.issuers.get(thesis.issuer_id)
                if issuer:
                    add_node("issuers", issuer.issuer_id, issuer)
                for decision in self.store.decisions.values():
                    if any((self.store.signals.get(signal_id) and self.store.signals[signal_id].thesis_id == thesis.thesis_id) for signal_id in decision.signal_ids):
                        add_decision_graph(decision)
        if decision_id:
            decision = self.store.decisions.get(decision_id)
            if decision:
                add_decision_graph(decision)
        if theme_id:
            theme = self.store.macro_themes.get(theme_id)
            if theme:
                add_node("macro_themes", theme.theme_id, theme)
                for chain in self.store.industry_chains.values():
                    if chain.root_theme_id == theme.theme_id:
                        add_chain_graph(chain, only_node_id=chain_node_id)
        if chain_id:
            chain = self.store.industry_chains.get(chain_id)
            if chain:
                add_chain_graph(chain, only_node_id=chain_node_id)
        if graph_limit:
            for collection, values in data.items():
                if len(values) <= graph_limit:
                    continue
                data[collection] = values[:graph_limit]
        return data

    def graph_neo4j_export(self, filters: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        filters = filters or {}
        graph = self.query_graph(filters)
        node_refs: dict[str, str] = {}
        nodes: list[dict[str, Any]] = []
        for collection, values in graph.items():
            if collection == "edges" or not isinstance(values, list):
                continue
            for row in values:
                if not isinstance(row, Mapping):
                    continue
                object_id = self._graph_node_identity(collection, row)
                if not object_id:
                    continue
                node_id = f"{collection}:{object_id}"
                node_refs.setdefault(object_id, node_id)
                nodes.append(
                    {
                        "id": node_id,
                        "labels": ["AIQuant", self._neo4j_label(collection)],
                        "properties": self._neo4j_properties(row, {"collection": collection, "ai_quant_id": object_id}),
                    }
                )
        relationships: list[dict[str, Any]] = []
        for edge in graph.get("edges", []):
            if not isinstance(edge, Mapping):
                continue
            start_ref = str(edge.get("from", ""))
            end_ref = str(edge.get("to", ""))
            relationships.append(
                {
                    "type": self._neo4j_relationship_type(str(edge.get("type", "RELATED_TO"))),
                    "start_id": node_refs.get(start_ref, start_ref),
                    "end_id": node_refs.get(end_ref, end_ref),
                    "properties": self._neo4j_properties(edge, {"source_ref": start_ref, "target_ref": end_ref}),
                }
            )
        payload = {
            "adapter": {
                "format": "neo4j_bulk_upsert_compatible",
                "node_key": "id",
                "relationship_key": ["type", "start_id", "end_id"],
                "external_sync_required": True,
                "submission_boundary": "payload_export_only_no_external_neo4j_call",
            },
            "node_count": len(nodes),
            "relationship_count": len(relationships),
            "nodes": nodes,
            "relationships": relationships,
            "payload_filter": {
                "issuer_id": str(filters.get("issuer_id", "")).strip(),
                "security_id": str(filters.get("security_id", "")).strip(),
                "evidence_id": str(filters.get("evidence_id", "")).strip(),
                "thesis_id": str(filters.get("thesis_id", "")).strip(),
                "decision_id": str(filters.get("decision_id", "")).strip(),
            },
            "rights_boundary": "inherits_graph_node_and_edge_source_metadata",
        }
        if self._truthy(filters.get("record_export", False)):
            self._audit(
                actor,
                "export_neo4j_graph_payload",
                "graph",
                payload["payload_filter"]["issuer_id"] or payload["payload_filter"]["security_id"] or "all",
                source="neo4j_adapter",
                approval_state=f"nodes={len(nodes)};relationships={len(relationships)}",
            )
        payload["content_sha256"] = self._payload_sha256(payload)
        return payload

    def create_graph_adapter_sync_notifications(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        export = self.graph_neo4j_export(payload, actor=actor)
        channel = str(payload.get("channel", "neo4j_graph_sync_outbox")).strip() or "neo4j_graph_sync_outbox"
        target = str(payload.get("target", "neo4j://graph-db")).strip()
        force = self._truthy(payload.get("force", False))
        mark_sent = self._truthy(payload.get("mark_sent", False))
        notification_id = str(payload.get("notification_id") or f"aln_neo4j_{export['content_sha256'][:16]}")
        skipped: list[dict[str, Any]] = []
        notifications: list[AlertNotification] = []
        if notification_id in self.store.alert_notifications and not force:
            skipped.append({"notification_id": notification_id, "reason": "already_exists"})
        else:
            notification = AlertNotification(
                notification_id=notification_id,
                alert_id="neo4j_graph_sync",
                channel=channel,
                target=target,
                status="sent" if mark_sent else "pending",
                payload={
                    "type": "graph_neo4j_sync",
                    "format": export["adapter"]["format"],
                    "content_sha256": export["content_sha256"],
                    "node_count": export["node_count"],
                    "relationship_count": export["relationship_count"],
                    "graph": export,
                    "delivery_policy": {
                        "provider": str(payload.get("provider", "dry-run-sender")),
                        "max_attempts": int(payload.get("max_delivery_attempts", 3)),
                        "backoff": str(payload.get("delivery_backoff", "manual_or_external_sender")),
                    },
                },
            )
            self.store.alert_notifications[notification.notification_id] = notification
            notifications.append(notification)
        self._audit(
            actor,
            "enqueue_neo4j_graph_sync",
            "graph",
            str(payload.get("issuer_id") or payload.get("security_id") or "batch"),
            source="neo4j_adapter",
            approval_state=f"notifications={len(notifications)};skipped={len(skipped)}",
        )
        return {
            "adapter": export["adapter"],
            "channel": channel,
            "target": target,
            "count": len(notifications),
            "skipped_count": len(skipped),
            "notifications": [to_plain(item) for item in notifications],
            "skipped": skipped,
            "external_delivery_ready": bool(target),
        }

    def search(self, filters: Mapping[str, Any]) -> dict[str, Any]:
        query = str(filters.get("q", "")).strip()
        if not query:
            return {"query": query, "results": []}
        issuer_filter = str(filters.get("issuer_id", "")).strip()
        limit = self._bounded_limit(filters.get("limit", 20))
        terms = [term.lower() for term in re.findall(r"[\w\u4e00-\u9fff]+", query)]
        if not terms:
            return {"query": query, "results": []}
        records = self._search_records()
        try:
            sync_result = self.search_index.sync(records)
            results = self.search_index.search(records, query=query, issuer_id=issuer_filter, limit=limit)
            return {"query": query, "backend": self.search_index.backend, "sync": sync_result, "results": results}
        except Exception as exc:
            if self.search_index.backend != "local" and self.search_fallback:
                results = self.local_search_index.search(records, query=query, issuer_id=issuer_filter, limit=limit)
                return {
                    "query": query,
                    "backend": "local",
                    "fallback_from": self.search_index.backend,
                    "fallback_error": str(exc),
                    "results": results,
                }
            raise

    def rebuild_search_indexes(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        issuer_filter = str(payload.get("issuer_id", "")).strip()
        resource_types = {str(item).strip() for item in payload.get("resource_types", []) if str(item).strip()} if isinstance(payload.get("resource_types", []), list) else set()
        include_restricted = self._truthy(payload.get("include_restricted", False))
        targets = {str(item).strip().lower() for item in payload.get("targets", ["keyword", "semantic"]) if str(item).strip()}
        if not targets <= {"keyword", "search", "semantic"}:
            raise ValidationError("search rebuild targets must be keyword/search and/or semantic")
        records = self._search_records()
        if issuer_filter:
            records = [record for record in records if record.issuer_id == issuer_filter]
        if resource_types:
            records = [record for record in records if record.resource_type in resource_types]
        if not include_restricted:
            records = [record for record in records if self._search_record_boundary(record)["risk_level"] != "restricted"]
        resource_counts: dict[str, int] = {}
        for record in records:
            resource_counts[record.resource_type] = resource_counts.get(record.resource_type, 0) + 1

        sync_results: dict[str, Any] = {}
        errors: list[dict[str, Any]] = []
        if {"keyword", "search"} & targets:
            try:
                sync_results["keyword"] = self.search_index.sync(records)
            except Exception as exc:
                if self.search_index.backend != "local" and self.search_fallback:
                    sync_results["keyword"] = {
                        **self.local_search_index.sync(records),
                        "fallback_from": self.search_index.backend,
                        "fallback_error": str(exc),
                    }
                else:
                    errors.append({"target": "keyword", "backend": self.search_index.backend, "error": str(exc)})
        if "semantic" in targets:
            try:
                sync_results["semantic"] = self.semantic_index.sync(records)
            except Exception as exc:
                errors.append({"target": "semantic", "backend": self.semantic_index.backend, "error": str(exc)})
        status = "ok" if not errors else "partial_failed" if sync_results else "failed"
        self._audit(
            actor,
            "rebuild_search_indexes",
            "search_index",
            issuer_filter or "all",
            source="search_rebuild",
            approval_state=f"{status};records={len(records)};errors={len(errors)}",
        )
        return {
            "status": status,
            "record_count": len(records),
            "resource_counts": resource_counts,
            "targets": sorted(targets),
            "sync": sync_results,
            "errors": errors,
            "rights_filter": "restricted_excluded" if not include_restricted else "include_restricted",
            "payload_filter": {"issuer_id": issuer_filter, "resource_types": sorted(resource_types)},
        }

    def semantic_search(self, filters: Mapping[str, Any]) -> dict[str, Any]:
        query = str(filters.get("q", "")).strip()
        if not query:
            return {"query": query, "results": []}
        issuer_filter = str(filters.get("issuer_id", "")).strip()
        resource_types = {str(item).strip() for item in filters.get("resource_types", []) if str(item).strip()} if isinstance(filters.get("resource_types", []), list) else set()
        include_restricted = self._truthy(filters.get("include_restricted", False))
        limit = self._bounded_limit(filters.get("limit", 20))
        records = self._search_records()
        if resource_types:
            records = [record for record in records if record.resource_type in resource_types]
        if not include_restricted:
            records = [record for record in records if self._search_record_boundary(record)["risk_level"] != "restricted"]
        sync_result = self.semantic_index.sync(records)
        results = self.semantic_index.search(records, query=query, issuer_id=issuer_filter, limit=limit)
        enriched_results = []
        for item in results:
            boundary = self._search_record_boundary_by_ref(str(item["resource_type"]), str(item["resource_id"]))
            enriched = dict(item)
            enriched["source_boundary"] = boundary["source_boundary"]
            enriched["rights_tag"] = boundary["rights_tag"]
            enriched["risk_level"] = boundary["risk_level"]
            if boundary["risk_level"] == "restricted":
                enriched["snippet"] = self._citation_limited_text(str(enriched.get("snippet", "")), source_publicness="restricted", char_limit=160)[0]
            enriched_results.append(enriched)
        return {
            "query": query,
            "backend": self.semantic_index.backend,
            "sync": sync_result,
            "results": enriched_results,
            "rights_filter": "inherits_search_record_scope",
            "payload_filter": {"issuer_id": issuer_filter, "resource_types": sorted(resource_types), "include_restricted": include_restricted},
        }

    def semantic_rerank(self, filters: Mapping[str, Any]) -> dict[str, Any]:
        query = str(filters.get("q", "")).strip()
        if not query:
            return {"query": query, "results": []}
        include_restricted = self._truthy(filters.get("include_restricted", False))
        candidate_limit = self._bounded_limit(filters.get("candidate_limit", filters.get("limit", 20)), max_value=200)
        limit = self._bounded_limit(filters.get("limit", 10), max_value=100)
        search_result = self.semantic_search({**filters, "limit": candidate_limit, "include_restricted": include_restricted})
        terms = [term.lower() for term in re.findall(r"[\w\u4e00-\u9fff]+", query) if term.strip()]
        records_by_ref = {(record.resource_type, record.resource_id): record for record in self._search_records()}
        reranked: list[dict[str, Any]] = []
        for item in search_result["results"]:
            record = records_by_ref.get((str(item["resource_type"]), str(item["resource_id"])))
            score_row = self._semantic_rerank_score(query_terms=terms, candidate=item, record=record)
            enriched = dict(item)
            enriched.update(score_row)
            if enriched.get("risk_level") == "restricted":
                enriched["requires_manual_boundary_review"] = True
            reranked.append(enriched)
        reranked.sort(key=lambda item: (-float(item["rerank_score"]), str(item["resource_type"]), str(item["resource_id"])))
        return {
            "query": query,
            "backend": self.semantic_index.backend,
            "embedding_backend": self.semantic_index.describe(),
            "reranker": "local_term_coverage_weighted_score",
            "candidate_count": len(search_result["results"]),
            "returned_count": min(limit, len(reranked)),
            "results": reranked[:limit],
            "rights_filter": "restricted_excluded" if not include_restricted else "include_restricted_with_boundary_flags",
            "payload_filter": search_result["payload_filter"],
            "adapter_recommendation": {
                "current_phase": "local_embedding_and_rerank_contract",
                "vector_adapter_trigger": "large corpus, latency targets, or ANN recall requirements require Qdrant or equivalent vector store",
                "reranker_trigger": "benchmark recall or precision drops, multilingual ambiguity, or dense candidate pools require a dedicated reranker model",
            },
        }

    def semantic_llm_rerank(self, filters: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        query = str(filters.get("q", "")).strip()
        if not query:
            return {"query": query, "results": []}
        local_result = self.semantic_rerank(filters)
        candidate_rows = list(local_result.get("results", []))
        limit = self._bounded_limit(filters.get("limit", 10), max_value=100)
        llm_run: LLMTaskRun | None = None
        ordered_ids: list[str] = []
        parse_error = ""
        if self._truthy(filters.get("run_model", True)) and candidate_rows:
            if "llmtpl_search_rerank_v1" not in self.store.llm_task_templates:
                self.seed_default_llm_task_templates(actor=actor)
            llm_run = self.run_llm_task(
                {
                    "run_id": str(filters.get("llm_run_id", new_id("llmrun_search_rerank"))),
                    "template_id": "llmtpl_search_rerank_v1",
                    "role": str(filters.get("template_role", "分析师")),
                    "variables": {
                        "query": query,
                        "candidate_rows": self._semantic_llm_candidate_rows(candidate_rows),
                    },
                    "temperature": float(filters.get("temperature", 0.0)),
                    "human_review_required": True,
                },
                actor=actor,
            )
            ordered_ids, parse_error = self._semantic_llm_ordered_resource_ids(llm_run, candidate_rows)

        rows_by_id = {self._semantic_candidate_ref(item): dict(item) for item in candidate_rows}
        results: list[dict[str, Any]] = []
        seen: set[str] = set()
        rank = 1
        if llm_run and llm_run.status == "succeeded" and ordered_ids and not parse_error:
            for resource_id in ordered_ids:
                candidate = rows_by_id.get(resource_id)
                if not candidate or resource_id in seen:
                    continue
                candidate["llm_rank"] = rank
                candidate["rerank_source"] = "llm"
                results.append(candidate)
                seen.add(resource_id)
                rank += 1
        for item in candidate_rows:
            resource_id = self._semantic_candidate_ref(item)
            if resource_id in seen:
                continue
            candidate = dict(item)
            candidate["llm_rank"] = rank
            candidate["rerank_source"] = "local_fallback" if llm_run else "local_only"
            results.append(candidate)
            seen.add(resource_id)
            rank += 1
        results = results[:limit]
        fallback_used = ""
        if llm_run and llm_run.fallback_used:
            fallback_used = llm_run.fallback_used
        elif llm_run and (llm_run.status != "succeeded" or parse_error):
            fallback_used = "local_rerank"
        elif not llm_run:
            fallback_used = "local_rerank"
        self._audit(
            actor,
            "semantic_llm_rerank",
            "search_index",
            query[:80] or "empty_query",
            source="semantic_search",
            version=llm_run.prompt_version if llm_run else "local-only",
            model_version=llm_run.model if llm_run else "local-rerank",
            prompt_version=llm_run.prompt_version if llm_run else "local-only",
            approval_state=llm_run.status if llm_run else "local_only",
        )
        return {
            "query": query,
            "backend": local_result.get("backend", self.semantic_index.backend),
            "embedding_backend": local_result.get("embedding_backend", self.semantic_index.describe()),
            "reranker": "llm_semantic_rerank_with_local_fallback",
            "candidate_count": local_result.get("candidate_count", len(candidate_rows)),
            "returned_count": len(results),
            "results": results,
            "llm_run": to_plain(llm_run) if llm_run else None,
            "llm_ordered_resource_ids": ordered_ids,
            "parse_error": parse_error,
            "fallback_used": fallback_used,
            "human_review_required": True,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "llm_rerank_is_ordering_assist_only_not_fact_or_trade_signal",
            "rights_filter": local_result.get("rights_filter", ""),
            "payload_filter": local_result.get("payload_filter", {}),
            "adapter_recommendation": {
                **dict(local_result.get("adapter_recommendation", {})),
                "llm_rerank_contract": "replace local fallback with approved reranker only after benchmark and human review gates pass",
            },
        }

    def semantic_llm_rerank_benchmark(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        samples = payload.get("samples", [])
        if not isinstance(samples, list) or not samples:
            raise ValidationError("semantic llm rerank benchmark requires samples list")
        sample_limit = self._bounded_limit(payload.get("sample_limit", len(samples)), max_value=500)
        candidate_limit = self._bounded_limit(payload.get("candidate_limit", 20), max_value=200)
        result_limit = self._bounded_limit(payload.get("limit", 10), max_value=100)
        run_model = self._truthy(payload.get("run_model", True))
        rows: list[dict[str, Any]] = []
        top1_hits = 0
        covered = 0
        reciprocal_sum = 0.0
        fallback_count = 0
        parse_error_count = 0
        llm_count = 0
        for index, sample in enumerate(samples[:sample_limit]):
            if not isinstance(sample, Mapping):
                continue
            query = str(sample.get("q", sample.get("query", ""))).strip()
            expected_refs = self._semantic_expected_refs(sample)
            if not query or not expected_refs:
                rows.append({"index": index, "query": query, "expected_resource_refs": expected_refs, "status": "invalid_sample", "hit": False})
                continue
            rerank = self.semantic_llm_rerank(
                {
                    "q": query,
                    "issuer_id": str(sample.get("issuer_id", "")),
                    "resource_types": sample.get("resource_types", []),
                    "include_restricted": sample.get("include_restricted", False),
                    "candidate_limit": int(sample.get("candidate_limit", candidate_limit)),
                    "limit": int(sample.get("limit", result_limit)),
                    "run_model": run_model,
                    "llm_run_id": str(sample.get("llm_run_id", f"llmrun_rerank_bm_{index}")),
                },
                actor=actor,
            )
            returned_refs = [self._semantic_candidate_ref(item) for item in rerank.get("results", [])]
            rank = next((position + 1 for position, ref in enumerate(returned_refs) if ref in expected_refs), 0)
            hit = rank == 1
            top1_hits += 1 if hit else 0
            covered += 1 if rank else 0
            reciprocal_sum += (1.0 / rank) if rank else 0.0
            fallback = str(rerank.get("fallback_used", ""))
            fallback_count += 1 if fallback else 0
            parse_error_count += 1 if rerank.get("parse_error") else 0
            llm_count += 1 if any(item.get("rerank_source") == "llm" for item in rerank.get("results", [])) else 0
            rows.append(
                {
                    "index": index,
                    "query": query,
                    "expected_resource_refs": expected_refs,
                    "returned_resource_refs": returned_refs,
                    "rank": rank,
                    "hit": hit,
                    "covered": bool(rank),
                    "reciprocal_rank": round((1.0 / rank) if rank else 0.0, 6),
                    "rerank_source": rerank["results"][0].get("rerank_source", "") if rerank.get("results") else "",
                    "fallback_used": fallback,
                    "parse_error": rerank.get("parse_error", ""),
                    "candidate_count": rerank.get("candidate_count", 0),
                    "returned_count": rerank.get("returned_count", 0),
                }
            )
        total = len([row for row in rows if row.get("status") != "invalid_sample"])
        report = {
            "benchmark_id": str(payload.get("benchmark_id", "llm_rerank_benchmark")),
            "samples": len(rows),
            "valid_samples": total,
            "top1_accuracy": round(top1_hits / max(1, total), 4),
            "coverage_at_k": round(covered / max(1, total), 4),
            "mrr": round(reciprocal_sum / max(1, total), 4),
            "fallback_rate": round(fallback_count / max(1, total), 4),
            "parse_error_rate": round(parse_error_count / max(1, total), 4),
            "llm_ordering_rate": round(llm_count / max(1, total), 4),
            "run_model": run_model,
            "results": rows,
            "human_review_required": True,
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "llm_rerank_benchmark_is_offline_quality_evaluation_not_fact_or_trade_signal",
        }
        self._audit(
            actor,
            "semantic_llm_rerank_benchmark",
            "search_index",
            report["benchmark_id"],
            source="semantic_search",
            approval_state=f"samples={report['valid_samples']};top1={report['top1_accuracy']};fallback={report['fallback_rate']}",
        )
        return report

    def semantic_search_benchmark(self, filters: Mapping[str, Any]) -> dict[str, Any]:
        samples = filters.get("samples", [])
        if not isinstance(samples, list):
            raise ValidationError("semantic search benchmark requires samples list")
        limit = self._bounded_limit(filters.get("limit", 5), max_value=50)
        rows: list[dict[str, Any]] = []
        hits = 0
        for index, sample in enumerate(samples):
            if not isinstance(sample, Mapping):
                continue
            expected_ids = {str(item) for item in sample.get("expected_resource_ids", [])}
            result = self.semantic_search(
                {
                    "q": str(sample.get("q", "")),
                    "issuer_id": str(sample.get("issuer_id", "")),
                    "resource_types": sample.get("resource_types", []),
                    "include_restricted": bool(sample.get("include_restricted", False)),
                    "limit": limit,
                }
            )
            returned_ids = {str(item["resource_id"]) for item in result["results"]}
            hit = bool(expected_ids & returned_ids) if expected_ids else bool(returned_ids)
            hits += 1 if hit else 0
            rows.append({"index": index, "query": sample.get("q", ""), "expected_resource_ids": sorted(expected_ids), "returned_resource_ids": sorted(returned_ids), "hit": hit})
        return {"samples": len(rows), "hits": hits, "recall_at_k": round(hits / max(1, len(rows)), 4), "results": rows}

    def qdrant_vector_export(self, filters: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        filters = filters or {}
        issuer_filter = str(filters.get("issuer_id", "")).strip()
        resource_types = {str(item).strip() for item in filters.get("resource_types", []) if str(item).strip()} if isinstance(filters.get("resource_types", []), list) else set()
        include_restricted = self._truthy(filters.get("include_restricted", False))
        collection = str(filters.get("collection", "ai_quant_semantic_records")).strip() or "ai_quant_semantic_records"
        records = self._search_records()
        if issuer_filter:
            records = [record for record in records if record.issuer_id == issuer_filter]
        if resource_types:
            records = [record for record in records if record.resource_type in resource_types]
        if not include_restricted:
            records = [record for record in records if self._search_record_boundary(record)["risk_level"] != "restricted"]
        points = [self._qdrant_point(record) for record in records]
        payload = {
            "adapter": {
                "format": "qdrant_points_upsert_compatible",
                "collection": collection,
                "vector_name": "text_tf_hash",
                "distance": "Cosine",
                "external_sync_required": True,
                "submission_boundary": "payload_export_only_no_external_qdrant_call",
            },
            "point_count": len(points),
            "points": points,
            "payload_filter": {"issuer_id": issuer_filter, "resource_types": sorted(resource_types), "include_restricted": include_restricted},
            "rights_filter": "restricted_excluded" if not include_restricted else "include_restricted_with_boundary_flags",
            "embedding_backend": {"backend": "local-hashed-term-frequency", "dimensions": 64},
        }
        if self._truthy(filters.get("record_export", False)):
            self._audit(
                actor,
                "export_qdrant_vector_payload",
                "search_index",
                issuer_filter or "all",
                source="qdrant_adapter",
                approval_state=f"points={len(points)};include_restricted={include_restricted}",
            )
        payload["content_sha256"] = self._payload_sha256(payload)
        return payload

    def create_qdrant_sync_notifications(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        export = self.qdrant_vector_export(payload, actor=actor)
        channel = str(payload.get("channel", "qdrant_vector_sync_outbox")).strip() or "qdrant_vector_sync_outbox"
        target = str(payload.get("target", "qdrant://vector-store")).strip()
        force = self._truthy(payload.get("force", False))
        mark_sent = self._truthy(payload.get("mark_sent", False))
        notification_id = str(payload.get("notification_id") or f"aln_qdrant_{export['content_sha256'][:16]}")
        skipped: list[dict[str, Any]] = []
        notifications: list[AlertNotification] = []
        if notification_id in self.store.alert_notifications and not force:
            skipped.append({"notification_id": notification_id, "reason": "already_exists"})
        else:
            notification = AlertNotification(
                notification_id=notification_id,
                alert_id="qdrant_vector_sync",
                channel=channel,
                target=target,
                status="sent" if mark_sent else "pending",
                payload={
                    "type": "qdrant_vector_sync",
                    "format": export["adapter"]["format"],
                    "content_sha256": export["content_sha256"],
                    "point_count": export["point_count"],
                    "vectors": export,
                    "delivery_policy": {
                        "provider": str(payload.get("provider", "dry-run-sender")),
                        "max_attempts": int(payload.get("max_delivery_attempts", 3)),
                        "backoff": str(payload.get("delivery_backoff", "manual_or_external_sender")),
                    },
                },
            )
            self.store.alert_notifications[notification.notification_id] = notification
            notifications.append(notification)
        self._audit(
            actor,
            "enqueue_qdrant_vector_sync",
            "search_index",
            str(payload.get("issuer_id") or payload.get("collection") or "batch"),
            source="qdrant_adapter",
            approval_state=f"notifications={len(notifications)};skipped={len(skipped)}",
        )
        return {
            "adapter": export["adapter"],
            "channel": channel,
            "target": target,
            "count": len(notifications),
            "skipped_count": len(skipped),
            "notifications": [to_plain(item) for item in notifications],
            "skipped": skipped,
            "external_delivery_ready": bool(target),
        }

    def graph_vector_readiness_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        graph_export = self.graph_neo4j_export(payload, actor=actor)
        qdrant_export = self.qdrant_vector_export(payload, actor=actor)
        traceability = self.graph_traceability_report({"include_details": False})
        edge_quality = self.graph_edge_quality_report({"limit": payload.get("edge_limit", 1000)})
        artifacts = self._graph_vector_artifact_uris(payload)
        adapters = self._graph_vector_adapter_config(payload)
        throughput = self._graph_vector_throughput(payload)
        retry_summary = self._graph_vector_retry_summary(payload)
        min_traceability = float(payload.get("min_traceability_rate", 0.95))
        min_edge_coverage = float(payload.get("min_edge_metadata_coverage", 1.0))
        min_nodes = int(payload.get("min_node_count", 1))
        min_points = int(payload.get("min_point_count", 1))
        gates = [
            self._readiness_numeric_gate("neo4j_node_count", int(graph_export["node_count"]), min_nodes, ">=", "Neo4j graph export node count"),
            self._readiness_numeric_gate("neo4j_relationship_count", int(graph_export["relationship_count"]), 1, ">=", "Neo4j graph export relationship count"),
            self._readiness_numeric_gate("qdrant_point_count", int(qdrant_export["point_count"]), min_points, ">=", "Qdrant vector export point count"),
            self._readiness_numeric_gate("traceability_rate", float(traceability["traceability_rate"]), min_traceability, ">=", "conclusion/research graph traceability"),
            self._readiness_numeric_gate("edge_metadata_coverage", float(edge_quality["edge_metadata_coverage"]), min_edge_coverage, ">=", "edge source/timestamp/version/confidence coverage"),
            self._readiness_bool_gate("rights_boundary_preserved", qdrant_export["rights_filter"] in {"restricted_excluded", "include_restricted_with_boundary_flags"} and graph_export["rights_boundary"], "source/rights/risk boundary preserved in payloads"),
            self._readiness_bool_gate("neo4j_non_local_config", adapters["neo4j"]["non_local_configured"], "non-local Neo4j staging/production endpoint"),
            self._readiness_bool_gate("qdrant_non_local_config", adapters["qdrant"]["non_local_configured"], "non-local Qdrant staging/production endpoint"),
            self._readiness_bool_gate("neo4j_sync_artifact_uri", bool(artifacts.get("neo4j_sync_artifact_uri")), "Neo4j sync artifact URI"),
            self._readiness_bool_gate("qdrant_sync_artifact_uri", bool(artifacts.get("qdrant_sync_artifact_uri")), "Qdrant sync artifact URI"),
            self._readiness_bool_gate("throughput_baseline", throughput["present"], "batch sync throughput baseline"),
            self._readiness_bool_gate("failure_recovery_evidence", retry_summary["recovery_evidence_present"], "failure injection and retry recovery evidence URI"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing
        report = {
            "ready_for_graph_vector_production": ready,
            "ready_for_external_acceptance": ready,
            "missing_requirements": missing,
            "gates": gates,
            "adapters": adapters,
            "artifact_uris": artifacts,
            "throughput": throughput,
            "retry_summary": retry_summary,
            "graph_export": {
                "node_count": graph_export["node_count"],
                "relationship_count": graph_export["relationship_count"],
                "content_sha256": graph_export["content_sha256"],
                "format": graph_export["adapter"]["format"],
            },
            "qdrant_export": {
                "point_count": qdrant_export["point_count"],
                "content_sha256": qdrant_export["content_sha256"],
                "format": qdrant_export["adapter"]["format"],
                "rights_filter": qdrant_export["rights_filter"],
            },
            "traceability": {
                "traceability_rate": traceability["traceability_rate"],
                "counts": traceability["counts"],
            },
            "edge_quality": {
                "edge_metadata_coverage": edge_quality["edge_metadata_coverage"],
                "total_edges": edge_quality["total_edges"],
                "missing_counts": edge_quality["missing_counts"],
            },
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "graph_vector_readiness_report_requires_external_neo4j_qdrant_sync_evidence_and_does_not_call_external_databases",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "graph_vector_readiness_report", "graph_vector", "neo4j_qdrant", source="graph_vector_adapter", approval_state="ready" if ready else "missing_evidence")
        return report

    def adapter_sync_retry_drill(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        default_channels = ["neo4j_graph_sync_outbox", "qdrant_vector_sync_outbox"]
        raw_channels = payload.get("channels", default_channels)
        if isinstance(raw_channels, str):
            channels = self._unique_strings(re.split(r"[,;]", raw_channels))
        else:
            channels = self._unique_strings(raw_channels)
        if not channels:
            channels = default_channels
        status = str(payload.get("status", "failed")).strip() or "failed"
        execute = self._truthy(payload.get("execute", False))
        provider = str(payload.get("provider", "")).strip()
        notification_ids = {str(item).strip() for item in payload.get("notification_ids", []) if str(item).strip()}
        max_delivery_attempts = payload.get("max_delivery_attempts")
        rows: list[dict[str, Any]] = []
        retry_results: list[dict[str, Any]] = []
        for notification in sorted(self.store.alert_notifications.values(), key=lambda item: item.created_at):
            if notification.channel not in channels:
                continue
            if notification_ids and notification.notification_id not in notification_ids:
                continue
            if status and notification.status != status:
                continue
            payload_type = str(notification.payload.get("type", ""))
            if payload_type not in {"graph_neo4j_sync", "qdrant_vector_sync"}:
                continue
            policy = notification.payload.get("delivery_policy", {})
            policy_max_attempts = 3
            if isinstance(policy, Mapping):
                policy_max_attempts = int(policy.get("max_attempts") or 3)
            attempts = int(notification.payload.get("delivery_attempts", 0))
            max_attempts = int(max_delivery_attempts or policy_max_attempts or 3)
            retryable = max_attempts <= 0 or attempts < max_attempts
            rows.append(
                {
                    "notification_id": notification.notification_id,
                    "channel": notification.channel,
                    "target": notification.target,
                    "status": notification.status,
                    "type": payload_type,
                    "content_sha256": str(notification.payload.get("content_sha256", "")),
                    "delivery_attempts": attempts,
                    "max_delivery_attempts": max_attempts,
                    "retryable": retryable,
                    "last_error": str(notification.payload.get("delivery_error", "")),
                }
            )
            if execute and retryable:
                result = self.deliver_alert_notifications(
                    {
                        "notification_ids": [notification.notification_id],
                        "status": notification.status,
                        "execute": True,
                        "provider": provider or (policy.get("provider", "") if isinstance(policy, Mapping) else ""),
                        "max_delivery_attempts": max_attempts,
                        "timeout_ms": payload.get("timeout_ms", 5000),
                    },
                    actor=actor,
                )
                retry_results.extend(result["notifications"])
        self._audit(
            actor,
            "adapter_sync_retry_drill",
            "search_adapter_sync",
            ",".join(channels),
            source="adapter_sync",
            approval_state=f"execute={execute};candidates={len(rows)};retried={len(retry_results)}",
        )
        return {
            "execute": execute,
            "status_filter": status,
            "channels": channels,
            "candidate_count": len(rows),
            "retryable_count": sum(1 for item in rows if item["retryable"]),
            "retried_count": len(retry_results),
            "candidates": rows,
            "retry_results": retry_results,
            "usage_boundary": "adapter_sync_retry_drill_reuses_notification_outbox_without_direct_neo4j_or_qdrant_client",
        }

    def record_readiness_check(self, check_id: str, payload: Mapping[str, Any], *, actor: str = "system") -> ReadinessCheckRecord:
        check_id = str(check_id or payload.get("check_id", "")).strip()
        known = {item["check_id"] for item in READINESS_CHECKLIST_ITEMS}
        if check_id not in known:
            raise ValidationError(f"unknown readiness check_id: {check_id}")
        measured_at = parse_datetime(payload.get("measured_at")) if payload.get("measured_at") else utcnow()
        expires_at = parse_datetime(payload.get("expires_at")) if payload.get("expires_at") else None
        record = ReadinessCheckRecord(
            check_id=check_id,
            status=str(payload.get("status", "passed")),
            owner=str(payload.get("owner", actor)),
            evidence_uri=str(payload.get("evidence_uri", "")),
            notes=str(payload.get("notes", "")),
            metrics=dict(payload.get("metrics", {})),
            measured_at=measured_at,
            expires_at=expires_at,
            updated_at=utcnow(),
        )
        action = "update_readiness_check" if check_id in self.store.readiness_checks else "record_readiness_check"
        self.store.readiness_checks[check_id] = record
        self._audit(actor, action, "readiness_check", check_id, approval_state=record.status)
        return record

    def record_capacity_baseline_result(self, payload: Mapping[str, Any], *, actor: str = "system") -> dict[str, Any]:
        result = dict(payload.get("result", payload.get("baseline", {})))
        if not result:
            raise ValidationError("capacity baseline result is required")
        max_ms = dict(result.get("max_ms", {}))
        thresholds = dict(payload.get("thresholds", {}))
        default_threshold_ms = float(payload.get("default_threshold_ms", 1000))
        breaches: list[dict[str, Any]] = []
        for metric, value in max_ms.items():
            threshold = float(thresholds.get(metric, default_threshold_ms))
            if float(value) > threshold:
                breaches.append({"metric": metric, "value": float(value), "threshold": threshold})
        status = str(payload.get("status", "failed" if breaches else "passed"))
        record = self.record_readiness_check(
            "capacity_latency_report",
            {
                "status": status,
                "owner": str(payload.get("owner", actor)),
                "evidence_uri": str(payload.get("evidence_uri", "")),
                "notes": str(payload.get("notes", "capacity latency baseline recorded")),
                "metrics": {
                    "baseline": result,
                    "thresholds": thresholds,
                    "default_threshold_ms": default_threshold_ms,
                    "breaches": breaches,
                },
                "measured_at": payload.get("measured_at"),
                "expires_at": payload.get("expires_at"),
            },
            actor=actor,
        )
        return {"check": to_plain(record), "breaches": breaches, "passed": status == "passed"}

    def readiness_deployment_report(self, payload: Mapping[str, Any] | None = None, *, actor: str = "system") -> dict[str, Any]:
        payload = payload or {}
        self._reject_secret_rotation_payload_values(payload)
        health = self.health()
        checklist = self.readiness_checklist_payload({})
        evidence = self._deployment_evidence_uris(payload)
        runtime = self._deployment_runtime_config(payload, health)
        secret_provider = self._deployment_secret_provider(payload)
        release_plan = self._deployment_release_plan(payload)
        backup_restore = self.store.readiness_checks.get("backup_restore_drill")
        capacity = self.store.readiness_checks.get("capacity_latency_report")
        launch = self.store.readiness_checks.get("launch_checklist")
        permission = self.store.readiness_checks.get("permission_red_team_test")
        compliance = self.store.readiness_checks.get("compliance_review_record")
        secret_rotations = self.secret_rotations_payload({"limit": 1000})
        gates = [
            self._readiness_bool_gate("production_environment_named", bool(runtime["environment"]) and runtime["environment"] not in {"local", "dev", "development"}, "production/staging environment name"),
            self._readiness_bool_gate("postgres_config_present", runtime["postgres_configured"], "PostgreSQL DSN supplied by deployment environment"),
            self._readiness_bool_gate("s3_object_store_config_present", runtime["s3_configured"], "S3-compatible object store parameters supplied"),
            self._readiness_bool_gate("opensearch_config_present", runtime["opensearch_configured"], "OpenSearch parameters supplied"),
            self._readiness_bool_gate("production_parameters_uri", bool(evidence.get("production_parameters_uri")), "production/staging environment parameter manifest artifact URI"),
            self._readiness_bool_gate("secret_manager_config_present", bool(secret_provider["provider"]) and secret_provider["provider"] not in {"local-development-metadata-only", "local", "none"}, "external secret manager provider configured"),
            self._readiness_bool_gate("secret_rotation_evidence", secret_rotations["count"] > 0 and bool(evidence.get("secret_manager_evidence_uri")), "external secret rotation/injection evidence URI"),
            self._readiness_bool_gate("backup_restore_drill_record", self._deployment_check_passed(backup_restore), "backup restore readiness checklist record"),
            self._readiness_bool_gate("backup_restore_evidence_uri", self._external_artifact_uri(backup_restore.evidence_uri if backup_restore else "") or bool(evidence.get("backup_restore_evidence_uri")), "backup/restore drill evidence URI"),
            self._readiness_bool_gate("capacity_baseline_record", self._deployment_check_passed(capacity), "capacity baseline readiness checklist record"),
            self._readiness_bool_gate("capacity_baseline_evidence_uri", self._external_artifact_uri(capacity.evidence_uri if capacity else "") or bool(evidence.get("capacity_baseline_uri")), "capacity baseline evidence URI"),
            self._readiness_bool_gate("permission_red_team_record", self._deployment_check_passed(permission), "permission red-team readiness record"),
            self._readiness_bool_gate("compliance_review_record", self._deployment_check_passed(compliance), "compliance review readiness record"),
            self._readiness_bool_gate("launch_checklist_record", self._deployment_check_passed(launch), "CEO launch checklist readiness record"),
            self._readiness_bool_gate("release_checklist_uri", bool(evidence.get("release_checklist_uri")), "release checklist artifact URI"),
            self._readiness_bool_gate("canary_plan_uri", bool(evidence.get("canary_plan_uri")), "canary/gray rollout plan artifact URI"),
            self._readiness_bool_gate("rollback_plan_uri", bool(evidence.get("rollback_plan_uri")), "rollback plan artifact URI"),
            self._readiness_bool_gate("broker_execution_blocked", not runtime["live_execution_enabled"], "no live broker or automatic order execution"),
        ]
        missing = [gate["gate"] for gate in gates if not gate["passed"]]
        ready = not missing and float(checklist.get("coverage", 0.0)) == 1.0
        report = {
            "ready_for_production_deployment": ready,
            "ready_for_launch": ready,
            "missing_requirements": missing,
            "gates": gates,
            "runtime": runtime,
            "secret_manager": secret_provider,
            "artifact_uris": evidence,
            "release_plan": release_plan,
            "checklist": {
                "required": checklist["required"],
                "passed": checklist["passed"],
                "coverage": checklist["coverage"],
                "pending_checklist": checklist["pending_checklist"],
            },
            "readiness_records": {
                "backup_restore_drill": to_plain(backup_restore) if backup_restore else None,
                "capacity_latency_report": to_plain(capacity) if capacity else None,
                "permission_red_team_test": to_plain(permission) if permission else None,
                "compliance_review_record": to_plain(compliance) if compliance else None,
                "launch_checklist": to_plain(launch) if launch else None,
            },
            "secret_rotation_summary": {
                "count": secret_rotations["count"],
                "overdue": secret_rotations["overdue"],
                "due_soon": secret_rotations["due_soon"],
            },
            "automation_allowed": False,
            "live_execution_allowed": False,
            "usage_boundary": "deployment_report_is_release_evidence_manifest_and_does_not_expose_secret_values_or_enable_live_trading",
        }
        if self._truthy(payload.get("record_readiness", False)):
            self._audit(actor, "readiness_deployment_report", "readiness", "deployment", approval_state="ready" if ready else "missing_evidence")
        return report

